def _reach_inc(name: str) -> None:
    _REACH_COUNTERS[name] = _REACH_COUNTERS.get(name, 0) + 1


def _reach_reset(*names: str) -> None:
    if not names:
        for k in list(_REACH_COUNTERS.keys()):
            _REACH_COUNTERS[k] = 0
        return
    for n in names:
        _REACH_COUNTERS[n] = 0


def _reach_get(name: str) -> int:
    return int(_REACH_COUNTERS.get(name, 0))


