def _d3s4_precedence_rank(reason: str) -> int:
    """R5-005 §18.15.10 closed precedence rank for a corruption reason (lower = higher
    precedence). Maps each concrete first_reason onto the five closed precedence levels:
    1 D2/local decode/framing CORRUPT (D1 CRC / decode / framing / invalid-enum / MBZ);
    2 PVD/raw/head CORRUPT (returned primary raw/raw2/aux/PVD/head/index digest mismatch);
    3 missing/duplicate/extra/SHA CORRUPT (absent/missing/duplicate/extra/SHA/manifest/
      budget/orphan/stale); 4 deferred authority; 5 local valid (default)."""
    r = str(reason).lower()
    if any(t in r for t in (
        "crc", "decode", "framing", "invalid_enum", "mbz", "d1_", "d2_",
    )):
        return 1
    if any(t in r for t in (
        "raw_mismatch", "raw2_mismatch", "aux_mismatch", "pvd_mismatch",
        "head_mismatch", "primary_raw", "member_value_digest", "raw_len_mismatch",
    )):
        return 2
    if any(t in r for t in (
        "absent", "missing", "duplicate", "extra", "sha", "manifest",
        "budget", "orphan", "stale", "reissue", "early_exit", "arm_bit",
    )):
        return 3
    if any(t in r for t in ("deferred", "sticky", "supersede", "partial_sticky")):
        return 4
    return 5

