def _contract_tables_sha() -> str:
    """Recompute contract-table digest from live tables (self-test / mutation only)."""
    masks_ser = {}
    for k, v in sorted(MODE_REQUIRED_MASKS.items()):
        masks_ser[str(k)] = [v[0], v[1], sorted(v[2]), sorted(v[3])]
    payload = json.dumps({
        "budget": GET_BUDGET_TABLE,
        "precedence": PRECEDENCE_ORDER,
        "publication": PUBLICATION_ORDER,
        "constraints": sorted(EXECUTION_CONSTRAINTS),
        "mode_masks": masks_ser,
    }, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(payload.encode()).hexdigest()


# Baked source literal — NOT recomputed at import. Self-test compares recompute
# against this pin; source mutations of tables without updating this pin RED.
CONTRACT_TABLES_SHA256 = (
    "75fe800ecc7b73a690d09682ee4cf627a90cfae4d632c2500143adae90c9083e"
)

# ---------------------------------------------------------------------------
# Validators
# ---------------------------------------------------------------------------

def validate_context_slot_map() -> Optional[str]:
    total = 0
    for offset, size, name in S4_CONTEXT_SLOT_MAP:
        if offset != total:
            return f"slot {name}: expected offset {total}, got {offset}"
        total += size
    if total != S4_CONTEXT_SIZEOF:
        return f"total {total} != sizeof {S4_CONTEXT_SIZEOF}"
    names = [name for _, _, name in S4_CONTEXT_SLOT_MAP]
    if len(names) != len(set(names)):
        return "duplicate slot names"
    return None


def validate_slot_map_alias_overlap() -> Optional[str]:
    for alias_name, variants in S4_ALIAS_GROUPS:
        if alias_name not in S4_SLOT_NAMES:
            return f"alias group root {alias_name} not in slot map"
        if len(variants) < 2:
            return f"alias group {alias_name} has fewer than 2 variants"
    return None


def validate_slot_map_phase_lifetime() -> Optional[str]:
    for slot_name, phases in S4_PHASE_LIFETIME_RULES.items():
        if slot_name not in S4_SLOT_NAMES:
            return f"phase-lifetime slot {slot_name} not in slot map"
        if not phases:
            return f"phase-lifetime slot {slot_name} has empty phase set"
        for p in phases:
            if p not in PHASE_VALID:
                return f"phase-lifetime slot {slot_name} references invalid phase {p}"
    return None


def validate_slot_map_unmapped_rejection() -> Optional[str]:
    mapped = set(S4_SLOT_NAMES)
    for slot_name in S4_PHASE_LIFETIME_RULES:
        if slot_name not in mapped:
            return f"unmapped attribute {slot_name} in phase-lifetime rules"
    for alias_name, _ in S4_ALIAS_GROUPS:
        if alias_name not in mapped:
            return f"unmapped attribute {alias_name} in alias groups"
    return None


def validate_coverage_matrix() -> Optional[str]:
    if len(COVERAGE_MATRIX_POSITIVE) != COVERAGE_POSITIVE_SIZE:
        return f"positive count {len(COVERAGE_MATRIX_POSITIVE)} != {COVERAGE_POSITIVE_SIZE}"
    if len(COVERAGE_MATRIX_NEGATIVE) != COVERAGE_NEGATIVE_SIZE:
        return f"negative count {len(COVERAGE_MATRIX_NEGATIVE)} != {COVERAGE_NEGATIVE_SIZE}"
    if len(COVERAGE_MATRIX_ALL) != COVERAGE_MATRIX_SIZE:
        return f"total {len(COVERAGE_MATRIX_ALL)} != {COVERAGE_MATRIX_SIZE}"
    ids = [vid for vid, _ in COVERAGE_MATRIX_ALL]
    if len(ids) != len(set(ids)):
        return "duplicate vector IDs in coverage matrix"
    for vid, desc in COVERAGE_MATRIX_ALL:
        if not vid.startswith("D3S4_"):
            return f"ID {vid} missing D3S4_ prefix"
        if not desc:
            return f"ID {vid} has empty description"
    all_desc = " ".join(desc for _, desc in COVERAGE_MATRIX_ALL)
    for subcase_name, keywords in COVERAGE_REQUIRED_SUBCASES:
        for kw in keywords:
            if kw.lower() not in all_desc.lower():
                return f"required subcase {subcase_name}: keyword {kw!r} not found in descriptions"
    live_all = COVERAGE_MATRIX_POSITIVE + COVERAGE_MATRIX_NEGATIVE
    payload = "|".join(f"{vid}:{desc}" for vid, desc in live_all)
    computed_pin = hashlib.sha256(payload.encode()).hexdigest()
    if computed_pin != COVERAGE_CONTENT_SHA256:
        return "coverage matrix content pin mismatch (description tampered)"
    return None


def validate_coverage_mode_alignment() -> Optional[str]:
    live_all = COVERAGE_MATRIX_POSITIVE + COVERAGE_MATRIX_NEGATIVE
    live_ids = set(vid for vid, _ in live_all)
    table_ids = set(COVERAGE_ITEM_EXPECTED_MODES.keys())
    if live_ids != table_ids:
        missing = table_ids - live_ids
        extra = live_ids - table_ids
        parts = []
        if missing:
            parts.append(f"missing from matrix: {sorted(missing)}")
        if extra:
            parts.append(f"extra in matrix: {sorted(extra)}")
        return "coverage mode table " + "; ".join(parts)
    for vid, _desc in live_all:
        expected_modes = COVERAGE_ITEM_EXPECTED_MODES[vid]
        parts = vid.split("_")
        id_modes = set()
        for p in parts:
            if p.startswith("M3") and len(p) == 3 and p[1:].isdigit():
                id_modes.add(int(p[1:]))
        if id_modes != expected_modes:
            return (
                f"ID {vid}: mode tokens {sorted(id_modes)} != "
                f"expected {sorted(expected_modes)}"
            )
    return None


def validate_get_budget_table() -> Optional[str]:
    keys = set(GET_BUDGET_TABLE.keys())
    if keys != GET_BUDGET_REQUIRED_KEYS:
        missing = GET_BUDGET_REQUIRED_KEYS - keys
        extra = keys - GET_BUDGET_REQUIRED_KEYS
        parts = []
        if missing:
            parts.append(f"missing: {sorted(missing)}")
        if extra:
            parts.append(f"extra: {sorted(extra)}")
        return "get-budget table " + "; ".join(parts)
    for k, v in GET_BUDGET_TABLE.items():
        if not isinstance(v, dict):
            return f"get-budget entry {k} is not a dict"
        if "formula" not in v:
            return f"get-budget entry {k} missing formula"
    m31 = GET_BUDGET_TABLE["31_32_per_header"]
    if m31.get("formula") != "2M+P":
        return "31_32_per_header formula != 2M+P"
    if m31.get("chunk_gets") != "M":
        return "31_32_per_header chunk_gets != M"
    if m31.get("member_gets") != "M":
        return "31_32_per_header member_gets != M"
    if m31.get("primary_gets") != "P":
        return "31_32_per_header primary_gets != P"
    inv = GET_BUDGET_TABLE["33_inventory"]
    if inv.get("gets_per_header") != 0:
        return "33_inventory gets_per_header != 0"
    cb = GET_BUDGET_TABLE["33_chunk_bind"]
    if cb.get("gets_per_chunk") != 1:
        return "33_chunk_bind gets_per_chunk != 1"
    return None


def validate_execution_constraints() -> Optional[str]:
    if not EXECUTION_CONSTRAINTS_REQUIRED.issubset(EXECUTION_CONSTRAINTS):
        missing = EXECUTION_CONSTRAINTS_REQUIRED - EXECUTION_CONSTRAINTS
        return f"execution constraints missing required: {sorted(missing)}"
    if "k4_equals_4" not in EXECUTION_CONSTRAINTS:
        return "execution constraints missing k4_equals_4"
    return None


def validate_precedence_order() -> Optional[str]:
    if len(PRECEDENCE_ORDER) != 5:
        return f"precedence order has {len(PRECEDENCE_ORDER)} entries, expected 5"
    if PRECEDENCE_ORDER[0] != "D2_local_decode_framing_CORRUPT":
        return "precedence[0] must be D2/local decode/framing CORRUPT"
    if PRECEDENCE_ORDER[-1] != "local_valid":
        return "precedence[-1] must be local_valid"
    if "deferred" not in PRECEDENCE_ORDER[3]:
        return "precedence[3] must contain deferred"
    return None


def validate_publication_contract() -> Optional[str]:
    if len(PUBLICATION_ORDER) != 4:
        return f"publication order has {len(PUBLICATION_ORDER)} entries, expected 4"
    if PUBLICATION_ORDER[0] != "derive_sample_scalar_disposition":
        return "publication[0] must be derive/sample disposition"
    if PUBLICATION_ORDER[-1] != "zero_s4_context":
        return "publication[-1] must be zero S4 context"
    if RESULT_HOST_ALIGNMENT != 8:
        return "result host alignment != 8"
    if RESULT_HOST_SIZEOF != 56:
        return "result host sizeof != 56"
    if RESULT_TARGET_CEILING != 64:
        return "result target ceiling != 64"
    if RESULT_FIELD_OFFSET_PRESENT != 52:
        return "result present offset != 52"
    if RESULT_FIELD_OFFSET_DISPOSITION != 53:
        return "result disposition offset != 53"
    if len(POISON_UNCHANGED_PATHS) < 7:
        return f"poison unchanged paths has {len(POISON_UNCHANGED_PATHS)} entries, expected >= 7"
    return None


def validate_mode_required_masks() -> Optional[str]:
    for mode in sorted(MODES_VALID):
        if mode not in MODE_REQUIRED_MASKS:
            return f"mode {mode} missing from MODE_REQUIRED_MASKS"
        count_req, binding_req, deferred_count, deferred_binding = MODE_REQUIRED_MASKS[mode]
        if count_req & COUNT_MBZ:
            return f"mode {mode} required count mask has MBZ bits"
        if binding_req & BINDING_MBZ:
            return f"mode {mode} required binding mask has MBZ bits"
    m31_count, m31_bind, _, m31_def_bind = MODE_REQUIRED_MASKS[31]
    if m31_count != COUNT_BIT_M31:
        return "mode 31 required count != bit0"
    if m31_bind != 0:
        return "mode 31 required binding != 0"
    m34_count, m34_bind, _, m34_def_bind = MODE_REQUIRED_MASKS[34]
    if m34_count != COUNT_BIT_M34:
        return "mode 34 required count != bit2"
    expected_m34_bind = BINDING_BIT_M34_A | BINDING_BIT_M34_B | BINDING_BIT_M34_C | BINDING_BIT_M34_ALL
    if m34_bind != expected_m34_bind:
        return "mode 34 required binding != bits1|2|3|4"
    if m34_def_bind != frozenset({0x00}):
        return "mode 34 deferred binding must be {0}"
    return None


def derive_disposition(flags: int, binding_complete_mask: int) -> int:
    bit7 = 1 if (flags & FLAG_S5_REQUIRED_SEEN) else 0
    bit5 = 1 if (binding_complete_mask & BINDING_BIT_S6_REQUIRED) else 0
    return bit7 | (bit5 << 1)


def validate_disposition_derivation() -> Optional[str]:
    if derive_disposition(0, 0) != DISPOSITION_LOCAL_COMPLETE:
        return "disposition(0,0) != LOCAL_COMPLETE"
    if derive_disposition(FLAG_S5_REQUIRED_SEEN, 0) != DISPOSITION_S5_REQUIRED:
        return "disposition(bit7,0) != S5_REQUIRED"
    if derive_disposition(0, BINDING_BIT_S6_REQUIRED) != DISPOSITION_S6_REQUIRED:
        return "disposition(0,bit5) != S6_REQUIRED"
    if derive_disposition(FLAG_S5_REQUIRED_SEEN, BINDING_BIT_S6_REQUIRED) != DISPOSITION_S5_AND_S6_REQUIRED:
        return "disposition(bit7,bit5) != S5_AND_S6_REQUIRED"
    return None


def d3s4_compose_accumulate(inputs: List[Dict[str, Any]]) -> Dict[str, int]:
    """A2-b rev5 step5 (catalog #10): the higher composition accumulator. It consumes
    ONLY results whose status is NINLIL_OK and present is 1 (a non-OK or present-0 result
    is never composed), and OR-folds the contributed dispositions: a Mode32 S5_REQUIRED
    result (disp 1, bit7) plus a Mode33 S6_REQUIRED result (disp 2, bit5) compose to
    S5_AND_S6_REQUIRED (disp 3). Dropping either input, or substituting a duplicate that
    carries only one sticky bit, yields disp != 3."""
    present = 0
    disp = 0
    for inp in inputs:
        if str(inp.get("status")) == "NINLIL_OK" and int(inp.get("present", 0)) == 1:
            present = 1
            disp |= int(inp.get("disp", 0))
    return {"present": present, "disp": disp}


def validate_complete_ready_exclusivity() -> Optional[str]:
    flags_complete = FLAG_COMPLETE_READY
    if flags_complete & FLAG_S5_REQUIRED_SEEN:
        return "COMPLETE_READY and bit7 overlap"
    return None


