# ---------------------------------------------------------------------------
# Closed recursive schema (all depths / all types)
# leaf = type pin; object = closed key tree; list = element schema; union = arms
# Schema node: ("leaf", frozenset types) | ("obj", {k: schema}) |
#              ("list", elem_schema) | ("union", (schema, ...)) | ("empty_obj",)
# ---------------------------------------------------------------------------

_SLeaf = lambda *ts: ("leaf", frozenset(ts))  # noqa: E731
_SObj = lambda d: ("obj", d)  # noqa: E731
_SList = lambda e: ("list", e)  # noqa: E731
_SUnion = lambda *arms: ("union", arms)  # noqa: E731
_SEmptyObj = ("empty_obj",)

_S_STR = _SLeaf("str")
_S_INT = _SLeaf("int")
_S_BOOL = _SLeaf("bool")
_S_NULL = _SLeaf("null")
_S_STR_NULL = _SLeaf("str", "null")
_S_INT_NULL = _SLeaf("int", "null")

