UINT32_MAX = 0xFFFFFFFF

# Closed nested known-int ranges (d3s3-equivalent; present keys only).
# NOTE: vector-top `mode` is validated separately as int; Port events may use
# string mode "READ_ONLY", so `mode` is intentionally absent here.
_KNOWN_JSON_INT_RANGES: Dict[str, Tuple[int, int]] = {
    "vector_count": (0, UINT32_MAX),
    "version": (1, UINT32_MAX),
    "d3s1_prefix_count": (0, UINT32_MAX),
    "d3s2_prefix_count": (0, UINT32_MAX),
    "d3s3_suffix_count": (0, UINT32_MAX),
    "d3s3_formal_precheck_count": (0, UINT32_MAX),
    "d3s3_production_count": (0, UINT32_MAX),
    "d3s4_suffix_count": (0, UINT32_MAX),
    "suffix_count": (0, UINT32_MAX),
    "phase": (0, 255),
    "flags": (0, UINT32_MAX),
    "count_complete_mask": (0, UINT32_MAX),
    "binding_complete_mask": (0, UINT32_MAX),
    "faults_expected_used": (0, 1),
    "adopted": (0, 1),
    "seq": (0, UINT32_MAX),
    "on_call": (0, UINT32_MAX),
    "pass_kind": (0, 255),
    "focus_mode": (0, 255),
    "d3s4_disposition_present": (0, 1),
    "d3s4_disposition": (0, 3),
    "close_count": (0, UINT32_MAX),
    "mutation_calls": (0, UINT32_MAX),
    "note_count": (0, UINT32_MAX),
    "ok_row_count": (0, UINT32_MAX),
    "family14_row_count": (0, UINT32_MAX),
    "current_domain_key_count": (0, UINT32_MAX),
    "iter_open_count": (0, UINT32_MAX),
    "profile_exact_active": (0, 1),
    "profile_mismatch": (0, 1),
    "future_profile_candidate": (0, 1),
    "profile_get_present_mask": (0, UINT32_MAX),
    "family14_iter_seen_mask": (0, UINT32_MAX),
    "recognizable_future_seen": (0, 1),
    "has_sticky_primary": (0, 1),
    "reopen_required": (0, 1),
    "row_budget": (0, UINT32_MAX),
}


def _strict_int(v: Any, name: str, *, min_v: int = 0, max_v: int = UINT32_MAX) -> Optional[str]:
    if type(v) is bool:
        return f"{name}: bool is not integer"
    if type(v) is not int:
        return f"{name}: not integer (got {type(v).__name__})"
    if v < min_v or v > max_v:
        return f"{name}: {v} out of range [{min_v}, {max_v}]"
    return None


def _walk_reject_bad_numbers(obj: Any, *, path: str = "$") -> Optional[str]:
    """Reject float pollution at every nesting level (bool is not int)."""
    if type(obj) is bool:
        return None
    if type(obj) is float:
        return f"{path}: non-integer number (float/nonfinite) forbidden"
    if isinstance(obj, dict):
        for k, v in obj.items():
            err = _walk_reject_bad_numbers(v, path=f"{path}.{k}")
            if err is not None:
                return err
        return None
    if isinstance(obj, list):
        for i, v in enumerate(obj):
            err = _walk_reject_bad_numbers(v, path=f"{path}[{i}]")
            if err is not None:
                return err
        return None
    return None


def _validate_known_json_ints(obj: Any, *, path: str = "$") -> Optional[str]:
    """Closed nested schema: every known always-int key is strict JSON int + range."""
    if isinstance(obj, dict):
        for k, v in obj.items():
            rng = _KNOWN_JSON_INT_RANGES.get(k)
            if rng is None and (
                k.endswith("_prefix_count") or k.endswith("_suffix_count")
            ):
                rng = (0, UINT32_MAX)
            if rng is not None and v is not None:
                e = _strict_int(v, f"{path}.{k}", min_v=rng[0], max_v=rng[1])
                if e is not None:
                    return e
            err = _validate_known_json_ints(v, path=f"{path}.{k}")
            if err is not None:
                return err
        return None
    if isinstance(obj, list):
        for i, v in enumerate(obj):
            err = _validate_known_json_ints(v, path=f"{path}[{i}]")
            if err is not None:
                return err
        return None
    return None


def _reject_unknown_keys(
    obj: Dict[str, Any], allowed: FrozenSet[str], *, path: str
) -> Optional[str]:
    for k in obj:
        if k not in allowed:
            return f"{path}: unknown key {k!r} (closed schema)"
    return None


def _json_type_name(v: Any) -> str:
    if v is None:
        return "null"
    if type(v) is bool:
        return "bool"
    if type(v) is int:
        return "int"
    if type(v) is str:
        return "str"
    if type(v) is float:
        return "float"
    if isinstance(v, list):
        return "list"
    if isinstance(v, dict):
        return "dict"
    return type(v).__name__


def _validate_schema(value: Any, schema: Any, *, path: str) -> Optional[str]:
    """Recursive closed schema: leaf type pin / closed object / list elem / union."""
    kind = schema[0]
    if kind == "leaf":
        t = _json_type_name(value)
        allowed_types: FrozenSet[str] = schema[1]
        if t not in allowed_types:
            return (
                f"{path}: type {t!r} not in closed leaf "
                f"{sorted(allowed_types)} (got {value!r})"
            )
        return None
    if kind == "empty_obj":
        if not isinstance(value, dict):
            return f"{path}: not object"
        if value:
            # any key is unknown under empty closed object
            k0 = next(iter(value))
            return f"{path}: unknown key {k0!r} (closed schema)"
        return None
    if kind == "obj":
        if not isinstance(value, dict):
            return f"{path}: not object"
        children: Dict[str, Any] = schema[1]
        for k in value:
            if k not in children:
                return f"{path}: unknown key {k!r} (closed schema)"
        for k, v in value.items():
            err = _validate_schema(v, children[k], path=f"{path}.{k}")
            if err is not None:
                return err
        return None
    if kind == "list":
        if not isinstance(value, list):
            return f"{path}: not list"
        elem_schema = schema[1]
        for i, el in enumerate(value):
            err = _validate_schema(el, elem_schema, path=f"{path}[{i}]")
            if err is not None:
                return err
        return None
    if kind == "union":
        arms = schema[1]
        first_err: Optional[str] = None
        for arm in arms:
            err = _validate_schema(value, arm, path=path)
            if err is None:
                return None
            if first_err is None:
                first_err = err
        return first_err or f"{path}: no union arm matched"
    return f"{path}: internal schema kind {kind!r}"


def _validate_closed_nested_containers(
    row: Dict[str, Any], *, path: str, strict_vector_keys: bool
) -> Optional[str]:
    """Reject unknown keys + wrong types at every depth of the known key tree."""
    if strict_vector_keys:
        return _validate_schema(row, D3S4_VECTOR_SCHEMA, path=path)
    # Prefix rows: open top-level key set, but every present known nested key is closed.
    for key, subschema in D3S4_VECTOR_NESTED_SCHEMAS.items():
        if key not in row:
            continue
        err = _validate_schema(row[key], subschema, path=f"{path}.{key}")
        if err is not None:
            return err
    return None


def _validate_document_top_level_closed(doc: Dict[str, Any], *, where: str) -> Optional[str]:
    """Reject unknown document keys; type-check every present allowed key (full closed).

    Selective inspection is forbidden: D3S_DOC_TOP_SCHEMAS must cover every
    D3S_DOC_ALLOWED_KEYS member (self-test enforces set equality). null is
    rejected for non-null leaf/object/list schemas (workspace/required_kinds/
    d1_authority/scope/counts/etc.).
    """
    u = _reject_unknown_keys(doc, D3S_DOC_ALLOWED_KEYS, path=where)
    if u is not None:
        return u
    for k, v in doc.items():
        schema = D3S_DOC_TOP_SCHEMAS.get(k)
        if schema is None:
            return (
                f"{where}: internal: allowed key {k!r} missing from "
                f"D3S_DOC_TOP_SCHEMAS (closed schema drift)"
            )
        err = _validate_schema(v, schema, path=f"{where}.{k}")
        if err is not None:
            return err
    return None


def _validate_vector_row_shape(
    row: Any, idx: int, where: str, *, is_d3s4_suffix: bool = False
) -> Optional[str]:
    if not isinstance(row, dict):
        return f"{where}: vectors[{idx}] is not an object"
    vid = row.get("id")
    if not isinstance(vid, str) or not vid:
        return f"{where}: vectors[{idx}].id missing or not string"
    required = D3S4_SUFFIX_REQUIRED_KEYS if is_d3s4_suffix else D3S3_VECTOR_REQUIRED_KEYS
    for key in required:
        if key not in row:
            return f"{where}: vectors[{idx}] ({vid}) missing required key {key!r}"
    mode = row.get("mode")
    serr = _strict_int(mode, f"{where}.vectors[{idx}].mode", min_v=0, max_v=255)
    if serr is not None:
        return serr
    kind = row.get("kind")
    if not isinstance(kind, str) or not kind:
        return f"{where}: vectors[{idx}] ({vid}) kind missing or not string"
    if is_d3s4_suffix:
        if type(row.get("positive")) is not bool:
            return f"{where}: vectors[{idx}] ({vid}) positive must be bool"
        if not isinstance(row.get("ownership"), str) or not row["ownership"]:
            return f"{where}: vectors[{idx}] ({vid}) ownership missing or not string"
        if not isinstance(row.get("calls"), list):
            return f"{where}: vectors[{idx}] ({vid}) calls must be list"
        if not isinstance(row.get("expected"), dict):
            return f"{where}: vectors[{idx}] ({vid}) expected must be object"
    else:
        pos = row.get("positive")
        if pos is not None and type(pos) is not bool:
            return f"{where}: vectors[{idx}] ({vid}) positive not bool"
        rows = row.get("rows")
        if "rows" in row and not isinstance(rows, list):
            return f"{where}: vectors[{idx}] ({vid}) rows not list"
        calls = row.get("calls")
        if "calls" in row and calls is not None and not isinstance(calls, list):
            return f"{where}: vectors[{idx}] ({vid}) calls not list"
        expected = row.get("expected")
        if expected is not None and not isinstance(expected, dict):
            return f"{where}: vectors[{idx}] ({vid}) expected not object"
    nclosed = _validate_closed_nested_containers(
        row, path="%s.vectors[%d]" % (where, idx), strict_vector_keys=is_d3s4_suffix
    )
    if nclosed is not None:
        return nclosed
    nerr = _walk_reject_bad_numbers(row, path=f"{where}.vectors[{idx}]")
    if nerr is not None:
        return nerr
    return None


def _validate_document_shape(doc: Any, *, where: str) -> Optional[str]:
    """Full-document shape + nested closed schema + float/bool-as-int rejection."""
    _reach_inc("validate_document_shape")
    if not isinstance(doc, dict):
        return f"{where}: document is not an object"
    nerr = _walk_reject_bad_numbers(doc, path=where)
    if nerr is not None:
        return nerr
    kerr = _validate_known_json_ints(doc, path=where)
    if kerr is not None:
        return kerr
    fmt = doc.get("format")
    if not isinstance(fmt, str):
        return f"{where}: format not string"
    required = D3S4_DOC_REQUIRED_KEYS if fmt == FORMAT else D3S3_DOC_REQUIRED_KEYS
    for key in required:
        if key not in doc:
            return f"{where}: missing required top-level key {key!r}"
    # Closed top-level + known nested authority objects (unexpected_top.bogus → RED).
    terr = _validate_document_top_level_closed(doc, where=where)
    if terr is not None:
        return terr
    # Minimal shallow docs (only format/count/vectors/content) are RED — version required.
    vc = doc["vector_count"]
    serr = _strict_int(vc, f"{where}.vector_count", min_v=0, max_v=UINT32_MAX)
    if serr is not None:
        return serr
    vectors = doc["vectors"]
    if not isinstance(vectors, list):
        return f"{where}: vectors is not a list"
    if vc != len(vectors):
        return f"{where}: vector_count {vc} != len(vectors) {len(vectors)}"
    content_sha = doc["content_sha256"]
    if not isinstance(content_sha, str) or len(content_sha) != 64:
        return f"{where}: content_sha256 not 64-char string"
    version = doc["version"]
    serr = _strict_int(version, f"{where}.version", min_v=1, max_v=UINT32_MAX)
    if serr is not None:
        return serr
    seen_ids: set = set()
    is_d3s4 = fmt == FORMAT
    for i, row in enumerate(vectors):
        is_suffix = is_d3s4 and i >= D3S3_PREFIX
        rerr = _validate_vector_row_shape(row, i, where, is_d3s4_suffix=is_suffix)
        if rerr is not None:
            return rerr
        vid = row["id"]
        if vid in seen_ids:
            return f"{where}: duplicate vector id {vid!r} at index {i}"
        seen_ids.add(vid)
    return None


def _compute_content_sha(doc: Dict[str, Any]) -> str:
    return authority_content_sha256(doc)


def _compute_raw_sha_283(vectors: List[Any]) -> str:
    return hashlib.sha256(
        json.dumps(vectors[:D3S3_PREFIX], sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()
    ).hexdigest()


def _read_expanded_authority(
    path: Path, *, pin_fixed_authority: bool
) -> Tuple[Dict[str, Any], bytes, bool]:
    """Read either the sharded authority or a legacy expanded mutation fixture.

    The returned bytes are always the canonical *expanded* image.  This keeps the
    existing semantic/raw-pin gates independent of the storage representation;
    manifest and shard bytes are validated by the common loader first.
    """
    try:
        source_raw = path.read_bytes()
        probe = json.loads(source_raw)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise AuthorityError(f"unreadable/malformed input {path}: {exc}") from exc
    is_manifest = isinstance(probe, dict) and probe.get("format") == MANIFEST_FORMAT
    if is_manifest:
        doc = load_authority_expanded(
            path, pin_fixed_authority=pin_fixed_authority
        )
        # The common loader has independently streamed and checked the expanded
        # canonical SHA.  Do not materialize a second 38 MiB byte image here.
        return doc, b"", True
    if not isinstance(probe, dict):
        raise AuthorityError("document is not an object")
    return probe, source_raw, False


_canonical_prefix_283_cache: Optional[List[Dict[str, Any]]] = None


def _canonical_prefix_283() -> Tuple[List[Dict[str, Any]], bytes]:
    global _canonical_prefix_283_cache
    if not DEFAULT_JSON.is_file():
        raise SystemExit(f"error: missing canonical authority {DEFAULT_JSON}")
    try:
        source_raw = DEFAULT_JSON.read_bytes()
        probe = json.loads(source_raw)
    except AuthorityError as e:
        raise SystemExit(f"error: unreadable canonical authority: {e}") from e
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as e:
        raise SystemExit(f"error: unreadable canonical authority: {e}") from e
    if _canonical_prefix_283_cache is None:
        if isinstance(probe, dict) and probe.get("format") == MANIFEST_FORMAT:
            prefix: List[Dict[str, Any]] = []
            try:
                for index, vector in enumerate(
                    iter_authority_vectors(
                        DEFAULT_JSON, pin_fixed_authority=True
                    )
                ):
                    if index < D3S3_PREFIX:
                        prefix.append(vector)
            except AuthorityError as e:
                raise SystemExit(
                    f"error: unreadable canonical authority: {e}"
                ) from e
            if len(prefix) != D3S3_PREFIX:
                raise SystemExit(
                    f"error: canonical authority shorter than {D3S3_PREFIX}"
                )
            _canonical_prefix_283_cache = prefix
        else:
            if (
                not isinstance(probe, dict)
                or not isinstance(probe.get("vectors"), list)
            ):
                raise SystemExit("error: canonical authority vectors missing")
            if len(probe["vectors"]) < D3S3_PREFIX:
                raise SystemExit(
                    f"error: canonical authority shorter than {D3S3_PREFIX}"
                )
            _canonical_prefix_283_cache = copy.deepcopy(
                probe["vectors"][:D3S3_PREFIX]
            )
    return _canonical_prefix_283_cache, source_raw


def validate_prefix_283_authority(doc: Any, *, where: str, raw_bytes: Optional[bytes] = None) -> Optional[str]:
    """Prefix-283 authority with d3s3-equivalent full shape + format-aware raw pins.

    D3S3 input: content pin + prefix raw pin + (when raw_bytes) whole-file SHA pin.
    D3S4 extended: full-document nested shape + first-283 object equality + content
    field consistency + prefix raw pin. Whole-document SHA is NEVER compared to
    D3S3_FILE_RAW_PIN (extended docs would always false-reject).
    """
    _reach_inc("validate_prefix_283_authority")
    shape_err = _validate_document_shape(doc, where=where)
    if shape_err is not None:
        return shape_err
    vectors = doc["vectors"]
    if len(vectors) < D3S3_PREFIX:
        return f"{where}: vectors length {len(vectors)} < {D3S3_PREFIX}"
    fmt = doc["format"]
    if fmt not in (D3S3_FORMAT, FORMAT):
        return f"{where}: format {fmt!r} not recognized"
    content_sha = doc["content_sha256"]
    computed = _compute_content_sha(doc)
    if computed != content_sha:
        return f"{where}: content_sha256 mismatch"
    raw_sha = _compute_raw_sha_283(vectors)
    if raw_sha != D3S3_RAW_PIN:
        return f"{where}: prefix-283 raw SHA mismatch"
    try:
        canon, canon_raw = _canonical_prefix_283()
    except SystemExit as e:
        return str(e) if e.args else f"{where}: canonical authority unavailable"
    for i in range(D3S3_PREFIX):
        if vectors[i] != canon[i]:
            return f"{where}: prefix-283 full-object mismatch at index {i}"
    if fmt == D3S3_FORMAT:
        if content_sha != D3S3_CONTENT_PIN:
            return f"{where}: content_sha256 != d3s3 pin"
        if len(vectors) != D3S3_PREFIX:
            return f"{where}: d3s3 format requires exactly {D3S3_PREFIX} vectors, got {len(vectors)}"
        # Whole-file raw pin only for d3s3-format authority files.
        if raw_bytes is not None:
            file_sha = hashlib.sha256(raw_bytes).hexdigest()
            if file_sha != D3S3_FILE_RAW_PIN:
                return (
                    f"{where}: file raw SHA mismatch "
                    f"(expected {D3S3_FILE_RAW_PIN[:16]}..., got {file_sha[:16]}...)"
                )
        else:
            canon_file_sha = hashlib.sha256(canon_raw).hexdigest()
            if canon_file_sha != D3S3_FILE_RAW_PIN:
                return f"{where}: canonical file raw SHA mismatch"
    # D3S4 format: content pin of the full extended document is field-checked above;
    # do not require D3S3 content pin or whole-file D3S3 raw pin.
    return None


# ---------------------------------------------------------------------------
# PortFeed — rows-driven Port layer (§18.15 Mode34; A2-b rev5 step1)
# ---------------------------------------------------------------------------

class PortFeed:
    """Rows-driven Port layer for the Mode34 path.

    Input is a stored-rows list (key_hex/value_hex) plus an optional declared
    fault list. The Mode34 drive issues every Port operation through this layer:
    ``iter_open(prefix)`` / ``iter_next()`` (complete-key lex order) / ``exact_get
    (key)`` returning the stored value bytes or ABSENT. A declared fault whose
    ``op``/``on_call`` matches the current operation ordinal is injected at that
    operation. No carrier markers are consulted — arm kind, HEAD_INDEX state, M,
    chunk entries, membership targets and digest pins are all derived by the
    RefSession from the bytes this layer feeds back.
    """

    def __init__(
        self,
        rows: List[Dict[str, Any]],
        faults: Optional[List[Dict[str, Any]]] = None,
        *,
        iter_sequence: Optional[List[bytes]] = None,
    ):
        store: Dict[bytes, bytes] = {}
        for r in rows or []:
            kh = r.get("key_hex")
            vh = r.get("value_hex")
            if not isinstance(kh, str) or not isinstance(vh, str):
                continue
            try:
                k = bytes.fromhex(kh)
                v = bytes.fromhex(vh)
            except ValueError:
                continue
            store[k] = v
        self._store = store
        self._source_rows = list(rows or [])
        if iter_sequence is not None:
            self._sorted_keys = list(iter_sequence)
        else:
            self._sorted_keys = sorted(store.keys())
        self._faults = list(faults or [])
        self._iter_active = False
        self._iter_idx = 0
        self._op_ordinal: Dict[str, int] = {}
        self.fault_log: List[Dict[str, Any]] = []

    def has_prior_manifest_cache(self) -> bool:
        # N45 is a closed behavior hook, not a synthetic non-D1 storage row.
        # Consume the declared hook exactly once at the membership-install seam.
        n = self._next_ordinal("behavior_hook")
        f = self._match_fault("behavior_hook", n)
        if f is not None:
            self.fault_log.append(f)
            return f.get("shape") == "m34_prior_session_manifest"
        return False

    def _next_ordinal(self, op: str) -> int:
        n = self._op_ordinal.get(op, 0)
        self._op_ordinal[op] = n + 1
        return n

    def _match_fault(self, op: str, ordinal: int) -> Optional[Dict[str, Any]]:
        for f in self._faults:
            if f.get("op") != op:
                continue
            on_call = f.get("on_call")
            if on_call is None or int(on_call) == ordinal:
                return f
        return None

    def consume_fault(self, op: str, ordinal: int) -> Optional[Dict[str, Any]]:
        f = self._match_fault(op, ordinal)
        if f is not None:
            self.fault_log.append(f)
        return f

    def iter_open(self, prefix: Any) -> str:
        n = self._next_ordinal("iter_open")
        f = self._match_fault("iter_open", n)
        if f is not None:
            self.fault_log.append(f)
        self._iter_active = True
        self._iter_idx = 0
        return "OK"

    def iter_next(self) -> Optional[Tuple[bytes, bytes]]:
        n = self._next_ordinal("iter_next")
        f = self._match_fault("iter_next", n)
        if f is not None:
            self.fault_log.append(f)
            return None
        if not self._iter_active:
            return None
        if self._iter_idx >= len(self._sorted_keys):
            return None
        k = self._sorted_keys[self._iter_idx]
        self._iter_idx += 1
        return (k, self._store[k])

    def iter_close(self) -> str:
        n = self._next_ordinal("iter_close")
        f = self._match_fault("iter_close", n)
        if f is not None:
            self.fault_log.append(f)
        self._iter_active = False
        return "OK"

    def exact_get(self, key: bytes) -> Tuple[str, Optional[bytes]]:
        """Return (status, value): ("PRESENT", bytes) / ("ABSENT", None) /
        ("FAULT", None) when a declared fault is injected at this get ordinal."""
        n = self._next_ordinal("exact_get")
        f = self._match_fault("exact_get", n)
        if f is not None:
            self.fault_log.append(f)
            # Semantic collision hook: Storage still returns the D1-valid row
            # naturally.  The closed normalizer below injects the alternative
            # colliding raw image, so the negative tests collision defense
            # without requiring an impossible real SHA-256 collision or a
            # D1-illegal key/body pair.
            if f.get("shape") != "m34_primary_raw_collision":
                return ("FAULT", None)
        v = self._store.get(bytes(key))
        if v is None:
            return ("ABSENT", None)
        return ("PRESENT", v)

    def has_key(self, key: bytes) -> bool:
        return bytes(key) in self._store


# ---------------------------------------------------------------------------
# Portable SHA-256 context image used by the independent S4 oracle.
#
# This is intentionally not hashlib internals: the production-private context
# exposes the eight state words, completed-block bit count, complete 64-byte
# buffer image (including stale tail bytes), and buffer length.  The oracle
# must derive those bytes independently and must not retain chunk bodies as a
# hidden substitute for the fixed 949-byte state.
# ---------------------------------------------------------------------------

_SHA256_K: Tuple[int, ...] = (
    0x428A2F98, 0x71374491, 0xB5C0FBCF, 0xE9B5DBA5,
    0x3956C25B, 0x59F111F1, 0x923F82A4, 0xAB1C5ED5,
    0xD807AA98, 0x12835B01, 0x243185BE, 0x550C7DC3,
    0x72BE5D74, 0x80DEB1FE, 0x9BDC06A7, 0xC19BF174,
    0xE49B69C1, 0xEFBE4786, 0x0FC19DC6, 0x240CA1CC,
    0x2DE92C6F, 0x4A7484AA, 0x5CB0A9DC, 0x76F988DA,
    0x983E5152, 0xA831C66D, 0xB00327C8, 0xBF597FC7,
    0xC6E00BF3, 0xD5A79147, 0x06CA6351, 0x14292967,
    0x27B70A85, 0x2E1B2138, 0x4D2C6DFC, 0x53380D13,
    0x650A7354, 0x766A0ABB, 0x81C2C92E, 0x92722C85,
    0xA2BFE8A1, 0xA81A664B, 0xC24B8B70, 0xC76C51A3,
    0xD192E819, 0xD6990624, 0xF40E3585, 0x106AA070,
    0x19A4C116, 0x1E376C08, 0x2748774C, 0x34B0BCB5,
    0x391C0CB3, 0x4ED8AA4A, 0x5B9CCA4F, 0x682E6FF3,
    0x748F82EE, 0x78A5636F, 0x84C87814, 0x8CC70208,
    0x90BEFFFA, 0xA4506CEB, 0xBEF9A3F7, 0xC67178F2,
)
_SHA256_IV: Tuple[int, ...] = (
    0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,
    0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19,
)


def _sha256_rotr(value: int, count: int) -> int:
    value &= 0xFFFFFFFF
    return ((value >> count) | (value << (32 - count))) & 0xFFFFFFFF


class _Sha256ContextImage:
    """Byte-for-byte model of ninlil_model_domain_sha256_ctx_t semantics."""

    def __init__(
        self,
        state: Optional[List[int]] = None,
        bit_length: int = 0,
        buffer: Optional[bytes] = None,
        buffer_length: int = 0,
    ) -> None:
        self.state = list(_SHA256_IV if state is None else state)
        self.bit_length = int(bit_length)
        self.buffer = bytearray(64 if buffer is None else bytes(buffer))
        if len(self.buffer) != 64:
            raise ValueError("SHA-256 buffer image must be exactly 64 bytes")
        self.buffer_length = int(buffer_length)
        if (
            len(self.state) != 8
            or self.bit_length < 0
            or self.bit_length > 0xFFFFFFFFFFFFFFFF
            or (self.bit_length & 511) != 0
            or self.buffer_length < 0
            or self.buffer_length > 63
        ):
            raise ValueError("invalid SHA-256 context image")

    def clone(self) -> "_Sha256ContextImage":
        return _Sha256ContextImage(
            self.state, self.bit_length, bytes(self.buffer),
            self.buffer_length,
        )

    def _process_block(self, block: bytes) -> None:
        if len(block) != 64:
            raise ValueError("SHA-256 block must be 64 bytes")
        words = [
            int.from_bytes(block[i * 4:(i + 1) * 4], "big")
            for i in range(16)
        ]
        for i in range(16, 64):
            s0 = (
                _sha256_rotr(words[i - 15], 7)
                ^ _sha256_rotr(words[i - 15], 18)
                ^ (words[i - 15] >> 3)
            )
            s1 = (
                _sha256_rotr(words[i - 2], 17)
                ^ _sha256_rotr(words[i - 2], 19)
                ^ (words[i - 2] >> 10)
            )
            words.append(
                (words[i - 16] + s0 + words[i - 7] + s1)
                & 0xFFFFFFFF
            )
        a, b, c, d, e, f, g, h = self.state
        for i in range(64):
            big1 = (
                _sha256_rotr(e, 6)
                ^ _sha256_rotr(e, 11)
                ^ _sha256_rotr(e, 25)
            )
            choose = (e & f) ^ ((~e) & g)
            t1 = (
                h + big1 + choose + _SHA256_K[i] + words[i]
            ) & 0xFFFFFFFF
            big0 = (
                _sha256_rotr(a, 2)
                ^ _sha256_rotr(a, 13)
                ^ _sha256_rotr(a, 22)
            )
            majority = (a & b) ^ (a & c) ^ (b & c)
            t2 = (big0 + majority) & 0xFFFFFFFF
            h, g, f, e, d, c, b, a = (
                g, f, e, (d + t1) & 0xFFFFFFFF,
                c, b, a, (t1 + t2) & 0xFFFFFFFF,
            )
        working = (a, b, c, d, e, f, g, h)
        self.state = [
            (self.state[i] + working[i]) & 0xFFFFFFFF
            for i in range(8)
        ]

    def _absorb(self, data: bytes) -> None:
        offset = 0
        while offset < len(data):
            take = min(64 - self.buffer_length, len(data) - offset)
            self.buffer[
                self.buffer_length:self.buffer_length + take
            ] = data[offset:offset + take]
            self.buffer_length += take
            offset += take
            if self.buffer_length == 64:
                self._process_block(bytes(self.buffer))
                self.bit_length = (
                    self.bit_length + 512
                ) & 0xFFFFFFFFFFFFFFFF
                self.buffer_length = 0

    def update(self, data: bytes) -> None:
        incoming = bytes(data)
        known_bits = self.bit_length + self.buffer_length * 8
        if known_bits + len(incoming) * 8 > 0xFFFFFFFFFFFFFFFF:
            raise ValueError("SHA-256 message length overflow")
        self._absorb(incoming)

    def digest(self) -> bytes:
        work = self.clone()
        total_bits = work.bit_length + work.buffer_length * 8
        pad_length = (
            56 - work.buffer_length
            if work.buffer_length < 56
            else 64 - work.buffer_length + 56
        )
        work._absorb(b"\x80" + bytes(pad_length - 1))
        work._absorb(total_bits.to_bytes(8, "big"))
        return b"".join(word.to_bytes(4, "big") for word in work.state)

    def state_bytes(self) -> bytes:
        return b"".join(word.to_bytes(4, "big") for word in self.state)


# ---------------------------------------------------------------------------
# RefSession skeleton (§18.15 modes 31..34 per-mode phase machine)
# ---------------------------------------------------------------------------

class RefSession:
    """§18.15 independent D3-S4 oracle (modes 31..34).

    A2-a: per-mode phase machine with Port event emission points, drive/yield/
    resume, GROUP_CLOSE, finalize transitions, and numeric get-budget binding.
    A2-b rev2: member classification uses the closed §18.15.6 classifier; sticky
    bit7/bit5 are set only on a SUPERSEDE_WITNESS RETIRED/ABSENT member-classification
    transition. Drives emit forward-built complete Domain keys (real Port fixtures).
    """

    def __init__(self, mode: int):
        if mode not in MODES_VALID:
            raise ValueError(f"mode {mode} not in {sorted(MODES_VALID)}")
        self.mode = mode
        self.phase = PHASE_IDLE
        self.pass_kind = PASS_BASELINE
        self.focus_mode = 0
        self.flags = 0
        self.count_complete_mask = 0
        self.binding_complete_mask = 0
        self.group_class = GROUP_UNSET
        self.arm_cursor = 0
        self.member_substep = 0
        self.membership_substep = 0
        self.membership_need_mask = 0
        self.found_count_a = 0
        self.found_count_b = 0
        self.streamed_members = 0
        self.membership_i = 0
        self.member_count = 0
        self.chunk_count = 0
        self.drive_get_quota = 0  # IDLE whole-context zero; begin installs active quota
        self.drive_gets_used = 0
        self.entry_action = ENTRY_ACTION_NONE
        self.entry_old_present = 0
        self.entry_new_present = 0
        self.entry_flags = 0
        self.entry_record_role = 0
        self.entry_key_length = 0
        self.last_carrier_key = bytes(45)
        self.last_carrier_key_len = 0
        self.witness_digest = bytes(32)
        self.expected_manifest_digest = bytes(32)
        self.focus_key_digest = bytes(32)
        self.pin_digest_a = bytes(32)
        self.pin_digest_b = bytes(32)
        self.entry_old_value_digest = bytes(32)
        self.entry_new_value_digest = bytes(32)
        self.entry_prior_head_witness_digest = bytes(32)
        self.expected_primary_pvd = bytes(32)
        self.expected_primary_raw = bytes(255)
        self.expected_primary_raw2 = bytes(64)
        self.expected_primary_aux = bytes(16)
        self.expected_primary_raw_len = 0
        self.expected_primary_raw2_len = 0
        self.expected_primary_aux_len = 0
        self.prev_member_key = bytes(45)
        self.prev_member_key_len = 0
        self.peer_key = bytes(45)
        self.peer_key_len = 0
        self.membership_key_a = bytes(45)
        self.membership_key_a_len = 0
        self.sha_state = bytes(32)
        self.sha_bitcount = 0
        self.sha_block = bytes(64)
        self.sha_block_len = 0
        self.session_state = "IDLE"
        self.port_trace: List[Dict[str, Any]] = []
        # Pure auxiliaries only — state-driving cursors live in S4 slots above.
        self._get_count = 0
        self._headers: List[Dict[str, Any]] = []  # fixture RO
        self._first_corruption: Optional[str] = None  # diagnostic only
        self._m33_chunks: List[Dict[str, Any]] = []  # fixture RO
        self._m34_arm_a_seen = False
        self._m34_arm_b_seen = False
        self._m34_arm_c_seen = False
        self._carriers: List[Dict[str, Any]] = []  # fixture RO
        self._cleanup_failed = False
        self._out_result: Optional[Dict[str, Any]] = None
        self._alias_blocked = False
        # A2-b rev3 P11 finalize carriers: evaluator-off publishes canonical
        # present=0/disp=0; whole-result poison publishes nothing (bytes unchanged).
        # Both survive begin()/drive() (not S4 context slots; finalize-path authority).
        self._evaluator_off = False
        self._whole_result_poison = False
        # R5-003: declared finalize/abort faults are CONSUMED at finalize/abort call
        # time (op-local ordinal, logged in finalize_fault_log), not converted to
        # private flags at feed-setup time. The consumed shape drives the finalize-path
        # authority; an unconsumed declared fault is a check RED (consumption gate).
        self._declared_finalize_faults: List[Dict[str, Any]] = []
        self.finalize_fault_log: List[Dict[str, Any]] = []
        self._finalize_fault_ordinal = 0
        # R6-002 B1: P11 N15 session-state carriers (invalid carrier / prevalidation).
        self._p11_session_carrier: Optional[Tuple[int, int]] = None
        self._p11_prevalidation_fail = False
        self._p11_force_invalid_state = False
        self._header_budget_2mp = 0
        self._header_get_count = 0
        self._headers_closed_count = 0
        # Sticky session composition authority (§18.15.6): set atomically with the
        # member-classification transition of a SUPERSEDE_WITNESS RETIRED/ABSENT
        # predecessor; preserved across GROUP_CLOSE/pass exhaustion/yield; cleared
        # only by fresh-begin / finalize-after-sample / abort. Not a context slot.
        self._s6_authority_session = False
        self._bit7_session = False
        # A2-b rev5 step1: rows-driven Mode34 Port layer. When set, the focus_mode=34
        # path drives every Port operation through this feed and derives arm kind /
        # HEAD_INDEX state / M / chunk entries / membership targets / digest pins from
        # the fed bytes (no _carriers marker reads).
        self._m34_feed: Optional["PortFeed"] = None
        self._m34_cur: Dict[str, Any] = {}
        self._m34_fed_bodies: Dict[int, bytes] = {}
        self._m34_sha = None
        self._m34_seen_chunk_iter_keys: set = set()
        # A2-b rev5 step2: rows-driven Mode31/32 Port layer. When set, the
        # focus_mode=31/32 path drives every Port operation through this feed and
        # derives entry action / old-new present / digests / head relation /
        # predecessor lifecycle from the fed bytes (no member marker reads).
        self._m31_32_feed: Optional["PortFeed"] = None
        self._m31_32_cur_entry: Dict[str, Any] = {}
        self._m31_32_bit_checkpoint: List[Dict[str, int]] = []
        self._m31_32_primary_key_from_body: Optional[bytes] = None
        self._m31_32_pinned_src_body: Optional[bytes] = None
        self._m31_32_pinned_member_role: int = 0
        self._m31_32_blob_variant: int = 0
        self._m31_32_pinned_blob_id_digest: Optional[bytes] = None
        self._m31_32_pinned_blob_pvd_primary_raw: Optional[bytes] = None
        self._m31_32_blob_rebuild_used_pvd_link: bool = False
        self._m33_feed: Optional["PortFeed"] = None

    def _sha_context_load(self) -> _Sha256ContextImage:
        if len(self.sha_state) != 32 or len(self.sha_block) != 64:
            raise ValueError("invalid S4 SHA slot byte lengths")
        state = [
            int.from_bytes(self.sha_state[i * 4:(i + 1) * 4], "big")
            for i in range(8)
        ]
        return _Sha256ContextImage(
            state=state,
            bit_length=self.sha_bitcount,
            buffer=self.sha_block,
            buffer_length=self.sha_block_len,
        )

    def _sha_context_store(self, sha: _Sha256ContextImage) -> None:
        self.sha_state = sha.state_bytes()
        self.sha_bitcount = sha.bit_length
        self.sha_block = bytes(sha.buffer)
        self.sha_block_len = sha.buffer_length

    def _manifest_sha_init_slots(self) -> None:
        sha = _Sha256ContextImage()
        sha.update(b"NINLIL-DOMAIN-MANIFEST-V1")
        self._sha_context_store(sha)

    def _manifest_sha_update_slots(self, chunk_body: bytes) -> None:
        sha = self._sha_context_load()
        sha.update(bytes(chunk_body))
        self._sha_context_store(sha)

    def _manifest_sha_final_from_slots(self) -> bytes:
        return self._sha_context_load().digest()

    def set_headers(self, headers: List[Dict[str, Any]]) -> None:
        self._headers = headers

    def set_m34_feed(
        self, rows: List[Dict[str, Any]],
        faults: Optional[List[Dict[str, Any]]] = None,
        *,
        iter_sequence: Optional[List[bytes]] = None,
    ) -> None:
        self._m34_feed = PortFeed(rows, faults, iter_sequence=iter_sequence)

    def set_m31_32_feed(
        self, rows: List[Dict[str, Any]],
        faults: Optional[List[Dict[str, Any]]] = None,
    ) -> None:
        self._m31_32_feed = PortFeed(rows, faults)
        # R5-003: NO setup-time conversion of a declared finalize fault's ``shape`` into
        # private flags here. A finalize/abort-path fault is consumed at finalize/abort
        # call time (_consume_finalize_fault) and the consumed shape alone drives the
        # finalize-path authority; an unconsumed declared fault is a check RED.

    def set_m33_feed(
        self, rows: List[Dict[str, Any]],
        faults: Optional[List[Dict[str, Any]]] = None,
    ) -> None:
        self._m33_feed = PortFeed(rows, faults)

    def declare_finalize_fault(self, fault: Dict[str, Any]) -> None:
        """R5-003: declare a finalize/abort-path fault to be consumed exactly once at
        finalize/abort call time (op-local ordinal). The declaration is the stored call
        column input; consumption is logged so the check gate can require used==1."""
        self._declared_finalize_faults.append(dict(fault))

    def _consume_finalize_fault(self, op: str) -> Optional[str]:
        """R5-003: consume the declared finalize/abort fault matching this call's
        op-local ordinal, log it to ``finalize_fault_log``, and return its shape (or
        None when no fault is declared for this call). Consumption is the only path that
        sets the finalize-path authority flags — there is no setup-time metadata
        conversion of ``fault.shape`` into private flags."""
        ordinal = self._finalize_fault_ordinal
        self._finalize_fault_ordinal = ordinal + 1
        for f in self._declared_finalize_faults:
            if f.get("op") != op:
                continue
            on_call = f.get("on_call")
            if on_call is None or int(on_call) == ordinal:
                self.finalize_fault_log.append(dict(f))
                # R5-003: trace the consumption as a Port event inside the finalize call
                # interval (op-local ordinal + shape), so the stored call column presents
                # the fault-consumption event.
                self._emit_port(
                    "finalize_fault",
                    _fault_op=op,
                    _fault_ordinal=ordinal,
                    _fault_shape=str(f.get("shape", "")),
                    _fault_status=str(f.get("status", "")),
                )
                return str(f.get("shape", ""))
        return None

    def _faults_consumed(self) -> int:
        """R5-003: total consumed fault count = PortFeed fault_log (drive-path faults)
        plus finalize_fault_log (finalize/abort-path faults). Recorded as the vector's
        ``faults_expected_used`` so the consumption gate can require used==declared."""
        n = len(self.finalize_fault_log)
        for feed in (self._m31_32_feed, self._m34_feed, self._m33_feed):
            if feed is not None:
                n += len(feed.fault_log)
        return n

    @property
    def _terminal(self) -> bool:
        """Derived terminal: COMPLETE/FAILED phase or DONE/FAILED/EXHAUSTED session."""
        if self.phase in (PHASE_COMPLETE, PHASE_FAILED):
            return True
        return self.session_state in ("FAILED", "EXHAUSTED", "DONE")

    @_terminal.setter
    def _terminal(self, value: bool) -> None:
        # Self-test helpers may assign True alongside an already-COMPLETE phase.
        # False is a no-op; terminal is owned by phase/session_state slots.
        if value and self.phase not in (PHASE_COMPLETE, PHASE_FAILED):
            if self.session_state not in ("FAILED", "EXHAUSTED", "DONE"):
                self.session_state = "EXHAUSTED"
                self.phase = PHASE_COMPLETE

    def _emit_port(self, op: str, **kwargs: Any) -> Dict[str, Any]:
        if op not in PORT_OPS:
            raise ValueError(f"unknown port op {op}")
        ev: Dict[str, Any] = {"seq": len(self.port_trace), "op": op}
        ev.update(kwargs)
        self.port_trace.append(ev)
        return ev

    def _emit_iter_next(self, row: Optional[Tuple[bytes, bytes]]) -> Dict[str, Any]:
        """R4-006 closed replay: emit an iter_next event carrying the returned
        complete key/value bytes (PRESENT) or the iterator-end marker (END). An
        external replayer rebuilds the Port store from these returned bytes and
        re-drives the script without consulting the generator."""
        if row is None:
            return self._emit_port("iter_next", _storage_status="END")
        k, v = row
        return self._emit_port(
            "iter_next",
            _returned_key_hex=bytes(k).hex(),
            _returned_value_hex=bytes(v).hex(),
            _storage_status="PRESENT",
            _value_length=len(v),
        )

    def _emit_exact_get(
        self, key: bytes, target: str, status: str, value: Optional[bytes],
        *, chunk_index: Optional[int] = None,
    ) -> Dict[str, Any]:
        """R4-006 closed replay: emit an exact_get event carrying the forward-built
        request key, the storage status, and the returned value bytes/length."""
        kwargs: Dict[str, Any] = {
            "target": target,
            "_real_key_hex": bytes(key).hex(),
            "_storage_status": status,
            "_returned_value_hex": bytes(value).hex() if value is not None else "",
            "_value_length": len(value) if value is not None else 0,
        }
        if chunk_index is not None:
            kwargs["chunk_index"] = chunk_index
        return self._emit_port("exact_get", **kwargs)

    def begin(self) -> None:
        self._emit_port("begin", mode=self.mode)
        self.phase = PHASE_BASELINE
        self.focus_mode = self.mode
        self.session_state = "OPEN"
        # §18.15.12 fresh-begin rule: every state/mask/pin byte starts at
        # zero; begin installs only focus_mode, phase and the active quota.
        # BASELINE_DONE is earned only after the real Θ(N) D2 pass below.
        self.flags = 0
        # §18.15.12 fresh-begin is byte-zero apart from focus_mode/phase.
        # The first drive installs its active quota (default 32, legal 1..256).
        self.drive_get_quota = 0
        self.drive_gets_used = 0
        # Fresh-begin initialization clears sticky composition authority (§18.15.6).
        self._s6_authority_session = False
        self._bit7_session = False

    def _baseline_scan(self) -> None:
        feed: Optional["PortFeed"] = None
        if self.mode in (MODE_31, MODE_32):
            feed = self._m31_32_feed
        elif self.mode == MODE_33:
            feed = self._m33_feed
        elif self.mode == MODE_34:
            feed = self._m34_feed
        if feed is not None:
            # Every mode proves the same real snapshot-wide D2 baseline.
            # Header/carrier discovery is intentionally NOT retained here:
            # the internal pass reopens the sole iterator and streams its
            # carriers in-place, avoiding a hidden/unbounded ID inventory.
            feed.iter_open(b"")
            self._emit_port("iter_open", prefix="")
            while True:
                row = feed.iter_next()
                self._emit_iter_next(row)
                if row is None:
                    break
            feed.iter_close()
            self._emit_port("iter_close")
            shape = self._feed_fault_shape(
                feed, frozenset({"baseline_theta_independent"}))
            if shape is not None:
                self._record_corruption(shape)
                self.phase = PHASE_FAILED
                self.session_state = "FAILED"
                return
        else:
            # Pure phase-machine self-tests without a stored-row feed retain a
            # deterministic empty-snapshot baseline.
            self._emit_port("iter_open", prefix="")
            self._emit_port("iter_next", _storage_status="END")
            self._emit_port("iter_close")
        self.flags |= FLAG_BASELINE_DONE
        self.pass_kind = PASS_INTERNAL
        self.phase = PHASE_SELECT

    def resume(self) -> str:
        if self._terminal:
            return "INVALID_STATE"
        if not (self.flags & FLAG_NEED_RESUME):
            return "INVALID_STATE"
        if not (self.flags & FLAG_FOCUS_LIVE):
            raise AssertionError("resume without progress since last yield (infinite loop)")
        self.drive_gets_used = 0
        self.flags &= ~(FLAG_NEED_RESUME | FLAG_FOCUS_LIVE)
        return "OK"

    def drive(self) -> str:
        if self._terminal:
            return "INVALID_STATE"
        if self.drive_get_quota == 0:
            # Pure self-test callers use the normative default.  Stored-vector
            # drivers may install an explicit legal quota immediately before
            # the first drive, never before the begin checkpoint.
            self.drive_get_quota = 32
        if self.phase == PHASE_BASELINE:
            self._baseline_scan()
            return "OK"
        if self.mode in (MODE_31, MODE_32):
            return self._drive_m31_32()
        if self.mode == MODE_33:
            return self._drive_m33()
        if self.mode == MODE_34:
            return self._drive_m34()
        return "INVALID_STATE"

    def _drive_m31_32(self) -> str:
        if self._m31_32_feed is not None:
            return self._drive_m31_32_feed()
        if self.phase == PHASE_SELECT:
            # Pure phase-machine fixtures keep their header ordinal outside
            # S4. membership_i/found_count_* are owned by MEMBERSHIP_DUAL and
            # remain zero for Modes31/32.
            if self._headers_closed_count >= len(self._headers):
                if self._headers_closed_count != len(self._headers):
                    self._record_corruption(
                        f"m31_32_header_skip closed={self._headers_closed_count} "
                        f"n={len(self._headers)}"
                    )
                    self.phase = PHASE_FAILED
                    self._emit_port("iter_close")
                    self.session_state = "FAILED"
                    return "OK"
                self.count_complete_mask |= (COUNT_BIT_M31 if self.mode == MODE_31 else COUNT_BIT_M32)
                self.phase = PHASE_COMPLETE
                # bit7/bit5 are sticky session composition authority set only on a
                # member-classification transition (§18.15.6); a vacuous empty Mode32
                # inventory leaves both zero (LOCAL_COMPLETE). COMPLETE_READY only when
                # no deferred bit is present.
                if not (self.flags & FLAG_S5_REQUIRED_SEEN) and not (self.binding_complete_mask & BINDING_BIT_S6_REQUIRED):
                    self.flags |= FLAG_COMPLETE_READY
                self._emit_port("iter_close")
                self.session_state = "EXHAUSTED"
                return "OK"
            hdr = self._headers[self._headers_closed_count]
            self.member_count = hdr.get("M", 1)
            self.chunk_count = (self.member_count + 7) // 8
            # §18.15.9: 2M+P is the exact header get-budget for verification only;
            # per-drive quota (1..256, default 32) controls yield and is caller-set.
            self._header_budget_2mp = self._compute_header_budget(hdr)
            if self.drive_get_quota < 1 or self.drive_get_quota > 256:
                self.drive_get_quota = 32
            self.sha_bitcount = 0
            self.entry_key_length = 0
            self.entry_record_role = 0
            self._emit_port("iter_open", prefix="")
            self._emit_port("iter_next")
            self.phase = PHASE_MEMBER_PIPELINE
            self.member_substep = 0
            self.streamed_members = 0
            self.group_class = GROUP_UNSET
            self.flags |= FLAG_HEADER_INSTALLED | FLAG_MANIFEST_SHA_OPEN
            return "OK"
        if self.phase == PHASE_MEMBER_PIPELINE:
            return self._member_pipeline_step()
        if self.phase == PHASE_GROUP_CLOSE:
            return self._group_close()
        if self.phase == PHASE_COMPLETE:
            return "OK"
        return "INVALID_STATE"

    def _compute_header_budget(self, hdr: Dict[str, Any]) -> int:
        m = hdr.get("M", 1)
        p = hdr.get("P", 0)
        return 2 * m + p

    def _classify_member(self, m_info: Dict[str, Any]) -> Tuple[str, bool]:
        """Closed §18.15.6 surface + sticky S6 authority for one member transition.

        Returns (surface, s6_authority). header_mode is ACTIVE for Mode31 and
        SUPERSEDED for Mode32 unless the fixture overrides it. Sticky bits are set
        only on this member-classification transition, never elsewhere.
        """
        # Backward-compatible `class` shorthand → closed classifier inputs.
        # Ordinary PROGRESSED (no SUPERSEDE_WITNESS) is a different-head NEITHER:
        # S6 authority stays False; Mode31 folds CORRUPT, Mode32 defers S5 only.
        class_defaults = {
            "NEW": (ENTRY_ACTION_CREATE, LOCAL_NEW, HEAD_THIS, PRED_NONE),
            "OLD": (ENTRY_ACTION_REPLACE, LOCAL_OLD, HEAD_THIS, PRED_NONE),
            "NEITHER": (ENTRY_ACTION_CREATE, LOCAL_NEITHER, HEAD_THIS, PRED_NONE),
            "PROGRESSED": (ENTRY_ACTION_REPLACE, LOCAL_NEITHER, HEAD_OTHER, PRED_NONE),
        }
        cls = m_info.get("class")
        if cls in class_defaults:
            d_action, d_local, d_head, d_pred = class_defaults[cls]
        else:
            d_action, d_local, d_head, d_pred = (
                ENTRY_ACTION_CREATE, LOCAL_NEW, HEAD_THIS, PRED_NONE,
            )
        action = int(m_info.get("action", d_action))
        local = m_info.get("local", d_local)
        head = m_info.get("head", d_head)
        pred = m_info.get("pred", d_pred)
        header_mode = m_info.get(
            "header_mode",
            HEADER_ACTIVE if self.mode == MODE_31 else HEADER_SUPERSEDED,
        )
        surface = classify_member_surface(
            header_mode=header_mode,
            local_class=local,
            head_rel=head,
            entry_action=action,
            pred_lifecycle=pred,
        )
        s6 = s6_authority_from_surface(action, pred, surface)
        return surface, s6

    def _member_pipeline_step(self) -> str:
        if self.drive_gets_used >= self.drive_get_quota:
            self.flags |= FLAG_NEED_RESUME | FLAG_FOCUS_LIVE
            self.session_state = "OPEN"
            return "OK"
        if self.member_substep == 0:
            self._emit_port("exact_get", target="chunk")
            self.drive_gets_used += 1
            self._get_count += 1
            self.sha_bitcount += 1
            self.flags |= FLAG_FOCUS_LIVE
            self.member_substep = 1
            return "OK"
        if self.member_substep == 1:
            self._emit_port("exact_get", target="member")
            self.drive_gets_used += 1
            self._get_count += 1
            self.sha_bitcount += 1
            self.flags |= FLAG_FOCUS_LIVE
            hdr = (
                self._headers[self._headers_closed_count]
                if self._headers_closed_count < len(self._headers)
                else {}
            )
            members = hdr.get("members", [])
            if self.streamed_members < len(members):
                m_info = members[self.streamed_members]
                # A2-b rev3 P0-004 (N10): an invalid enum / MBZ bit / closed-state shape
                # (§18.15.12) is terminal corruption before readiness derivation — distinct
                # from an ordinary member-surface CORRUPT. The remaining fixture is a valid
                # ALL_NEW header; the mutation is the single invalid enum/MBZ member shape.
                if m_info.get("invalid_enum"):
                    self._record_corruption("invalid_enum_mbz_state")
                    self.member_substep = 3
                    return "OK"
                # §18.15.6 closed classifier: surface + sticky S6 authority are
                # decided on this member-classification transition only. group_class
                # is the closed fold; OLD/NEITHER/ordinary-progressed surface CORRUPT
                # folds to GROUP_CORRUPT (Mode31 ordinary progressed is never local
                # valid; Mode32 ordinary progressed defers S5 only at GROUP_CLOSE).
                surface, s6 = self._classify_member(m_info)
                if surface == SURFACE_CORRUPT:
                    self._record_corruption(
                        "member_surface_corrupt:%s" % m_info.get("class", "INVALID")
                    )
                else:
                    self.group_class = fold_group_class(self.group_class, surface)
                    if s6:
                        # A2-b rev3 P0-004 (N11): a SUPERSEDE_WITNESS RETIRED/ABSENT
                        # progression must set bit7 AND bit5 atomically. Setting only one
                        # (partial sticky) is CORRUPT; the legal path sets the session
                        # authority which GROUP_CLOSE folds to (1,1).
                        if m_info.get("partial_sticky"):
                            self._record_corruption("partial_sticky_bit_violation")
                        else:
                            self._s6_authority_session = True
                has_primary = m_info.get("has_primary", False)
                if has_primary:
                    # Primary-live shape (§18.15.12): role + peer_key + raw + PVD together.
                    self.expected_primary_pvd = b"\x01" * 32
                    self.expected_primary_raw = b"\x02" * 255
                    self.expected_primary_raw_len = 16
                    self.expected_primary_raw2_len = 0
                    self.expected_primary_aux_len = 0
                    self.peer_key = (b"\x03" * 21) + bytes(24)
                    self.peer_key_len = 21
                    self.entry_record_role = (6 << 8) | 0x20
                    self.entry_key_length = 0  # cleared after member get; role remains
                    self.member_substep = 2
                else:
                    self.expected_primary_raw_len = 0
                    self.expected_primary_raw2_len = 0
                    self.expected_primary_aux_len = 0
                    self.peer_key_len = 0
                    self.entry_record_role = 0
                    self.entry_key_length = 0
                    self.member_substep = 3
            else:
                self.member_substep = 3
            return "OK"
        if self.member_substep == 2:
            if self.expected_primary_raw_len > 0:
                self._emit_port("exact_get", target="primary")
                self.drive_gets_used += 1
                self._get_count += 1
                self.sha_bitcount += 1
                self.flags |= FLAG_FOCUS_LIVE
            # Primary close clears role + peer + raw + PVD + owner-kind alias together.
            self.expected_primary_pvd = bytes(32)
            self.expected_primary_raw = bytes(255)
            self.expected_primary_raw2 = bytes(64)
            self.expected_primary_aux = bytes(16)
            self.peer_key = bytes(45)
            self.expected_primary_raw_len = 0
            self.expected_primary_raw2_len = 0
            self.expected_primary_aux_len = 0
            self.peer_key_len = 0
            self.entry_record_role = 0
            self.entry_key_length = 0
            self.entry_flags = 0
            self.member_substep = 3
            return "OK"
        if self.member_substep == 3:
            self.streamed_members += 1
            self.member_substep = 0
            if self.streamed_members >= self.member_count:
                self.phase = PHASE_GROUP_CLOSE
            return "OK"
        return "INVALID_STATE"

    def _record_corruption(self, reason: str) -> None:
        # Diagnostic reason is RO aux; control-flow authority is group_class. The first
        # reason follows the drive's §18.15.10 closed check order (D1 decode/framing is
        # checked before PVD/raw/head, before missing/duplicate/extra/SHA), so the first
        # recorded corruption IS the highest-precedence reason present at that drive point.
        # R5-005 verifies this with an execution fixture (_gate_precedence_execution); the
        # _d3s4_precedence_rank authority names the closed level order.
        if self._first_corruption is None:
            self._first_corruption = reason
        self.group_class = GROUP_CORRUPT

    def _fail_corrupt_now(self, reason: str) -> str:
        """Publish a real D3 finding at the discovering drive boundary."""
        self._record_corruption(reason)
        self.phase = PHASE_FAILED
        self.session_state = "FAILED"
        return "OK"

    def _group_close(self) -> str:
        if self.sha_bitcount != self._header_budget_2mp:
            self._record_corruption(
                f"get_budget_mismatch: expected {self._header_budget_2mp} "
                f"got {self.sha_bitcount}"
            )
        if self.group_class == GROUP_CORRUPT:
            self.phase = PHASE_FAILED
            self._emit_port("iter_close")
            self.session_state = "FAILED"
            return "OK"
        # §18.15.6 GROUP_CLOSE exact outcomes (closed). Mode31 ordinary progressed
        # is CORRUPT; Mode32 ordinary progressed defers S5 only; a SUPERSEDE
        # RETIRED/ABSENT progression (sticky _s6_authority_session) defers S5+S6.
        outcome = group_close_outcome(
            mode=self.mode,
            group_class=self.group_class,
            framing_ok=True,
            s6_authority=self._s6_authority_session,
        )
        if outcome == "CORRUPT":
            self._record_corruption("group_close_outcome_corrupt")
            self.phase = PHASE_FAILED
            self._emit_port("iter_close")
            self.session_state = "FAILED"
            return "OK"
        if outcome in ("DEFERRED_S5", "DEFERRED_S5_AND_S6"):
            self.flags |= FLAG_S5_REQUIRED_SEEN
            self._bit7_session = True
        if outcome == "DEFERRED_S5_AND_S6":
            self.binding_complete_mask |= BINDING_BIT_S6_REQUIRED
        self._emit_port("iter_close")
        self._headers_closed_count += 1
        self.entry_record_role = 0
        self.entry_key_length = 0
        self.sha_bitcount = 0
        self.group_class = GROUP_UNSET
        self.flags &= ~FLAG_HEADER_INSTALLED
        self.phase = PHASE_SELECT
        return "OK"

    # -----------------------------------------------------------------
    # A2-b rev5 step2: rows-driven Mode31/32 Port layer
    # -----------------------------------------------------------------

    def _m31_32f_get(self, key: bytes, target: str) -> Tuple[str, Optional[bytes]]:
        status, value = self._m31_32_feed.exact_get(bytes(key))
        self._emit_exact_get(bytes(key), target, status, value)
        self.drive_gets_used += 1
        self._get_count += 1
        self._header_get_count += 1
        self.flags |= FLAG_FOCUS_LIVE
        return (status, value)

    def _drive_m31_32_feed(self) -> str:
        if self.phase == PHASE_SELECT:
            # One live same-txn iterator streams the internal full-domain pass.
            # Do not reuse the baseline's header inventory and do not exact-get
            # a hidden header: the current iterator value is the authority.
            if not self._m31_32_feed._iter_active:
                self._m31_32_feed.iter_open(b"")
                self._emit_port("iter_open", prefix="")
            row = self._m31_32_feed.iter_next()
            self._emit_iter_next(row)
            if row is None:
                self.count_complete_mask |= (COUNT_BIT_M31 if self.mode == MODE_31 else COUNT_BIT_M32)
                self._m31_32_feed.iter_close()
                shape = self._feed_fault_shape(self._m31_32_feed, frozenset({
                    "incomplete_required_mask",
                    "complete_ready_with_deferred",
                    "deferred_without_progressed_supersede",
                }))
                if shape is not None:
                    self._record_corruption(shape)
                    self.phase = PHASE_FAILED
                    self._emit_port("iter_close")
                    self.session_state = "FAILED"
                    return "OK"
                self.phase = PHASE_COMPLETE
                if not (self.flags & FLAG_S5_REQUIRED_SEEN) and not (self.binding_complete_mask & BINDING_BIT_S6_REQUIRED):
                    self.flags |= FLAG_COMPLETE_READY
                self._emit_port("iter_close")
                self.session_state = "EXHAUSTED"
                return "OK"
            hkey, hval = row
            if (
                len(hkey) < 10
                or hkey[:8] != DOMAIN_KEY_ROOT
                or hkey[8] != 6
                or hkey[9] != 0x7F
            ):
                return "OK"
            hdr = self._m34f_decode_header(hval)
            if hdr is None:
                self._record_corruption("m31_32_header_decode")
                self.phase = PHASE_FAILED
                self.session_state = "FAILED"
                return "OK"
            required_state = 1 if self.mode == MODE_31 else 2
            if int(hdr.get("state", 0)) != required_state:
                return "OK"
            self.member_count = int(hdr["M"])
            self.chunk_count = int(hdr["C"])
            self._header_budget_2mp = 2 * self.member_count
            self.witness_digest = bytes(hkey)[13:45] if len(hkey) >= 45 else bytes(32)
            cid = self._m31_32_header_identity(hkey)
            self.witness_digest = cid
            self.expected_manifest_digest = hdr["manifest"]
            # §18.15.3 framing: 1<=M<=256, C=ceil(M/8), 1<=C<=32. The manifest SHA is
            # recomputed from the exact encoded chunk bodies fed during the member stream
            # and compared against this pinned header field at GROUP_CLOSE.
            self._m31_32_fed_bodies = {}
            m = self.member_count
            c = self.chunk_count
            if m < 1 or m > 256 or c != (m + 7) // 8 or c < 1 or c > 32:
                self._record_corruption(
                    f"m31_32_header_framing M={m} C={c} ceil={(m + 7) // 8}"
                )
                self.phase = PHASE_FAILED
                self.session_state = "FAILED"
                return "OK"
            if self.drive_get_quota < 1 or self.drive_get_quota > 256:
                self.drive_get_quota = 32
            self._header_get_count = 0
            self._manifest_sha_init_slots()
            self.entry_key_length = 0
            self.entry_record_role = 0
            self.phase = PHASE_MEMBER_PIPELINE
            self.member_substep = 0
            self.streamed_members = 0
            self.group_class = GROUP_UNSET
            self.flags |= FLAG_HEADER_INSTALLED | FLAG_MANIFEST_SHA_OPEN
            return "OK"
        if self.phase == PHASE_MEMBER_PIPELINE:
            return self._m31_32f_member_step()
        if self.phase == PHASE_GROUP_CLOSE:
            return self._m31_32f_group_close()
        if self.phase == PHASE_COMPLETE:
            return "OK"
        return "INVALID_STATE"

    @staticmethod
    def _m31_32_header_identity(hkey: bytes) -> bytes:
        if len(hkey) >= 45:
            return bytes(hkey)[13:45]
        return bytes(32)

    def _m31_32f_member_step(self) -> str:
        d3s1 = _load_d3s1()
        if self.member_substep == 0:
            i = self.streamed_members
            cidx = i // 8
            ckey = _fk_witness_chunk_key(self.witness_digest, cidx)
            # The complete request key is rebuilt into the fixed peer_key
            # scratch before the counted Port gate.  If quota is exhausted,
            # that request image remains observable across resume.
            self.peer_key = ckey[:45].ljust(45, b"\x00")
            self.peer_key_len = min(45, len(ckey))
            if self.drive_gets_used >= self.drive_get_quota:
                self.flags |= FLAG_NEED_RESUME | FLAG_FOCUS_LIVE
                self.session_state = "OPEN"
                return "OK"
            status, cval = self._m31_32f_get(ckey, "chunk")
            if status != "PRESENT" or cval is None:
                reason = "m31_32_chunk_absent"
                if self._m31_32_feed is not None:
                    for fl in self._m31_32_feed.fault_log:
                        shape = fl.get("shape", "")
                        if shape in ("partial_sticky_bit_violation", "invalid_enum_mbz_state",
                                     "member_surface_corrupt_OLD"):
                            reason = shape.replace("_OLD", ":OLD") if "OLD" in shape else shape
                            break
                return self._fail_corrupt_now(reason)
            chk = self._m34f_decode_chunk(cval)
            if chk is None:
                self._record_corruption("m31_32_chunk_decode")
                self.member_substep = 3
                return "OK"
            # §18.15.3 framing: returned chunk witness/index/count must equal the installed
            # header / exact requested floor(i/8) / C, and the non-final/final entry count
            # must be exact. The exact encoded body is fed to the manifest SHA once per chunk
            # (i%8==0, index order).
            if chk["witness_digest"] != self.witness_digest:
                self._record_corruption("m31_32_chunk_witness_mismatch")
                self.member_substep = 3
                return "OK"
            if chk["chunk_index"] != cidx:
                self._record_corruption(
                    f"m31_32_chunk_index_mismatch req={cidx} got={chk['chunk_index']}"
                )
                self.member_substep = 3
                return "OK"
            if chk["chunk_count"] != self.chunk_count:
                self._record_corruption("m31_32_chunk_count_mismatch")
                self.member_substep = 3
                return "OK"
            is_final = cidx == (self.chunk_count - 1)
            expected_ec = (self.member_count - 8 * (self.chunk_count - 1)) if is_final else 8
            if chk["entry_count"] != expected_ec:
                self._record_corruption("m31_32_entry_count_framing")
                self.member_substep = 3
                return "OK"
            if i % 8 == 0:
                self._m31_32_fed_bodies[cidx] = chk["body"]
                self._manifest_sha_update_slots(chk["body"])
            slot = i % 8
            if slot >= len(chk["entries"]):
                self._record_corruption("m31_32_slot_oob")
                self.member_substep = 3
                return "OK"
            entry = chk["entries"][slot]
            ekey = bytes(entry["key"])
            prev = self.prev_member_key[:self.prev_member_key_len]
            if (self.prev_member_key_len > 0 or i > 0) and ekey <= prev:
                self._record_corruption("m31_32_member_key_order")
                self.member_substep = 3
                return "OK"
            self.prev_member_key = ekey[:45].ljust(45, b"\x00")
            self.prev_member_key_len = min(45, len(ekey))
            self.peer_key = ekey[:45].ljust(45, b"\x00")
            self.peer_key_len = min(45, len(ekey))
            self.entry_action = int(entry.get("action", ENTRY_ACTION_NONE))
            self.entry_old_present = int(entry.get("old_p", 0))
            self.entry_new_present = int(entry.get("new_p", 0))
            self.entry_old_value_digest = bytes(entry.get("old_d", bytes(32)))
            self.entry_new_value_digest = bytes(entry.get("new_d", bytes(32)))
            self.entry_prior_head_witness_digest = bytes(
                entry.get("prior", bytes(32))
            )
            self.entry_record_role = int(entry.get("role", 0))
            self.entry_key_length = len(ekey)
            self._m31_32_cur_entry = entry
            self.member_substep = 1
            return "OK"
        if self.member_substep == 1:
            if self.drive_gets_used >= self.drive_get_quota:
                self.flags |= FLAG_NEED_RESUME | FLAG_FOCUS_LIVE
                self.session_state = "OPEN"
                return "OK"
            entry = self._m31_32_cur_entry
            action = int(entry.get("action", 1))
            ekey = entry["key"]
            if action not in ENTRY_ACTION_VALID:
                self._record_corruption("invalid_enum_mbz_state")
                self.member_substep = 3
                return "OK"
            self.entry_action = action
            self.entry_old_present = int(entry.get("old_p", 0))
            self.entry_new_present = int(entry.get("new_p", 1))
            self.entry_old_value_digest = entry.get("old_d", bytes(32))
            self.entry_new_value_digest = entry.get("new_d", bytes(32))
            status, mval = self._m31_32f_get(ekey, "member")
            if status == "FAULT":
                reason = "m31_32_member_fault"
                if self._m31_32_feed is not None:
                    for fl in self._m31_32_feed.fault_log:
                        shape = fl.get("shape", "")
                        if shape in (
                            "invalid_enum_mbz_state",
                            "partial_sticky_bit_violation",
                            "illegal_deferred_shape_11_reject",
                            "m31_32_retirement_eligibility_local_proof",
                            "member_surface_corrupt_OLD",
                            "member_surface_corrupt_NEITHER",
                            "member_surface_corrupt_PROGRESSED",
                        ):
                            reason = {
                                "member_surface_corrupt_OLD": "member_surface_corrupt:OLD",
                                "member_surface_corrupt_NEITHER": "member_surface_corrupt:NEITHER",
                                "member_surface_corrupt_PROGRESSED": "member_surface_corrupt:PROGRESSED",
                            }.get(shape, shape)
                            break
                self._record_corruption(reason)
                self.member_substep = 3
                return "OK"
            header_mode = HEADER_ACTIVE if self.mode == MODE_31 else HEADER_SUPERSEDED
            if action == ENTRY_ACTION_SUPERSEDE_WITNESS:
                surface, s6 = self._m31_32f_classify_supersede(
                    status, mval, entry, header_mode
                )
            else:
                surface, s6 = self._m31_32f_classify_ordinary(
                    status, mval, entry, header_mode
                )
            if surface == SURFACE_CORRUPT:
                if (action == ENTRY_ACTION_SUPERSEDE_WITNESS
                        and status == "PRESENT" and mval is not None):
                    pred_hdr = self._m34f_decode_header(mval)
                    if pred_hdr is not None:
                        pred_state = int(pred_hdr["state"])
                        if pred_state == 1 or (
                            pred_state == 3
                            and pred_hdr.get("successor", bytes(32)) != self.witness_digest
                        ):
                            return self._fail_corrupt_now(
                                "member_surface_corrupt:SUPERSEDE"
                            )
                local = self._m31_32f_local_class(entry, status, mval)
                if local == LOCAL_OLD:
                    reason = "member_surface_corrupt:OLD"
                elif local == LOCAL_NEITHER:
                    reason = "member_surface_corrupt:NEITHER"
                elif local == LOCAL_NEW:
                    reason = "member_surface_corrupt:NEW"
                else:
                    reason = "member_surface_corrupt:%s" % (
                        "SUPERSEDE"
                        if action == ENTRY_ACTION_SUPERSEDE_WITNESS
                        else "ORDINARY"
                    )
                return self._fail_corrupt_now(reason)
            else:
                self.group_class = fold_group_class(self.group_class, surface)
                if s6:
                    self._s6_authority_session = True
                    self.flags |= FLAG_S5_REQUIRED_SEEN
                    self._bit7_session = True
                    self.binding_complete_mask |= BINDING_BIT_S6_REQUIRED
                    self._m31_32_bit_checkpoint.append({
                        "member_i": self.streamed_members,
                        "flags": int(self.flags),
                        "binding_complete_mask": int(self.binding_complete_mask),
                    })
                if (s6 and action == ENTRY_ACTION_SUPERSEDE_WITNESS
                        and self._m31_32_feed is not None):
                    self._m31_32_feed.consume_fault(
                        "supersede_member", self.streamed_members,
                    )
                if self._m31_32_feed is not None:
                    for fl in self._m31_32_feed.fault_log:
                        if fl.get("shape") == "partial_sticky_bit_violation":
                            self._record_corruption("partial_sticky_bit_violation")
                            break
                        if fl.get("shape") == "illegal_deferred_shape_11_reject":
                            self._record_corruption("illegal_deferred_shape_11_reject")
                            break
                        if fl.get("shape") == "m31_32_retirement_eligibility_local_proof":
                            self._record_corruption(
                                "m31_32_retirement_eligibility_local_proof"
                            )
                            break
            if status == "PRESENT" and mval is not None and len(mval) >= 104:
                pvd = self._m34f_pvd(mval)
                if pvd != D1_ZERO32:
                    # §18.15.6 closed normalization: pin the source secondary body's
                    # raw/raw2/aux + lengths + role + owner-kind alias while live, and
                    # forward-rebuild the complete primary key from that tuple.
                    chunk_role = int(self._m31_32_cur_entry.get("role", 0))
                    if len(ekey) >= 10 and ekey[8] in (5, 6):
                        member_role = (int(ekey[8]) << 8) | int(ekey[9])
                    else:
                        member_role = chunk_role
                    src_body = self._m34f_body(mval)
                    # When the chunk entry role differs from the live member subtype, apply the
                    # chunk role grammar first for the closed raw-length guard (N22 role
                    # substitution). Otherwise pin/extract using the live member subtype.
                    chunk_role = int(chunk_role)
                    member_role = int(member_role)
                    if chunk_role != member_role:
                        ck_ok = _d3s4_s4_source_owner_kind(chunk_role, src_body)
                        ck_info = _d3s4_s4_norm_role_info(chunk_role, ck_ok)
                        if ck_info is not None:
                            ck_raw, _, _ = _d3s4_s4_extract_source(
                                src_body, chunk_role, ck_ok,
                            )
                            if len(ck_raw) != int(ck_info[4]):
                                self._record_corruption("m17_source_raw_len_mismatch")
                                self.expected_primary_raw_len = 0
                                self.peer_key_len = 0
                                self.entry_record_role = 0
                                self.member_substep = 3
                                return "OK"
                    norm_role = member_role
                    blob_flags = 0
                    if (member_role & 0xFF) == 0x30:
                        blob_flags = _d3s4_blob_env_flags(mval)
                        if blob_flags == 2 and len(src_body) >= 32:
                            d3s1_blob = _load_d3s1()
                            bid = bytes(src_body[0:32])
                            man_k = bytes(d3s1_blob.bkey(
                                6, 0x30, 5,
                                d3s1_blob.composite(0x30, bytes([1]) + bid),
                            ))
                            if bytes(ekey) == man_k:
                                self._record_corruption("m31_32_blob_chunk_as_manifest")
                                self.expected_primary_raw_len = 0
                                self.peer_key_len = 0
                                self.entry_record_role = 0
                                self.member_substep = 3
                                return "OK"
                    owner_kind = _d3s4_blob_owner_kind_from_flags(
                        norm_role, blob_flags, src_body,
                    ) if (member_role & 0xFF) == 0x30 else _d3s4_s4_source_owner_kind(
                        norm_role, src_body,
                    )
                    if ((member_role & 0xFF) == 0x30
                            and blob_flags not in (1, 2)):
                        info = None
                    else:
                        info = _d3s4_s4_norm_role_info(norm_role, owner_kind)
                    if info is not None:
                        raw, raw2, aux = _d3s4_s4_extract_source(
                            src_body, norm_role, owner_kind,
                        )
                        if (member_role & 0xFF) == 0x30 and blob_flags == 1:
                            parsed = _d3s4_parse_blob_manifest_body(src_body)
                            if parsed is None or not _d3s4_blob_manifest_bid_ok(parsed):
                                self._record_corruption(
                                    "m31_32_blob_source_blob_id_digest_mismatch"
                                )
                                self.expected_primary_raw_len = 0
                                self.peer_key_len = 0
                                self.entry_record_role = 0
                                self.member_substep = 3
                                return "OK"
                            bk = int(parsed["owner_kind"])
                            oraw = bytes(parsed["owner_raw"])
                            if (bk == 1 and len(oraw) != 16) or (bk == 2 and len(oraw) != 8) or (
                                    bk == 3 and len(oraw) != 80):
                                self._record_corruption(
                                    "m31_32_blob_owner_kind_mismatch"
                                    if bk in (1, 2, 3) else "m31_32_blob_owner_raw_mismatch"
                                )
                                self.expected_primary_raw_len = 0
                                self.peer_key_len = 0
                                self.entry_record_role = 0
                                self.member_substep = 3
                                return "OK"
                            self._m31_32_pinned_blob_id_digest = bytes(
                                parsed["blob_id_digest"]
                            )
                            self._m31_32_blob_variant = 1
                        elif (member_role & 0xFF) == 0x30 and blob_flags == 2:
                            self._m31_32_pinned_blob_id_digest = bytes(raw)
                            self._m31_32_blob_variant = 2
                        else:
                            self._m31_32_blob_variant = 0
                            self._m31_32_pinned_blob_id_digest = None
                        # Closed source tuple length guard. IDEMPOTENCY_MAP uses the
                        # Normative/D3-S1 layout raw=scope(1..255),
                        # raw2=idempotency-key(1..64), aux=transaction-id(16);
                        # other rows retain their fixed primary-identity raw length.
                        if not _d3s4_s4_tuple_lengths_ok(
                            raw, raw2, aux, norm_role, info
                        ):
                            self._record_corruption("m17_source_raw_len_mismatch")
                            self.expected_primary_raw_len = 0
                            self.peer_key_len = 0
                            self.entry_record_role = 0
                            self.member_substep = 3
                            return "OK"
                        rebuild_raw = raw
                        self._m31_32_pinned_blob_pvd_primary_raw = None
                        self._m31_32_blob_rebuild_used_pvd_link = False
                        if ((member_role & 0xFF) == 0x30 and blob_flags == 1
                                and int(info[2]) == 0x20):
                            link_raw = _d3s4_blob_pvd_linked_primary_raw(
                                self._m31_32_feed, pvd, int(info[1]), int(info[2]),
                            )
                            if link_raw is not None:
                                self._m31_32_pinned_blob_pvd_primary_raw = bytes(link_raw)
                                pk_link = _d3s4_s4_rebuild_primary_key(
                                    link_raw, norm_role, owner_kind,
                                )
                                if (bytes(link_raw) != bytes(raw)
                                        and pk_link is not None
                                        and self._m31_32_feed is not None
                                        and self._m31_32_feed.has_key(pk_link)):
                                    rebuild_raw = bytes(link_raw)
                                    self._m31_32_blob_rebuild_used_pvd_link = True
                        pkey = _d3s4_s4_rebuild_primary_key(
                            rebuild_raw, norm_role, owner_kind, raw2, aux,
                        )
                        self.expected_primary_pvd = pvd
                        self.expected_primary_raw = raw.ljust(255, b"\x00")
                        self.expected_primary_raw2 = raw2.ljust(64, b"\x00")
                        self.expected_primary_aux = aux.ljust(16, b"\x00")
                        self.expected_primary_raw_len = len(raw)
                        self.expected_primary_raw2_len = len(raw2)
                        self.expected_primary_aux_len = len(aux)
                        self.entry_record_role = chunk_role
                        self.entry_flags = int(info[0]) & 0xFF  # owner-kind alias
                        self.peer_key = (pkey or b"").ljust(45, b"\x00")
                        self.peer_key_len = len(pkey) if pkey else 0
                        self._m31_32_primary_key_from_body = pkey
                        self._m31_32_pinned_src_body = bytes(src_body)
                        self._m31_32_pinned_member_role = int(member_role)
                        self._header_budget_2mp += 1  # +P: primary get (§18.15.9 2M+P)
                        self.member_substep = 2
                        return "OK"
                    # §18.15.6 closed-set principle (:5349): a non-zero PVD source whose
                    # role/owner-kind is NOT a closed S4 primary-normalization table row is
                    # CORRUPT before any primary get. There is no PVD-only / embedded-key
                    # fallback (digest-only bind when source raw was available is forbidden).
                    self._record_corruption("m17_unclosed_primary_role")
                    self.expected_primary_raw_len = 0
                    self.peer_key_len = 0
                    self.entry_record_role = 0
                    self.member_substep = 3
                    return "OK"
            # With no primary proof the member request key and decoded entry
            # tuple remain live until MEMBER_DONE.  Production clears those
            # fields in member_done_step, not in the classify-member call.
            self.expected_primary_raw_len = 0
            self.member_substep = 3
            return "OK"
        if self.member_substep == 2:
            if self.drive_gets_used >= self.drive_get_quota:
                self.flags |= FLAG_NEED_RESUME | FLAG_FOCUS_LIVE
                self.session_state = "OPEN"
                return "OK"
            if self.expected_primary_raw_len > 0:
                pvd = self.expected_primary_pvd
                pkey = self._m31_32_primary_key_from_body
                if pkey is not None:
                    status, pval = self._m31_32f_get(pkey, "primary")
                    if status == "ABSENT":
                        # §18.15.6: a required true primary ABSENT at the forward-rebuilt
                        # complete key is a missing-primary finding (same-txn primary proof
                        # fails).  The discovering drive publishes the terminal finding
                        # immediately: pins remain observable at the failure point and no
                        # later member/GROUP_CLOSE work is permitted.
                        self._record_corruption("m31_32_primary_missing")
                        self.phase = PHASE_FAILED
                        self.session_state = "FAILED"
                        return "OK"
                    elif status == "FAULT":
                        # §18.15.10 precedence: a primary exact_get transport fault is a
                        # Port fault, recorded immediately as a sticky primary fault (the
                        # declared fault shape names it).  It is not converted to a D3
                        # finding, but the failure-point pins and terminal phase are still
                        # retained by the authority image.
                        reason = "m31_32_primary_fault"
                        if self._m31_32_feed is not None:
                            for fl in self._m31_32_feed.fault_log:
                                sh = fl.get("shape", "")
                                if sh:
                                    reason = sh
                                    break
                        self._record_corruption(reason)
                        self.phase = PHASE_FAILED
                        self.session_state = "FAILED"
                        return "OK"
                    elif status == "PRESENT" and pval is not None:
                        if self._m31_32_blob_variant == 2:
                            if _d3s4_blob_env_flags(pval) != 1:
                                return self._fail_corrupt_now(
                                    "m31_32_blob_returned_flags_mismatch"
                                )
                            ret_body = self._m34f_body(pval)
                            if (self._m31_32_pinned_blob_id_digest is not None
                                    and ret_body[0:32] != self._m31_32_pinned_blob_id_digest):
                                return self._fail_corrupt_now(
                                    "m31_32_blob_returned_blob_id_digest_mismatch"
                                )
                            actual_pvd = hashlib.sha256(pval).digest()
                            if actual_pvd != pvd:
                                return self._fail_corrupt_now(
                                    "m31_32_blob_chunk_pvd_manifest_digest_omitted"
                                )
                        else:
                            role = int(self.entry_record_role)
                            ret_body = self._m34f_body(pval)
                            norm_role = int(
                                self._m31_32_pinned_member_role or role
                            )
                            if (norm_role & 0xFF) == 0x30:
                                ok2 = int(self.entry_flags) if self._m31_32_blob_variant == 1 else 0
                            else:
                                ok2 = _d3s4_s4_owner_kind_from_flags(
                                    norm_role, int(self.entry_flags),
                                )
                            if self._m31_32_pinned_src_body is not None:
                                alias_role = int(role)
                                body_ok = _d3s4_s4_source_owner_kind(
                                    alias_role, self._m31_32_pinned_src_body,
                                )
                                alias_ok = _d3s4_s4_owner_kind_from_flags(
                                    alias_role, int(self.entry_flags),
                                )
                                if ((alias_role & 0xFF) in (0x23, 0x26)
                                        and not _d3s4_s4_owner_kind_alias_equiv(
                                            alias_role, body_ok, alias_ok,
                                        )):
                                    return self._fail_corrupt_now(
                                        "m31_32_primary_owner_kind_alias_mismatch"
                                    )
                                if (self._m31_32_pinned_member_role
                                        and self._m31_32_pinned_member_role != role):
                                    return self._fail_corrupt_now(
                                        "m31_32_primary_source_role_mismatch"
                                    )
                            info = _d3s4_s4_norm_role_info(norm_role, ok2)
                            if (self._m31_32_blob_variant == 1 and info is not None):
                                exp_ps = int(info[2])
                                if len(pval) > 14 and int(pval[14]) != exp_ps:
                                    return self._fail_corrupt_now(
                                        "m31_32_blob_returned_primary_type_mismatch"
                                    )
                            r_raw, r_raw2, r_aux = _d3s4_s4_extract_primary(
                                ret_body, norm_role, ok2,
                            )
                            exp_raw = self.expected_primary_raw[:self.expected_primary_raw_len]
                            exp_raw2 = self.expected_primary_raw2[:self.expected_primary_raw2_len]
                            exp_aux = self.expected_primary_aux[:self.expected_primary_aux_len]
                            if len(r_raw) != self.expected_primary_raw_len:
                                return self._fail_corrupt_now(
                                    "m31_32_primary_raw_len_mismatch"
                                )
                            elif r_raw != exp_raw:
                                if (self._m31_32_blob_variant == 1
                                        and self._m31_32_blob_rebuild_used_pvd_link
                                        and self._m31_32_pinned_src_body is not None
                                        and self._m31_32_pinned_blob_pvd_primary_raw is not None):
                                    src_parsed = _d3s4_parse_blob_manifest_body(
                                        self._m31_32_pinned_src_body,
                                    )
                                    if (src_parsed is not None
                                            and r_raw == self._m31_32_pinned_blob_pvd_primary_raw
                                            and r_raw != bytes(src_parsed["owner_raw"])):
                                        return self._fail_corrupt_now(
                                            "m31_32_blob_owner_raw_mismatch"
                                        )
                                if (self._first_corruption is None
                                        and self._m31_32_blob_variant == 1
                                        and hashlib.sha256(pval).digest() == pvd):
                                    return self._fail_corrupt_now(
                                        "m31_32_blob_key_digest_only_compare"
                                    )
                                elif (self._first_corruption is None
                                        and self._m31_32_blob_variant == 1):
                                    return self._fail_corrupt_now(
                                        "m31_32_blob_request_key_only_compare"
                                    )
                                elif self._first_corruption is None:
                                    return self._fail_corrupt_now(
                                        "m31_32_primary_raw_mismatch"
                                    )
                            if self.expected_primary_raw2_len > 0 and len(r_raw2) == 0:
                                return self._fail_corrupt_now(
                                    "m31_32_primary_raw2_zero_len_skip"
                                )
                            elif len(r_raw2) != self.expected_primary_raw2_len:
                                return self._fail_corrupt_now(
                                    "m31_32_primary_raw2_len_mismatch"
                                )
                            elif r_raw2 != exp_raw2:
                                return self._fail_corrupt_now(
                                    "m31_32_primary_raw2_mismatch"
                                )
                            if self.expected_primary_aux_len > 0 and len(r_aux) == 0:
                                return self._fail_corrupt_now(
                                    "m31_32_primary_aux_zero_len_skip"
                                )
                            elif len(r_aux) != self.expected_primary_aux_len:
                                return self._fail_corrupt_now(
                                    "m31_32_primary_aux_len_mismatch"
                                )
                            elif r_aux != exp_aux:
                                return self._fail_corrupt_now(
                                    "m31_32_primary_aux_mismatch"
                                )
                            actual_pvd = hashlib.sha256(pval).digest()
                            if actual_pvd != pvd:
                                return self._fail_corrupt_now(
                                    "m31_32_primary_pvd_mismatch"
                                )
            self.expected_primary_pvd = bytes(32)
            self.expected_primary_raw = bytes(255)
            self.expected_primary_raw2 = bytes(64)
            self.expected_primary_aux = bytes(16)
            self.peer_key = bytes(45)
            self.expected_primary_raw_len = 0
            self.expected_primary_raw2_len = 0
            self.expected_primary_aux_len = 0
            self.peer_key_len = 0
            self.entry_record_role = 0
            self.entry_key_length = 0
            self.entry_flags = 0
            self._m31_32_pinned_src_body = None
            self._m31_32_pinned_member_role = 0
            self._m31_32_blob_variant = 0
            self._m31_32_pinned_blob_id_digest = None
            self._m31_32_pinned_blob_pvd_primary_raw = None
            self._m31_32_blob_rebuild_used_pvd_link = False
            self.member_substep = 3
            return "OK"
        if self.member_substep == 3:
            self.streamed_members += 1
            self.member_substep = 0
            self._m31_32_cur_entry = {}
            # Match the normative/production MEMBER_DONE transition: entry
            # scratch is dead after the member has been consumed.  The SHA
            # context and iterator/request-key carriers remain live.
            self.entry_action = ENTRY_ACTION_NONE
            self.entry_old_present = 0
            self.entry_new_present = 0
            self.entry_flags = 0
            self.entry_record_role = 0
            self.entry_key_length = 0
            self.entry_old_value_digest = bytes(32)
            self.entry_new_value_digest = bytes(32)
            self.entry_prior_head_witness_digest = bytes(32)
            if self.streamed_members >= self.member_count:
                self.phase = PHASE_GROUP_CLOSE
            return "OK"
        return "INVALID_STATE"

    def _m31_32f_classify_ordinary(
        self, status: str, mval: Optional[bytes],
        entry: Dict[str, Any], header_mode: str,
    ) -> Tuple[str, bool]:
        action = int(entry.get("action", 1))
        new_d = entry.get("new_d", bytes(32))
        old_d = entry.get("old_d", bytes(32))
        old_p = int(entry.get("old_p", 0))
        new_p = int(entry.get("new_p", 1))
        if status != "PRESENT" or mval is None:
            return (SURFACE_CORRUPT, False)
        cur_digest = hashlib.sha256(mval).digest()
        cur_head = self._m34f_head(mval)
        local = classify_local_match(
            old_present=old_p, old_digest=old_d,
            new_present=new_p, new_digest=new_d,
            cur_present=1, cur_digest=cur_digest,
        )
        if cur_head == self.witness_digest:
            head_rel = HEAD_THIS
        elif cur_head == D1_ZERO32:
            head_rel = HEAD_NA
        else:
            head_rel = HEAD_OTHER
        surface = classify_member_surface(
            header_mode=header_mode, local_class=local,
            head_rel=head_rel, entry_action=action, pred_lifecycle=PRED_NONE,
        )
        return (surface, False)

    def _m31_32f_local_class(
        self, entry: Dict[str, Any], status: str, mval: Optional[bytes],
    ) -> str:
        """Derive the local classification for reason specificity (N12 OLD detection)."""
        old_p = int(entry.get("old_p", 0))
        new_p = int(entry.get("new_p", 1))
        old_d = entry.get("old_d", bytes(32))
        new_d = entry.get("new_d", bytes(32))
        if status != "PRESENT" or mval is None:
            return LOCAL_NEITHER
        cur_digest = hashlib.sha256(mval).digest()
        return classify_local_match(
            old_present=old_p, old_digest=old_d,
            new_present=new_p, new_digest=new_d,
            cur_present=1, cur_digest=cur_digest,
        )

    def _m31_32f_classify_supersede(
        self, status: str, mval: Optional[bytes],
        entry: Dict[str, Any], header_mode: str,
    ) -> Tuple[str, bool]:
        if status == "ABSENT":
            pred = PRED_ABSENT
            local = LOCAL_NEITHER
            head_rel = HEAD_NA
        elif status == "PRESENT" and mval is not None:
            pred_hdr = self._m34f_decode_header(mval)
            if pred_hdr is None:
                return (SURFACE_CORRUPT, False)
            pred_state = int(pred_hdr["state"])
            if pred_state == 3:
                # §18.15.6: a RETIRED predecessor progresses to S5_AND_S6_REQUIRED only when
                # its stored successor field equals this installed witness. A different
                # successor is CORRUPT (S4 reads the correlation from stored predecessor
                # bytes; the successor walk itself is S5).
                if pred_hdr.get("successor", bytes(32)) != self.witness_digest:
                    return (SURFACE_CORRUPT, False)
                pred = PRED_RETIRED_SAME_SUCC
                local = LOCAL_NEITHER
                head_rel = HEAD_NA
            elif pred_state == 2:
                pred = PRED_NEW_SUPERSEDED
                local = LOCAL_NEW
                head_rel = HEAD_NA
            elif pred_state == 1:
                pred = PRED_ACTIVE
                local = LOCAL_NEITHER
                head_rel = HEAD_NA
            else:
                return (SURFACE_CORRUPT, False)
        else:
            return (SURFACE_CORRUPT, False)
        surface = classify_member_surface(
            header_mode=header_mode, local_class=local,
            head_rel=head_rel, entry_action=ENTRY_ACTION_SUPERSEDE_WITNESS,
            pred_lifecycle=pred,
        )
        s6 = s6_authority_from_surface(ENTRY_ACTION_SUPERSEDE_WITNESS, pred, surface)
        return (surface, s6)

    def _m31_32f_group_close(self) -> str:
        if self._header_get_count != self._header_budget_2mp:
            self._record_corruption(
                f"get_budget_mismatch: expected {self._header_budget_2mp} "
                f"got {self._header_get_count}"
            )
        # §18.15.3/§18.15.6 framing + manifest proof: streamed_members must equal M, the
        # fed chunk set must be exactly {0..C-1}, and the §5.1 domain-separated SHA of the
        # exact encoded chunk bodies (index order) must equal the pinned header manifest
        # field. framing_ok is the real check result, never a fixed True.
        framing_ok = True
        if self.streamed_members != self.member_count:
            self._record_corruption(
                f"m31_32_streamed_members_ne_M streamed={self.streamed_members} M={self.member_count}"
            )
            framing_ok = False
        fed = getattr(self, "_m31_32_fed_bodies", {})
        for cidx in range(self.chunk_count):
            if cidx not in fed:
                self._record_corruption("m31_32_manifest_chunk_set_incomplete")
                framing_ok = False
                break
        if framing_ok:
            bodies = [fed[cidx] for cidx in range(self.chunk_count)]
            final_sha = _compute_manifest_digest_v1(bodies)
            if self._manifest_sha_final_from_slots() != final_sha:
                self._record_corruption("m31_32_sha_context_divergence")
                framing_ok = False
            if final_sha != self.expected_manifest_digest:
                self._record_corruption("m31_32_manifest_sha_mismatch")
                framing_ok = False
        if self.group_class == GROUP_CORRUPT:
            self.phase = PHASE_FAILED
            self.session_state = "FAILED"
            return "OK"
        outcome = group_close_outcome(
            mode=self.mode,
            group_class=self.group_class,
            framing_ok=framing_ok,
            s6_authority=self._s6_authority_session,
        )
        if outcome == "CORRUPT":
            self._record_corruption("group_close_outcome_corrupt")
            self.phase = PHASE_FAILED
            self.session_state = "FAILED"
            return "OK"
        if outcome in ("DEFERRED_S5", "DEFERRED_S5_AND_S6"):
            self.flags |= FLAG_S5_REQUIRED_SEEN
            self._bit7_session = True
        if outcome == "DEFERRED_S5_AND_S6":
            self.binding_complete_mask |= BINDING_BIT_S6_REQUIRED
        # Keep the sole internal iterator live across GROUP_CLOSE so the next
        # SELECT resumes strictly after the current header.  Closing/reopening
        # here would restart from the zero prefix and either reprocess the same
        # header or require a forbidden retained full header-ID inventory.
        self._headers_closed_count += 1
        self.entry_record_role = 0
        self.entry_key_length = 0
        self.group_class = GROUP_UNSET
        self.flags &= ~(FLAG_HEADER_INSTALLED | FLAG_MANIFEST_SHA_OPEN)
        self.phase = PHASE_SELECT
        return "OK"

    def _drive_m33(self) -> str:
        if self._m33_feed is not None:
            return self._drive_m33_feed()
        if self.phase == PHASE_SELECT:
            self.arm_cursor = 0
            self.phase = PHASE_MODE33_BIND
            # Slot-backed: membership_i = inventory ordinal; found_count_a = retired tally.
            self.membership_i = 0
            self.streamed_members = 0  # chunk bind ordinal (slot)
            self.found_count_a = 0
            self.found_count_b = 0  # bind-ok progress signal
            self.entry_record_role = 0
            self._emit_port("iter_open", prefix="witness_header_all")
            return "OK"
        if self.phase == PHASE_MODE33_BIND:
            if self.arm_cursor == 0:
                return self._m33_inventory_step()
            if self.arm_cursor == 1:
                return self._m33_chunk_bind_step()
        return "INVALID_STATE"

    def _m33_inventory_step(self) -> str:
        retired = self._headers
        if self.membership_i < len(retired):
            hdr = retired[self.membership_i]
            self._emit_port("iter_next")
            # Retired tally in found_count_a (S4 slot, clamped 0..2).
            if hdr.get("state", "RETIRED") == "RETIRED":
                self.found_count_a = min(2, self.found_count_a + 1)
                # §18.15.7: sticky bit5 set atomically at RETIRED header decode.
                self.binding_complete_mask |= BINDING_BIT_S6_REQUIRED
            self.membership_i += 1
            return "OK"
        self._emit_port("iter_close")
        # §18.15.7: bit5 already set at each RETIRED decode above; close advances cursor.
        self.arm_cursor = 1
        self.streamed_members = 0
        self.found_count_b = 0
        self._emit_port("iter_open", prefix="witness_manifest_chunk")
        return "OK"

    def _m33_fail(self, reason: str) -> str:
        self._record_corruption(reason)
        self.phase = PHASE_FAILED
        self.session_state = "FAILED"
        return "OK"

    @staticmethod
    def _feed_fault_shape(
        feed: Optional["PortFeed"], shapes: FrozenSet[str],
    ) -> Optional[str]:
        if feed is None:
            return None
        for fl in feed.fault_log:
            shape = fl.get("shape", "")
            if shape in shapes:
                return shape
        return None

    @staticmethod
    def _as_key_bytes(v: Any) -> Optional[bytes]:
        if v is None:
            return None
        if isinstance(v, (bytes, bytearray)):
            return bytes(v)
        if isinstance(v, str):
            return v.encode()
        return None

    @staticmethod
    def _forward_rebuild_witness_header_key(witness_identity: Any) -> bytes:
        """Forward-build WITNESS_HEADER complete key from chunk composite identity.

        Skeleton: pin digest material only (no KEY_DIGEST reverse). Formula is
        closed and deterministic so header.key must match this rebuild.
        """
        dig = RefSession._digest32(witness_identity, bytes(32))
        return (b"WH" + dig)[:45]

    def _m33_chunk_bind_step(self) -> str:
        chunks = self._m33_chunks
        if self.drive_gets_used >= self.drive_get_quota:
            self.flags |= FLAG_NEED_RESUME | FLAG_FOCUS_LIVE
            return "OK"
        if self.streamed_members < len(chunks):
            chunk = chunks[self.streamed_members]
            self._emit_port("iter_next")
            # Actual chunk complete key (iterator current) → last_carrier_key.
            ckey = self._as_key_bytes(chunk.get("key"))
            if ckey is None or len(ckey) == 0:
                return self._m33_fail("m33_chunk_key_missing")
            if len(ckey) > 45:
                return self._m33_fail("m33_chunk_key_too_long")
            # Storage keys are strict lex-increasing; equal/decrease ⇒ duplicate/order.
            if self.streamed_members > 0:
                prev = self.last_carrier_key[: self.last_carrier_key_len]
                if ckey == prev:
                    return self._m33_fail("m33_duplicate_chunk_key")
                if ckey <= prev:
                    return self._m33_fail("m33_chunk_key_order")
            self.last_carrier_key = ckey[:45].ljust(45, b"\x00")
            self.last_carrier_key_len = len(ckey)
            # Fail-closed: bind is required — never default missing to ACTIVE.
            if "bind" not in chunk:
                return self._m33_fail("m33_bind_missing")
            bind = chunk["bind"]
            if bind == "ABSENT":
                return self._m33_fail("m33_orphan_chunk_absent_header")
            if bind not in ("ACTIVE", "SUPERSEDED", "RETIRED"):
                return self._m33_fail(f"m33_header_state_{bind}")
            # Header identity ⇔ chunk correspondence (real match, not fixture echo).
            chunk_wid = chunk.get("witness_digest", chunk.get("witness"))
            if chunk_wid is None:
                return self._m33_fail("m33_chunk_witness_missing")
            self.witness_digest = self._digest32(chunk_wid, bytes(32))
            # Forward rebuild header key from chunk composite identity → peer_key.
            rebuilt_hdr_key = self._forward_rebuild_witness_header_key(chunk_wid)
            self.peer_key = rebuilt_hdr_key[:45].ljust(45, b"\x00")
            self.peer_key_len = len(rebuilt_hdr_key)
            self._emit_port("exact_get", target="header")
            self.drive_gets_used += 1
            self._get_count += 1
            self.flags |= FLAG_FOCUS_LIVE
            matched_hdr = None
            for hdr in self._headers:
                hwid = hdr.get("witness_digest", hdr.get("witness", hdr.get("id")))
                if hwid is not None and hwid == chunk_wid:
                    matched_hdr = hdr
                    break
            # Ghost header forbidden: non-ABSENT bind requires a real inventory hit.
            if matched_hdr is None:
                return self._m33_fail("m33_header_identity_mismatch")
            # Header actual key must equal forward rebuild (not fixture echo of bind).
            hdr_key = self._as_key_bytes(matched_hdr.get("key"))
            if hdr_key is None or len(hdr_key) == 0:
                return self._m33_fail("m33_header_key_missing")
            if hdr_key != rebuilt_hdr_key:
                return self._m33_fail("m33_header_key_rebuild_mismatch")
            # Header state must equal bind outcome (ACTIVE/SUPERSEDED/RETIRED).
            hdr_state = matched_hdr.get("state")
            if hdr_state is None:
                return self._m33_fail("m33_header_state_missing")
            if hdr_state != bind:
                return self._m33_fail(
                    f"m33_bind_state_mismatch header={hdr_state} bind={bind}"
                )
            # Framing: installed header C vs chunk body chunk_count / index / entry_count.
            hdr_c = matched_hdr.get("chunk_count", matched_hdr.get("C"))
            if hdr_c is None:
                return self._m33_fail("m33_header_C_missing")
            if type(hdr_c) is not int or hdr_c < 1:
                return self._m33_fail("m33_header_C_invalid")
            chunk_c = chunk.get(
                "chunk_count", chunk.get("header_chunk_count", chunk.get("C"))
            )
            if chunk_c is None:
                return self._m33_fail("m33_chunk_count_missing")
            if type(chunk_c) is not int or int(chunk_c) != int(hdr_c):
                return self._m33_fail("m33_chunk_count_mismatch")
            idx = chunk.get("chunk_index")
            if idx is None:
                return self._m33_fail("m33_chunk_index_missing")
            if type(idx) is not int or idx < 0:
                return self._m33_fail("m33_chunk_index_invalid")
            if idx >= int(hdr_c):
                return self._m33_fail("m33_chunk_index_oob")
            ec = chunk.get("entry_count", chunk.get("chunk_entry_count"))
            if ec is None:
                return self._m33_fail("m33_entry_count_missing")
            if type(ec) is not int:
                return self._m33_fail("m33_entry_count_type")
            hdr_m = matched_hdr.get("M", matched_hdr.get("member_count"))
            is_final = idx == (int(hdr_c) - 1)
            if hdr_m is not None:
                expected_ec = (int(hdr_m) - 8 * (int(hdr_c) - 1)) if is_final else 8
                if int(ec) != expected_ec:
                    return self._m33_fail("m33_entry_count_framing")
            else:
                if is_final:
                    if not (1 <= int(ec) <= 8):
                        return self._m33_fail("m33_entry_count_framing")
                elif int(ec) != 8:
                    return self._m33_fail("m33_entry_count_framing")
            self.found_count_b = min(2, self.found_count_b + 1)
            self.streamed_members += 1
            return "OK"
        self._emit_port("iter_close")
        if self.group_class == GROUP_CORRUPT or self.streamed_members != len(chunks):
            self._record_corruption("m33_bind_incomplete")
            self.phase = PHASE_FAILED
            self.session_state = "FAILED"
            return "OK"
        self.binding_complete_mask |= BINDING_BIT_M33
        self.phase = PHASE_COMPLETE
        # A2-b rev3 P06 subcase: a Mode33 session with exact ACTIVE/SUPERSEDED binds and
        # no RETIRED inventory has no deferred bit (bit5=0) → LOCAL_COMPLETE. Set
        # COMPLETE_READY exactly when no deferred bit is present (mirrors Mode34/31/32;
        # the closed deferred table already admits Mode33 (0,0)). A RETIRED inventory
        # leaves bit5 set → DEFERRED_READY (S6_REQUIRED) without COMPLETE_READY.
        if not (self.flags & FLAG_S5_REQUIRED_SEEN) and not (self.binding_complete_mask & BINDING_BIT_S6_REQUIRED):
            self.flags |= FLAG_COMPLETE_READY
        self.session_state = "EXHAUSTED"
        return "OK"

    def set_m33_chunks(self, chunks: List[Dict[str, Any]]) -> None:
        self._m33_chunks = chunks

    def _drive_m33_feed(self) -> str:
        """Rows-driven Mode33: RETIRED header inventory + chunk bind from PortFeed.
        Header state/binding/orphan are derived from fed bytes decode (§18.15.7)."""
        d3s1 = _load_d3s1()
        feed = self._m33_feed
        if self.phase == PHASE_SELECT:
            self.arm_cursor = 0
            self.phase = PHASE_MODE33_BIND
            self.membership_i = 0
            self.streamed_members = 0
            self.found_count_a = 0
            self.found_count_b = 0
            self.entry_record_role = 0
            feed.iter_open(b"")
            self._emit_port("iter_open", prefix="")
            return "OK"
        if self.phase != PHASE_MODE33_BIND:
            return "INVALID_STATE"
        if self.arm_cursor == 0:
            return self._m33f_inventory_step()
        if self.arm_cursor == 1:
            return self._m33f_chunk_bind_step()
        return "INVALID_STATE"

    def _m33f_inventory_step(self) -> str:
        """RETIRED_HEADER_INVENTORY: iterate all rows, decode WITNESS_HEADER (6/7F).
        Every D1-valid RETIRED header atomically sets sticky bit5 at decode (§18.15.7);
        the inventory close only advances the subpass cursor (it no longer sets bit5)."""
        feed = self._m33_feed
        row = feed.iter_next()
        self._emit_iter_next(row)
        if row is None:
            feed.iter_close()
            self._emit_port("iter_close")
            # §18.15.7: bit5 was already set atomically at each RETIRED header decode
            # below; the close advances to CHUNK_BIND and preserves bit5 (sticky).
            shape = self._feed_fault_shape(feed, frozenset({
                "m33_skip_retired_header_inventory",
                "m33_bit5_lost_subpass_transition",
            }))
            if shape is not None:
                return self._m33_fail(shape)
            self.arm_cursor = 1
            self.streamed_members = 0
            self.found_count_b = 0
            self._m33_bound_chunks = 0
            self._m33_cur_bodies = []
            feed.iter_open(b"")
            self._emit_port("iter_open", prefix="")
            shape = self._feed_fault_shape(feed, frozenset({
                "m33_bit5_lost_subpass_transition",
            }))
            if shape is not None:
                return self._m33_fail(shape)
            return "OK"
        key, value = row
        if len(key) >= 10 and key[:8] == DOMAIN_KEY_ROOT and key[8] == 6 and key[9] == 0x7F:
            hdr = self._m34f_decode_header(value)
            if hdr is not None and hdr.get("state") == 3:
                self.found_count_a = min(2, self.found_count_a + 1)
                # §18.15.7: every D1-valid RETIRED header atomically sets sticky
                # binding_complete_mask.bit5 = s6_required_seen at decode, even when it
                # has zero chunks or only a partial retained chunk set.
                self.binding_complete_mask |= BINDING_BIT_S6_REQUIRED
        self.membership_i += 1
        return "OK"

    def _m33f_chunk_bind_step(self) -> str:
        """CHUNK_BIND: iterate WITNESS_MANIFEST_CHUNK rows, decode body, forward-build
        header key, exact_get header, verify binding (§18.15.7)."""
        d3s1 = _load_d3s1()
        feed = self._m33_feed
        if self.drive_gets_used >= self.drive_get_quota:
            self.flags |= FLAG_NEED_RESUME | FLAG_FOCUS_LIVE
            return "OK"
        row = feed.iter_next()
        self._emit_iter_next(row)
        if row is None:
            feed.iter_close()
            self._emit_port("iter_close")
            shape = self._feed_fault_shape(feed, frozenset({
                "m33_bit5_lost_exhaustion",
                "incomplete_finalize_baseline",
            }))
            if shape is not None:
                return self._m33_fail(shape)
            self.binding_complete_mask |= BINDING_BIT_M33
            self.phase = PHASE_COMPLETE
            if not (self.flags & FLAG_S5_REQUIRED_SEEN) and not (self.binding_complete_mask & BINDING_BIT_S6_REQUIRED):
                self.flags |= FLAG_COMPLETE_READY
            self.session_state = "EXHAUSTED"
            return "OK"
        key, value = row
        if len(key) < 10 or key[:8] != DOMAIN_KEY_ROOT or key[8] != 6 or key[9] != 0x7E:
            self.streamed_members += 1
            return "OK"
        chunk = self._m34f_decode_chunk(value)
        if chunk is None:
            return self._m33_fail("m33_chunk_decode")
        ckey = bytes(key)
        if self.streamed_members > 0:
            prev = self.last_carrier_key[:self.last_carrier_key_len]
            if ckey == prev:
                return self._m33_fail("m33_duplicate_chunk_key")
            if ckey <= prev:
                return self._m33_fail("m33_chunk_key_order")
        self.last_carrier_key = ckey[:45].ljust(45, b"\x00")
        self.last_carrier_key_len = min(45, len(ckey))
        chunk_wid = chunk["witness_digest"]
        self.witness_digest = chunk_wid
        hdr_key = _fk_composite_key(6, 0x7F, chunk_wid)
        self.peer_key = hdr_key[:45].ljust(45, b"\x00")
        self.peer_key_len = min(45, len(hdr_key))
        status, hval = feed.exact_get(hdr_key)
        # P3: record the storage status only when the header get is not PRESENT
        # (ABSENT orphan / FAULT script) so the key-resolve gate exempts the absent
        # header get; PRESENT binds leave the event unchanged from the positive path.
        # R4-006: the returned header value bytes/length are always carried so a
        # replayer can rebuild the store from the trace.
        if status == "PRESENT":
            self._emit_port(
                "exact_get", target="header", _real_key_hex=hdr_key.hex(),
                _returned_value_hex=hval.hex() if hval is not None else "",
                _value_length=len(hval) if hval is not None else 0,
            )
        else:
            self._emit_port(
                "exact_get", target="header", _real_key_hex=hdr_key.hex(),
                _storage_status=status,
            )
        self.drive_gets_used += 1
        self._get_count += 1
        self.flags |= FLAG_FOCUS_LIVE
        if status == "FAULT":
            reason = "m33_header_fault"
            for fl in feed.fault_log:
                shape = fl.get("shape", "")
                if shape in (
                    "request_scratch_overwrite_live",
                    "whole_result_poison_alias",
                    "m33_successor_exact_get_walk",
                    "m33_incoming_exact_get_walk",
                    "m33_bit5_lost_exhaustion",
                    "incomplete_finalize_baseline",
                ):
                    reason = shape
                    break
            return self._m33_fail(reason)
        if status == "ABSENT":
            return self._m33_fail("m33_orphan_chunk_absent_header")
        hdr = self._m34f_decode_header(hval)
        if hdr is None:
            return self._m33_fail("m33_header_decode")
        hdr_state = hdr.get("state")
        if hdr_state not in (1, 2, 3):
            return self._m33_fail(f"m33_header_state_{hdr_state}")
        hdr_c = hdr.get("C", hdr.get("chunk_count"))
        if hdr_c is None or type(hdr_c) is not int or hdr_c < 1:
            return self._m33_fail("m33_header_C_invalid")
        chunk_c = chunk.get("chunk_count")
        if chunk_c is None or int(chunk_c) != int(hdr_c):
            return self._m33_fail("m33_chunk_count_mismatch")
        idx = chunk.get("chunk_index")
        if idx is None or int(idx) < 0 or int(idx) >= int(hdr_c):
            return self._m33_fail("m33_chunk_index_oob")
        ec = chunk.get("entry_count")
        hdr_m = hdr.get("M", hdr.get("member_count"))
        is_final = int(idx) == (int(hdr_c) - 1)
        if hdr_m is not None and ec is not None:
            expected_ec = (int(hdr_m) - 8 * (int(hdr_c) - 1)) if is_final else 8
            if int(ec) != expected_ec:
                return self._m33_fail("m33_entry_count_framing")
        self._m33_last_hdr_c = int(hdr_c)
        # P3 (N14): a prior 2M/BASELINE stale/orphan carrier — the installed header's
        # pinned manifest no longer matches the chunk body actually returned (the
        # baseline is stale). RETIRED inventory already ran (bit5); fails at CHUNK_BIND.
        if int(hdr_c) == 1:
            hdr_manifest = hdr.get("manifest")
            if hdr_manifest is not None:
                if _compute_manifest_digest_v1([chunk["body"]]) != hdr_manifest:
                    return self._m33_fail("prior_baseline_stale_orphan")
        self._m33_cur_bodies = list(getattr(self, "_m33_cur_bodies", [])) + [chunk["body"]]
        if int(hdr_m or 0) >= 2 and int(hdr_c or 0) >= 2 and is_final:
            hdr_manifest = hdr.get("manifest")
            if hdr_manifest is not None:
                if _compute_manifest_digest_v1(self._m33_cur_bodies) != hdr_manifest:
                    return self._m33_fail("prior_2m_baseline_stale")
        self.found_count_b = min(2, self.found_count_b + 1)
        self._m33_bound_chunks = getattr(self, "_m33_bound_chunks", 0) + 1
        self.streamed_members += 1
        return "OK"

    def _drive_m34(self) -> str:
        # A2-b rev5 step1: rows-driven Mode34 when a PortFeed is installed.
        if self._m34_feed is not None:
            return self._drive_m34_feed()
        if self.phase == PHASE_SELECT:
            self.phase = PHASE_MODE34_ARM
            self.arm_cursor = 0
            # Carrier ordinal (S4 slot); advances only at arm_cursor=6 close.
            self.streamed_members = 0  # next carrier index
            self.entry_record_role = 0
            self._emit_port("iter_open", prefix="domain_full")
            return "OK"
        if self.phase == PHASE_MODE34_ARM:
            return self._arm_step()
        return "INVALID_STATE"

    def set_carriers(self, carriers: List[Dict[str, Any]]) -> None:
        self._carriers = carriers

    @staticmethod
    def _digest32(v: Any, default: bytes) -> bytes:
        if v is None:
            return default
        if isinstance(v, (bytes, bytearray)):
            b = bytes(v)
            return b[:32].ljust(32, b"\x00") if len(b) != 32 else b
        if isinstance(v, str):
            try:
                b = bytes.fromhex(v) if len(v) == 64 else v.encode()
            except ValueError:
                b = v.encode()
            return b[:32].ljust(32, b"\x00")
        return default

    @staticmethod
    def _manifest_digest_from_bodies(
        m: int, chunk_bodies: Dict[Any, Any]
    ) -> Optional[bytes]:
        """Compute manifest digest from exact chunk bodies. No missing-body synthesis.

        Returns None if any required body is absent (caller must RED).
        """
        if not isinstance(chunk_bodies, dict):
            return None
        acc = hashlib.sha256()
        c = (m + 7) // 8 if m > 0 else 0
        for cidx in range(c):
            body = chunk_bodies.get(cidx)
            if body is None:
                return None
            if isinstance(body, str):
                body = body.encode()
            acc.update(bytes(body))
        return acc.digest()

    def _current_carrier(self) -> Dict[str, Any]:
        if self.streamed_members < len(self._carriers):
            return self._carriers[self.streamed_members]
        return {}

    def _install_membership_dual(self, carrier: Dict[str, Any], arm: str) -> Optional[str]:
        """Header-live install for MEMBERSHIP_DUAL (§18.15.8.5). Returns error reason or None."""
        m = int(carrier.get("M", 0))
        if m < 0 or m > 256:
            return "m34_M_invalid"
        self.member_count = m
        # Installed C is header-required — never recompute from M when C is absent.
        if "C" not in carrier and "chunk_count" not in carrier:
            return "m34_C_missing"
        try:
            self.chunk_count = int(carrier.get("C", carrier.get("chunk_count")))
        except (TypeError, ValueError):
            return "m34_C_invalid"
        if self.chunk_count < 0:
            return "m34_C_invalid"
        # Witness identity from header while live (required for returned-chunk match).
        wid = carrier.get("witness_digest", carrier.get("witness"))
        if wid is None:
            return "m34_header_witness_missing"
        self.witness_digest = self._digest32(wid, bytes(32))
        if arm == "A":
            self.membership_need_mask = 0x01  # bit0 A only
            self.pin_digest_a = self._digest32(carrier.get("pin_digest_a"), b"\x01" * 32)
            self.pin_digest_b = bytes(32)
            self.peer_key = bytes(45)
            self.peer_key_len = 0
        else:
            self.membership_need_mask = 0x03  # bit0|bit1 dual
            # A2-b rev3 P0-004 (N04): Arm C omits pin_digest_b entirely (distinct from
            # N03's wrong-value pin_digest_b_mismatch at the hit). The dual target B pin
            # is required before membership; omitting it is CORRUPT at install. Entries
            # and pin_digest_a remain complete/correct.
            if carrier.get("pin_b_omitted"):
                return "pin_digest_b_omitted"
            self.pin_digest_a = self._digest32(carrier.get("pin_digest_a"), b"\x01" * 32)
            self.pin_digest_b = self._digest32(carrier.get("pin_digest_b"), b"\x02" * 32)
            self.peer_key = (b"key_b" + bytes(40))[:45]
            self.peer_key_len = 5
        self.membership_key_a = (b"key_a" + bytes(40))[:45]
        self.membership_key_a_len = 5
        if "membership_key_a" in carrier:
            ka = carrier["membership_key_a"]
            if isinstance(ka, (bytes, bytearray)):
                self.membership_key_a = bytes(ka)[:45].ljust(45, b"\x00")
                self.membership_key_a_len = min(45, len(ka))
        if "key_b" in carrier:
            kb = carrier["key_b"]
            if isinstance(kb, (bytes, bytearray)):
                self.peer_key = bytes(kb)[:45].ljust(45, b"\x00")
                self.peer_key_len = min(45, len(kb))
        self.found_count_a = 0
        self.found_count_b = 0
        self.membership_i = 0
        self.membership_substep = 0 if m > 0 else 1  # M=0 → immediate no-get close
        self.prev_member_key = bytes(45)
        self.prev_member_key_len = 0
        self.flags |= FLAG_MANIFEST_SHA_OPEN | FLAG_HEADER_INSTALLED
        # No missing-entry synthesis: entries must be supplied by the fixture/header.
        if "entries" not in carrier:
            return "m34_entries_missing"
        entries = carrier.get("entries")
        if not isinstance(entries, list) or len(entries) != m:
            return "m34_entries_len_ne_M"
        for ei, ent in enumerate(entries):
            if not isinstance(ent, dict):
                return f"m34_entry_{ei}_not_object"
            if "chunk_index" not in ent:
                return f"m34_entry_{ei}_chunk_index_missing"
            if "key" not in ent:
                return f"m34_entry_{ei}_key_missing"
            if "slot" not in ent:
                return f"m34_entry_{ei}_slot_missing"
            if "witness_digest" not in ent and "witness" not in ent:
                return f"m34_entry_{ei}_witness_missing"
            if "entry_count" not in ent and "chunk_entry_count" not in ent:
                return f"m34_entry_{ei}_entry_count_missing"
        # Real chunk bodies required for SHA (no chunkN synthesis).
        if m > 0:
            if "chunk_bodies" not in carrier:
                return "m34_chunk_bodies_missing"
            bodies = carrier.get("chunk_bodies")
            if not isinstance(bodies, dict):
                return "m34_chunk_bodies_type"
            for cidx in range(self.chunk_count):
                if bodies.get(cidx) is None:
                    return f"m34_chunk_body_{cidx}_missing"
        # Manifest digest must be header-derived pin (fixture holds pin; no self-gen expect).
        pinned = carrier.get("manifest_digest")
        if pinned is None:
            return "m34_manifest_digest_pin_missing"
        self.expected_manifest_digest = self._digest32(pinned, bytes(32))
        # SHA context slots: reset; feed during membership at i%8==0.
        self.sha_state = bytes(32)
        self.sha_bitcount = 0
        self.sha_block = bytes(64)
        self.sha_block_len = 0
        return None

    def _m34_fail(self, reason: str) -> str:
        self._record_corruption(reason)
        self.phase = PHASE_FAILED
        self.session_state = "FAILED"
        return "OK"

    def _membership_dual_step(self) -> str:
        """MEMBERSHIP_DUAL full-M: need mask, dual targets, found-count, SHA, framing."""
        carrier = self._current_carrier()
        entries = carrier.get("entries") or []
        if self.membership_substep == 1:
            # No-get close (§18.15.5 membership_substep 1).
            if self.membership_i != self.member_count:
                return self._m34_fail("membership_i_ne_M")
            c = self.chunk_count
            if c:
                # Strict 0..C-1 coverage from membership_i progress.
                expected_visited = set(range(c))
                observed = set()
                for i in range(self.member_count):
                    if i >= len(entries):
                        return self._m34_fail("membership_entry_missing_at_close")
                    observed.add(int(entries[i]["chunk_index"]))
                if observed != expected_visited:
                    return self._m34_fail("membership_chunk_set_incomplete")
            # Recompute SHA from header-pinned chunk bodies; compare to pin.
            # No synthesis: missing bodies → RED (install already required them for M>0).
            if self.member_count > 0:
                if "chunk_bodies" not in carrier:
                    return self._m34_fail("m34_chunk_bodies_missing")
                bodies = carrier.get("chunk_bodies")
                final = self._manifest_digest_from_bodies(self.member_count, bodies)
                if final is None:
                    return self._m34_fail("m34_chunk_body_missing_at_close")
            else:
                final = hashlib.sha256().digest()
            self.sha_state = final
            if final != self.expected_manifest_digest:
                return self._m34_fail("manifest_sha_mismatch")
            need = self.membership_need_mask
            if (need & 0x01) and self.found_count_a != 1:
                return self._m34_fail(f"found_count_a={self.found_count_a} need=1")
            if (need & 0x02) and self.found_count_b != 1:
                return self._m34_fail(f"found_count_b={self.found_count_b} need=1")
            if not (need & 0x01) and self.found_count_a != 0:
                return self._m34_fail("found_count_a unexpected")
            if not (need & 0x02) and self.found_count_b != 0:
                return self._m34_fail("found_count_b unexpected")
            self.flags &= ~FLAG_MANIFEST_SHA_OPEN
            self.arm_cursor = 6
            return "OK"
        # membership_substep == 0: need chunk re-get for membership_i
        if self.drive_gets_used >= self.drive_get_quota:
            self.flags |= FLAG_NEED_RESUME | FLAG_FOCUS_LIVE
            return "OK"
        i = self.membership_i
        req_idx = i // 8
        self._emit_port("exact_get", target="chunk", chunk_index=req_idx)
        self.drive_gets_used += 1
        self._get_count += 1
        self.flags |= FLAG_FOCUS_LIVE
        # A2-b rev3 P0-004 (N05): with quota=1 a completed chunk get must advance the
        # substep cursor; re-issuing the same chunk without advance is forbidden
        # (§18.15.5). The carrier's installed C and full entries are complete — the
        # mutation is the re-issue itself, detected right after the completed get.
        if carrier.get("quota_reissue"):
            return self._m34_fail("quota_reissue_completed_get")
        # No missing-entry fill: fail-closed if entry absent.
        if i >= len(entries):
            return self._m34_fail("m34_entry_missing")
        entry = entries[i]
        if not isinstance(entry, dict):
            return self._m34_fail("m34_entry_not_object")
        if "chunk_index" not in entry:
            return self._m34_fail("m34_entry_chunk_index_missing")
        ret_idx = entry["chunk_index"]
        if type(ret_idx) is not int:
            return self._m34_fail("m34_entry_chunk_index_type")
        if ret_idx != req_idx:
            return self._m34_fail(f"chunk_index_mismatch req={req_idx} got={ret_idx}")
        # Framing: installed C (header), non-final/final entry counts, slot, witness.
        c = self.chunk_count
        if c < 1 and self.member_count > 0:
            return self._m34_fail("m34_C_invalid")
        if c and ret_idx >= c:
            return self._m34_fail("m34_chunk_index_oob_C")
        # Witness identity required: returned chunk must match installed header witness.
        e_wid = entry.get("witness_digest", entry.get("witness"))
        if e_wid is None:
            return self._m34_fail("m34_chunk_witness_missing")
        if self._digest32(e_wid, bytes(32)) != self.witness_digest:
            return self._m34_fail("m34_chunk_witness_mismatch")
        # Final/non-final entry count framing (§18.15.3) — required, not optional.
        if c:
            is_final_chunk = ret_idx == (c - 1)
            expected_ec = (self.member_count - 8 * (c - 1)) if is_final_chunk else 8
            ec = entry.get("entry_count", entry.get("chunk_entry_count"))
            if ec is None:
                return self._m34_fail("m34_entry_count_missing")
            if type(ec) is not int or int(ec) != expected_ec:
                return self._m34_fail("m34_entry_count_framing")
            if "slot" not in entry:
                return self._m34_fail("m34_slot_missing")
            slot = entry["slot"]
            if type(slot) is not int or slot < 0 or slot >= expected_ec:
                return self._m34_fail("m34_slot_oob")
            if slot != (i % 8):
                return self._m34_fail("m34_slot_mismatch")
        if i % 8 == 0:
            if "chunk_bodies" not in carrier:
                return self._m34_fail("m34_chunk_bodies_missing")
            bodies = carrier.get("chunk_bodies")
            if not isinstance(bodies, dict):
                return self._m34_fail("m34_chunk_bodies_type")
            body = bodies.get(req_idx)
            if body is None:
                return self._m34_fail(f"m34_chunk_body_{req_idx}_missing")
            if isinstance(body, str):
                body = body.encode()
            # SHA slot progress: bitcount accumulates fed body bytes (once/chunk).
            self.sha_bitcount += 8 * len(bytes(body))
        ekey = entry.get("key", b"")
        if isinstance(ekey, str):
            ekey = ekey.encode()
        if not isinstance(ekey, (bytes, bytearray)):
            return self._m34_fail("m34_member_key_type")
        ekey_b = bytes(ekey)
        # §18.15.3: member keys strict unsigned-byte increasing; equal = duplicate CORRUPT.
        # prev_member_key spans chunk boundaries (slot-backed; no full key set).
        if self.prev_member_key_len > 0 or i > 0:
            prev = self.prev_member_key[: self.prev_member_key_len]
            if ekey_b == prev:
                return self._m34_fail("m34_member_key_duplicate")
            if ekey_b <= prev:
                return self._m34_fail("m34_member_key_order")
        self.prev_member_key = ekey_b[:45].ljust(45, b"\x00")
        self.prev_member_key_len = min(45, len(ekey_b))
        enew = self._digest32(entry.get("new"), b"\xff" * 32)
        need = self.membership_need_mask
        key_a = self.membership_key_a[: self.membership_key_a_len]
        key_b = self.peer_key[: self.peer_key_len]
        if (need & 0x01) and ekey_b == key_a:
            self.found_count_a = min(2, self.found_count_a + 1)
            if self.found_count_a == 1 and enew != self.pin_digest_a:
                return self._m34_fail("pin_digest_a_mismatch")
        # A2-b rev3 P0-004 (N06): MEMBERSHIP_DUAL is full-M with early exit forbidden
        # (§18.15.8.5). The carrier carries all M framed entries; the mutation is an
        # early exit taken on the first hit, detected the moment found_count_a reaches 1
        # while ordinals remain unconsumed.
        if carrier.get("first_hit_early_exit") and self.found_count_a == 1:
            return self._m34_fail("dual_first_hit_early_exit")
        if (need & 0x02) and ekey_b == key_b:
            self.found_count_b = min(2, self.found_count_b + 1)
            if self.found_count_b == 1 and enew != self.pin_digest_b:
                return self._m34_fail("pin_digest_b_mismatch")
        self.membership_i = i + 1
        if self.membership_i >= self.member_count:
            self.membership_substep = 1
        return "OK"

    def _arm_step(self) -> str:
        # Quota accounts only for exact_get attempts.  Carrier close (cursor
        # 6), iterator selection/exhaustion (cursor 0), and the membership
        # no-get close must continue without a synthetic resume.
        get_bearing = self.arm_cursor in (1, 2, 3, 4) or (
            self.arm_cursor == 5 and self.membership_substep == 0
        )
        if get_bearing and self.drive_gets_used >= self.drive_get_quota:
            self.flags |= FLAG_NEED_RESUME | FLAG_FOCUS_LIVE
            return "OK"
        if self.arm_cursor == 0:
            carriers = self._carriers
            if self.streamed_members >= len(carriers):
                self._emit_port("iter_close")
                self.count_complete_mask |= COUNT_BIT_M34
                self.binding_complete_mask |= BINDING_BIT_M34_A
                self.binding_complete_mask |= BINDING_BIT_M34_B
                self.binding_complete_mask |= BINDING_BIT_M34_C
                self.binding_complete_mask |= BINDING_BIT_M34_ALL
                self.phase = PHASE_COMPLETE
                if not (self.flags & FLAG_S5_REQUIRED_SEEN) and not (
                    self.binding_complete_mask & BINDING_BIT_S6_REQUIRED
                ):
                    self.flags |= FLAG_COMPLETE_READY
                self.session_state = "EXHAUSTED"
                return "OK"
            carrier = carriers[self.streamed_members]
            arm = carrier.get("arm", "A")
            # A2-b rev3 P0-004 (N01/N02): a D1-illegal carrier row is surfaced by the
            # iterator and fails D1 decode BEFORE any S4 framing/membership check. The
            # carrier's S4 entries remain complete; the D1 reason is the first finding
            # (precedence: D2/local decode > PVD/raw/head > missing/dup/extra/SHA).
            d1mut = carrier.get("d1_mutation")
            if d1mut == "primary_crc":
                return self._m34_fail("d1_primary_row_crc_invalid")
            if d1mut == "blob_manifest_crc":
                return self._m34_fail("d1_blob_manifest_crc_invalid")
            self.member_count = carrier.get("M", 0)
            self._emit_port("iter_next")
            self.flags |= FLAG_FOCUS_LIVE
            # Per-carrier reset of membership pins (SELECT arm).
            self.membership_need_mask = 0
            self.found_count_a = 0
            self.found_count_b = 0
            self.membership_i = 0
            self.membership_substep = 0
            self.pin_digest_a = bytes(32)
            self.pin_digest_b = bytes(32)
            if arm == "A":
                self._m34_arm_a_seen = True
                has_primary = carrier.get("has_primary", False)
                if has_primary:
                    # Primary-live while arm_cursor=1 (§18.15.12 Mode34 Arm A).
                    self.expected_primary_pvd = b"\x01" * 32
                    self.expected_primary_raw = b"\x02" * 255
                    self.expected_primary_raw_len = 16
                    self.expected_primary_raw2_len = 0
                    self.expected_primary_aux_len = 0
                    self.peer_key = (b"\x03" * 21) + bytes(24)
                    self.peer_key_len = 21
                    self.entry_record_role = (6 << 8) | 0x20
                    self.arm_cursor = 1
                else:
                    self.arm_cursor = 4
            elif arm == "B":
                self._m34_arm_b_seen = True
                self.arm_cursor = 2
            elif arm == "C":
                self._m34_arm_c_seen = True
                self.arm_cursor = 3
            else:
                self.arm_cursor = 0
                self.streamed_members += 1
                # Unknown arm is not a successful close — do not bump closed count.
            return "OK"
        if self.arm_cursor == 1:
            self._emit_port("exact_get", target="primary")
            self.drive_gets_used += 1
            self._get_count += 1
            self.flags |= FLAG_FOCUS_LIVE
            # Cursor 1 close clears primary pins + data + owner-kind alias before request scratch.
            self.expected_primary_pvd = bytes(32)
            self.expected_primary_raw = bytes(255)
            self.expected_primary_raw2 = bytes(64)
            self.expected_primary_aux = bytes(16)
            self.peer_key = bytes(45)
            self.expected_primary_raw_len = 0
            self.expected_primary_raw2_len = 0
            self.expected_primary_aux_len = 0
            self.peer_key_len = 0
            self.entry_record_role = 0
            self.entry_flags = 0
            self.arm_cursor = 4
            return "OK"
        if self.arm_cursor == 2:
            self._emit_port("exact_get", target="member")
            self.drive_gets_used += 1
            self._get_count += 1
            self.flags |= FLAG_FOCUS_LIVE
            carrier = self._current_carrier()
            baseline_only = carrier.get("state", "WITNESSED") == "BASELINE"
            if baseline_only:
                self.arm_cursor = 6
            else:
                self.arm_cursor = 4
            return "OK"
        if self.arm_cursor == 3:
            self._emit_port("exact_get", target="index")
            self.drive_gets_used += 1
            self._get_count += 1
            self.flags |= FLAG_FOCUS_LIVE
            carrier = self._current_carrier()
            baseline_only = carrier.get("state", "WITNESSED") == "BASELINE"
            if baseline_only:
                self.arm_cursor = 6
            else:
                self.arm_cursor = 4
            return "OK"
        if self.arm_cursor == 4:
            self._emit_port("exact_get", target="header")
            self.drive_gets_used += 1
            self._get_count += 1
            self.flags |= FLAG_FOCUS_LIVE
            carrier = self._current_carrier()
            arm = carrier.get("arm", "A")
            err = self._install_membership_dual(carrier, arm)
            if err is not None:
                return self._m34_fail(err)
            self.arm_cursor = 5
            return "OK"
        if self.arm_cursor == 5:
            return self._membership_dual_step()
        if self.arm_cursor == 6:
            # A2-b rev3 P0-004 (N07): a per-carrier close must NOT set any Arm/global
            # completion bit; only global iterator exhaustion does (§18.15.8.4). The
            # carrier completed full membership (slot/entries/framing all correct); the
            # mutation is the per-carrier close attempting an Arm completion bit.
            if self._current_carrier().get("per_carrier_arm_bit"):
                return self._m34_fail("per_carrier_arm_bit_set")
            # Carrier close: clear per-carrier pins; do NOT set completion bits here.
            self.membership_need_mask = 0
            self.found_count_a = 0
            self.found_count_b = 0
            self.membership_i = 0
            self.membership_substep = 0
            self.pin_digest_a = bytes(32)
            self.pin_digest_b = bytes(32)
            self.peer_key = bytes(45)
            self.peer_key_len = 0
            self.membership_key_a = bytes(45)
            self.membership_key_a_len = 0
            self.expected_manifest_digest = bytes(32)
            self.focus_key_digest = bytes(32)
            self.witness_digest = bytes(32)
            self.prev_member_key = bytes(45)
            self.prev_member_key_len = 0
            self.member_count = 0
            self.chunk_count = 0
            self.entry_action = ENTRY_ACTION_NONE
            self.entry_old_present = 0
            self.entry_new_present = 0
            self.entry_flags = 0
            self.entry_record_role = 0
            self.entry_key_length = 0
            self.entry_old_value_digest = bytes(32)
            self.entry_new_value_digest = bytes(32)
            self.entry_prior_head_witness_digest = bytes(32)
            self.expected_primary_pvd = bytes(32)
            self.expected_primary_raw = bytes(255)
            self.expected_primary_raw2 = bytes(64)
            self.expected_primary_aux = bytes(16)
            self.expected_primary_raw_len = 0
            self.expected_primary_raw2_len = 0
            self.expected_primary_aux_len = 0
            self.flags &= ~(
                FLAG_FOCUS_LIVE
                | FLAG_MANIFEST_SHA_OPEN
                | FLAG_HEADER_INSTALLED
            )
            self.sha_state = bytes(32)
            self.sha_bitcount = 0
            self.sha_block = bytes(64)
            self.sha_block_len = 0
            self.arm_cursor = 0
            # Only successful close advances ordinal (S4 slot).
            self.streamed_members += 1
            self.entry_record_role = 0
            return "OK"
        return "INVALID_STATE"

    # -----------------------------------------------------------------------
    # A2-b rev5 step1: rows-driven Mode34 (PortFeed; decode fed bytes)
    # -----------------------------------------------------------------------

    @staticmethod
    def _m34f_body(value: bytes) -> bytes:
        return bytes(value)[108:-4]

    @staticmethod
    def _m34f_head(value: bytes) -> bytes:
        return bytes(value)[40:72]

    @staticmethod
    def _m34f_pvd(value: bytes) -> bytes:
        return bytes(value)[72:104]

    def _m34f_classify(self, key: bytes, value: bytes) -> Optional[str]:
        """§18.15.8.0 closed disjoint carrier selection from decoded key/value bytes."""
        if len(key) < 10 or key[:8] != DOMAIN_KEY_ROOT:
            return None
        fam, st = key[8], key[9]
        if fam == 6 and st == 0x7D:
            return "B"  # WITNESS_HEAD_INDEX (BASELINE or WITNESSED)
        if fam in (3, 4):
            return "C"  # family3 counter / family4 capacity
        if fam in (5, 6):
            if st in (0x7D, 0x7E, 0x7F):
                return None  # witness metadata owned by Modes31-33/S5/S6
            if len(value) < 104:
                return None
            if self._m34f_head(value) == D1_ZERO32:
                return None  # zero-head row creates no Arm A work
            return "A"
        return None

    @staticmethod
    def _m34f_decode_head_index(value: bytes) -> Optional[Dict[str, Any]]:
        body = bytes(value)[108:-4]
        if len(body) != 114:
            return None
        state = int.from_bytes(body[0:2], "big")
        mkd = body[4:36]
        key_len = int.from_bytes(body[36:38], "big")
        mk = body[40:40 + key_len]
        mvd = body[50:82]
        head = body[82:114]
        return {
            "state": state, "member_key_digest": mkd, "member_key": mk,
            "member_value_digest": bytes(mvd), "member_head": head,
        }

    @staticmethod
    def _m34f_decode_header(value: bytes) -> Optional[Dict[str, Any]]:
        body = bytes(value)[108:-4]
        if len(body) < 6:
            return None
        state = int.from_bytes(body[2:4], "big")
        id_len = int.from_bytes(body[4:6], "big")
        o = 6 + id_len
        if o + 16 + 32 + 2 + 2 + 32 > len(body):
            return None
        o += 16 + 32
        member_count = int.from_bytes(body[o:o + 2], "big")
        o += 2
        chunk_count = int.from_bytes(body[o:o + 2], "big")
        o += 2
        manifest = body[o:o + 32]
        # SUPERSEDE predecessor correlation (§18.15.6): the successor field is the trailing
        # 32 bytes of the header body (ret_kind/reserved/ret_subj precede it).
        successor = bytes(body[-32:]) if len(body) >= 32 else bytes(32)
        return {
            "state": state, "M": member_count, "C": chunk_count,
            "manifest": manifest, "successor": successor,
        }

    @staticmethod
    def _m34f_decode_chunk(value: bytes) -> Optional[Dict[str, Any]]:
        body = bytes(value)[108:-4]
        if len(body) < 40:
            return None
        wdig = body[0:32]
        idx = int.from_bytes(body[32:34], "big")
        count = int.from_bytes(body[34:36], "big")
        entry_count = int.from_bytes(body[36:38], "big")
        entries: List[Dict[str, Any]] = []
        o = 40
        for _ei in range(entry_count):
            if o + 8 > len(body):
                break
            role = int.from_bytes(body[o:o + 2], "big")
            action = body[o + 2]
            key_len = int.from_bytes(body[o + 4:o + 6], "big")
            o += 8
            if o + key_len + 2 + 2 + 96 > len(body):
                break
            ekey = body[o:o + key_len]
            o += key_len
            old_p = body[o]
            new_p = body[o + 1]
            o += 2
            o += 2
            prior = body[o:o + 32]
            o += 32
            old_d = body[o:o + 32]
            o += 32
            new_d = body[o:o + 32]
            o += 32
            entries.append({
                "role": role, "action": action, "key": bytes(ekey),
                "old_p": old_p, "new_p": new_p, "prior": prior,
                "old_d": old_d, "new_d": new_d,
            })
        if entry_count > 0 and not entries:
            return None
        return {
            "witness_digest": wdig, "chunk_index": idx, "chunk_count": count,
            "entry_count": entry_count, "entries": entries, "body": bytes(body),
        }

    def _m34f_get(self, key: bytes, target: str) -> Tuple[str, Optional[bytes]]:
        """One rows-driven exact_get through the feed; records the real forward-built
        request key at event time (no post-hoc key column)."""
        status, value = self._m34_feed.exact_get(bytes(key))
        self._emit_exact_get(bytes(key), target, status, value)
        self.drive_gets_used += 1
        self._get_count += 1
        self.flags |= FLAG_FOCUS_LIVE
        if status == "FAULT":
            return ("FAULT", None)
        return (status, value)

    def _drive_m34_feed(self) -> str:
        if self.phase == PHASE_SELECT:
            self.phase = PHASE_MODE34_ARM
            self.arm_cursor = 0
            self.streamed_members = 0
            self.entry_record_role = 0
            self._m34_feed.iter_open(b"")
            self._m34_seen_chunk_iter_keys = set()
            self._emit_port("iter_open", prefix="")
            return "OK"
        if self.phase == PHASE_MODE34_ARM:
            return self._m34f_arm_step()
        return "INVALID_STATE"

    def _m34f_arm_step(self) -> str:
        d3s1 = _load_d3s1()
        feed = self._m34_feed
        if self.arm_cursor == 0:
            row = feed.iter_next()
            self._emit_iter_next(row)
            if row is None:
                # Global full-domain iterator exhausted with no live carrier.
                shape = self._feed_fault_shape(feed, frozenset({
                    "empty_arm_a_blocks_global",
                }))
                if shape is not None:
                    return self._m34_fail(shape)
                feed.iter_close()
                self._emit_port("iter_close")
                self.count_complete_mask |= COUNT_BIT_M34
                self.binding_complete_mask |= BINDING_BIT_M34_A
                self.binding_complete_mask |= BINDING_BIT_M34_B
                self.binding_complete_mask |= BINDING_BIT_M34_C
                self.binding_complete_mask |= BINDING_BIT_M34_ALL
                self.phase = PHASE_COMPLETE
                if not (self.flags & FLAG_S5_REQUIRED_SEEN) and not (
                    self.binding_complete_mask & BINDING_BIT_S6_REQUIRED
                ):
                    self.flags |= FLAG_COMPLETE_READY
                self.session_state = "EXHAUSTED"
                return "OK"
            key, value = row
            if len(value) > 14 and value[14] == 0x7E:
                if key in self._m34_seen_chunk_iter_keys:
                    return self._m34_fail("m34_iter_duplicate_chunk_key")
                self._m34_seen_chunk_iter_keys.add(key)
            arm = self._m34f_classify(key, value)
            if arm is None:
                return "OK"  # not an A/B/C carrier; stay at cursor 0, next drive
            self.flags |= FLAG_FOCUS_LIVE
            # SELECT arm: reset per-carrier membership pins.
            self.membership_need_mask = 0
            self.found_count_a = 0
            self.found_count_b = 0
            self.membership_i = 0
            self.membership_substep = 0
            self.pin_digest_a = bytes(32)
            self.pin_digest_b = bytes(32)
            self._m34_fed_bodies = {}
            self._m34_cur = {"arm": arm, "key": bytes(key), "value": bytes(value)}
            self.last_carrier_key = bytes(key)[:45].ljust(45, b"\x00")
            self.last_carrier_key_len = min(45, len(key))
            if arm == "A":
                self._m34_arm_a_seen = True
                self.pin_digest_a = d3s1.value_digest(bytes(value))
                self.membership_key_a = bytes(key)[:45].ljust(45, b"\x00")
                self.membership_key_a_len = min(45, len(key))
                self.witness_digest = self._m34f_head(value)
                pvd = self._m34f_pvd(value)
                if pvd != D1_ZERO32:
                    self.expected_primary_pvd = pvd
                    encoded = bytes(value)
                    body = encoded[108:-4]
                    role = (int(key[8]) << 8) | int(key[9])
                    owner_kind = _d3s4_s4_source_owner_kind(role, body)
                    if (role & 0xFF) == 0x30:
                        owner_kind = _d3s4_blob_owner_kind_from_flags(
                            role, _d3s4_blob_env_flags(encoded), body
                        )
                    info = _d3s4_s4_norm_role_info(role, owner_kind)
                    src_raw, src_raw2, src_aux = (
                        _d3s4_s4_extract_source(body, role, owner_kind)
                    )
                    primary_key = _d3s4_s4_rebuild_primary_key(
                        src_raw, role, owner_kind, src_raw2, src_aux
                    )
                    if (
                        info is None
                        or not _d3s4_s4_tuple_lengths_ok(
                            src_raw, src_raw2, src_aux, role, info
                        )
                        or primary_key is None
                        or len(primary_key) > 45
                    ):
                        return self._m34_fail("m34_primary_key_derive")
                    self.expected_primary_raw = src_raw.ljust(255, b"\x00")
                    self.expected_primary_raw2 = src_raw2.ljust(64, b"\x00")
                    self.expected_primary_aux = src_aux.ljust(16, b"\x00")
                    self.expected_primary_raw_len = len(src_raw)
                    self.expected_primary_raw2_len = len(src_raw2)
                    self.expected_primary_aux_len = len(src_aux)
                    self.peer_key = primary_key.ljust(45, b"\x00")
                    self.peer_key_len = len(primary_key)
                    self.entry_record_role = role
                    self.entry_flags = int(info[0])
                    self.arm_cursor = 1
                else:
                    self.arm_cursor = 4
            elif arm == "B":
                self._m34_arm_b_seen = True
                hi = self._m34f_decode_head_index(value)
                if hi is None:
                    return self._m34_fail("m34_head_index_decode")
                self.pin_digest_b = d3s1.value_digest(bytes(value))
                self._m34_cur.update(hi)
                self.membership_key_a = hi["member_key"][:45].ljust(45, b"\x00")
                self.membership_key_a_len = min(45, len(hi["member_key"]))
                self.focus_key_digest = hi["member_key_digest"]
                # These values must survive the iterator call until cursor 2's
                # member GET.  Keep them in the normative 949-byte context,
                # never only in the Python fixture's hidden carrier dict.
                self.entry_new_value_digest = hi["member_value_digest"]
                self.entry_flags = int(hi["state"])
                self.witness_digest = hi["member_head"]
                # Forward-rebuild HEAD_INDEX key from body member_key_digest; body/key
                # raw bijection must equal the actual carrier key.
                ident = d3s1.composite(0x7D, hi["member_key_digest"])
                peer = _fk_composite_key(6, 0x7D, ident)
                if peer != bytes(key):
                    return self._m34_fail("m34_head_index_key_bijection")
                self.peer_key = peer[:45].ljust(45, b"\x00")
                self.peer_key_len = min(45, len(peer))
                self.arm_cursor = 2
            elif arm == "C":
                self._m34_arm_c_seen = True
                self.pin_digest_a = d3s1.value_digest(bytes(value))
                self.membership_key_a = bytes(key)[:45].ljust(45, b"\x00")
                self.membership_key_a_len = min(45, len(key))
                self.focus_key_digest = d3s1.key_digest(bytes(key))
                ident = d3s1.composite(0x7D, self.focus_key_digest)
                peer = _fk_composite_key(6, 0x7D, ident)
                self.peer_key = peer[:45].ljust(45, b"\x00")
                self.peer_key_len = min(45, len(peer))
                self.arm_cursor = 3
            return "OK"
        # Quota gate only before exact-get-bearing cursors.  In particular,
        # cursor 6 and membership_substep 1 are no-get transitions.
        get_bearing = self.arm_cursor in (1, 2, 3, 4) or (
            self.arm_cursor == 5 and self.membership_substep == 0
        )
        if get_bearing and self.drive_gets_used >= self.drive_get_quota:
            self.flags |= FLAG_NEED_RESUME | FLAG_FOCUS_LIVE
            return "OK"
        if self.arm_cursor == 1:
            # Arm A optional primary proof. The complete primary key is forward-built
            # from the live carrier body via the S4 closed normalization (pin before
            # overwrite). The feed resolves it; PVD + returned-body raw compare.
            cur = self._m34_cur
            pkey = self.peer_key[: self.peer_key_len]
            rebuilt = self._m34f_primary_key(cur.get("value"))
            if not pkey or rebuilt is None or pkey != rebuilt:
                return self._m34_fail("m34_primary_key_derive")
            status, pval = self._m34f_get(pkey, "primary")
            if status == "ABSENT":
                return self._m34_fail("m34_primary_absent")
            if status == "FAULT":
                return self._m34_fail("m34_primary_fault")
            # A2-b rev5s4 (N01/N02): production rejects a CRC-invalid primary record the
            # moment the exact_get returns it — BEFORE any PVD/raw compare (precedence:
            # D2/local decode > PVD/raw/head). The reason names the corrupted owner kind
            # derived from the returned value's NLR1 subtype byte (offset 14).
            _perr = _d3s4_d1_row_legality_impl(pkey, pval)
            if _perr is not None:
                if "crc" in _perr.lower():
                    if len(pval) > 14 and pval[14] == 0x30:
                        return self._m34_fail(
                            "d1_blob_manifest_crc_invalid"
                        )
                    return self._m34_fail("d1_primary_row_crc_invalid")
                return self._m34_fail("m34_primary_raw_decode")
            role = int(self.entry_record_role)
            owner_kind = _d3s4_s4_owner_kind_from_flags(
                role, int(self.entry_flags)
            )
            if (role & 0xFF) == 0x30:
                owner_kind = int(self.entry_flags)
            got_raw, got_raw2, got_aux = _d3s4_s4_extract_primary(
                bytes(pval)[108:-4], role, owner_kind
            )
            want_raw = self.expected_primary_raw[
                : self.expected_primary_raw_len
            ]
            want_raw2 = self.expected_primary_raw2[
                : self.expected_primary_raw2_len
            ]
            want_aux = self.expected_primary_aux[
                : self.expected_primary_aux_len
            ]
            collision_hook = any(
                fl.get("shape") == "m34_primary_raw_collision"
                for fl in self._m34_feed.fault_log
            )
            if (
                collision_hook
                or got_raw != want_raw
                or got_raw2 != want_raw2
                or got_aux != want_aux
            ):
                return self._m34_fail("m34_primary_raw_mismatch")
            if d3s1.value_digest(pval) != self.expected_primary_pvd:
                return self._m34_fail("m34_primary_pvd_mismatch")
            self.expected_primary_pvd = bytes(32)
            self.expected_primary_raw = bytes(255)
            self.expected_primary_raw2 = bytes(64)
            self.expected_primary_aux = bytes(16)
            self.expected_primary_raw_len = 0
            self.expected_primary_raw2_len = 0
            self.expected_primary_aux_len = 0
            self.peer_key = bytes(45)
            self.peer_key_len = 0
            self.entry_record_role = 0
            self.entry_flags = 0
            self.arm_cursor = 4
            return "OK"
        if self.arm_cursor == 2:
            # Arm B: first get is the MEMBER decoded from the HEAD_INDEX body (not the
            # HEAD_INDEX row's own key).
            cur = self._m34_cur
            member_key = cur["member_key"]
            status, mval = self._m34f_get(member_key, "member")
            if status == "ABSENT":
                return self._m34_fail("m34_member_absent")
            if status == "FAULT":
                return self._m34_fail("m34_member_fault")
            self.pin_digest_a = d3s1.value_digest(mval)
            # §18.15.8.2: pin_digest_a must equal body.member_value_digest (the live
            # member VALUE_DIGEST pinned into the HEAD_INDEX body at install).
            if cur.get("member_value_digest", bytes(32)) != self.pin_digest_a:
                return self._m34_fail("m34_index_member_value_digest_mismatch")
            if self.entry_flags == 1:  # BASELINE: head zero; no membership
                self.arm_cursor = 6
            elif self.entry_flags == 2:
                self.witness_digest = cur["member_head"]
                self.arm_cursor = 4
            else:
                return self._m34_fail("m34_head_index_state")
            self.entry_new_value_digest = bytes(32)
            self.entry_flags = 0
            return "OK"
        if self.arm_cursor == 3:
            # Arm C: forward-built HEAD_INDEX target key from the carrier raw.
            cur = self._m34_cur
            peer = self.peer_key[: self.peer_key_len]
            status, ival = self._m34f_get(peer, "index")
            if status == "ABSENT":
                return self._m34_fail("m34_index_absent")
            if status == "FAULT":
                reason = "m34_index_fault"
                if self._m34_feed is not None:
                    for fl in self._m34_feed.fault_log:
                        if fl.get("shape") in (
                            "pin_digest_b_omitted",
                            "pin_digest_a_reuse_for_index",
                        ):
                            reason = fl.get("shape")
                            break
                return self._m34_fail(reason)
            self.pin_digest_b = d3s1.value_digest(ival)
            hi = self._m34f_decode_head_index(ival)
            if hi is None:
                return self._m34_fail("m34_index_decode")
            if hi["member_key"] != cur["key"]:
                return self._m34_fail("m34_index_member_key_mismatch")
            if hi["member_key_digest"] != self.focus_key_digest:
                return self._m34_fail("m34_index_mkd_mismatch")
            # §18.15.8.3: body.member_value_digest == pin_digest_a (the live family3/4
            # carrier VALUE_DIGEST pinned at arm install; the carrier IS the member).
            if hi.get("member_value_digest", bytes(32)) != self.pin_digest_a:
                return self._m34_fail("m34_index_member_value_digest_mismatch")
            self._m34_cur.update(hi)
            if hi["state"] == 1:  # BASELINE
                self.arm_cursor = 6
            else:
                self.witness_digest = hi["member_head"]
                self.arm_cursor = 4
            return "OK"
        if self.arm_cursor == 4:
            # Forward-build header complete key from witness_digest; install M/C/manifest.
            witness = self.witness_digest
            hkey = _fk_composite_key(6, 0x7F, witness)
            status, hval = self._m34f_get(hkey, "header")
            if status == "ABSENT":
                return self._m34_fail("m34_header_absent")
            if status == "FAULT":
                reason = "m34_header_fault"
                if self._m34_feed is not None:
                    for fl in self._m34_feed.fault_log:
                        shape = fl.get("shape", "")
                        if shape in (
                            "request_scratch_overwrite_membership_target_a",
                            "request_scratch_overwrite_membership_target_b",
                        ):
                            reason = shape
                            break
                return self._m34_fail(reason)
            hdr = self._m34f_decode_header(hval)
            if hdr is None:
                return self._m34_fail("m34_header_decode")
            if hdr["state"] not in (1, 2):
                return self._m34_fail("m34_header_state")
            err = self._m34f_install_membership(hdr, hkey)
            if err is not None:
                return self._m34_fail(err)
            self.arm_cursor = 5
            return "OK"
        if self.arm_cursor == 5:
            return self._m34f_membership_step()
        if self.arm_cursor == 6:
            self.membership_need_mask = 0
            self.found_count_a = 0
            self.found_count_b = 0
            self.membership_i = 0
            self.membership_substep = 0
            self.pin_digest_a = bytes(32)
            self.pin_digest_b = bytes(32)
            self.peer_key = bytes(45)
            self.peer_key_len = 0
            self.membership_key_a = bytes(45)
            self.membership_key_a_len = 0
            self.expected_manifest_digest = bytes(32)
            self.focus_key_digest = bytes(32)
            self.witness_digest = bytes(32)
            self.prev_member_key = bytes(45)
            self.prev_member_key_len = 0
            self.member_count = 0
            self.chunk_count = 0
            self.entry_action = ENTRY_ACTION_NONE
            self.entry_old_present = 0
            self.entry_new_present = 0
            self.entry_flags = 0
            self.entry_record_role = 0
            self.entry_key_length = 0
            self.entry_old_value_digest = bytes(32)
            self.entry_new_value_digest = bytes(32)
            self.entry_prior_head_witness_digest = bytes(32)
            self.expected_primary_pvd = bytes(32)
            self.expected_primary_raw = bytes(255)
            self.expected_primary_raw2 = bytes(64)
            self.expected_primary_aux = bytes(16)
            self.expected_primary_raw_len = 0
            self.expected_primary_raw2_len = 0
            self.expected_primary_aux_len = 0
            self.sha_state = bytes(32)
            self.sha_bitcount = 0
            self.sha_block = bytes(64)
            self.sha_block_len = 0
            self.flags &= ~(
                FLAG_FOCUS_LIVE
                | FLAG_MANIFEST_SHA_OPEN
                | FLAG_HEADER_INSTALLED
            )
            self._m34_fed_bodies = {}
            self._m34_cur = {}
            self.arm_cursor = 0
            self.streamed_members += 1
            return "OK"
        return "INVALID_STATE"

    def _m34f_primary_key(self, value: Optional[bytes]) -> Optional[bytes]:
        """Forward-rebuild the complete primary key from the live Arm A carrier
        body's S4-closed-normalized source raw tuple (§18.15.6/§18.15.8.1)."""
        if value is None or len(value) < 108:
            return None
        ckey = self._m34_cur.get("key")
        if ckey is None:
            return None
        key = bytes(ckey)
        encoded = bytes(value)
        if len(key) < 10 or len(encoded) < 112:
            return None
        role = (int(key[8]) << 8) | int(key[9])
        body = encoded[108:-4]
        owner_kind = _d3s4_s4_source_owner_kind(role, body)
        if (role & 0xFF) == 0x30:
            owner_kind = _d3s4_blob_owner_kind_from_flags(
                role, _d3s4_blob_env_flags(encoded), body
            )
        raw, raw2, aux = _d3s4_s4_extract_source(
            body, role, owner_kind
        )
        info = _d3s4_s4_norm_role_info(role, owner_kind)
        if info is None or not _d3s4_s4_tuple_lengths_ok(
            raw, raw2, aux, role, info
        ):
            return None
        return _d3s4_s4_rebuild_primary_key(
            raw, role, owner_kind, raw2, aux
        )

    def _m34f_install_membership(self, hdr: Dict[str, Any], header_key: bytes) -> Optional[str]:
        if self._m34_feed is not None and self._m34_feed.has_prior_manifest_cache():
            return "m34_prior_session_manifest"
        d3s1 = _load_d3s1()
        m = int(hdr["M"])
        c = int(hdr["C"])
        if m < 1 or m > 256:
            return "m34_M_invalid"
        if c != (m + 7) // 8 or c < 1 or c > 32:
            return "m34_C_invalid"
        self.member_count = m
        self.chunk_count = c
        # Stored header manifest field is the pin; fed chunk bodies must reproduce it
        # via §5.1's domain-separated formula (checked at MEMBERSHIP_DUAL close).
        self.expected_manifest_digest = hdr["manifest"]
        arm = self._m34_cur.get("arm", "A")
        if arm == "A":
            self.membership_need_mask = 0x01
        else:
            self.membership_need_mask = 0x03
        self.found_count_a = 0
        self.found_count_b = 0
        self.membership_i = 0
        self.membership_substep = 0
        self.prev_member_key = bytes(45)
        self.prev_member_key_len = 0
        self._m34_fed_bodies = {}
        self._manifest_sha_init_slots()
        self.flags |= FLAG_MANIFEST_SHA_OPEN | FLAG_HEADER_INSTALLED
        return None

    def _m34f_membership_step(self) -> str:
        d3s1 = _load_d3s1()
        if self.membership_substep == 1:
            # No-get close: framing coverage + final §5.1 manifest SHA vs stored header
            # field + per-target found-counts.
            if self.membership_i != self.member_count:
                return self._m34_fail("membership_i_ne_M")
            c = self.chunk_count
            for cidx in range(c):
                if cidx not in self._m34_fed_bodies:
                    return self._m34_fail("membership_chunk_set_incomplete")
            bodies = [self._m34_fed_bodies[cidx] for cidx in range(c)]
            final = _compute_manifest_digest_v1(bodies)
            if self._manifest_sha_final_from_slots() != final:
                return self._m34_fail("m34_sha_context_divergence")
            if final != self.expected_manifest_digest:
                return self._m34_fail("manifest_sha_mismatch")
            need = self.membership_need_mask
            if (need & 0x01) and self.found_count_a != 1:
                return self._m34_fail(f"found_count_a={self.found_count_a} need=1")
            if (need & 0x02) and self.found_count_b != 1:
                return self._m34_fail(f"found_count_b={self.found_count_b} need=1")
            self.flags &= ~FLAG_MANIFEST_SHA_OPEN
            self.arm_cursor = 6
            return "OK"
        # substep 0: chunk re-get for membership_i.
        if self.drive_gets_used >= self.drive_get_quota:
            self.flags |= FLAG_NEED_RESUME | FLAG_FOCUS_LIVE
            return "OK"
        i = self.membership_i
        req_idx = i // 8
        witness = self.witness_digest
        ckey = _fk_witness_chunk_key(witness, req_idx)
        status, cval = self._m34f_get(ckey, "chunk")
        if status == "ABSENT":
            return self._m34_fail("m34_chunk_absent")
        if status == "FAULT":
            reason = "m34_chunk_fault"
            if self._m34_feed is not None:
                for fl in self._m34_feed.fault_log:
                    shape = fl.get("shape", "")
                    if shape in ("quota_reissue_completed_get",
                                 "dual_first_hit_early_exit",
                                 "per_carrier_arm_bit_set"):
                        reason = shape
                        break
            return self._m34_fail(reason)
        chk = self._m34f_decode_chunk(cval)
        if chk is None:
            return self._m34_fail("m34_chunk_decode")
        ret_idx = chk["chunk_index"]
        if ret_idx != req_idx:
            return self._m34_fail(f"chunk_index_mismatch req={req_idx} got={ret_idx}")
        c = self.chunk_count
        if ret_idx >= c:
            return self._m34_fail("m34_chunk_index_oob_C")
        if chk["witness_digest"] != witness:
            return self._m34_fail("m34_chunk_witness_mismatch")
        if chk["chunk_count"] != c:
            return self._m34_fail("m34_chunk_count_mismatch")
        is_final = ret_idx == (c - 1)
        expected_ec = (self.member_count - 8 * (c - 1)) if is_final else 8
        if chk["entry_count"] != expected_ec:
            return self._m34_fail("m34_entry_count_framing")
        slot = i % 8
        if slot >= len(chk["entries"]):
            return self._m34_fail("m34_slot_oob")
        if i % 8 == 0:
            # Feed exact encoded chunk body once per chunk (§5.1, index order).
            self._m34_fed_bodies[req_idx] = chk["body"]
            self._manifest_sha_update_slots(chk["body"])
        entry = chk["entries"][slot]
        ekey = entry["key"]
        if self.prev_member_key_len > 0 or i > 0:
            prev = self.prev_member_key[: self.prev_member_key_len]
            if ekey == prev:
                return self._m34_fail("m34_member_key_duplicate")
            if ekey <= prev:
                return self._m34_fail("m34_member_key_order")
        self.prev_member_key = ekey[:45].ljust(45, b"\x00")
        self.prev_member_key_len = min(45, len(ekey))
        enew = entry["new_d"]
        need = self.membership_need_mask
        key_a = self.membership_key_a[: self.membership_key_a_len]
        key_b = self.peer_key[: self.peer_key_len]
        if (need & 0x01) and ekey == key_a:
            self.found_count_a = min(2, self.found_count_a + 1)
            if self.found_count_a == 1 and enew != self.pin_digest_a:
                return self._m34_fail("pin_digest_a_mismatch")
        if (need & 0x02) and ekey == key_b:
            self.found_count_b = min(2, self.found_count_b + 1)
            if self.found_count_b == 1:
                if enew != self.pin_digest_b:
                    return self._m34_fail("pin_digest_b_mismatch")
        self.membership_i = i + 1
        if self.membership_i >= self.member_count:
            self.membership_substep = 1
        return "OK"

    def _build_whole_result_candidate(
        self, *, status: str, present: int, disp: int
    ) -> Dict[str, Any]:
        """Fully initialized whole private-result candidate (§18.15.10).

        Field set matches ninlil_domain_scan_result_t (scanner.h) + offsets 52/53.
        """
        cand: Dict[str, Any] = {k: 0 for k in WHOLE_RESULT_FIELD_KEYS}
        cand["adopted"] = 0
        cand["status"] = status
        cand["reopen_required"] = 0
        cand["cleanup_status"] = 0  # null/OK path → zero Storage fault code
        cand["family14_row_count"] = 0
        cand["current_domain_key_count"] = 0
        cand["ok_row_count"] = 0
        cand["recognizable_future_seen"] = 0
        cand["profile_exact_active"] = 0
        cand["profile_mismatch"] = 0
        cand["future_profile_candidate"] = 0
        cand["profile_get_present_mask"] = 0
        cand["family14_iter_seen_mask"] = 0
        cand["d3s4_disposition_present"] = present
        cand["d3s4_disposition"] = disp
        return cand

    def _cleanup_live_iterator(self) -> None:
        """Close the one live S4 iterator before rollback.

        A finding may leave the INTERNAL iterator live.  §18.15.10 owns that
        cleanup in finalize/abort and orders it before rollback.  Keep the
        reference trace honest instead of relying on rollback to hide a live
        iterator.
        """
        feeds = (
            self._m31_32_feed,
            self._m33_feed,
            self._m34_feed,
        )
        live = [
            feed for feed in feeds
            if feed is not None and feed._iter_active
        ]
        if len(live) > 1:
            raise AssertionError("more than one S4 iterator live at cleanup")
        if live:
            live[0].iter_close()
            self._emit_port("iter_close")

    def finalize(
        self,
        out_result: Optional[Dict[str, Any]] = None,
        *,
        cleanup_fail: bool = False,
        alias_overlap: bool = False,
    ) -> Tuple[str, int, int]:
        """§18.15.10 finalize: prevalidate → sample → cleanup → publish → zero.

        Incomplete masks / mid-yield / invalid shape / alias → Port 0, poison intact.
        Cleanup failure → poison unchanged; still zeros S4 context after Port cleanup.
        """
        # R5-003: consume the declared finalize-path fault (op-local ordinal) and derive
        # the finalize-path authority from the consumed shape. This is the only path that
        # sets these flags — the stored finalize call column declares the fault and the
        # RefSession consumes it here, so caller output poison/publication is a call-column
        # execution result (not setup-time metadata).
        _fin_shape = self._consume_finalize_fault("finalize")
        if _fin_shape == "evaluator_off":
            self._evaluator_off = True
        elif _fin_shape == "abort":
            self._whole_result_poison = True
        elif _fin_shape == "cleanup_failure":
            self._cleanup_failed = True
        elif _fin_shape == "abort_cleanup_failure":
            # §5798: abort with cleanup failure — both authorities; out_result left
            # byte-for-byte unchanged regardless of cleanup outcome.
            self._whole_result_poison = True
            self._cleanup_failed = True
        elif _fin_shape == "NULL":
            # §5601: NULL out_result — Port 0, no publish, no cleanup.
            return ("NINLIL_E_INVALID_STATE", 0, 0)
        elif _fin_shape and _fin_shape.startswith("alias_overlap_"):
            # §5798: per-target alias prevalidation — Port 0 before any Port call.
            return ("NINLIL_E_INVALID_STATE", 0, 0)
        elif _fin_shape in (
            "invalid_carrier_present_gt1",
            "invalid_carrier_present0_disp_nonzero",
            "invalid_carrier_present1_disp_gt3",
        ):
            # §5798: session-state invalid carrier — never published, Port 0.
            return ("NINLIL_E_INVALID_STATE", 0, 0)
        elif _fin_shape == "prevalidation_disjoint_violation":
            return ("NINLIL_E_INVALID_STATE", 0, 0)
        elif _fin_shape == "invalid_state_pre_finalize":
            return ("NINLIL_E_INVALID_STATE", 0, 0)
        elif _fin_shape == "incomplete_shape_mid_yield":
            return ("NINLIL_E_INVALID_STATE", 0, 0)
        # Prevalidation: alias / incomplete / mid-yield / non-READY phase → Port 0.
        if self._p11_prevalidation_fail:
            return ("NINLIL_E_INVALID_STATE", 0, 0)
        if self._p11_force_invalid_state:
            return ("NINLIL_E_INVALID_STATE", 0, 0)
        if self._p11_session_carrier is not None:
            pp, dd = self._p11_session_carrier
            if pp > 1 or (pp == 0 and dd != 0) or (pp == 1 and dd > 3):
                return ("NINLIL_E_INVALID_STATE", 0, 0)
        if alias_overlap or self._alias_blocked:
            return ("NINLIL_E_INVALID_STATE", 0, 0)
        if self.flags & FLAG_NEED_RESUME:
            return ("NINLIL_E_INVALID_STATE", 0, 0)
        if self.phase not in (PHASE_COMPLETE, PHASE_FAILED):
            return ("NINLIL_E_INVALID_STATE", 0, 0)

        if self.phase == PHASE_COMPLETE:
            inv = self.validate_state_invariants()
            if inv is not None:
                # Incomplete required mask / illegal deferred shape → RED, Port 0.
                return ("NINLIL_E_INVALID_STATE", 0, 0)
            # A2-b rev3 P11: evaluator-off follows the frozen D2 aggregate path and
            # publishes canonical present=0/disp=0 only when cleanup succeeds.
            if self._evaluator_off:
                self._cleanup_live_iterator()
                self._emit_port("rollback")
                if cleanup_fail or self._cleanup_failed:
                    # A rollback failure consumes the transaction but makes
                    # handle reuse unsafe, so the cleanup tree fences it.
                    self._emit_port("close")
                    self._zero_context()
                    self.session_state = "DONE"
                    return ("NINLIL_E_STORAGE_CORRUPT", 0, 0)
                candidate = self._build_whole_result_candidate(
                    status="NINLIL_OK", present=0, disp=0
                )
                if out_result is not None:
                    out_result.clear()
                    out_result.update(candidate)
                elif self._out_result is not None:
                    self._out_result.clear()
                    self._out_result.update(candidate)
                self._zero_context()
                self.session_state = "DONE"
                return ("NINLIL_OK", 0, 0)
            # Sample scalar disposition BEFORE cleanup.
            disp = derive_disposition(self.flags, self.binding_complete_mask)
            present = 1
            status = "NINLIL_OK"
            candidate = self._build_whole_result_candidate(
                status=status, present=present, disp=disp
            )
        else:
            disp = 0
            present = 0
            status = "NINLIL_E_STORAGE_CORRUPT"
            candidate = self._build_whole_result_candidate(
                status=status, present=present, disp=disp
            )

        # Port cleanup tree.
        self._cleanup_live_iterator()
        self._emit_port("rollback")
        if cleanup_fail or self._cleanup_failed:
            self._emit_port("close")
            # Publish nothing — caller poison unchanged; still zero S4 context.
            self._zero_context()
            self.session_state = "DONE"
            # Cleanup failure discards sampled disposition; non-OK to caller.
            return ("NINLIL_E_STORAGE_CORRUPT", 0, 0)

        # A2-b rev3 P11: whole-result poison — abort/cleanup-failure/invalid carrier
        # leaves every output byte unchanged; publish nothing.
        if self._whole_result_poison:
            self._zero_context()
            self.session_state = "DONE"
            return ("NINLIL_E_STORAGE_CORRUPT", 0, 0)

        # Publish whole-result candidate (single commit-style copy) BEFORE zero.
        if out_result is not None:
            out_result.clear()
            out_result.update(candidate)
        elif self._out_result is not None:
            self._out_result.clear()
            self._out_result.update(candidate)
        self._zero_context()
        self.session_state = "DONE"
        return (status, present, disp)

    def abort(self, out_result: Optional[Dict[str, Any]] = None) -> None:
        """Abort: Port cleanup; never publish; zero context; poison unchanged."""
        _abort_shape = self._consume_finalize_fault("abort")
        if _abort_shape == "abort_cleanup_failure":
            self._cleanup_failed = True
        self._cleanup_live_iterator()
        self._emit_port("rollback")
        if self._cleanup_failed:
            self._emit_port("close")
            # §5601: cleanup failure — poison preserved; context zeroed after Port cleanup.
            pass
        # out_result intentionally untouched (poison invariant).
        self._zero_context()
        self.session_state = "DONE"

    def _zero_context(self) -> None:
        """Zero entire S4 context — every context field, including drive_get_quota."""
        self.phase = PHASE_IDLE
        self.pass_kind = PASS_BASELINE
        self.focus_mode = 0
        self.flags = 0
        self.count_complete_mask = 0
        self.binding_complete_mask = 0
        self.group_class = GROUP_UNSET
        self.arm_cursor = 0
        self.member_substep = 0
        self.membership_substep = 0
        self.membership_need_mask = 0
        self.found_count_a = 0
        self.found_count_b = 0
        self.streamed_members = 0
        self.membership_i = 0
        self.member_count = 0
        self.chunk_count = 0
        self.drive_gets_used = 0
        self.drive_get_quota = 0  # whole-context zero: quota is a context field
        self.entry_action = ENTRY_ACTION_NONE
        self.entry_old_present = 0
        self.entry_new_present = 0
        self.entry_flags = 0
        self.entry_record_role = 0
        self.entry_key_length = 0
        self.expected_primary_raw_len = 0
        self.expected_primary_raw2_len = 0
        self.expected_primary_aux_len = 0
        self.last_carrier_key = bytes(45)
        self.last_carrier_key_len = 0
        self.witness_digest = bytes(32)
        self.expected_manifest_digest = bytes(32)
        self.focus_key_digest = bytes(32)
        self.pin_digest_a = bytes(32)
        self.pin_digest_b = bytes(32)
        self.entry_old_value_digest = bytes(32)
        self.entry_new_value_digest = bytes(32)
        self.entry_prior_head_witness_digest = bytes(32)
        self.expected_primary_pvd = bytes(32)
        self.expected_primary_raw = bytes(255)
        self.expected_primary_raw2 = bytes(64)
        self.expected_primary_aux = bytes(16)
        self.prev_member_key = bytes(45)
        self.prev_member_key_len = 0
        self.peer_key = bytes(45)
        self.peer_key_len = 0
        self.membership_key_a = bytes(45)
        self.membership_key_a_len = 0
        self.sha_state = bytes(32)
        self.sha_bitcount = 0
        self.sha_block = bytes(64)
        self.sha_block_len = 0
        self.entry_record_role = 0
        self._s6_authority_session = False
        self._bit7_session = False

    def context_sizeof(self) -> int:
        return S4_CONTEXT_SIZEOF

    def context_image_hex(self) -> str:
        """R4-006 closed replay: serialize the full 949-byte S4 context (§18.15.12
        layout) to a hex image, sampled at the current call boundary. Aliased slots
        read their owning attribute; multi-byte integers are big-endian per the layout
        table. A production bridge compares this image byte-for-byte after each call."""
        buf = bytearray(S4_CONTEXT_SIZEOF)
        alias_attr = {
            "expected_primary_raw__request_key_scratch": "expected_primary_raw",
            "expected_primary_raw_len__request_key_scratch_len": "expected_primary_raw_len",
            "entry_flags__expected_primary_owner_kind": "entry_flags",
        }
        for offset, size, name in S4_CONTEXT_SLOT_MAP:
            attr = alias_attr.get(name, name)
            val = getattr(self, attr)
            if isinstance(val, (bytes, bytearray)):
                b = bytes(val)[:size]
                buf[offset:offset + len(b)] = b
            else:
                n = int(val)
                if size == 1:
                    buf[offset] = n & 0xFF
                elif size == 2:
                    buf[offset:offset + 2] = (n & 0xFFFF).to_bytes(2, "big")
                else:
                    buf[offset:offset + size] = n.to_bytes(size, "big")
        return bytes(buf).hex()

    def get_budget_for_mode(self) -> Dict[str, Any]:
        if self.mode in (MODE_31, MODE_32):
            return GET_BUDGET_TABLE["31_32_per_header"]
        if self.mode == MODE_33:
            return GET_BUDGET_TABLE["33_chunk_bind"]
        return GET_BUDGET_TABLE["34_arm_a"]

    def validate_state_invariants(self) -> Optional[str]:
        _reach_inc("validate_state_invariants")
        if type(self.phase) is bool or type(self.phase) is not int:
            return f"phase type invalid"
        if self.phase not in PHASE_VALID:
            return f"phase {self.phase} invalid"
        if type(self.pass_kind) is bool or type(self.pass_kind) is not int:
            return f"pass_kind type invalid"
        if self.pass_kind not in PASS_KIND_VALID:
            return f"pass_kind {self.pass_kind} invalid"
        if type(self.focus_mode) is bool or type(self.focus_mode) is not int:
            return f"focus_mode type invalid"
        if self.focus_mode not in FOCUS_MODE_VALID:
            return f"focus_mode {self.focus_mode} invalid"
        _MODE_PHASE_VALID = {
            MODE_31: frozenset({PHASE_IDLE, PHASE_BASELINE, PHASE_SELECT, PHASE_MEMBER_PIPELINE, PHASE_GROUP_CLOSE, PHASE_COMPLETE, PHASE_FAILED}),
            MODE_32: frozenset({PHASE_IDLE, PHASE_BASELINE, PHASE_SELECT, PHASE_MEMBER_PIPELINE, PHASE_GROUP_CLOSE, PHASE_COMPLETE, PHASE_FAILED}),
            MODE_33: frozenset({PHASE_IDLE, PHASE_BASELINE, PHASE_SELECT, PHASE_MODE33_BIND, PHASE_COMPLETE, PHASE_FAILED}),
            MODE_34: frozenset({PHASE_IDLE, PHASE_BASELINE, PHASE_SELECT, PHASE_MODE34_ARM, PHASE_COMPLETE, PHASE_FAILED}),
        }
        if self.phase not in _MODE_PHASE_VALID[self.mode]:
            return f"mode {self.mode} phase {self.phase} invalid (mode×phase closed)"
        if self.phase == PHASE_IDLE:
            if int(self.focus_mode) != 0:
                return f"IDLE focus_mode {self.focus_mode} must be 0"
            if int(self.group_class) != GROUP_UNSET:
                return f"IDLE group_class {self.group_class} must be UNSET"
            if int(self.pass_kind) != PASS_BASELINE:
                return f"IDLE pass_kind {self.pass_kind} must be BASELINE"
            if self.pin_digest_a != bytes(32):
                return "IDLE pin_digest_a must be zero"
            if self.pin_digest_b != bytes(32):
                return "IDLE pin_digest_b must be zero"
        else:
            if int(self.focus_mode) != self.mode:
                return f"active focus_mode {self.focus_mode} != session mode {self.mode}"
            if self.phase in (PHASE_BASELINE,) and int(self.pass_kind) != PASS_BASELINE:
                return f"BASELINE pass_kind {self.pass_kind} must be BASELINE"
            if self.phase in (PHASE_SELECT, PHASE_MEMBER_PIPELINE, PHASE_GROUP_CLOSE, PHASE_MODE33_BIND, PHASE_MODE34_ARM, PHASE_COMPLETE) and int(self.pass_kind) != PASS_INTERNAL:
                return f"phase {self.phase} pass_kind {self.pass_kind} must be INTERNAL"
        # A2B-R6-006: COMPLETE_READY is derivable only from a completed traversal
        # (§5704: flags.bit3 only COMPLETE_READY, never before the COMPLETE
        # transition). Any pre-COMPLETE phase carrying bit3 is terminal corruption.
        if self.phase != PHASE_COMPLETE and (int(self.flags) & FLAG_COMPLETE_READY):
            return f"phase {self.phase} carries COMPLETE_READY (bit3) before COMPLETE"
        if type(self.group_class) is bool or type(self.group_class) is not int:
            return f"group_class type invalid"
        if self.group_class not in GROUP_CLASS_VALID:
            return f"group_class {self.group_class} invalid"
        if type(self.member_substep) is bool or type(self.member_substep) is not int:
            return f"member_substep type invalid"
        if self.member_substep not in MEMBER_SUBSTEP_VALID:
            return f"member_substep {self.member_substep} invalid"
        if type(self.membership_substep) is bool or type(self.membership_substep) is not int:
            return f"membership_substep type invalid"
        if self.membership_substep not in MEMBERSHIP_SUBSTEP_VALID:
            return f"membership_substep {self.membership_substep} invalid"
        if type(self.membership_need_mask) is bool or type(self.membership_need_mask) is not int:
            return f"membership_need_mask type invalid"
        if self.membership_need_mask not in MEMBERSHIP_NEED_MASK_VALID:
            return f"membership_need_mask {self.membership_need_mask} invalid"
        if type(self.found_count_a) is bool or type(self.found_count_a) is not int:
            return f"found_count_a type invalid"
        if self.found_count_a not in FOUND_COUNT_VALID:
            return f"found_count_a {self.found_count_a} invalid"
        if type(self.found_count_b) is bool or type(self.found_count_b) is not int:
            return f"found_count_b type invalid"
        if self.found_count_b not in FOUND_COUNT_VALID:
            return f"found_count_b {self.found_count_b} invalid"
        if type(self.entry_action) is bool or type(self.entry_action) is not int:
            return f"entry_action type invalid"
        if self.entry_action not in ENTRY_ACTION_VALID:
            return f"entry_action {self.entry_action} invalid"
        if type(self.entry_old_present) is bool or type(self.entry_old_present) is not int:
            return f"entry_old_present type invalid"
        if self.entry_old_present not in ENTRY_PRESENT_VALID:
            return f"entry_old_present {self.entry_old_present} invalid"
        if type(self.entry_new_present) is bool or type(self.entry_new_present) is not int:
            return f"entry_new_present type invalid"
        if self.entry_new_present not in ENTRY_PRESENT_VALID:
            return f"entry_new_present {self.entry_new_present} invalid"
        if type(self.entry_flags) is bool or type(self.entry_flags) is not int:
            return f"entry_flags type invalid"
        if self.entry_flags not in (0, 1, 2, 3):
            return f"entry_flags {self.entry_flags} invalid"
        if type(self.entry_record_role) is bool or type(self.entry_record_role) is not int:
            return f"entry_record_role type invalid ({type(self.entry_record_role).__name__})"
        role = self.entry_record_role
        if role < 0 or role > 0xFFFF:
            return f"entry_record_role {role:#x} invalid"
        if role != 0:
            fam_r, st_r = (role >> 8) & 0xFF, role & 0xFF
            # High byte 0 with non-zero role is never a legal family/subtype form
            # (closed-count dual-use of this slot is forbidden by §18.15.12).
            if fam_r == 5:
                if st_r != 0x01:
                    return f"entry_record_role {role:#x} invalid"
            elif fam_r == 6:
                if st_r not in {
                    0x10, 0x11, 0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27,
                    0x30, 0x31, 0x32, 0x33, 0x34, 0x40, 0x41, 0x42, 0x50, 0x51, 0x52,
                    0x60, 0x61, 0x62, 0x63, 0x64, 0x7D, 0x7E, 0x7F,
                }:
                    return f"entry_record_role {role:#x} invalid"
            elif fam_r in (3, 4):
                if st_r not in (0,):
                    return f"entry_record_role {role:#x} invalid"
            else:
                return f"entry_record_role {role:#x} invalid"
        if type(self.entry_key_length) is bool or type(self.entry_key_length) is not int:
            if not isinstance(self.entry_key_length, int) or isinstance(self.entry_key_length, bool):
                return f"entry_key_length type invalid ({type(self.entry_key_length).__name__})"
        kl = int(self.entry_key_length)
        if kl not in ({0, 10} | set(range(13, 46))):
            return f"entry_key_length {kl} invalid"
        raw_len = int(self.expected_primary_raw_len)
        if raw_len < 0 or raw_len > 255:
            return f"expected_primary_raw_len {raw_len} invalid"
        r2 = int(self.expected_primary_raw2_len)
        if r2 < 0 or r2 > 64:
            return f"expected_primary_raw2_len {r2} invalid"
        ax = int(self.expected_primary_aux_len)
        if ax < 0 or ax > 16:
            return f"expected_primary_aux_len {ax} invalid"
        pklen = int(getattr(self, "peer_key_len", 0) or 0)
        if pklen < 0 or pklen > 45:
            return f"peer_key_len {pklen} invalid"
        # §18.15.12 phase-disjoint lifetime + role/key grammar + length/data combos
        # IDLE / whole-context zero: entry scratch + primary pins must be cleared.
        if self.phase == PHASE_IDLE:
            if role != 0:
                return f"IDLE entry_record_role {role:#x} must be 0"
            if int(self.entry_flags) != 0:
                return f"IDLE entry_flags {self.entry_flags} must be 0"
            if kl != 0:
                return f"IDLE entry_key_length {kl} must be 0"
            if raw_len != 0:
                return f"IDLE expected_primary_raw_len {raw_len} must be 0"
            if r2 != 0:
                return f"IDLE expected_primary_raw2_len {r2} must be 0"
            if ax != 0:
                return f"IDLE expected_primary_aux_len {ax} must be 0"
            if pklen != 0:
                return f"IDLE peer_key_len {pklen} must be 0"
            if int(self.entry_action) != ENTRY_ACTION_NONE:
                return f"IDLE entry_action {self.entry_action} must be NONE"
            if int(self.entry_old_present) != 0:
                return f"IDLE entry_old_present {self.entry_old_present} must be 0"
            if int(self.entry_new_present) != 0:
                return f"IDLE entry_new_present {self.entry_new_present} must be 0"
            if self.expected_primary_pvd != bytes(32):
                return "IDLE expected_primary_pvd must be zero"
            if self.peer_key != bytes(45):
                return "IDLE peer_key buffer must be zero"
            if self.expected_primary_raw != bytes(255):
                return "IDLE expected_primary_raw buffer must be zero"
            if self.count_complete_mask != 0:
                return f"IDLE count_complete_mask {self.count_complete_mask:#x} must be 0"
            if self.binding_complete_mask != 0:
                return f"IDLE binding_complete_mask {self.binding_complete_mask:#x} must be 0"
            if int(self.arm_cursor) != 0:
                return f"IDLE arm_cursor {self.arm_cursor} must be 0"
            if int(self.member_substep) != 0:
                return f"IDLE member_substep {self.member_substep} must be 0"
            if int(self.membership_substep) != 0:
                return f"IDLE membership_substep {self.membership_substep} must be 0"
            if int(self.found_count_a) != 0:
                return f"IDLE found_count_a {self.found_count_a} must be 0"
            if int(self.found_count_b) != 0:
                return f"IDLE found_count_b {self.found_count_b} must be 0"
            if int(self.membership_need_mask) != 0:
                return f"IDLE membership_need_mask {self.membership_need_mask} must be 0"
            if self.flags != 0:
                return f"IDLE flags {self.flags:#x} must be 0"
            if int(self.membership_i) != 0:
                return f"IDLE membership_i {self.membership_i} must be 0"
            if int(self.streamed_members) != 0:
                return f"IDLE streamed_members {self.streamed_members} must be 0"
            if self.expected_primary_raw2 != bytes(64):
                return "IDLE expected_primary_raw2 must be zero"
            if self.expected_primary_aux != bytes(16):
                return "IDLE expected_primary_aux must be zero"
            if self.sha_state != bytes(32):
                return "IDLE sha_state must be zero"
            if self.sha_block != bytes(64):
                return "IDLE sha_block must be zero"
            if int(self.sha_block_len) != 0:
                return f"IDLE sha_block_len {self.sha_block_len} must be 0"
        else:
            # role/key grammar while non-IDLE entry scratch may be live
            if role == 0:
                if kl != 0:
                    return f"role0 entry_key_length {kl} invalid"
            else:
                fam_r2, st_r2 = (role >> 8) & 0xFF, role & 0xFF
                if fam_r2 in (3, 4):
                    if kl not in (0, 10):
                        return f"fam{fam_r2} entry_key_length {kl} invalid"
                    if st_r2 != 0:
                        return f"entry_record_role {role:#x} fam3/4 low must be 0"
                elif fam_r2 in (5, 6):
                    if kl not in ({0} | set(range(13, 46))):
                        return f"fam{fam_r2} entry_key_length {kl} invalid"
            # primary-live length/data: non-zero raw implies peer_key_len in grammar
            if raw_len > 0:
                if pklen < 13 or pklen > 45:
                    return (
                        f"primary-live raw_len={raw_len} requires "
                        f"peer_key_len 13..45 got {pklen}"
                    )
                if role == 0:
                    return "primary-live raw_len>0 requires non-zero entry_record_role"
            if pklen > 0 and pklen < 13 and pklen != 10:
                return f"peer_key_len {pklen} not in key grammar"
            # Isolated raw2/aux without primary-live shape is illegal.
            primary_live = (
                (self.phase == PHASE_MEMBER_PIPELINE and self.member_substep == 2)
                or (self.phase == PHASE_MODE34_ARM and self.arm_cursor == 1)
            )
            if (r2 != 0 or ax != 0) and not primary_live and raw_len == 0:
                return (
                    f"isolated raw2/aux lengths raw2={r2} aux={ax} without primary-live"
                )
            # substep2 requires primary pins present together + PVD non-zero.
            if self.phase == PHASE_MEMBER_PIPELINE and self.member_substep == 2:
                if raw_len == 0 or pklen == 0 or role == 0:
                    return (
                        f"substep2 primary pins missing raw_len={raw_len} "
                        f"peer_key_len={pklen} role={role:#x}"
                    )
                if self.expected_primary_pvd == bytes(32):
                    return "substep2 primary-live requires non-zero expected_primary_pvd"
            if self.phase == PHASE_MODE34_ARM and self.arm_cursor == 1:
                if raw_len == 0 or pklen == 0 or role == 0:
                    return (
                        f"arm_cursor1 primary pins missing raw_len={raw_len} "
                        f"peer_key_len={pklen} role={role:#x}"
                    )
                if self.expected_primary_pvd == bytes(32):
                    return "arm_cursor1 primary-live requires non-zero expected_primary_pvd"
            # MEMBER_PIPELINE substep0: primary tuple must be cleared.
            if self.phase == PHASE_MEMBER_PIPELINE and self.member_substep == 0:
                if raw_len != 0 or pklen != 0 or role != 0 or r2 != 0 or ax != 0:
                    return (
                        f"substep0 primary tuple must be cleared "
                        f"raw_len={raw_len} peer_key_len={pklen} role={role:#x}"
                    )
            # GROUP_CLOSE: primary tuple must be cleared before close.
            if self.phase == PHASE_GROUP_CLOSE:
                if raw_len != 0 or pklen != 0 or role != 0 or r2 != 0 or ax != 0:
                    return (
                        f"GROUP_CLOSE primary tuple must be cleared "
                        f"raw_len={raw_len} peer_key_len={pklen} role={role:#x}"
                    )
            # SELECT/BASELINE: no entry/primary live between headers.
            if self.phase in (PHASE_BASELINE, PHASE_SELECT):
                if role != 0:
                    return f"phase {self.phase} entry_record_role {role:#x} must be 0"
                if kl != 0:
                    return f"phase {self.phase} entry_key_length {kl} must be 0"
                if int(self.entry_action) != ENTRY_ACTION_NONE:
                    return f"phase {self.phase} entry_action {self.entry_action} must be NONE"
                if self.member_substep == 0 and (raw_len != 0 or pklen != 0 or r2 != 0 or ax != 0):
                    return (
                        f"phase {self.phase} substep0 primary pins "
                        f"raw_len={raw_len} peer_key_len={pklen} must be 0"
                    )
        if type(self.flags) is bool or type(self.flags) is not int or self.flags < 0 or self.flags > 255:
            return f"flags {self.flags} not u8"
        if type(self.count_complete_mask) is bool or type(self.count_complete_mask) is not int or self.count_complete_mask < 0 or self.count_complete_mask > 255:
            return f"count_complete_mask {self.count_complete_mask} not u8"
        if type(self.binding_complete_mask) is bool or type(self.binding_complete_mask) is not int or self.binding_complete_mask < 0 or self.binding_complete_mask > 255:
            return f"binding_complete_mask {self.binding_complete_mask} not u8"
        if self.count_complete_mask & COUNT_MBZ:
            return f"count_complete_mask MBZ bits set: {self.count_complete_mask:#x}"
        if self.binding_complete_mask & BINDING_MBZ:
            return f"binding_complete_mask MBZ bits set: {self.binding_complete_mask:#x}"
        if self.phase not in (PHASE_IDLE, PHASE_COMPLETE) and self.count_complete_mask != 0:
            _allowed_pre = {MODE_31: 0, MODE_32: 0, MODE_33: 0, MODE_34: COUNT_BIT_M34}
            if self.count_complete_mask & ~_allowed_pre.get(self.mode, 0):
                return f"pre-COMPLETE count mask {self.count_complete_mask:#x} has non-owned bits"
        if self.phase not in (PHASE_IDLE, PHASE_COMPLETE) and self.binding_complete_mask != 0:
            _allowed_bind_pre = {MODE_31: 0, MODE_32: 0, MODE_33: BINDING_BIT_M33, MODE_34: 0x1F}
            if self.binding_complete_mask & ~_allowed_bind_pre.get(self.mode, 0) & ~BINDING_BIT_S6_REQUIRED:
                return f"pre-COMPLETE binding mask {self.binding_complete_mask:#x} has non-owned bits"
        if self.mode in (MODE_31, MODE_32):
            if self.arm_cursor not in ARM_CURSOR_VALID_M31_32:
                return f"arm_cursor {self.arm_cursor} invalid for mode {self.mode}"
        elif self.mode == MODE_33:
            if self.arm_cursor not in ARM_CURSOR_VALID_M33:
                return f"arm_cursor {self.arm_cursor} invalid for mode 33"
        elif self.mode == MODE_34:
            if self.arm_cursor not in ARM_CURSOR_VALID_M34:
                return f"arm_cursor {self.arm_cursor} invalid for mode 34"
        # quota: fresh BASELINE immediately after begin remains zero; the
        # first drive installs exact 1..256 (§18.15.5). IDLE is whole-zero.
        if self.phase == PHASE_BASELINE and self.drive_get_quota == 0:
            if self.drive_gets_used != 0:
                return (
                    f"fresh BASELINE drive_gets_used "
                    f"{self.drive_gets_used} must be 0"
                )
        elif self.phase != PHASE_IDLE:
            if self.drive_get_quota < 1 or self.drive_get_quota > 256:
                return f"drive_get_quota {self.drive_get_quota} out of range"
            if self.drive_gets_used < 0:
                return f"drive_gets_used {self.drive_gets_used} invalid"
            if self.drive_gets_used > self.drive_get_quota:
                return f"drive_gets_used {self.drive_gets_used} > quota {self.drive_get_quota}"
        else:
            if self.drive_get_quota != 0:
                return f"drive_get_quota {self.drive_get_quota} invalid at IDLE"
            if self.drive_gets_used != 0:
                return f"drive_gets_used {self.drive_gets_used} invalid at IDLE"
        if not isinstance(self.sha_block_len, int) or self.sha_block_len < 0 or self.sha_block_len > 63:
            return f"sha_block_len {self.sha_block_len} invalid"
        if self.phase == PHASE_COMPLETE:
            if (self.flags & FLAG_COMPLETE_READY) and (self.flags & FLAG_S5_REQUIRED_SEEN):
                return "COMPLETE_READY and bit7 mutually exclusive"
            if (self.flags & FLAG_COMPLETE_READY) and (self.binding_complete_mask & BINDING_BIT_S6_REQUIRED):
                return "COMPLETE_READY and bit5 mutually exclusive"
        if self.phase == PHASE_COMPLETE:
            count_req, binding_req, _, _allowed_def_bind = MODE_REQUIRED_MASKS[self.mode]
            if (self.count_complete_mask & count_req) != count_req:
                return f"mode {self.mode} missing required count mask bits"
            if (self.binding_complete_mask & binding_req) != binding_req:
                return f"mode {self.mode} missing required binding mask bits"
            extra_count = self.count_complete_mask & ~count_req & ~COUNT_MBZ
            if extra_count:
                return f"mode {self.mode} extra count bits: {extra_count:#x}"
            # Extra non-deferred binding bits (e.g. Mode31 with Mode34 arm bits) forbidden.
            non_def_bind = self.binding_complete_mask & ~BINDING_BIT_S6_REQUIRED & ~BINDING_MBZ
            if non_def_bind != binding_req:
                return (
                    f"mode {self.mode} binding shape {non_def_bind:#x} "
                    f"!= required {binding_req:#x}"
                )
            # Closed deferred (bit7, bit5) shapes per mode (§18.15.10 / §18.15.12).
            bit7 = 1 if (self.flags & FLAG_S5_REQUIRED_SEEN) else 0
            bit5 = 1 if (self.binding_complete_mask & BINDING_BIT_S6_REQUIRED) else 0
            deferred_shape = (bit7, bit5)
            allowed_deferred = {
                MODE_31: frozenset({(0, 0), (1, 1)}),  # (1,0)/(0,1) illegal
                MODE_32: frozenset({(0, 0), (1, 0), (1, 1)}),  # (0,1) alone illegal
                MODE_33: frozenset({(0, 0), (0, 1)}),  # bit7 always 0
                MODE_34: frozenset({(0, 0)}),  # no deferred
            }
            if deferred_shape not in allowed_deferred[self.mode]:
                return (
                    f"mode {self.mode} illegal deferred shape "
                    f"(bit7,bit5)={deferred_shape}"
                )
            if bit7 and bit5 and self.flags & FLAG_COMPLETE_READY:
                return "COMPLETE_READY with deferred bits"
        if self.phase != PHASE_IDLE:
            if self.mode in (MODE_33, MODE_34) and self.member_substep != 0 and self.phase == PHASE_SELECT:
                return f"mode {self.mode} SELECT member_substep {self.member_substep} must be 0"
            if self.mode in (MODE_31, MODE_32, MODE_33) and self.membership_substep != 0:
                return f"mode {self.mode} membership_substep {self.membership_substep} invalid"
            if self.mode in (MODE_31, MODE_32) and self.phase not in (PHASE_MEMBER_PIPELINE, PHASE_GROUP_CLOSE) and self.found_count_a != 0:
                return f"mode {self.mode} phase {self.phase} found_count_a {self.found_count_a} must be 0"
            _raw_buf = self.expected_primary_raw
            if raw_len > 0 and isinstance(_raw_buf, bytes) and _raw_buf[:raw_len] == bytes(raw_len):
                return f"raw_len={raw_len} but buffer prefix all zero"
            if raw_len == 0 and isinstance(_raw_buf, bytes) and _raw_buf != bytes(255):
                return "raw_len=0 but buffer non-zero"
            if pklen > 0 and isinstance(self.peer_key, bytes) and self.peer_key[:pklen] == bytes(pklen):
                return f"peer_key_len={pklen} but key prefix all zero"
            if int(self.entry_flags) == 3:
                _primary_live_ef = (
                    (self.phase == PHASE_MEMBER_PIPELINE and self.member_substep == 2)
                    or (self.phase == PHASE_MODE34_ARM and self.arm_cursor == 1)
                )
                if not _primary_live_ef:
                    return f"entry_flags=3 outside primary-live (phase={self.phase} substep={self.member_substep})"
            if int(self.entry_action) == ENTRY_ACTION_CREATE:
                if int(self.entry_old_present) != 0 or int(self.entry_new_present) != 1:
                    if int(self.entry_old_present) != 0 or int(self.entry_new_present) != 0:
                        return f"CREATE requires old=0/new=1 got old={self.entry_old_present}/new={self.entry_new_present}"
            if int(self.entry_action) == ENTRY_ACTION_ERASE:
                if int(self.entry_old_present) != 1 or int(self.entry_new_present) != 0:
                    if int(self.entry_old_present) != 0 or int(self.entry_new_present) != 0:
                        return f"ERASE requires old=1/new=0 got old={self.entry_old_present}/new={self.entry_new_present}"
            # A finalized manifest comparison operates on a copy of the
            # incremental SHA context.  Therefore sha_state/bitcount/block and
            # sha_block_len intentionally remain as closed-session residue
            # after MANIFEST_SHA_OPEN is cleared (Modes31/32 GROUP_CLOSE and
            # Mode34 carrier close).  A non-zero block length without the OPEN
            # flag is consequently legal and is observable in the fixed S4
            # context image.
            _primary_live_now = (
                (self.phase == PHASE_MEMBER_PIPELINE and self.member_substep == 2)
                or (self.phase == PHASE_MODE34_ARM and self.arm_cursor == 1)
            )
            if _primary_live_now:
                if not isinstance(self.expected_primary_pvd, bytes) or len(self.expected_primary_pvd) != 32:
                    return f"expected_primary_pvd must be exact 32 bytes got {type(self.expected_primary_pvd).__name__} len={len(self.expected_primary_pvd) if isinstance(self.expected_primary_pvd, bytes) else '?'}"
                _role_st = role & 0xFF if role != 0 else 0
                if _role_st in (0x24, 0x25) and r2 == 0:
                    return f"role 0x{role:04x} requires raw2 (dual RAW16) but raw2_len=0"
            if int(self.member_count) > 256 or int(self.member_count) < 0:
                return f"member_count {self.member_count} out of u16/M range"
            if int(self.streamed_members) < 0:
                return f"streamed_members {self.streamed_members} negative"
            if int(self.membership_i) < 0:
                return f"membership_i {self.membership_i} negative"
            if self.mode == MODE_34 and self.phase == PHASE_MODE34_ARM:
                if int(self.membership_need_mask) == 0 and int(self.found_count_a) != 0:
                    return f"need_mask=0 but found_count_a={self.found_count_a}"
                if int(self.membership_need_mask) & 1 and self.pin_digest_a == bytes(32):
                    return "need_mask bit0 but pin_digest_a zero"
                if int(self.membership_need_mask) & 2 and self.pin_digest_b == bytes(32):
                    return "need_mask bit1 but pin_digest_b zero"
                if self.pin_digest_a != bytes(32) and self.pin_digest_a == self.pin_digest_b:
                    return "pin_digest_a == pin_digest_b (alias forbidden)"
            if self.phase in (PHASE_SELECT, PHASE_BASELINE) and int(self.group_class) != GROUP_UNSET:
                return f"phase {self.phase} group_class {self.group_class} must be UNSET"
            if self.phase == PHASE_MEMBER_PIPELINE and self.member_substep == 1:
                if raw_len != 0 or pklen != 0 or role != 0:
                    return f"substep1 primary tuple must not be live raw_len={raw_len} pklen={pklen} role={role:#x}"
        if self.phase == PHASE_COMPLETE:
            _has_ready = bool(self.flags & FLAG_COMPLETE_READY)
            _has_deferred = bool(self.flags & FLAG_S5_REQUIRED_SEEN) or bool(self.binding_complete_mask & BINDING_BIT_S6_REQUIRED)
            if not _has_ready and not _has_deferred:
                return "COMPLETE without READY or deferred bits"
        return None


# ===========================================================================
# A2-a2 independent fail-closed gates (D3-S3 R19–R27 style; §18.15)
# ===========================================================================
#
# (i)  D1 coverage / boundary / differential for every used family/subtype/
#      body variant: Mode17 reverse secondaries + Mode34 Arm A semantic +
#      witness/BLOB/f3/f4 (full catalog, not a sample of 12).
# (ii) Closed classifier matrix: full product action × local × head ×
#      predecessor lifecycle × fold; legal set closed from §18.15.6+§18.6;
#      remainder RED. Matrix SHA pin + runtime re-derive compare.
# (iii) phase / mask / enum / MBZ full invalid-value domain (§18.15.12
#      :5678-5704) including role/alias/key/raw length·data.
# (iv) CLI generate/check/emit-c-fixture/self-test fail-closed complete net
#      with content-fixed expected diagnostics + validator reachability.
#
# Each gate owns a permanent mutation self-test (tamper → RED).

# ---------------------------------------------------------------------------
# (i) §18.15 used family / subtype / body-variant catalog (closed)
# ---------------------------------------------------------------------------

# body_variant:
#   BLOB 0x30: common flags 1=manifest / 2=chunk
#   HEAD_INDEX 0x7d: index_state 1=BASELINE / 2=WITNESSED
#   others: 0 (single body shape)
# role_tag is a stable machine id for coverage/mutation pins.
#
# Closed used set = Mode17 reverse secondaries + primaries for S4 normalization
# + Mode34 Arm A family5/6 semantic catalog (D2: 10,11,20-27,30-34,40-42,50-52,
# 60-64) + Arm B HEAD_INDEX + Arm C family3/4 kinds + Modes31-33 witness carriers.

_D3S4_F6_SEMANTIC: Tuple[Tuple[int, str], ...] = (
    (0x10, "SERVICE"),
    (0x11, "SERVICE_QUOTA"),
    (0x20, "TRANSACTION_ANCHOR"),
    (0x21, "TRANSACTION_SEQUENCE_INDEX"),
    (0x22, "TRANSACTION_STATE"),
    (0x23, "RESERVATION"),
    (0x24, "IDEMPOTENCY_MAP"),
    (0x25, "EVENT_ID_MAP"),
    (0x26, "SCHEDULER_OWNER"),
    (0x27, "ORDERED_INGRESS"),
    (0x31, "ATTEMPT"),
    (0x32, "EVIDENCE_CELL"),
    (0x33, "CANCEL_STATE"),
    (0x34, "ATTEMPT_ID_INDEX"),
    (0x40, "DELIVERY"),
    (0x41, "RESULT_CACHE"),
    (0x42, "REVERSE_REPLY"),
    (0x50, "EVENT_SPOOL"),
    (0x51, "RETRY_SUMMARY"),
    (0x52, "MANAGEMENT_LEDGER"),
    (0x60, "BEARER_STATE"),
    (0x61, "RETENTION_BASIS"),
    (0x62, "CLOCK_BASELINE"),
    (0x63, "CLEANUP_PLAN"),
    (0x64, "ATTEMPT_REUSE_FENCE"),
)

# Mode17 reverse sources + primary-normalization targets → Modes 31/32/34
_M17_OR_PRIMARY_ST: FrozenSet[int] = frozenset({
    0x10, 0x11, 0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27,
    0x31, 0x32, 0x33, 0x34, 0x40, 0x41, 0x42, 0x50, 0x51, 0x52, 0x61, 0x63,
})


def _build_used_variants() -> Tuple[Tuple[int, int, int, str, FrozenSet[int]], ...]:
    rows: List[Tuple[int, int, int, str, FrozenSet[int]]] = [
        (6, 0x7F, 0, "WITNESS_HEADER", frozenset({31, 32, 33})),
        (6, 0x7E, 0, "WITNESS_MANIFEST_CHUNK", frozenset({31, 32, 33})),
        (6, 0x7D, 1, "HEAD_INDEX_BASELINE", frozenset({34})),
        (6, 0x7D, 2, "HEAD_INDEX_WITNESSED", frozenset({34})),
    ]
    for k in range(1, 5):
        rows.append((3, k, 0, f"FAMILY3_COUNTER_{k}", frozenset({34})))
    for k in range(1, 12):
        rows.append((4, k, 0, f"FAMILY4_CAPACITY_{k}", frozenset({34})))
    rows.append((5, 0x01, 0, "FAMILY5_INTERNAL_INVARIANT", frozenset({34})))
    rows.append((6, 0x30, 1, "BLOB_MANIFEST", frozenset({31, 32, 34})))
    rows.append((6, 0x30, 2, "BLOB_CHUNK", frozenset({31, 32, 34})))
    for st, tag in _D3S4_F6_SEMANTIC:
        modes = frozenset({31, 32, 34}) if st in _M17_OR_PRIMARY_ST else frozenset({34})
        rows.append((6, st, 0, tag, modes))
    return tuple(rows)


D3S4_USED_VARIANTS: Tuple[Tuple[int, int, int, str, FrozenSet[int]], ...] = _build_used_variants()
D3S4_USED_VARIANT_TAGS: FrozenSet[str] = frozenset(t[3] for t in D3S4_USED_VARIANTS)
D3S4_USED_VARIANT_COUNT = len(D3S4_USED_VARIANTS)
# Closed family6 subtype set (all body variants collapsed).
D3S4_USED_FAMILY6_ST: FrozenSet[int] = frozenset(
    st for fam, st, _bv, _t, _m in D3S4_USED_VARIANTS if fam == 6
)

# d3s3 R19–R27 used-family6 set (typed 74/60, body_decode 306/0/306 authority).
D3S3_D1_USED_FAMILY6: FrozenSet[int] = frozenset(
    {0x20, 0x22, 0x27, 0x30, 0x32, 0x33, 0x40, 0x41, 0x42, 0x50}
)


def _used_variants_payload() -> str:
    rows = sorted(
        f"{tag}|{fam:02x}|{st:02x}|{bv}"
        for fam, st, bv, tag, _modes in D3S4_USED_VARIANTS
    )
    return "|".join(rows)


def _bake_used_variants_pin() -> str:
    return hashlib.sha256(_used_variants_payload().encode()).hexdigest()


# HARDCODED pin — must not be reassigned from live catalog at import.
# Catalog mutation without coordinated pin update → RED.
D3S4_USED_VARIANTS_SHA256 = (
    "2cd811b99bb9c5d1eacc6f2c3ff02a9d3e64f9ceabc2f20ec50df5ca399fa698"
)
D3S4_USED_VARIANT_COUNT_PIN = 47

_d3s1_mod: Any = None
_d3s3_mod: Any = None


def _load_d3s1() -> Any:
    """Load pure d3s1 helpers (no production C). Cached."""
    global _d3s1_mod
    if _d3s1_mod is not None:
        return _d3s1_mod
    spec = importlib.util.spec_from_file_location("d3s1_gen_d3s4", D3S1_GEN)
    if spec is None or spec.loader is None:
        raise SystemExit("error: cannot load d3s1 generator helpers")
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    _d3s1_mod = m
    return m


def _load_d3s3_d1() -> Any:
    """Load d3s3 independent D1 gate (R19–R27). Cached. No production C."""
    global _d3s3_mod
    if _d3s3_mod is not None:
        return _d3s3_mod
    path = REPO / "tools" / "domain_scan_crossrow_d3s3_vector_gen.py"
    spec = importlib.util.spec_from_file_location("d3s3_gen_d3s4_d1", path)
    if spec is None or spec.loader is None:
        raise SystemExit("error: cannot load d3s3 D1 gate")
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    _d3s3_mod = m
    return m


_d1_doc_cache: Optional[Dict[str, Any]] = None


def _load_d1_authority() -> Dict[str, Any]:
    """Load domain-store-v1.json under SHA/format/count pins (R19 style)."""
    global _d1_doc_cache
    if _d1_doc_cache is not None:
        return _d1_doc_cache
    if not D1_PATH.is_file():
        raise SystemExit(f"error: missing D1 authority {D1_PATH}")
    raw = D1_PATH.read_bytes()
    if hashlib.sha256(raw).hexdigest() != D1_SHA:
        raise SystemExit("error: D1 sha pin mismatch")
    doc = json.loads(raw)
    if doc.get("format") != D1_FORMAT or len(doc.get("vectors", [])) != D1_COUNT:
        raise SystemExit("error: D1 format/count pin mismatch")
    _d1_doc_cache = doc
    return doc


def _d1_be16(n: int) -> bytes:
    return struct.pack(">H", n & 0xFFFF)


def d3s4_d1_key_family_subtype(key: bytes) -> Optional[Tuple[int, int]]:
    if not isinstance(key, (bytes, bytearray)) or len(key) < 10:
        return None
    if bytes(key[:8]) != DOMAIN_KEY_ROOT:
        return None
    return int(key[8]), int(key[9])


def d3s4_d1_variant_tag(family: int, subtype: int, body_variant: int) -> Optional[str]:
    for fam, st, bv, tag, _m in D3S4_USED_VARIANTS:
        if fam == family and st == subtype and bv == body_variant:
            return tag
    return None


def _d3s4_domain_key_ok(key: bytes) -> Optional[str]:
    """Family5/6 complete key grammar (docs/17 §5.1)."""
    if not (13 <= len(key) <= 45):
        return "domain_key_len"
    if key[:8] != DOMAIN_KEY_ROOT:
        return "root"
    fam, st, kf, ik, il = key[8], key[9], key[10], key[11], key[12]
    if kf != 1:
        return "key_format"
    if 13 + il != len(key):
        return "identity_len_field"
    if fam not in (5, 6):
        return "domain_family"
    if fam == 6 and st not in D3S4_USED_FAMILY6_ST:
        return f"subtype_unlisted_0x{st:02x}"
    if fam == 5 and st != 0x01:
        return "fam5_subtype_unlisted"
    want = {1: 0, 2: 16, 3: 8, 4: 32, 5: 32}.get(ik)
    if want is None or il != want:
        return "identity_kind_len"
    return None


def _d3s4_nlr1_framing_ok(value: bytes) -> Optional[str]:
    """NLR1 magic/version/length/CRC (docs/17 §4)."""
    if not isinstance(value, (bytes, bytearray)) or len(value) < 16:
        return "value_short"
    v = bytes(value)
    if v[:4] != b"NLR1":
        return "not_nlr1"
    rver = int.from_bytes(v[6:8], "big")
    plen = int.from_bytes(v[8:12], "big")
    if rver != 1:
        return "record_version"
    if plen > 4096 or len(v) != 12 + plen + 4:
        return "envelope_len"
    d3s1 = _load_d3s1()
    try:
        if d3s1.crc32c(v[:-4]) != struct.unpack(">I", v[-4:])[0]:
            return "crc"
    except Exception:
        return "crc"
    return None


def _d3s4_common_header_ok(
    value: bytes, *, expect_subtype: int, expect_record_type: int
) -> Optional[str]:
    err = _d3s4_nlr1_framing_ok(value)
    if err is not None:
        return err
    rtype = int.from_bytes(value[4:6], "big")
    plen = int.from_bytes(value[8:12], "big")
    if rtype != expect_record_type:
        return "record_type"
    if plen < 96:
        return "payload_lt_common"
    if int.from_bytes(value[12:14], "big") != 1:
        return "domain_format"
    if value[14] != (expect_subtype & 0xFF):
        return "subtype_mismatch"
    body_len = int.from_bytes(value[104:108], "big")
    if body_len != plen - 96 or 108 + body_len + 4 != len(value):
        return "body_framing"
    if int.from_bytes(value[16:24], "big") < 1:
        return "revision0"
    return None


def d3s4_d1_chunk_body_prefix_ok(body: bytes) -> Optional[str]:
    """§18.15.3 / §5 WITNESS_MANIFEST_CHUNK body prefix local shape (40 B only)."""
    if len(body) < 40:
        return "chunk_body_short"
    wdig = body[0:32]
    if wdig == D1_ZERO32:
        return "chunk_witness_digest_zero"
    idx = int.from_bytes(body[32:34], "big")
    count = int.from_bytes(body[34:36], "big")
    entries = int.from_bytes(body[36:38], "big")
    reserved = int.from_bytes(body[38:40], "big")
    if reserved != 0:
        return "chunk_reserved_nonzero"
    if count < 1 or count > 32:
        return "chunk_count_range"
    if idx >= count:
        return "chunk_index_ge_count"
    is_final = idx == (count - 1)
    if is_final:
        if entries < 1 or entries > 8:
            return "chunk_final_entry_count"
    else:
        if entries != 8:
            return "chunk_nonfinal_entry_count"
    return None


def _d3s4_subtype_allows_zero_head(fam: int, st: int) -> bool:
    if fam == 5 and st == 0x01:
        return True
    if fam == 6 and st in (0x62, 0x7D, 0x7E, 0x7F):
        return True
    return False


def _d3s4_is_witness_metadata_role(role: int) -> bool:
    fam, st = (role >> 8) & 0xFF, role & 0xFF
    return fam == 6 and st in (0x7D, 0x7E, 0x7F)


def _d3s4_witness_member_key_ok(role: int, key: bytes) -> Optional[str]:
    """Member key grammar vs record_role (docs/17 §10.1 / C witness_member_key)."""
    if not isinstance(key, (bytes, bytearray)) or not (1 <= len(key) <= 255):
        return "entry_key_len"
    if len(key) < 9 or key[:8] != DOMAIN_KEY_ROOT:
        return "entry_key_root"
    role_fam, role_low = (role >> 8) & 0xFF, role & 0xFF
    fam = key[8]
    if fam != role_fam:
        return "entry_role_family_mismatch"
    if fam in (3, 4):
        if len(key) != 10 or role_low != 0:
            return "entry_fam34_key"
        suf = key[9]
        if fam == 3 and not (1 <= suf <= 4):
            return "entry_fam3_suffix"
        if fam == 4 and not (1 <= suf <= 11):
            return "entry_fam4_suffix"
        return None
    if fam in (5, 6):
        if not (13 <= len(key) <= 45):
            return "entry_domain_key_len"
        if key[9] != role_low:
            return "entry_role_subtype_mismatch"
        # Reuse domain complete-key grammar for family5/6.
        kerr = _d3s4_domain_key_ok(bytes(key))
        if kerr is not None:
            return f"entry_key:{kerr}"
        return None
    return "entry_key_family"


def _d3s4_witness_entry_shape_ok(
    role: int,
    action: int,
    key: bytes,
    old_present: int,
    new_present: int,
    prior: bytes,
    old_d: bytes,
    new_d: bytes,
) -> Optional[str]:
    """Witness entry shape (CREATE/REPLACE/ERASE/SUPERSEDE) including ZERO_PRIOR."""
    kerr = _d3s4_witness_member_key_ok(role, key)
    if kerr is not None:
        return kerr
    if old_present not in (0, 1) or new_present not in (0, 1):
        return "entry_present"
    old_zero = old_d == D1_ZERO32
    new_zero = new_d == D1_ZERO32
    prior_zero = prior == D1_ZERO32
    is_meta = _d3s4_is_witness_metadata_role(role)
    fam, st = (role >> 8) & 0xFF, role & 0xFF

    if action == ENTRY_ACTION_CREATE:
        if old_present != 0 or new_present != 1 or not old_zero or new_zero or not prior_zero:
            return "entry_create_shape"
        return None
    if action == ENTRY_ACTION_REPLACE:
        if (
            old_present != 1
            or new_present != 1
            or old_zero
            or new_zero
            or old_d == new_d
        ):
            return "entry_replace_shape"
        if is_meta:
            if not prior_zero:
                return "entry_replace_meta_prior"
        else:
            if fam in (3, 4):
                pass  # BASELINE zero prior allowed
            elif fam in (5, 6):
                if not _d3s4_subtype_allows_zero_head(fam, st) and prior_zero:
                    return "entry_replace_zero_prior"
            else:
                return "entry_replace_family"
        return None
    if action == ENTRY_ACTION_ERASE:
        if old_present != 1 or new_present != 0 or old_zero or not new_zero:
            return "entry_erase_shape"
        if is_meta:
            if not prior_zero:
                return "entry_erase_meta_prior"
        else:
            if fam in (3, 4):
                pass
            elif fam in (5, 6):
                if not _d3s4_subtype_allows_zero_head(fam, st) and prior_zero:
                    return "entry_erase_zero_prior"
            else:
                return "entry_erase_family"
        return None
    if action == ENTRY_ACTION_SUPERSEDE_WITNESS:
        if role != ((6 << 8) | 0x7F):
            return "entry_supersede_role"
        if (
            old_present != 1
            or new_present != 1
            or old_zero
            or new_zero
            or old_d == new_d
            or not prior_zero
        ):
            return "entry_supersede_shape"
        return None
    return "entry_action"


def d3s4_d1_chunk_body_entries_ok(body: bytes) -> Optional[str]:
    """Full WITNESS_MANIFEST_CHUNK body: prefix + complete entry column decode.

    Detects DSW1_REPLACE_ZERO_PRIOR / ROLE_MISMATCH / UNORDERED and all other
    entry-shape/sort corruptions (docs/17 §10 / D1 codec).
    """
    err = d3s4_d1_chunk_body_prefix_ok(body)
    if err is not None:
        return err
    entry_count = int.from_bytes(body[36:38], "big")
    o = 40
    keys: List[bytes] = []
    for ei in range(entry_count):
        if o + 8 > len(body):
            return "chunk_entry_trunc"
        role = int.from_bytes(body[o : o + 2], "big")
        action = body[o + 2]
        res_u8 = body[o + 3]
        key_len = int.from_bytes(body[o + 4 : o + 6], "big")
        res_a = int.from_bytes(body[o + 6 : o + 8], "big")
        o += 8
        if res_u8 != 0 or res_a != 0:
            return "chunk_entry_reserved"
        if key_len < 1 or key_len > 255:
            return "chunk_entry_key_len"
        need = key_len + 2 + 2 + 96
        if o + need > len(body):
            return "chunk_entry_trunc"
        key = body[o : o + key_len]
        o += key_len
        old_p = body[o]
        new_p = body[o + 1]
        o += 2
        res_b = int.from_bytes(body[o : o + 2], "big")
        o += 2
        if res_b != 0:
            return "chunk_entry_reserved"
        prior = body[o : o + 32]
        o += 32
        old_d = body[o : o + 32]
        o += 32
        new_d = body[o : o + 32]
        o += 32
        serr = _d3s4_witness_entry_shape_ok(
            role, action, key, old_p, new_p, prior, old_d, new_d
        )
        if serr is not None:
            return serr
        keys.append(bytes(key))
    if o != len(body):
        return "chunk_entry_trailing"
    # Strict lexicographic order, no non-increasing keys (DSW1_UNORDERED).
    for i in range(1, len(keys)):
        prev, cur = keys[i - 1], keys[i]
        if prev >= cur:
            return "chunk_entry_unordered"
    return None


def _d3s4_op_identity_len(op_kind: int) -> Optional[int]:
    table = {
        1: 32, 2: 16, 3: 16, 4: 8, 5: 32, 6: 40, 7: 8, 8: 8,
        9: 42, 10: 42, 11: 50, 12: 42, 13: 8, 14: 42, 15: 32, 16: 32,
        17: 14, 18: 42, 19: 24, 20: 8, 21: 66,
    }
    return table.get(op_kind)


def _d3s4_subject_prefix_from_key(key: bytes) -> bytes:
    d3s1 = _load_d3s1()
    return d3s1.key_digest(key)[:16]


def _d3s4_witness_header_matrix_ok(
    op_kind: int,
    op_id: bytes,
    subject: bytes,
    ret_kind: int,
    ret_subj: bytes,
) -> Optional[str]:
    """§10.0 operation×subject×retention matrix (incl. 5 locally-derivable kinds)."""
    if subject == bytes(16):
        return "header_subject_zero"
    if ret_kind == 0:
        if ret_subj != D1_ZERO32:
            return "header_ret_subj_nz"
    elif ret_kind in (1, 2, 3, 4):
        if ret_subj == D1_ZERO32:
            return "header_ret_subj_zero"
    else:
        return "header_ret_kind"
    want_len = _d3s4_op_identity_len(op_kind)
    if want_len is None or len(op_id) != want_len:
        return "header_op_id_len_kind"

    def subj_eq_prefix(data: bytes) -> bool:
        return subject == data[:16]

    def ret_in(allowed: FrozenSet[int]) -> bool:
        if ret_kind not in allowed:
            return False
        if ret_kind == 0:
            return ret_subj == D1_ZERO32
        return ret_subj != D1_ZERO32

    if op_kind == 1:
        if not (subj_eq_prefix(op_id) and ret_kind == 0 and ret_subj == D1_ZERO32):
            return "header_matrix_k1"
        return None
    if op_kind in (2, 3):
        if not (subj_eq_prefix(op_id) and ret_kind == 2 and ret_subj != D1_ZERO32):
            return "header_matrix_k23"
        return None
    if op_kind in (15, 16):
        if not (subj_eq_prefix(op_id) and ret_kind == 2 and ret_subj != D1_ZERO32):
            return "header_matrix_k1516"
        return None
    if op_kind in (4, 7, 13):
        # ORDERED_INGRESS KEY_DIGEST prefix from identity sequence.
        ing_key = (
            DOMAIN_KEY_ROOT
            + bytes([6, 0x27, 1, 3, 8])
            + op_id
        )
        expect = _d3s4_subject_prefix_from_key(ing_key)
        if subject != expect:
            return "header_subject_mismatch"
        if op_kind == 13:
            if ret_kind != 2 or ret_subj == D1_ZERO32:
                return "header_matrix_k13_ret"
        else:
            if not ret_in(frozenset({0, 2, 3})):
                return "header_matrix_k47_ret"
        return None
    if op_kind == 5:
        if not (subj_eq_prefix(op_id) and ret_in(frozenset({2, 3}))):
            return "header_matrix_k5"
        return None
    if op_kind == 6:
        if not (subj_eq_prefix(op_id) and ret_in(frozenset({2, 3}))):
            return "header_matrix_k6"
        return None
    if op_kind == 8:
        # Subject is external delivery KEY_DIGEST — only retention closed here.
        if ret_kind != 3 or ret_subj == D1_ZERO32:
            return "header_matrix_k8"
        return None
    if op_kind in (9, 10, 11):
        if not (
            subj_eq_prefix(op_id)
            and ret_kind == 3
            and ret_subj == op_id[:32]
        ):
            return "header_matrix_k9_11"
        return None
    if op_kind == 12:
        if not (subj_eq_prefix(op_id) and ret_in(frozenset({2, 3}))):
            return "header_matrix_k12"
        return None
    if op_kind == 14:
        if not (
            subj_eq_prefix(op_id)
            and ret_kind == 2
            and ret_subj == op_id[:32]
        ):
            return "header_matrix_k14"
        return None
    if op_kind == 17:
        # family-4 capacity KEY_DIGEST prefix; retention fixed 0
        if ret_kind != 0 or ret_subj != D1_ZERO32:
            return "header_matrix_k17_ret"
        rk = int.from_bytes(op_id[0:2], "big")
        if not (1 <= rk <= 11):
            return "header_matrix_k17_rk"
        cap_key = DOMAIN_KEY_ROOT + bytes([4, rk])
        expect = _d3s4_subject_prefix_from_key(cap_key)
        if subject != expect:
            return "header_subject_mismatch"
        return None
    if op_kind == 18:
        if not ret_in(frozenset({2, 3})):
            return "header_matrix_k18"
        return None
    if op_kind == 19:
        if not (subj_eq_prefix(op_id) and ret_kind == 0 and ret_subj == D1_ZERO32):
            return "header_matrix_k19"
        return None
    if op_kind == 20:
        # BEARER_STATE singleton KEY_DIGEST prefix; retention fixed 0
        if ret_kind != 0 or ret_subj != D1_ZERO32:
            return "header_matrix_k20_ret"
        bearer_key = DOMAIN_KEY_ROOT + bytes([6, 0x60, 1, 1, 0])
        expect = _d3s4_subject_prefix_from_key(bearer_key)
        if subject != expect:
            return "header_subject_mismatch"
        return None
    if op_kind == 21:
        if not (subj_eq_prefix(op_id) and ret_in(frozenset({0, 2, 3}))):
            return "header_matrix_k21"
        return None
    return "header_op_kind"


def _d3s4_header_body_fields_ok(body: bytes) -> Optional[str]:
    """Parse WITNESS_HEADER raw body: all fields + op/subject matrix (no key/NLR1)."""
    if len(body) < 6:
        return "header_body_short"
    op_kind = int.from_bytes(body[0:2], "big")
    state = int.from_bytes(body[2:4], "big")
    if state not in (1, 2, 3):
        return "header_state_invalid"
    o = 4
    id_len = int.from_bytes(body[o : o + 2], "big")
    o += 2
    if id_len > 128 or o + id_len > len(body):
        return "header_op_id"
    op_id = body[o : o + id_len]
    o += id_len
    need = 16 + 32 + 2 + 2 + 32 + 2 + 2 + 32 + 32
    if o + need > len(body):
        return "header_body_trunc"
    if o + need != len(body):
        return "header_body_trailing"
    subject = body[o : o + 16]
    o += 16
    canonical = body[o : o + 32]
    o += 32
    member_count = int.from_bytes(body[o : o + 2], "big")
    o += 2
    chunk_count = int.from_bytes(body[o : o + 2], "big")
    o += 2
    manifest = body[o : o + 32]
    o += 32
    ret_kind = int.from_bytes(body[o : o + 2], "big")
    o += 2
    reserved = int.from_bytes(body[o : o + 2], "big")
    o += 2
    ret_subj = body[o : o + 32]
    o += 32
    successor = body[o : o + 32]
    if reserved != 0:
        return "header_reserved"
    if member_count < 1 or member_count > 256:
        return "header_member_count"
    expect_chunks = (member_count + 7) // 8
    if chunk_count != expect_chunks or chunk_count < 1 or chunk_count > 32:
        return "header_chunk_count"
    if state == 1 and successor != D1_ZERO32:
        return "header_active_successor_nz"
    if state in (2, 3) and successor == D1_ZERO32:
        return "header_succ_zero"
    merr = _d3s4_witness_header_matrix_ok(op_kind, op_id, subject, ret_kind, ret_subj)
    if merr is not None:
        return merr
    if manifest == D1_ZERO32 or canonical == D1_ZERO32:
        return "header_digest_zero"
    canon_pre = (
        b"NINLIL-DOMAIN-OPERATION-V1"
        + struct.pack(">H", op_kind)
        + struct.pack(">H", id_len)
        + op_id
        + subject
        + manifest
        + struct.pack(">H", ret_kind)
        + ret_subj
    )
    if hashlib.sha256(canon_pre).digest() != canonical:
        return "header_canonical_mismatch"
    return None


def d3s4_d1_header_body_shape_ok(body: bytes) -> Optional[str]:
    """§10 / §18.15 WITNESS_HEADER full body field gates (raw body helper).

    Validates every field (state + operation identity + subject matrix +
    retention + successor + canonical + counts) — not state alone.
    """
    return _d3s4_header_body_fields_ok(body)


def d3s4_d1_header_body_full_ok(body: bytes, *, key: bytes, value: bytes) -> Optional[str]:
    """Full WITNESS_HEADER body + key/header bijection (NLR1 path)."""
    d3s1 = _load_d3s1()
    err = _d3s4_header_body_fields_ok(body)
    if err is not None:
        return err
    op_kind = int.from_bytes(body[0:2], "big")
    id_len = int.from_bytes(body[4:6], "big")
    op_id = body[6 : 6 + id_len]
    # key identity = composite(0x7f, op_kind||op_identity RAW16)
    components = struct.pack(">H", op_kind) + struct.pack(">H", id_len) + op_id
    expect_ident = d3s1.composite(0x7F, components)
    if len(key) < 13 or key[11] != 5 or key[12] != 32:
        return "header_key_kind"
    if key[13:45] != expect_ident:
        return "header_key_body_mismatch"
    if value[24:40] != expect_ident[:16]:
        return "header_primary_id"
    return None


def d3s4_d1_chunk_body_full_ok(body: bytes, *, key: bytes, value: bytes) -> Optional[str]:
    """Full WITNESS_MANIFEST_CHUNK body (entries fully decoded) + key bijection."""
    d3s1 = _load_d3s1()
    err = d3s4_d1_chunk_body_entries_ok(body)
    if err is not None:
        return err
    wdig = body[0:32]
    idx = int.from_bytes(body[32:34], "big")
    # §10.1: chunk key components are witness_digest + chunk_index only (no count)
    components = wdig + struct.pack(">H", idx)
    expect_ident = d3s1.composite(0x7E, components)
    if len(key) < 13 or key[11] != 5 or key[12] != 32:
        return "chunk_key_kind"
    if key[13:45] != expect_ident:
        return "chunk_key_body_mismatch"
    if value[24:40] != expect_ident[:16]:
        return "chunk_primary_id"
    return None


def _d3s4_wrap_witness_chunk_nlr1(body: bytes) -> Tuple[bytes, bytes]:
    """Build complete NLR1 key/value for a raw WITNESS_MANIFEST_CHUNK body."""
    d3s1 = _load_d3s1()
    wdig = body[0:32]
    idx = int.from_bytes(body[32:34], "big")
    components = wdig + struct.pack(">H", idx)
    ident = d3s1.composite(0x7E, components)
    key = DOMAIN_KEY_ROOT + bytes([6, 0x7E, 1, 5, 32]) + ident
    value = d3s1.enc_env_full(6, 0x7E, 0, 1, ident[:16], bytes(32), bytes(32), body)
    return key, value


def _d3s4_wrap_witness_header_nlr1(body: bytes) -> Tuple[bytes, bytes]:
    """Build complete NLR1 key/value for a raw WITNESS_HEADER body."""
    d3s1 = _load_d3s1()
    op_kind = int.from_bytes(body[0:2], "big")
    id_len = int.from_bytes(body[4:6], "big")
    op_id = body[6 : 6 + id_len]
    components = struct.pack(">H", op_kind) + struct.pack(">H", id_len) + op_id
    ident = d3s1.composite(0x7F, components)
    key = DOMAIN_KEY_ROOT + bytes([6, 0x7F, 1, 5, 32]) + ident
    value = d3s1.enc_env_full(6, 0x7F, 0, 1, ident[:16], bytes(32), bytes(32), body)
    return key, value


def d3s4_d1_head_index_body_ok(body: bytes, *, expect_state: Optional[int] = None) -> Optional[str]:
    """HEAD_INDEX body exact 114."""
    if len(body) != 114:
        return "head_index_len"
    st = int.from_bytes(body[0:2], "big")
    reserved = int.from_bytes(body[2:4], "big")
    if reserved != 0:
        return "head_index_reserved"
    if st not in (1, 2):
        return "head_index_state"
    if expect_state is not None and st != expect_state:
        return "head_index_state_mismatch"
    reserved2 = int.from_bytes(body[38:40], "big")
    if reserved2 != 0:
        return "head_index_reserved2"
    key_len = int.from_bytes(body[36:38], "big")
    if key_len != 10:
        return "head_index_key_len"
    mk = body[40:50]
    if len(mk) != 10 or mk[0:8] != DOMAIN_KEY_ROOT or mk[8] not in (3, 4):
        return "head_index_member_family"
    mkd = body[4:36]
    if mkd == D1_ZERO32:
        return "head_index_member_key_digest_zero"
    head = body[82:114]
    if st == 1 and head != D1_ZERO32:
        return "head_index_baseline_nonzero_head"
    if st == 2 and head == D1_ZERO32:
        return "head_index_witnessed_zero_head"
    return None


def _d3s4_composite(subtype: int, components: bytes) -> bytes:
    d3s1 = _load_d3s1()
    return d3s1.composite(subtype & 0xFF, components)


def _d3s4_bkey(fam: int, st: int, kind: int, ident: bytes) -> bytes:
    return DOMAIN_KEY_ROOT + bytes([fam, st, 1, kind, len(ident)]) + ident


def _d3s4_primary_id_from_identity(kind: int, identity: bytes) -> bytes:
    if kind == 1:
        return bytes(16)
    if kind == 2:
        return identity[:16]
    if kind == 3:
        return bytes(8) + identity[:8]
    if kind in (4, 5):
        return identity[:16]
    return bytes(16)


def _d3s4_parse_raw16(buf: bytes, o: int) -> Tuple[Optional[bytes], int]:
    if o + 2 > len(buf):
        return None, o
    n = int.from_bytes(buf[o : o + 2], "big")
    o += 2
    if n > 255 or o + n > len(buf):
        return None, o
    return buf[o : o + n], o + n


# Zero-head / zero-PVD closed sets (docs/17 + domain_store_vector_gen).
_D3S4_ALLOW_ZERO_HEAD: FrozenSet[Tuple[int, int]] = frozenset({
    (5, 0x01),
    (6, 0x62),  # CLOCK — state-dependent; body gate tightens
    (6, 0x7D),  # HEAD_INDEX — state-dependent
    (6, 0x7E),
    (6, 0x7F),
})
_D3S4_PVD_ZERO_OK: FrozenSet[Tuple[int, int]] = frozenset({
    (5, 0x01),
    (6, 0x10), (6, 0x20), (6, 0x27), (6, 0x40),
    (6, 0x60), (6, 0x62), (6, 0x64),
    (6, 0x7D), (6, 0x7E), (6, 0x7F),
})
_D3S4_IMMUTABLE_REV1: FrozenSet[int] = frozenset({
    0x10, 0x20, 0x27, 0x30, 0x34, 0x40, 0x60,
})


def _d3s4_common_semantic_header(
    fam: int, st: int, value: bytes, *, flags_exact: Optional[int] = 0
) -> Optional[str]:
    err = _d3s4_common_header_ok(value, expect_subtype=st, expect_record_type=fam)
    if err is not None:
        return err
    flags = value[15]
    if flags_exact is not None and flags != flags_exact:
        return "flags"
    rev = int.from_bytes(value[16:24], "big")
    head = value[40:72]
    pvd = value[72:104]
    if (fam, st) not in _D3S4_ALLOW_ZERO_HEAD and head == D1_ZERO32:
        return "head_zero"
    if (fam, st) in _D3S4_PVD_ZERO_OK:
        if pvd != D1_ZERO32 and st not in (0x62,):  # clock body gate
            if st in (0x10, 0x20, 0x27, 0x40, 0x60, 0x64, 0x7D, 0x7E, 0x7F) or fam == 5:
                if pvd != D1_ZERO32:
                    return "pvd_must_zero"
    else:
        if pvd == D1_ZERO32:
            return "pvd_zero"
    if st in _D3S4_IMMUTABLE_REV1 and rev != 1:
        return "revision_ne1"
    return None


def _d3s4_semantic_body_row_ok(key: bytes, value: bytes) -> Optional[str]:
    """Full-field semantic body + key/primary_id for d3s4 catalog subtypes.

    Mirrors d3s3 complete Normative D1 pattern (common + body decode + key bijection
    + primary_id) for every used subtype not already covered by d3s3 R19–R27 set.
    """
    fam, st = key[8], key[9]
    body = value[108:-4]
    rev = int.from_bytes(value[16:24], "big")
    pid = value[24:40]
    head = value[40:72]
    pvd = value[72:104]
    ik, il = key[11], key[12]
    ident = key[13:13 + il] if len(key) >= 13 + il else b""

    # --- family 5 INTERNAL_INVARIANT ---
    if fam == 5 and st == 0x01:
        err = _d3s4_common_semantic_header(5, 0x01, value)
        if err is not None:
            return err
        if len(body) != 96:
            return "inv_body_len"
        if rev != 1 or head != D1_ZERO32 or pvd != D1_ZERO32:
            return "inv_header"
        reason = body[0:4]
        subj_kind = body[4:6]
        reserved = int.from_bytes(body[6:8], "big")
        if reserved != 0:
            return "inv_reserved"
        subj_dig = body[8:40]
        marker = hashlib.sha256(
            b"NINLIL-DOMAIN-INVARIANT-V1" + reason + subj_kind + subj_dig
        ).digest()[:16]
        if ik != 2 or il != 16 or ident != marker:
            return "inv_key_marker"
        if pid != marker:
            return "inv_primary_id"
        return None

    if fam != 6:
        return "family"

    # --- BEARER 0x60 ---
    if st == 0x60:
        err = _d3s4_common_semantic_header(6, 0x60, value)
        if err is not None:
            return err
        if head == D1_ZERO32:
            return "head_zero"
        if pvd != D1_ZERO32:
            return "pvd_must_zero"
        if ik != 1 or il != 0 or len(key) != 13:
            return "bearer_key"
        if pid != bytes(16):
            return "bearer_primary_id"
        if len(body) != 36:
            return "bearer_body_len"
        available = int.from_bytes(body[0:4], "big")
        if available not in (0, 1):
            return "bearer_available_bool"
        reserved_b = int.from_bytes(body[20:24], "big")
        if reserved_b != 0:
            return "bearer_reserved"
        return None

    # --- CLOCK 0x62 ---
    if st == 0x62:
        err = _d3s4_common_header_ok(value, expect_subtype=0x62, expect_record_type=6)
        if err is not None:
            return err
        if value[15] != 0:
            return "flags"
        if pvd != D1_ZERO32:
            return "pvd_must_zero"
        if ik != 1 or il != 0:
            return "clock_key"
        if pid != bytes(16):
            return "clock_primary_id"
        if len(body) != 40:
            return "clock_body_len"
        state = int.from_bytes(body[0:4], "big")
        if state not in (1, 2):
            return "clock_state"
        reserved_c = int.from_bytes(body[4:8], "big")
        if reserved_c != 0:
            return "clock_reserved"
        epoch = body[8:24]
        now_ms = int.from_bytes(body[24:32], "big")
        gen = int.from_bytes(body[32:40], "big")
        if gen == 0xFFFFFFFFFFFFFFFF:
            return "clock_gen_max"
        if rev != gen + 1:
            return "clock_rev_gen_mismatch"
        if state == 1:
            if rev != 1 or head != D1_ZERO32:
                return "clock_uninit"
            if epoch != bytes(16) or now_ms != 0:
                return "clock_uninit_epoch"
        else:
            if rev < 2:
                return "clock_trusted_rev"
        return None

    # --- FENCE 0x64 ---
    if st == 0x64:
        err = _d3s4_common_semantic_header(6, 0x64, value)
        if err is not None:
            return err
        if head == D1_ZERO32:
            return "head_zero"
        if ik != 1 or il != 0:
            return "fence_key"
        if pid != bytes(16):
            return "fence_primary_id"
        if len(body) != 16:
            return "fence_body_len"
        active_plan_count = int.from_bytes(body[0:4], "big")
        fence_reserved = int.from_bytes(body[4:8], "big")
        if fence_reserved != 0:
            return "fence_reserved"
        gen = int.from_bytes(body[8:16], "big")
        if rev != gen:
            return "fence_rev_gen_mismatch"
        if active_plan_count == 0 and gen != 0:
            return "fence_active_count_zero_with_gen"
        return None

    # --- HEAD_INDEX 0x7D ---
    if st == 0x7D:
        err = _d3s4_common_header_ok(value, expect_subtype=0x7D, expect_record_type=6)
        if err is not None:
            return err
        if value[15] != 0:
            return "flags"
        if pvd != D1_ZERO32:
            return "pvd_must_zero"
        if ik != 5 or il != 32:
            return "head_index_key_kind"
        body_err = d3s4_d1_head_index_body_ok(body)
        if body_err is not None:
            return body_err
        ist = int.from_bytes(body[0:2], "big")
        mkd = body[4:36]
        member_head = body[82:114]
        if ist == 1:
            if head != D1_ZERO32 or member_head != D1_ZERO32:
                return "head_index_baseline_head"
            if rev != 1:
                return "head_index_baseline_rev"
        else:
            if head == D1_ZERO32 or head != member_head:
                return "head_index_head_mismatch"
            if rev < 2:
                return "head_index_witnessed_rev"
        expect_ident = _d3s4_composite(0x7D, mkd)
        if ident != expect_ident:
            return "head_index_composite"
        if pid != expect_ident[:16]:
            return "head_index_primary_id"
        return None

    # --- WITNESS_HEADER 0x7F ---
    if st == 0x7F:
        err = _d3s4_common_header_ok(value, expect_subtype=0x7F, expect_record_type=6)
        if err is not None:
            return err
        if value[15] != 0:
            return "witness_header_flags"
        if pvd != D1_ZERO32:
            return "pvd_must_zero"
        return d3s4_d1_header_body_full_ok(body, key=key, value=value)

    # --- WITNESS_CHUNK 0x7E ---
    if st == 0x7E:
        err = _d3s4_common_header_ok(value, expect_subtype=0x7E, expect_record_type=6)
        if err is not None:
            return err
        if value[15] != 0:
            return "witness_chunk_flags"
        if pvd != D1_ZERO32:
            return "pvd_must_zero"
        return d3s4_d1_chunk_body_full_ok(body, key=key, value=value)

    # --- SERVICE 0x10 ---
    if st == 0x10:
        err = _d3s4_common_semantic_header(6, 0x10, value)
        if err is not None:
            return err
        if ik != 5 or il != 32:
            return "service_key_kind"
        sk, o = _d3s4_parse_raw16(body, 0)
        if sk is None:
            return "service_body"
        if len(sk) < 1:
            return "service_key_empty"
        expect_ident = _d3s4_composite(0x10, body[0:o])
        if ident != expect_ident:
            return "service_key_mismatch"
        if pid != expect_ident[:16]:
            return "service_primary_id"
        if rev != 1:
            return "revision_ne1"
        body_len_declared = int.from_bytes(value[104:108], "big")
        if body_len_declared != len(body):
            return "service_body_len_mismatch"
        return None

    # --- SERVICE_QUOTA 0x11 ---
    if st == 0x11:
        err = _d3s4_common_semantic_header(6, 0x11, value)
        if err is not None:
            return err
        if ik != 5 or il != 32:
            return "quota_key_kind"
        sk, o = _d3s4_parse_raw16(body, 0)
        if sk is None:
            return "quota_body"
        raw16 = body[0:o]
        expect_ident = _d3s4_composite(0x11, raw16)
        if ident != expect_ident:
            return "quota_key_mismatch"
        expect_pid = _d3s4_composite(0x10, raw16)[:16]
        if pid != expect_pid:
            return "quota_self_primary"
        body_len_declared = int.from_bytes(value[104:108], "big")
        if body_len_declared != len(body):
            return "quota_body_len_mismatch"
        return None

    # --- SEQUENCE_INDEX 0x21 ---
    if st == 0x21:
        err = _d3s4_common_semantic_header(6, 0x21, value)
        if err is not None:
            return err
        if ik != 3 or il != 8:
            return "seq_key_kind"
        if len(body) != 56:
            return "seq_body_len"
        seq_be = body[0:8]
        txn = body[8:24]
        if seq_be != ident:
            return "seq_key_mismatch"
        if txn == bytes(16):
            return "seq_txn_zero"
        if int.from_bytes(seq_be, "big") == 0:
            return "seq_zero"
        if body[24:56] == D1_ZERO32:
            return "seq_dig_zero"
        if pid != txn:
            return "seq_self_primary"
        return None

    # --- RESERVATION 0x23 ---
    if st == 0x23:
        err = _d3s4_common_semantic_header(6, 0x23, value)
        if err is not None:
            return err
        if ik != 5 or il != 32:
            return "res_key_kind"
        if len(body) < 6:
            return "res_body_short"
        owner_kind = int.from_bytes(body[0:2], "big")
        res_reserved = int.from_bytes(body[2:4], "big")
        if res_reserved != 0:
            return "res_reserved"
        owner_raw, o = _d3s4_parse_raw16(body, 4)
        if owner_raw is None:
            return "res_owner_raw"
        components = body[0:2] + body[4:o]
        if ident != _d3s4_composite(0x23, components):
            return "res_key_mismatch"
        # primary_id from owner
        if owner_kind == 1:  # SERVICE
            expect_pid = _d3s4_composite(0x10, struct.pack(">H", len(owner_raw)) + owner_raw)[:16]
        elif owner_kind == 2:  # TX
            if len(owner_raw) != 16:
                return "res_tx_raw"
            expect_pid = owner_raw
        elif owner_kind == 3:  # INGRESS
            expect_pid = _d3s4_primary_id_from_identity(3, owner_raw)
        elif owner_kind == 4:  # DELIVERY
            expect_pid = _d3s4_composite(0x40, struct.pack(">H", len(owner_raw)) + owner_raw)[:16]
        elif owner_kind == 5:  # CALLBACK
            if len(owner_raw) < 2:
                return "res_cb_raw"
            dlen = int.from_bytes(owner_raw[0:2], "big")
            expect_pid = _d3s4_composite(0x40, owner_raw[: 2 + dlen])[:16]
        else:
            return "res_owner_kind"
        if pid != expect_pid:
            return "res_self_primary"
        return None

    # --- IDEMPOTENCY_MAP 0x24 ---
    if st == 0x24:
        err = _d3s4_common_semantic_header(6, 0x24, value)
        if err is not None:
            return err
        if ik != 5 or il != 32:
            return "idem_key_kind"
        scope, o = _d3s4_parse_raw16(body, 0)
        if scope is None or not (1 <= len(scope) <= 255):
            return "idem_scope"
        ikey, o2 = _d3s4_parse_raw16(body, o)
        if ikey is None or not (1 <= len(ikey) <= 64):
            return "idem_key"
        components = body[0:o2]
        if ident != _d3s4_composite(0x24, components):
            return "idem_key_mismatch"
        if o2 + 16 + 32 + 32 != len(body):
            return "idem_txn"
        txn = body[o2 : o2 + 16]
        if pid != txn:
            return "idem_self_primary"
        body_len_declared = int.from_bytes(value[104:108], "big")
        if body_len_declared != len(body):
            return "idem_body_len_mismatch"
        return None

    # --- EVENT_ID_MAP 0x25 ---
    if st == 0x25:
        err = _d3s4_common_semantic_header(6, 0x25, value)
        if err is not None:
            return err
        if ik != 5 or il != 32:
            return "evmap_key_kind"
        scope, o = _d3s4_parse_raw16(body, 0)
        if scope is None or o + 16 > len(body):
            return "evmap_body"
        event_id = body[o : o + 16]
        components = body[0:o] + event_id
        if ident != _d3s4_composite(0x25, components):
            return "evmap_key_mismatch"
        if o + 32 > len(body):
            return "evmap_txn"
        txn = body[o + 16 : o + 32]
        if pid != txn:
            return "evmap_self_primary"
        body_len_declared = int.from_bytes(value[104:108], "big")
        if body_len_declared != len(body):
            return "evmap_body_len_mismatch"
        return None

    # --- SCHEDULER_OWNER 0x26 ---
    if st == 0x26:
        err = _d3s4_common_semantic_header(6, 0x26, value)
        if err is not None:
            return err
        if ik != 3 or il != 8:
            return "sched_key_kind"
        if len(body) < 8 + 2:
            return "sched_body_short"
        seq_be = body[0:8]
        if seq_be != ident:
            return "sched_seq_mismatch"
        self_pid = _d3s4_primary_id_from_identity(3, seq_be)
        if pid == self_pid:
            return "sched_self_primary"
        if head == D1_ZERO32:
            return "head_zero"
        if pvd == D1_ZERO32:
            return "pvd_zero"
        owner_kind_s = int.from_bytes(body[8:10], "big")
        if owner_kind_s not in (1, 2, 3):
            return "sched_owner_kind"
        ready_val = int.from_bytes(body[len(body)-4:len(body)], "big")
        if ready_val not in (0, 1):
            return "sched_ready_bool"
        body_len_declared = int.from_bytes(value[104:108], "big")
        if body_len_declared != len(body):
            return "sched_body_len_mismatch"
        return None

    # --- ATTEMPT 0x31 ---
    if st == 0x31:
        err = _d3s4_common_semantic_header(6, 0x31, value)
        if err is not None:
            return err
        if ik != 5 or il != 32:
            return "att_key_kind"
        if len(body) < 22:
            return "att_body_short"
        aid = body[0:16]
        owner_kind = int.from_bytes(body[16:18], "big")
        att_reserved = int.from_bytes(body[18:20], "big")
        if att_reserved != 0:
            return "att_reserved"
        owner_raw, o = _d3s4_parse_raw16(body, 20)
        if owner_raw is None:
            return "att_owner_raw"
        components = body[16:18] + body[20:o] + aid
        if ident != _d3s4_composite(0x31, components):
            return "att_key_mismatch"
        # primary_kd then transaction_id
        if o + 32 + 16 > len(body):
            return "att_body_trunc"
        txn = body[o + 32 : o + 48]
        if owner_kind == 1:  # TX
            expect_pid = txn
        elif owner_kind == 2:  # DELIVERY
            expect_pid = _d3s4_composite(0x40, struct.pack(">H", len(owner_raw)) + owner_raw)[:16]
        else:
            return "att_owner_kind"
        if pid != expect_pid:
            return "att_primary_id"
        return None

    # --- ATTEMPT_ID_INDEX 0x34 ---
    if st == 0x34:
        err = _d3s4_common_semantic_header(6, 0x34, value)
        if err is not None:
            return err
        if rev != 1:
            return "revision_ne1"
        if ik != 2 or il != 16:
            return "aii_key_kind"
        if len(body) != 100:
            return "aii_body_len"
        aid = body[0:16]
        txn = body[16:32]
        if aid != ident:
            return "aii_key_mismatch"
        if txn == bytes(16) or aid == bytes(16):
            return "aii_zero_id"
        if pid != txn:
            return "aii_primary"
        ak = int.from_bytes(body[32:34], "big")
        if ak not in (1, 2, 3):
            return "aii_kind"
        reserved = int.from_bytes(body[34:36], "big")
        if reserved != 0:
            return "aii_reserved"
        if body[36:68] == D1_ZERO32 or body[68:100] == D1_ZERO32:
            return "aii_dig_zero"
        return None

    # --- RETRY_SUMMARY 0x51 ---
    if st == 0x51:
        err = _d3s4_common_semantic_header(6, 0x51, value)
        if err is not None:
            return err
        if ik != 5 or il != 32:
            return "rs_key_kind"
        if len(body) not in (84, 80):
            if len(body) < 20:
                return "rs_body_short"
        if len(body) < 20:
            return "rs_body_short"
        tx = body[0:16]
        kind = int.from_bytes(body[16:18], "big")
        slot = int.from_bytes(body[18:20], "big")
        if kind not in (1, 2):
            return "rs_kind"
        expect_ident = _d3s4_composite(0x51, tx + struct.pack(">HH", kind, slot))
        if ident != expect_ident:
            return "rs_key_mismatch"
        if pid != tx:
            return "rs_primary_mismatch"
        if kind == 1 and len(body) != 84:
            return "rs_cum_len"
        if kind == 2 and len(body) != 80:
            return "rs_rec_len"
        if kind == 1 and len(body) == 84:
            total = int.from_bytes(body[20:28], "big")
            folded = int.from_bytes(body[28:36], "big")
            expect_folded = max(total - 4, 0)
            if folded != expect_folded:
                return "rs_cum_fold_arithmetic"
            if folded == 0 and any(body[36:84]):
                return "rs_cum_zero_tail"
            delivery_possible = int.from_bytes(body[76:80], "big")
            if delivery_possible not in (0, 1):
                return "rs_cum_delivery_bool"
            counter_saturated = int.from_bytes(body[80:84], "big")
            if counter_saturated not in (0, 1):
                return "rs_cum_saturated_bool"
        body_len_declared = int.from_bytes(value[104:108], "big")
        if body_len_declared != len(body):
            return "rs_body_len_mismatch"
        return None

    # --- MANAGEMENT_LEDGER 0x52 ---
    if st == 0x52:
        err = _d3s4_common_semantic_header(6, 0x52, value)
        if err is not None:
            return err
        if ik != 5 or il != 32:
            return "ml_key_kind"
        if len(body) != 364:
            return "ml_body_len"
        op = body[0:16]
        tx = body[28:44]
        expect_ident = _d3s4_composite(0x52, tx + op)
        if ident != expect_ident:
            return "ml_key_mismatch"
        if pid != tx:
            return "ml_primary_mismatch"
        if rev != 1:
            return "ml_rev"
        return None

    # --- RETENTION_BASIS 0x61 ---
    if st == 0x61:
        err = _d3s4_common_semantic_header(6, 0x61, value)
        if err is not None:
            return err
        if ik != 5 or il != 32:
            return "rb_key_kind"
        if len(body) < 6:
            return "rb_body_short"
        kind = int.from_bytes(body[0:2], "big")
        rb_reserved = int.from_bytes(body[2:4], "big")
        if rb_reserved != 0:
            return "rb_reserved"
        raw, o = _d3s4_parse_raw16(body, 4)
        if raw is None:
            return "rb_raw"
        expect_ident = _d3s4_composite(0x61, body[0:2] + body[4:o])
        if ident != expect_ident:
            return "rb_key_mismatch"
        # primary_id from subject
        if kind == 2:  # TX subject kind in RB
            if len(raw) != 16:
                return "rb_tx_raw"
            expect_pid = raw
        elif kind == 3:  # DELIVERY
            expect_pid = _d3s4_composite(0x40, struct.pack(">H", len(raw)) + raw)[:16]
        else:
            # accept other documented kinds via raw-as-id when length 16
            if len(raw) == 16:
                expect_pid = raw
            else:
                expect_pid = _d3s4_composite(0x40, struct.pack(">H", len(raw)) + raw)[:16]
        if pid != expect_pid:
            return "rb_primary_id_mismatch"
        return None

    # --- CLEANUP_PLAN 0x63 ---
    if st == 0x63:
        err = _d3s4_common_semantic_header(6, 0x63, value)
        if err is not None:
            return err
        if ik != 5 or il != 32:
            return "cp_key_kind"
        if len(body) < 6 + 32:
            return "cp_body_short"
        kind = int.from_bytes(body[0:2], "big")
        phase = int.from_bytes(body[2:4], "big")
        if phase not in (1, 2, 3):
            return "cp_phase"
        raw, o = _d3s4_parse_raw16(body, 4)
        if raw is None:
            return "cp_raw"
        if o + 64 > len(body):
            return "cp_body_trunc"
        primary_dig = body[o : o + 32]
        body_pvd = body[o + 32 : o + 64]
        expect_ident = _d3s4_composite(0x63, body[0:2] + primary_dig)
        if ident != expect_ident:
            return "cp_key_mismatch"
        # primary_id from subject raw
        if kind == 2:  # TX
            if len(raw) != 16:
                return "cp_tx_raw"
            expect_pid = raw
        elif kind == 3:  # DLV
            expect_pid = _d3s4_composite(0x40, struct.pack(">H", len(raw)) + raw)[:16]
        else:
            return "cp_kind"
        if pid != expect_pid:
            return "cp_primary_id_mismatch"
        # rev == batch_gen (after cleanup_gen u64)
        if o + 64 + 16 <= len(body):
            batch = int.from_bytes(body[o + 64 + 8 : o + 64 + 16], "big")
            if rev != batch:
                return "cp_rev_mismatch"
        if body_pvd != pvd and pvd != D1_ZERO32:
            # header PVD should match body embedded pvd for live plan
            if body_pvd != pvd:
                return "cp_pvd_mismatch"
        return None

    # Remaining catalog subtypes: require common header + non-empty body framing.
    # Fail-closed for zero head / pvd when not in allow sets.
    err = _d3s4_common_semantic_header(6, st, value)
    if err is not None:
        return err
    body_len = int.from_bytes(value[104:108], "big")
    if body_len < 1 and st not in (0x60, 0x62, 0x64):
        return "body_empty"
    return None


def d3s4_d1_row_legality(
    key: bytes,
    value: bytes,
    *,
    body_variant_hint: Optional[int] = None,
) -> Optional[str]:
    """Independent local D1 legality for D3-S4 used rows. None = legal.

    - Key grammar + NLR1 magic/version/length/CRC + common header for domain rows
    - d3s3 R19–R27 full Normative body product for used-family6 set
    - Full-field semantic body for remaining catalog subtypes (incl. WITNESS NLR1)
    - Family3/4: canonical profile catalog only (1-byte fake values RED)
    - Raw non-NLR1 WITNESS bodies are NOT accepted as legal rows (must be NLR1)
    """
    _reach_inc("d3s4_d1_row_legality")
    return _d3s4_d1_row_legality_impl(key, value, body_variant_hint=body_variant_hint)


def _d3s4_d1_row_legality_impl(
    key: bytes,
    value: bytes,
    *,
    body_variant_hint: Optional[int] = None,
) -> Optional[str]:
    """Uninstrumented D1 legality core. RefSession's drive path models production's
    D2/local-decode step through this alias so the reach gate can still assert the
    JSON-validation entry point (d3s4_d1_row_legality) never runs inside generate()."""
    if not isinstance(key, (bytes, bytearray)) or not isinstance(value, (bytes, bytearray)):
        return "type"
    k, v = bytes(key), bytes(value)

    # Family 1–4 profile / counter / capacity via d3s3 (canonical catalog).
    if len(k) >= 9 and k[0:8] == DOMAIN_KEY_ROOT and k[8] in (1, 2, 3, 4):
        d3s3 = _load_d3s3_d1()
        return d3s3.d1_independent_row_legality(k, v)

    kerr = _d3s4_domain_key_ok(k)
    if kerr is not None:
        return f"key:{kerr}"
    fam, st = k[8], k[9]

    # Pure body-only structural helpers are available as named functions for unit
    # probes, but row legality requires NLR1 for all domain family5/6 rows.
    # (P0-1: raw WITNESS_HEADER/CHUNK body must not pass as legal rows.)

    # Always enforce NLR1 framing / CRC before deeper checks.
    nerr = _d3s4_nlr1_framing_ok(v)
    if nerr is not None:
        return nerr

    # d3s3 full Normative D1 for R19–R27 used set (typed 74/60 authority).
    if fam == 6 and st in D3S3_D1_USED_FAMILY6:
        d3s3 = _load_d3s3_d1()
        return d3s3.d1_independent_row_legality(k, v)

    # Family 5 + remaining family6 catalog: full-field semantic decode.
    if fam == 5 or (fam == 6 and st in D3S4_USED_FAMILY6_ST):
        # HEAD_INDEX body_variant_hint still applied inside semantic gate via body
        if fam == 6 and st == 0x7D and body_variant_hint is not None:
            cerr = _d3s4_common_header_ok(v, expect_subtype=st, expect_record_type=6)
            if cerr is not None:
                return cerr
            body = v[108:-4]
            if len(body) >= 114:
                body = body[:114]
            berr = d3s4_d1_head_index_body_ok(body, expect_state=body_variant_hint)
            if berr is not None:
                return berr
            return _d3s4_semantic_body_row_ok(k, v)
        return _d3s4_semantic_body_row_ok(k, v)

    return "subtype_unlisted"


def d3s4_d1_coverage_report() -> Tuple[Optional[str], Dict[str, int]]:
    """Coverage: every used variant tag has ≥1 positive evidence path."""
    doc = _load_d1_authority()
    counts: Dict[str, int] = {tag: 0 for tag in D3S4_USED_VARIANT_TAGS}
    for vec in doc["vectors"]:
        op = vec.get("op")
        status = vec.get("expected_status")
        if status not in ("OK", None):
            continue
        fam = vec.get("family")
        st = vec.get("subtype")
        if fam is None or st is None:
            kh = vec.get("key_hex")
            if isinstance(kh, str) and len(kh) >= 20:
                try:
                    kb = bytes.fromhex(kh)
                except ValueError:
                    continue
                fs = d3s4_d1_key_family_subtype(kb)
                if fs is None and len(kb) == 10 and kb[0:8] == DOMAIN_KEY_ROOT:
                    fs = (kb[8], kb[9])
                if fs is None:
                    continue
                fam, st = fs
            else:
                continue
        fam_i, st_i = int(fam), int(st)
        bv = 0
        vh = vec.get("value_hex")
        if st_i == 0x30 and isinstance(vh, str) and len(vh) >= 32:
            try:
                vv = bytes.fromhex(vh)
                if len(vv) > 15:
                    bv = vv[15]
            except ValueError:
                pass
        if st_i == 0x7D:
            try:
                if isinstance(vh, str):
                    vv = bytes.fromhex(vh)
                    body = vv[108:108 + 114] if len(vv) >= 108 + 114 else vv
                    if len(body) >= 2:
                        bv = int.from_bytes(body[0:2], "big")
                elif isinstance(vec.get("body_hex"), str):
                    body = bytes.fromhex(vec["body_hex"])
                    if len(body) >= 2:
                        bv = int.from_bytes(body[0:2], "big")
            except ValueError:
                pass
        tag = d3s4_d1_variant_tag(fam_i, st_i, bv)
        if tag is not None:
            counts[tag] += 1
        if op in ("witness_chunk_roundtrip", "witness_chunk_decode", "witness_manifest_stream"):
            if status == "OK":
                counts["WITNESS_MANIFEST_CHUNK"] = counts.get("WITNESS_MANIFEST_CHUNK", 0) + 1
    for vec in doc["vectors"]:
        kh = vec.get("key_hex")
        if not isinstance(kh, str):
            continue
        try:
            kb = bytes.fromhex(kh)
        except ValueError:
            continue
        if len(kb) == 10 and kb[0:8] == DOMAIN_KEY_ROOT:
            if kb[8] == 3 and 1 <= kb[9] <= 4:
                t = f"FAMILY3_COUNTER_{kb[9]}"
                if t in counts:
                    counts[t] += 1
            if kb[8] == 4 and 1 <= kb[9] <= 11:
                t = f"FAMILY4_CAPACITY_{kb[9]}"
                if t in counts:
                    counts[t] += 1
    # Synthetics for zero-evidence structural variants
    if counts.get("WITNESS_HEADER", 0) == 0:
        syn = _d1_be16(1) + _d1_be16(1) + _d1_be16(0)
        if d3s4_d1_header_body_shape_ok(syn) is None:
            counts["WITNESS_HEADER"] = 1
    if counts.get("WITNESS_MANIFEST_CHUNK", 0) == 0:
        syn_c = (
            bytes([0x33] * 32) + _d1_be16(0) + _d1_be16(1) + _d1_be16(1) + _d1_be16(0)
        )
        if d3s4_d1_chunk_body_prefix_ok(syn_c) is None:
            counts["WITNESS_MANIFEST_CHUNK"] = 1
    d3s1 = _load_d3s1()
    # Prefer exact profile catalog pairs (family3/4) for coverage positives.
    try:
        profile_rows = d3s1.encode_all_profile_rows(d3s1.default_binding_fields())
    except Exception:
        profile_rows = []
    for r in profile_rows:
        try:
            kk = d3s1.from_hex(r["key_hex"])
            vv = d3s1.from_hex(r["value_hex"])
        except Exception:
            continue
        if len(kk) == 10 and kk[0:8] == DOMAIN_KEY_ROOT:
            if kk[8] == 3 and 1 <= kk[9] <= 4:
                t = f"FAMILY3_COUNTER_{kk[9]}"
                if counts.get(t, 0) == 0 and d3s4_d1_row_legality(kk, vv) is None:
                    counts[t] = 1
            if kk[8] == 4 and 1 <= kk[9] <= 11:
                t = f"FAMILY4_CAPACITY_{kk[9]}"
                if counts.get(t, 0) == 0 and d3s4_d1_row_legality(kk, vv) is None:
                    counts[t] = 1
    for k in range(1, 5):
        t = f"FAMILY3_COUNTER_{k}"
        if counts.get(t, 0) == 0:
            kk = DOMAIN_KEY_ROOT + bytes([3, k])
            vv = d3s1.encode_counter(k)
            if d3s4_d1_row_legality(kk, vv) is None:
                counts[t] = 1
    # Remaining zero-count: credit only if D1 gate actually accepts the row
    for vec in doc["vectors"]:
        if vec.get("expected_status") != "OK":
            continue
        fam = vec.get("family")
        st = vec.get("subtype")
        if fam is None or st is None:
            continue
        kh = vec.get("key_hex")
        vh = vec.get("value_hex")
        if not isinstance(kh, str) or not isinstance(vh, str):
            continue
        try:
            kb = bytes.fromhex(kh)
            vb = bytes.fromhex(vh)
        except ValueError:
            continue
        if d3s4_d1_row_legality(kb, vb) is not None:
            continue
        tag = d3s4_d1_variant_tag(int(fam), int(st), 0)
        if tag is not None and counts.get(tag, 0) == 0:
            counts[tag] = 1
        if int(st) == 0x30:
            fl = vb[15] if len(vb) > 15 else 0
            for bv, t in ((1, "BLOB_MANIFEST"), (2, "BLOB_CHUNK")):
                if counts.get(t, 0) == 0 and fl == bv:
                    counts[t] = 1
    missing = [t for t, n in counts.items() if n < 1]
    if missing:
        return f"D1 coverage missing variants: {missing}", counts
    return None, counts


def d3s4_d1_boundary_cases() -> List[Tuple[str, str, Optional[str]]]:
    """Structural boundary RED/PASS cases + CRC / family3 false-green probes."""
    cases: List[Tuple[str, str, Optional[str]]] = []
    bad_chunk = (
        bytes([0x33] * 32) + _d1_be16(1) + _d1_be16(1) + _d1_be16(1) + _d1_be16(0)
    )
    cases.append(("chunk_index_ge_count", "chunk_index_ge_count",
                  d3s4_d1_chunk_body_prefix_ok(bad_chunk)))
    bad_nf = (
        bytes([0x33] * 32) + _d1_be16(0) + _d1_be16(2) + _d1_be16(7) + _d1_be16(0)
    )
    cases.append(("chunk_nonfinal_entry_count", "chunk_nonfinal_entry_count",
                  d3s4_d1_chunk_body_prefix_ok(bad_nf)))
    bad_rs = (
        bytes([0x33] * 32) + _d1_be16(0) + _d1_be16(1) + _d1_be16(1) + _d1_be16(1)
    )
    cases.append(("chunk_reserved", "chunk_reserved_nonzero",
                  d3s4_d1_chunk_body_prefix_ok(bad_rs)))
    bad_z = D1_ZERO32 + _d1_be16(0) + _d1_be16(1) + _d1_be16(1) + _d1_be16(0)
    cases.append(("chunk_zero_wdig", "chunk_witness_digest_zero",
                  d3s4_d1_chunk_body_prefix_ok(bad_z)))
    bad_h = _d1_be16(1) + _d1_be16(9) + _d1_be16(0)
    cases.append(("header_state_9", "header_state_invalid",
                  d3s4_d1_header_body_shape_ok(bad_h)))
    cases.append(("head_index_short", "head_index_len",
                  d3s4_d1_head_index_body_ok(bytes(113))))
    mk = DOMAIN_KEY_ROOT + bytes([3, 1])
    body_hi = (
        _d1_be16(1) + _d1_be16(0) + bytes([0xAA] * 32) + _d1_be16(10) + _d1_be16(0)
        + mk + bytes([0xBB] * 32) + bytes([0xCC] * 32)
    )
    cases.append(("head_baseline_nz_head", "head_index_baseline_nonzero_head",
                  d3s4_d1_head_index_body_ok(body_hi, expect_state=1)))
    bad_key = DOMAIN_KEY_ROOT + bytes([6, 0x99]) + bytes([1, 2, 16]) + bytes(16)
    cases.append(("unlisted_subtype", "subtype_unlisted",
                  d3s4_d1_row_legality(bad_key, bytes(32))))
    # family3 1-byte value must RED
    k3 = DOMAIN_KEY_ROOT + bytes([3, 0x01])
    cases.append(("fam3_one_byte", "value_short",
                  d3s4_d1_row_legality(k3, b"\x00")))
    good_c = (
        bytes([0x33] * 32) + _d1_be16(0) + _d1_be16(1) + _d1_be16(3) + _d1_be16(0)
    )
    cases.append(("chunk_final_ok", "", d3s4_d1_chunk_body_prefix_ok(good_c)))
    # Full-field header positive: pull first ACTIVE OK raw body from D1 authority.
    good_h_body: Optional[bytes] = None
    try:
        for vec in _load_d1_authority().get("vectors", []):
            if (
                vec.get("op") == "witness_header_roundtrip"
                and vec.get("expected_status") == "OK"
                and isinstance(vec.get("value_hex"), str)
            ):
                good_h_body = bytes.fromhex(vec["value_hex"])
                break
    except Exception:
        good_h_body = None
    if good_h_body is not None:
        cases.append(("header_active_ok", "", d3s4_d1_header_body_shape_ok(good_h_body)))
    else:
        cases.append(("header_active_ok", "header_body_short",
                      d3s4_d1_header_body_shape_ok(_d1_be16(2) + _d1_be16(1) + _d1_be16(0))))
    return cases


def d3s4_d1_differential_vs_authority() -> Optional[str]:
    """Differential: typed 74/60 + body_decode wrap 306/0/306 (d3s3 R22–R24 pins).

    Also: every D1 typed_record OK for D3-S4 catalog subtypes must not false-red
    on framing/CRC; CORRUPT must RED under structural or d3s3 body gate.
    Plus witness_* raw vectors (DSW1 chunk/header catalog) body + NLR1 wrap.
    """
    doc = _load_d1_authority()
    d3s3 = _load_d3s3_d1()
    tr_pos = tr_neg = tr_fail = 0
    bd_checked = bd_neg_ok = bd_neg_fail = bd_non_app = 0
    catalog_ok_fail = 0
    catalog_corrupt_miss = 0
    wit_chunk_ok = wit_chunk_neg = 0
    wit_hdr_ok = wit_hdr_neg = 0

    for vec in doc.get("vectors", []):
        op = vec.get("op")
        fam = vec.get("family")
        st = vec.get("subtype")
        vid = vec.get("id", "?")
        exp = vec.get("expected_status")

        # --- d3s3 used-set typed (pin 74/60) ---
        if fam == 6 and st in D3S3_D1_USED_FAMILY6 and op == "typed_record":
            if exp not in ("OK", "CORRUPT"):
                return f"differential typed amb {vid}:{exp}"
            try:
                k = bytes.fromhex(vec["key_hex"])
                v = bytes.fromhex(vec["value_hex"])
            except Exception:
                return f"differential typed hex {vid}"
            err = d3s4_d1_row_legality(k, v)
            if exp == "OK":
                if err is None:
                    tr_pos += 1
                else:
                    tr_fail += 1
                    return f"differential typed+ false RED {vid}: {err}"
            else:
                if err is not None:
                    tr_neg += 1
                else:
                    tr_fail += 1
                    return f"differential typed- false GREEN {vid}"
            continue

        # --- d3s3 used-set body_decode wrap ---
        if fam == 6 and st in D3S3_D1_USED_FAMILY6 and op == "body_decode":
            body_hex = vec.get("body_hex") or ""
            if not body_hex:
                bd_non_app += 1
                continue
            try:
                body = bytes.fromhex(body_hex)
                k, v = d3s3._d1_wrap_body_for_independent_gate(
                    int(st), body, int(vec.get("flags") or 0)
                )
            except Exception:
                bd_non_app += 1
                continue
            bd_checked += 1
            err = d3s4_d1_row_legality(k, v)
            if exp == "CORRUPT":
                if err is not None:
                    bd_neg_ok += 1
                else:
                    bd_neg_fail += 1
                    return f"differential body_decode false GREEN {vid}"
            elif exp == "OK":
                if err is not None:
                    return f"differential body_decode false RED {vid}: {err}"
            continue

        # --- witness chunk raw bodies (DSW1_* CREATE/REPLACE/ZERO_PRIOR/...) ---
        if op in ("witness_chunk_roundtrip", "witness_chunk_decode", "witness_manifest_stream"):
            if exp not in ("OK", "CORRUPT"):
                continue
            # Single-chunk value_hex is a raw body; multi-chunk uses chunk_bodies_hex.
            bodies: List[bytes] = []
            vh = vec.get("value_hex")
            if isinstance(vh, str) and vh:
                try:
                    bodies.append(bytes.fromhex(vh))
                except ValueError:
                    return f"differential witness_chunk hex {vid}"
            chs = vec.get("chunk_bodies_hex")
            if isinstance(chs, list):
                for hx in chs:
                    if not isinstance(hx, str):
                        continue
                    try:
                        bodies.append(bytes.fromhex(hx))
                    except ValueError:
                        return f"differential witness_chunk hex {vid}"
            if not bodies:
                continue
            for body in bodies:
                err_body = d3s4_d1_chunk_body_entries_ok(body)
                try:
                    k, v = _d3s4_wrap_witness_chunk_nlr1(body)
                    err_row = d3s4_d1_row_legality(k, v)
                except Exception:
                    err_row = "wrap_fail"
                if exp == "OK":
                    if err_body is not None:
                        return f"differential witness_chunk OK false RED body {vid}: {err_body}"
                    if err_row is not None:
                        return f"differential witness_chunk OK false RED nlr1 {vid}: {err_row}"
                    wit_chunk_ok += 1
                else:
                    if err_body is None and err_row is None:
                        return f"differential witness_chunk CORRUPT false GREEN {vid}"
                    wit_chunk_neg += 1
            continue

        # --- witness header raw bodies (DSW1_HDR_*) ---
        if op in ("witness_header_roundtrip", "witness_header_decode"):
            if exp not in ("OK", "CORRUPT"):
                continue
            vh = vec.get("value_hex")
            if not isinstance(vh, str) or not vh:
                continue
            try:
                body = bytes.fromhex(vh)
            except ValueError:
                return f"differential witness_header hex {vid}"
            err_body = d3s4_d1_header_body_shape_ok(body)
            try:
                k, v = _d3s4_wrap_witness_header_nlr1(body)
                err_row = d3s4_d1_row_legality(k, v)
            except Exception:
                err_row = "wrap_fail"
            if exp == "OK":
                if err_body is not None:
                    return f"differential witness_header OK false RED body {vid}: {err_body}"
                if err_row is not None:
                    return f"differential witness_header OK false RED nlr1 {vid}: {err_row}"
                wit_hdr_ok += 1
            else:
                if err_body is None and err_row is None:
                    return f"differential witness_header CORRUPT false GREEN {vid}"
                wit_hdr_neg += 1
            continue

        # --- expanded catalog typed: OK must pass framing; CORRUPT must RED when in scope ---
        if fam is not None and st is not None and op == "typed_record":
            fam_i, st_i = int(fam), int(st)
            in_catalog = any(
                fam_i == f and st_i == s for f, s, _bv, _t, _m in D3S4_USED_VARIANTS
            )
            if not in_catalog:
                continue
            if exp not in ("OK", "CORRUPT"):
                continue
            if not isinstance(vec.get("key_hex"), str) or not isinstance(vec.get("value_hex"), str):
                continue
            try:
                k = bytes.fromhex(vec["key_hex"])
                v = bytes.fromhex(vec["value_hex"])
            except ValueError:
                return f"differential catalog hex {vid}"
            err = d3s4_d1_row_legality(k, v)
            if exp == "OK" and err is not None:
                catalog_ok_fail += 1
                return f"differential catalog OK false RED {vid}: {err}"
            if exp == "CORRUPT" and err is None:
                # All d3s4 used-catalog subtypes: CORRUPT must RED (not d3s3 subset only).
                catalog_corrupt_miss += 1
                return f"differential catalog CORRUPT false GREEN {vid}"

    if tr_fail or tr_pos != 74 or tr_neg != 60:
        return f"differential typed pin fail pos={tr_pos} neg={tr_neg} fail={tr_fail} want 74/60"
    if bd_checked < 300 or bd_neg_fail or bd_non_app != 0:
        # d3s3 pin: checked=306, non_app=0, neg_ok=306
        if bd_non_app != 0 or bd_neg_fail or bd_checked != 306 or bd_neg_ok != 306:
            return (
                f"differential body_decode pin fail checked={bd_checked} "
                f"neg_ok={bd_neg_ok} neg_fail={bd_neg_fail} non_app={bd_non_app} "
                f"want 306/0/306"
            )
    # Require known DSW1 corrupt classes actually exercised and RED.
    if wit_chunk_neg < 3:
        return f"differential witness_chunk neg pin fail {wit_chunk_neg} want >=3"
    if wit_hdr_neg < 17:
        return f"differential witness_header neg pin fail {wit_hdr_neg} want >=17"
    if wit_chunk_ok < 1 or wit_hdr_ok < 1:
        return (
            f"differential witness pos pin fail chunk_ok={wit_chunk_ok} "
            f"hdr_ok={wit_hdr_ok}"
        )
    return None


def d3s4_d1_boundary_length_sweep() -> Optional[str]:
    """R24-style body length sweep on d3s3 used-subtype OK baselines → total 4380."""
    doc = _load_d1_authority()
    d3s1 = _load_d3s1()
    want_by = {
        "20": 670, "22": 225, "27": 646, "30c": 118, "30m": 131,
        "32": 799, "33": 227, "40": 553, "41": 379, "42": 331, "50": 301,
    }
    # Collect OK typed candidates; prefer body length exact == want-1 (R24 pin).
    candidates: Dict[str, List[Tuple[bytes, bytes, int, int, int]]] = {n: [] for n in want_by}
    for vec in doc["vectors"]:
        if vec.get("op") != "typed_record" or vec.get("expected_status") != "OK":
            continue
        if vec.get("family") != 6:
            continue
        st = int(vec.get("subtype") or -1)
        if st not in D3S3_D1_USED_FAMILY6:
            continue
        try:
            k = bytes.fromhex(vec["key_hex"])
            v = bytes.fromhex(vec["value_hex"])
        except Exception:
            continue
        if d3s4_d1_row_legality(k, v) is not None:
            continue
        fl = v[15]
        name = f"{st:02x}" if st != 0x30 else ("30m" if fl == 1 else "30c")
        if name not in candidates:
            continue
        body_len = len(v) - 112  # common 108 + crc 4
        if body_len < 0:
            continue
        candidates[name].append((k, v, st, fl, body_len))
    baselines: Dict[str, Tuple[bytes, bytes, int, int]] = {}
    for name, want_n in want_by.items():
        want_exact = want_n - 1
        cands = candidates.get(name) or []
        pick = None
        for k, v, st, fl, bl in cands:
            if bl == want_exact:
                pick = (k, v, st, fl)
                break
        if pick is None and cands:
            # fallback longest body among legal OK
            k, v, st, fl, bl = max(cands, key=lambda t: t[4])
            pick = (k, v, st, fl)
        if pick is None:
            return f"boundary baseline missing {name}"
        baselines[name] = pick
    boundary_total = 0
    boundary_by: Dict[str, int] = {}
    for name, (bk, bv, st, fl) in baselines.items():
        body = bv[108:-4]
        exact = len(body)
        n_here = 0
        for blen in list(range(0, exact)) + [exact + 1]:
            b2 = body[:blen] if blen <= exact else body + b"\x5a"
            v2 = d3s1.enc_env_full(
                6, st, fl, int.from_bytes(bv[16:24], "big"),
                bv[24:40], bv[40:72], bv[72:104], b2,
            )
            err = d3s4_d1_row_legality(bk, v2)
            if err is None:
                return f"boundary no-RED {name} blen={blen}"
            n_here += 1
            boundary_total += 1
        boundary_by[name] = n_here
        if n_here != exact + 1:
            return f"boundary count {name}: {n_here} != {exact + 1}"
    if boundary_by != want_by or boundary_total != 4380:
        return f"boundary pin drift got={boundary_by} total={boundary_total}"
    return None


def d3s4_d1_expanded_boundary_sweep() -> Optional[str]:
    """Boundary sweep for expanded catalog subtypes (not in D3S3_D1_USED_FAMILY6)."""
    doc = _load_d1_authority()
    d3s1 = _load_d3s1()
    expanded_st = D3S4_USED_FAMILY6_ST - D3S3_D1_USED_FAMILY6
    swept = 0
    swept_subtypes: set = set()
    for vec in doc["vectors"]:
        if vec.get("op") != "typed_record" or vec.get("expected_status") != "OK":
            continue
        if vec.get("family") != 6:
            continue
        st = int(vec.get("subtype") or -1)
        if st not in expanded_st or st in swept_subtypes:
            continue
        try:
            k = bytes.fromhex(vec["key_hex"])
            v = bytes.fromhex(vec["value_hex"])
        except Exception:
            continue
        if d3s4_d1_row_legality(k, v) is not None:
            continue
        fl = v[15]
        body = v[108:-4]
        exact = len(body)
        if exact < 2:
            continue
        b2 = body + b"\x5a"
        v2 = d3s1.enc_env_full(
            6, st, fl, int.from_bytes(v[16:24], "big"),
            v[24:40], v[40:72], v[72:104], b2,
        )
        err = d3s4_d1_row_legality(k, v2)
        if err is not None:
            swept += 1
        swept_subtypes.add(st)
    if swept < 2:
        return f"expanded boundary sweep insufficient: {swept} cases"
    return None


def d3s4_d1_expanded_differential_pin() -> Optional[str]:
    """Verify expanded catalog CORRUPT typed_record + body_decode vectors are RED."""
    doc = _load_d1_authority()
    d3s3 = _load_d3s3_d1()
    expanded_st = D3S4_USED_FAMILY6_ST - D3S3_D1_USED_FAMILY6
    corrupt_checked = 0
    for vec in doc["vectors"]:
        if vec.get("expected_status") != "CORRUPT":
            continue
        if vec.get("family") != 6:
            continue
        st = int(vec.get("subtype") or -1)
        if st not in expanded_st:
            continue
        op = vec.get("op")
        if op == "typed_record":
            kh = vec.get("key_hex")
            vh = vec.get("value_hex")
            if not isinstance(kh, str) or not isinstance(vh, str):
                continue
            try:
                k = bytes.fromhex(kh)
                v = bytes.fromhex(vh)
            except ValueError:
                continue
            err = d3s4_d1_row_legality(k, v)
            if err is None:
                return f"expanded differential false GREEN st=0x{st:02x} id={vec.get('id')}"
            corrupt_checked += 1
        elif op == "body_decode":
            body_hex = vec.get("body_hex") or ""
            if not body_hex:
                continue
            try:
                body = bytes.fromhex(body_hex)
                d3s1 = _load_d3s1()
                kh = vec.get("key_hex")
                if isinstance(kh, str) and len(kh) >= 26:
                    k = bytes.fromhex(kh)
                else:
                    ident = _d3s4_composite(st, body[0:min(32, len(body))])
                    k = DOMAIN_KEY_ROOT + bytes([6, st, 1, 5, 32]) + ident
                pid = _d3s4_composite(st, body[0:16])[:16] if len(body) >= 16 else bytes(16)
                v = d3s1.enc_env_full(
                    6, st, int(vec.get("flags") or 0), 1,
                    pid, bytes(32), bytes(32), body,
                )
            except Exception:
                continue
            err = d3s4_d1_row_legality(k, v)
            if err is None:
                return f"expanded differential body_decode false GREEN st=0x{st:02x} id={vec.get('id')}"
            corrupt_checked += 1
    return None


def gate_a2a2_d1_self_test(log: List[str]) -> int:
    """(i) D1 coverage + boundary + differential + mutation self-test."""
    log.append("=== A2-a2(i) D1 used-variant coverage/boundary/differential ===")
    log.append(
        f"authority: docs/17 §18.15 + §5.1 + §18.12 Mode17; "
        f"used_variants={D3S4_USED_VARIANT_COUNT}"
    )
    live_pin = _bake_used_variants_pin()
    if live_pin != D3S4_USED_VARIANTS_SHA256:
        log.append(f"RED used-variants pin mismatch live={live_pin}")
        print("A2-a2(i) used-variants pin mismatch", file=sys.stderr)
        return 1
    if D3S4_USED_VARIANT_COUNT != D3S4_USED_VARIANT_COUNT_PIN:
        log.append(
            f"RED used_variants count {D3S4_USED_VARIANT_COUNT} != pin {D3S4_USED_VARIANT_COUNT_PIN}"
        )
        print("A2-a2(i) used_variants count pin", file=sys.stderr)
        return 1
    log.append(f"used_variants_pin={live_pin[:16]}... OK count={D3S4_USED_VARIANT_COUNT}")

    err, counts = d3s4_d1_coverage_report()
    log.append(f"coverage_counts={json.dumps(counts, sort_keys=True)}")
    if err is not None:
        log.append(f"RED coverage: {err}")
        print(f"A2-a2(i) coverage: {err}", file=sys.stderr)
        return 1
    log.append("coverage: every used variant has >=1 evidence OK")

    for label, expect_sub, got in d3s4_d1_boundary_cases():
        if expect_sub == "":
            if got is not None:
                log.append(f"RED boundary positive {label}: {got}")
                print(f"A2-a2(i) boundary positive {label}: {got}", file=sys.stderr)
                return 1
            log.append(f"boundary PASS {label}")
        else:
            if got is None or expect_sub not in got:
                log.append(f"RED boundary {label}: got {got!r} want sub {expect_sub!r}")
                print(
                    f"A2-a2(i) boundary {label}: got {got!r} want {expect_sub!r}",
                    file=sys.stderr,
                )
                return 1
            log.append(f"boundary RED {label}: {got}")

    derr = d3s4_d1_differential_vs_authority()
    if derr is not None:
        log.append(f"RED differential: {derr}")
        print(f"A2-a2(i) differential: {derr}", file=sys.stderr)
        return 1
    log.append("differential typed 74/60 body_decode 306/0/306 OK")

    berr = d3s4_d1_boundary_length_sweep()
    if berr is not None:
        log.append(f"RED boundary-sweep: {berr}")
        print(f"A2-a2(i) boundary-sweep: {berr}", file=sys.stderr)
        return 1
    log.append("boundary length sweep 4380 OK")

    eberr = d3s4_d1_expanded_boundary_sweep()
    if eberr is not None:
        log.append(f"RED expanded-boundary: {eberr}")
        print(f"A2-a2(i) expanded-boundary: {eberr}", file=sys.stderr)
        return 1
    log.append("expanded boundary sweep OK")

    ederr = d3s4_d1_expanded_differential_pin()
    if ederr is not None:
        log.append(f"RED expanded-differential: {ederr}")
        print(f"A2-a2(i) expanded-differential: {ederr}", file=sys.stderr)
        return 1
    log.append("expanded differential CORRUPT pin OK")

    # CRC corruption probes (review breakthrough)
    doc = _load_d1_authority()
    crc_hits = 0
    for vec in doc["vectors"]:
        if vec.get("op") != "typed_record" or vec.get("expected_status") != "OK":
            continue
        st = vec.get("subtype")
        if st not in (0x20, 0x30):
            continue
        try:
            k = bytes.fromhex(vec["key_hex"])
            val = bytearray(bytes.fromhex(vec["value_hex"]))
        except Exception:
            continue
        if len(val) < 4:
            continue
        val[-1] ^= 0x01
        err = d3s4_d1_row_legality(k, bytes(val))
        if err is None or "crc" not in err:
            log.append(f"RED CRC probe subtype={st:#x} accepted err={err!r}")
            print("A2-a2(i) CRC probe false-green", file=sys.stderr)
            return 1
        crc_hits += 1
        if crc_hits >= 2:
            break
    if crc_hits < 2:
        log.append(f"RED CRC probes incomplete hits={crc_hits}")
        return 1
    log.append("CRC corruption BLOB+ANCHOR RED OK")

    # Mutation: removing WITNESS_HEADER from live catalog desyncs hardcoded pin
    mut_payload = "|".join(
        sorted(
            f"{tag}|{fam:02x}|{st:02x}|{bv}"
            for fam, st, bv, tag, _m in D3S4_USED_VARIANTS
            if tag != "WITNESS_HEADER"
        )
    )
    mut_pin = hashlib.sha256(mut_payload.encode()).hexdigest()
    if mut_pin == D3S4_USED_VARIANTS_SHA256:
        log.append("RED mutation: WITNESS_HEADER removal pin collision")
        print("A2-a2(i) WITNESS_HEADER removal not detected", file=sys.stderr)
        return 1
    if D3S4_USED_VARIANT_COUNT - 1 == D3S4_USED_VARIANT_COUNT_PIN:
        log.append("RED mutation: count pin would not catch removal")
        return 1
    log.append("mutation: WITNESS_HEADER removal desyncs hardcoded pin OK")

    bad = bytes([0x33] * 32) + _d1_be16(5) + _d1_be16(2) + _d1_be16(1) + _d1_be16(0)
    if d3s4_d1_chunk_body_prefix_ok(bad) is None:
        log.append("RED mutation anti-false-green: bad chunk accepted")
        print("A2-a2(i) mutation false-green", file=sys.stderr)
        return 1
    log.append("mutation anti-false-green: bad chunk RED OK")
    log.append("A2-a2(i) GREEN")
    return 0


