    ("SUPERSEDED", 4, "NEITHER", "ZERO", "RETIRED_SAME_SUCC", "PROGRESSED_S5_REQUIRED"),
    ("SUPERSEDED", 4, "NEITHER", "ZERO", "FULLY_ABSENT_PRED", "PROGRESSED_S5_REQUIRED"),
    ("SUPERSEDED", 4, "NEITHER", "N_A", "RETIRED_SAME_SUCC", "PROGRESSED_S5_REQUIRED"),
    ("SUPERSEDED", 4, "NEITHER", "N_A", "FULLY_ABSENT_PRED", "PROGRESSED_S5_REQUIRED"),
