def handwritten_expected_surface(
    header_mode: str,
    action: int,
    local: str,
    head: str,
    pred: str,
) -> str:
    """Lookup second-authority expected surface; default CORRUPT."""
    for row in _CLASSIFIER_LEGAL_HANDWRITTEN:
        if row[0] == header_mode and row[1] == action and row[2] == local and row[3] == head and row[4] == pred:
            return row[5]
    return SURFACE_CORRUPT


def classify_local_match(
    *,
    old_present: int,
    old_digest: bytes,
    new_present: int,
    new_digest: bytes,
    cur_present: int,
    cur_digest: bytes,
    local_invalid: bool = False,
) -> str:
    """§18.15.6 local class: OLD / NEW / NEITHER / INVALID.

    D1-forbidden: treating old/new both ABSENT as NEW. Both-absent is
    ABSENT_PAIR (surfaces as CORRUPT for ordinary members).
    """
    if local_invalid:
        return LOCAL_INVALID
    op, np, cp = int(old_present), int(new_present), int(cur_present)
    if op not in (0, 1) or np not in (0, 1) or cp not in (0, 1):
        return LOCAL_INVALID
    if op == 0 and np == 0:
        # both ABSENT pair is not a legal OLD/NEW match class
        return LOCAL_ABSENT_PAIR
    if cp == op and (cp == 0 or cur_digest == old_digest):
        if cp == np and (cp == 0 or cur_digest == new_digest):
            # old==new pair (both present equal) → NEW wins for all-new zero-transition
            return LOCAL_NEW
        return LOCAL_OLD
    if cp == np and (cp == 0 or cur_digest == new_digest):
        return LOCAL_NEW
    return LOCAL_NEITHER


def classify_member_surface(
    *,
    header_mode: str,
    local_class: str,
    head_rel: str,
    entry_action: int,
    pred_lifecycle: str = PRED_NONE,
) -> str:
    """§18.15.6 member surface after head/lifecycle rules.

    - entry_action=NONE is cleared scratch only → never NEW_THIS/PROGRESSED
    - SUPERSEDED + NEW + wrong head (OTHER/ZERO) → CORRUPT (not progressed)
    - SUPERSEDED + NEITHER + OTHER head → PROGRESSED
    - SUPERSEDE_WITNESS RETIRED/ABSENT → PROGRESSED (S5+S6 authority)
    """
    if entry_action not in ACTIONS_ALL:
        return SURFACE_CORRUPT
    if local_class not in LOCALS_ALL:
        return SURFACE_CORRUPT
    if head_rel not in HEADS_ALL:
        return SURFACE_CORRUPT
    if pred_lifecycle not in PREDS_ALL:
        return SURFACE_CORRUPT
    if header_mode not in HEADERS_ALL:
        return SURFACE_CORRUPT
    if local_class in (LOCAL_INVALID, LOCAL_ABSENT_PAIR):
        return SURFACE_CORRUPT
    if entry_action == ENTRY_ACTION_NONE:
        return SURFACE_CORRUPT

    if entry_action == ENTRY_ACTION_SUPERSEDE_WITNESS:
        if pred_lifecycle == PRED_NEW_SUPERSEDED:
            if local_class == LOCAL_NEW and head_rel == HEAD_NA:
                return SURFACE_NEW_THIS
            return SURFACE_CORRUPT
        if pred_lifecycle in (PRED_RETIRED_SAME_SUCC, PRED_ABSENT):
            if local_class == LOCAL_NEITHER:
                return SURFACE_PROGRESSED
            return SURFACE_CORRUPT
        return SURFACE_CORRUPT

    # Ordinary CREATE/REPLACE/ERASE — predecessor lifecycle must be NONE
    if pred_lifecycle != PRED_NONE:
        return SURFACE_CORRUPT

    if header_mode == HEADER_ACTIVE:
        if entry_action == ENTRY_ACTION_ERASE:
            if local_class == LOCAL_NEW and head_rel == HEAD_NA:
                return SURFACE_NEW_THIS
            return SURFACE_CORRUPT
        if local_class == LOCAL_NEW and head_rel in (HEAD_THIS, HEAD_NA):
            return SURFACE_NEW_THIS
        return SURFACE_CORRUPT

    if header_mode == HEADER_SUPERSEDED:
        if entry_action == ENTRY_ACTION_ERASE:
            if local_class == LOCAL_NEW and head_rel == HEAD_NA:
                return SURFACE_NEW_THIS
            return SURFACE_CORRUPT
        if local_class == LOCAL_OLD:
            return SURFACE_OLD
        if local_class == LOCAL_NEW and head_rel in (HEAD_THIS, HEAD_NA):
            return SURFACE_NEW_THIS
        if local_class == LOCAL_NEITHER and head_rel == HEAD_OTHER:
            return SURFACE_PROGRESSED
        if local_class == LOCAL_NEITHER and head_rel == HEAD_NA:
            return SURFACE_PROGRESSED
        return SURFACE_CORRUPT

    return SURFACE_CORRUPT


def fold_group_class(current: int, surface: str) -> int:
    """§18.15.6 group_class closed fold."""
    if surface == SURFACE_CORRUPT or current == GROUP_CORRUPT:
        return GROUP_CORRUPT
    if surface == SURFACE_OLD:
        if current == GROUP_UNSET:
            return GROUP_ALL_OLD
        if current == GROUP_ALL_OLD:
            return GROUP_ALL_OLD
        if current in (GROUP_ALL_NEW, GROUP_PROGRESSED_S5_REQUIRED, GROUP_MIXED_OLD_NEW):
            return GROUP_MIXED_OLD_NEW
        return GROUP_ALL_OLD
    if surface == SURFACE_PROGRESSED:
        if current in (GROUP_UNSET, GROUP_ALL_NEW, GROUP_PROGRESSED_S5_REQUIRED):
            return GROUP_PROGRESSED_S5_REQUIRED
        if current == GROUP_ALL_OLD:
            return GROUP_MIXED_OLD_NEW
        if current == GROUP_MIXED_OLD_NEW:
            return GROUP_MIXED_OLD_NEW
        return GROUP_PROGRESSED_S5_REQUIRED
    if surface == SURFACE_NEW_THIS:
        if current == GROUP_UNSET:
            return GROUP_ALL_NEW
        if current == GROUP_ALL_NEW:
            return GROUP_ALL_NEW
        if current == GROUP_ALL_OLD:
            return GROUP_MIXED_OLD_NEW
        if current == GROUP_PROGRESSED_S5_REQUIRED:
            return GROUP_PROGRESSED_S5_REQUIRED
        if current == GROUP_MIXED_OLD_NEW:
            return GROUP_MIXED_OLD_NEW
        return GROUP_ALL_NEW
    return GROUP_CORRUPT


def s6_authority_from_surface(entry_action: int, pred_lifecycle: str, surface: str) -> bool:
    """Mode31/32 SUPERSEDE RETIRED/ABSENT progression sets sticky S6 authority."""
    if surface != SURFACE_PROGRESSED:
        return False
    if entry_action != ENTRY_ACTION_SUPERSEDE_WITNESS:
        return False
    return pred_lifecycle in (PRED_RETIRED_SAME_SUCC, PRED_ABSENT)


def group_close_outcome(
    *,
    mode: int,
    group_class: int,
    framing_ok: bool = True,
    s6_authority: bool = False,
) -> str:
    """§18.15.6 GROUP_CLOSE exact outcomes.

    Mode32 SUPERSEDE predecessor RETIRED/ABSENT → DEFERRED_S5_AND_S6 (not S5-only).
    """
    if not framing_ok or group_class == GROUP_CORRUPT:
        return "CORRUPT"
    if mode == MODE_31:
        if group_class == GROUP_ALL_NEW:
            return "LOCAL_VALID"
        if group_class == GROUP_PROGRESSED_S5_REQUIRED:
            if s6_authority:
                return "DEFERRED_S5_AND_S6"
            return "CORRUPT"
        return "CORRUPT"
    if mode == MODE_32:
        if group_class in (GROUP_ALL_OLD, GROUP_MIXED_OLD_NEW, GROUP_CORRUPT):
            return "CORRUPT"
        if group_class == GROUP_PROGRESSED_S5_REQUIRED:
            if s6_authority:
                return "DEFERRED_S5_AND_S6"
            return "DEFERRED_S5"
        if group_class == GROUP_ALL_NEW:
            return "DEFERRED_S5"
        return "CORRUPT"
    return "CORRUPT"


def derive_surface_closed(
    header_mode: str,
    action: int,
    local: str,
    head: str,
    pred: str,
) -> str:
    """Authority derivation used for full-product matrix (single source of truth)."""
    return classify_member_surface(
        header_mode=header_mode,
        local_class=local,
        head_rel=head,
        entry_action=action,
        pred_lifecycle=pred,
    )


def classifier_full_product_rows() -> List[Dict[str, Any]]:
    """Full product enumeration: every combo has derived surface + fold outcomes.

    Legal cells keep explicit legal=True; all others legal=False / CORRUPT surface.
    """
    rows: List[Dict[str, Any]] = []
    for header in HEADERS_ALL:
        for action in ACTIONS_ALL:
            for local in LOCALS_ALL:
                for head in HEADS_ALL:
                    for pred in PREDS_ALL:
                        surface = derive_surface_closed(header, action, local, head, pred)
                        s6 = s6_authority_from_surface(action, pred, surface)
                        for fold_from in FOLDS_ALL:
                            fold_to = fold_group_class(fold_from, surface)
                            m31 = group_close_outcome(
                                mode=MODE_31, group_class=fold_to, s6_authority=s6,
                            )
                            m32 = group_close_outcome(
                                mode=MODE_32, group_class=fold_to, s6_authority=s6,
                            )
                            if header == HEADER_SUPERSEDED:
                                m31 = "CORRUPT"
                            if header == HEADER_ACTIVE:
                                m32 = "CORRUPT"
                            rows.append({
                                "header_mode": header,
                                "action": action,
                                "local": local,
                                "head": head,
                                "pred": pred,
                                "surface": surface,
                                "s6": s6,
                                "fold_from": fold_from,
                                "fold_to": fold_to,
                                "m31_close": m31,
                                "m32_close": m32,
                                "legal": surface != SURFACE_CORRUPT,
                            })
    return rows


def _classifier_matrix_payload() -> str:
    rows = classifier_full_product_rows()
    # Stable pin payload: full product sorted
    return json.dumps(rows, sort_keys=True, separators=(",", ":"))


def _classifier_matrix_pin() -> str:
    return hashlib.sha256(_classifier_matrix_payload().encode()).hexdigest()


# Baked once from full product; mutation of derive rules without pin update → RED.
# Placeholder overwritten at module load after functions defined — see assert below.
CLASSIFIER_MATRIX_SHA256 = "e051430c035b78758b519d51ed9ac63bc7e1d64df2ff72aa6beb8b3a2a5c081a"
CLASSIFIER_PRODUCT_COUNT = 8400


def gate_a2a2_classifier_self_test(log: List[str]) -> int:
    """(ii) Full-product closed classifier matrix + mutation self-test."""
    log.append("=== A2-a2(ii) classifier matrix §18.15.6 full product ===")
    rows = classifier_full_product_rows()
    live = hashlib.sha256(
        json.dumps(rows, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()
    # Hardcoded pin computed from closed product of this authority
    expected_count = (
        len(HEADERS_ALL) * len(ACTIONS_ALL) * len(LOCALS_ALL)
        * len(HEADS_ALL) * len(PREDS_ALL) * len(FOLDS_ALL)
    )
    if len(rows) != expected_count:
        log.append(f"RED product count {len(rows)} != {expected_count}")
        print("A2-a2(ii) product count", file=sys.stderr)
        return 1
    # HARDCODED pin of full product — mutation of derive rules without pin update RED.
    if live != CLASSIFIER_MATRIX_SHA256:
        log.append(f"RED classifier pin mismatch live={live}")
        print("A2-a2(ii) classifier pin mismatch", file=sys.stderr)
        return 1
    if CLASSIFIER_PRODUCT_COUNT != expected_count:
        log.append("RED product count pin")
        return 1
    legal_n = sum(1 for r in rows if r["legal"])
    illegal_n = len(rows) - legal_n
    log.append(
        f"classifier_pin={live[:16]}... OK product={len(rows)} "
        f"legal_cells={legal_n} corrupt_cells={illegal_n}"
    )

    # Local match unit cases
    d_old, d_new, d_cur = bytes([1]) * 32, bytes([2]) * 32, bytes([2]) * 32
    if classify_local_match(
        old_present=1, old_digest=d_old, new_present=1, new_digest=d_new,
        cur_present=1, cur_digest=d_cur,
    ) != LOCAL_NEW:
        print("A2-a2(ii) local NEW failed", file=sys.stderr)
        return 1
    if classify_local_match(
        old_present=1, old_digest=d_old, new_present=1, new_digest=d_new,
        cur_present=1, cur_digest=d_old,
    ) != LOCAL_OLD:
        print("A2-a2(ii) local OLD failed", file=sys.stderr)
        return 1
    if classify_local_match(
        old_present=1, old_digest=d_old, new_present=1, new_digest=d_new,
        cur_present=1, cur_digest=bytes([9]) * 32,
    ) != LOCAL_NEITHER:
        print("A2-a2(ii) local NEITHER failed", file=sys.stderr)
        return 1
    if classify_local_match(
        old_present=0, old_digest=D1_ZERO32, new_present=0, new_digest=D1_ZERO32,
        cur_present=0, cur_digest=D1_ZERO32,
    ) != LOCAL_ABSENT_PAIR:
        print("A2-a2(ii) both-absent must be ABSENT_PAIR not NEW", file=sys.stderr)
        return 1
    log.append("local match OLD/NEW/NEITHER/ABSENT_PAIR unit OK")

    # Second authority: every product surface must match handwritten §18.15.6 table
    # (independent of derive_surface_closed / matrix construction).
    for i, row in enumerate(rows):
        want = handwritten_expected_surface(
            row["header_mode"], row["action"], row["local"], row["head"], row["pred"],
        )
        if row["surface"] != want:
            msg = (
                f"product[{i}] surface {row['surface']} != handwritten {want} "
                f"for {(row['header_mode'], row['action'], row['local'], row['head'], row['pred'])}"
            )
            log.append("RED " + msg)
            print(f"A2-a2(ii) {msg}", file=sys.stderr)
            return 1
        surface = classify_member_surface(
            header_mode=row["header_mode"],
            local_class=row["local"],
            head_rel=row["head"],
            entry_action=row["action"],
            pred_lifecycle=row["pred"],
        )
        if surface != row["surface"]:
            msg = f"product[{i}] surface {surface} != {row['surface']}"
            log.append("RED " + msg)
            print(f"A2-a2(ii) {msg}", file=sys.stderr)
            return 1
        folded = fold_group_class(row["fold_from"], surface)
        if folded != row["fold_to"]:
            msg = f"product[{i}] fold {folded} != {row['fold_to']}"
            log.append("RED " + msg)
            print(f"A2-a2(ii) {msg}", file=sys.stderr)
            return 1
        s6 = s6_authority_from_surface(row["action"], row["pred"], surface)
        if s6 != row["s6"]:
            msg = f"product[{i}] s6 {s6} != {row['s6']}"
            log.append("RED " + msg)
            print(f"A2-a2(ii) {msg}", file=sys.stderr)
            return 1
        for mode, key in ((MODE_31, "m31_close"), (MODE_32, "m32_close")):
            out = group_close_outcome(mode=mode, group_class=folded, s6_authority=s6)
            if mode == MODE_31 and row["header_mode"] == HEADER_SUPERSEDED:
                out = "CORRUPT"
            if mode == MODE_32 and row["header_mode"] == HEADER_ACTIVE:
                out = "CORRUPT"
            if out != row[key]:
                msg = f"product[{i}] mode{mode} close {out} != {row[key]}"
                log.append("RED " + msg)
                print(f"A2-a2(ii) {msg}", file=sys.stderr)
                return 1
    log.append(f"full product {len(rows)} rows re-derived OK")

    # Review breakthroughs must RED
    if classify_member_surface(
        header_mode=HEADER_ACTIVE, local_class=LOCAL_NEW, head_rel=HEAD_THIS,
        entry_action=ENTRY_ACTION_NONE,
    ) != SURFACE_CORRUPT:
        print("A2-a2(ii) NONE+ACTIVE+NEW must CORRUPT", file=sys.stderr)
        return 1
    if classify_member_surface(
        header_mode=HEADER_SUPERSEDED, local_class=LOCAL_NEW, head_rel=HEAD_OTHER,
        entry_action=ENTRY_ACTION_CREATE,
    ) != SURFACE_CORRUPT:
        print("A2-a2(ii) SUPERSEDED NEW+OTHER must CORRUPT", file=sys.stderr)
        return 1
    if classify_member_surface(
        header_mode=HEADER_ACTIVE, local_class=LOCAL_OLD, head_rel=HEAD_NA,
        entry_action=ENTRY_ACTION_SUPERSEDE_WITNESS,
        pred_lifecycle=PRED_NEW_SUPERSEDED,
    ) != SURFACE_CORRUPT:
        print("A2-a2(ii) SUPERSEDE local=OLD must CORRUPT", file=sys.stderr)
        return 1
    if classify_member_surface(
        header_mode=HEADER_SUPERSEDED, local_class=LOCAL_NEITHER, head_rel=HEAD_NA,
        entry_action=ENTRY_ACTION_CREATE,
    ) != SURFACE_PROGRESSED:
        print("A2-a2(ii) SUPERSEDED fam3/4 NEITHER+HEAD_NA must PROGRESSED", file=sys.stderr)
        return 1
    # Mode32 SUPERSEDE RETIRED → S5+S6
    s6_out = group_close_outcome(
        mode=MODE_32, group_class=GROUP_PROGRESSED_S5_REQUIRED, s6_authority=True,
    )
    if s6_out != "DEFERRED_S5_AND_S6":
        print(f"A2-a2(ii) Mode32 S6 authority lost: {s6_out}", file=sys.stderr)
        return 1
    log.append("breakthrough NONE/ABSENT/SUPERSEDED-wrong-head/Mode32-S6 RED OK")

    # Mutation: drop one illegal product row → pin desync
    mut_rows = rows[:-1]
    mut_pin = hashlib.sha256(
        json.dumps(mut_rows, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()
    if mut_pin == live:
        log.append("RED mutation row-drop pin collision")
        return 1
    # Mutation: Mode31 ALL_NEW → CORRUPT in close without pin update
    if group_close_outcome(mode=MODE_31, group_class=GROUP_ALL_NEW) == "CORRUPT":
        # if implementation wrongly CORRUPT, pin still matches only if matrix also wrong;
        # force check that legal ALL_NEW is LOCAL_VALID
        print("A2-a2(ii) Mode31 ALL_NEW wrongly CORRUPT", file=sys.stderr)
        return 1
    # Source mutation both impl+expected to CORRUPT would stay green without pin:
    # we detect by re-deriving product and comparing to hardcoded live pin constant.
    log.append("mutation row-drop / ALL_NEW pin authority OK")
    log.append("A2-a2(ii) GREEN")
    return 0


# ---------------------------------------------------------------------------
# (iii) phase / mask / enum / MBZ full invalid domain (§18.15.12 :5678-5704)
# ---------------------------------------------------------------------------

# Legal value domains (closed). Invalid domain = type-domain complement + boundaries.
_U8 = range(0, 256)
_U16 = range(0, 65536)

ENTRY_FLAGS_VALID_ORDINARY = frozenset({0, 1, 2})  # 0 ordinary; 1 BASELINE; 2 WITNESSED
# primary-live owner-kind alias also allows 0..3 for BLOB kinds; closed max 3
ENTRY_FLAGS_VALID = frozenset({0, 1, 2, 3})
ENTRY_ROLE_VALID_ZERO = frozenset({0})
# role = (family<<8)|subtype while live; structural accept 0 or known catalog roles
ENTRY_ROLE_CATALOG: FrozenSet[int] = frozenset(
    {0}
    | {(5 << 8) | 0x01}
    | {(6 << 8) | st for st in D3S4_USED_FAMILY6_ST}
    | {(3 << 8), (4 << 8)}  # family3/4 low subtype 0 form
)
ENTRY_KEY_LEN_VALID = frozenset({0, 10} | set(range(13, 46)))
PRIMARY_RAW_LEN_VALID = frozenset(range(0, 256))  # u8 field; 256 not representable as u8
# u16 length field at 677 may be set out of range via setattr in tests
PRIMARY_RAW_LEN_U16_MAX_LEGAL = 255


def invalid_state_matrix() -> List[Tuple[str, int, Dict[str, Any]]]:
    """Full invalid domain probes (not 72 samples).

    For each field: illegal class representatives + all MBZ bits + review
    breakthrough values. Phase complement 9..255 is fully enumerated.
    """
    cases: List[Tuple[str, int, Dict[str, Any]]] = []

    # phase 9..255 full complement
    for ph in range(9, 256):
        cases.append((f"phase_{ph}", 31, {"phase": ph}))
    # pass_kind complement 2..255
    for pk in range(2, 256):
        cases.append((f"pass_kind_{pk}", 31, {"pass_kind": pk}))
    # focus_mode: 1..30, 35..255
    for fm in list(range(1, 31)) + list(range(35, 256)):
        cases.append((f"focus_mode_{fm}", 31, {"focus_mode": fm}))
    # group_class 6..255
    for gc in range(6, 256):
        cases.append((f"group_class_{gc}", 31, {"group_class": gc}))
    # arm_cursor mode-specific complements
    for ac in range(0, 256):
        if ac not in ARM_CURSOR_VALID_M31_32:
            cases.append((f"m31_arm_{ac}", 31, {"arm_cursor": ac}))
            cases.append((f"m32_arm_{ac}", 32, {"arm_cursor": ac}))
        if ac not in ARM_CURSOR_VALID_M33:
            cases.append((f"m33_arm_{ac}", 33, {"arm_cursor": ac}))
        if ac not in ARM_CURSOR_VALID_M34:
            cases.append((f"m34_arm_{ac}", 34, {"arm_cursor": ac}))
    # member_substep 4..255
    for ms in range(4, 256):
        cases.append((f"member_substep_{ms}", 31, {"member_substep": ms}))
    # membership_substep 2..255
    for ms in range(2, 256):
        cases.append((f"membership_substep_{ms}", 34, {"membership_substep": ms}))
    # membership_need_mask: only 0..3 legal
    for nm in range(4, 256):
        cases.append((f"need_mask_{nm}", 34, {"membership_need_mask": nm}))
    # found_count 3..255
    for fc in range(3, 256):
        cases.append((f"found_a_{fc}", 34, {"found_count_a": fc}))
        cases.append((f"found_b_{fc}", 34, {"found_count_b": fc}))
    # entry_action 5..255
    for ea in range(5, 256):
        cases.append((f"entry_action_{ea}", 31, {"entry_action": ea}))
    # entry present 2..255
    for ep in range(2, 256):
        cases.append((f"old_present_{ep}", 31, {"entry_old_present": ep}))
        cases.append((f"new_present_{ep}", 31, {"entry_new_present": ep}))
    # count MBZ bits3..7 individually + combos
    for bit in range(3, 8):
        cases.append((f"count_mbz_bit{bit}", 31, {"count_complete_mask": 1 << bit}))
    cases.append(("count_mbz_all", 31, {"count_complete_mask": COUNT_MBZ}))
    # binding MBZ bits6..7
    for bit in (6, 7):
        cases.append((f"binding_mbz_bit{bit}", 31, {"binding_complete_mask": 1 << bit}))
    # sha_block_len 64..255
    for sl in range(64, 256):
        cases.append((
            f"sha_block_len_{sl}", 31,
            {"sha_block_len": sl, "phase": PHASE_MEMBER_PIPELINE,
             "drive_get_quota": 1, "drive_gets_used": 0},
        ))
    # negative sha_block_len / gets
    cases.append(("sha_block_len_neg", 31, {
        "sha_block_len": -1, "phase": PHASE_MEMBER_PIPELINE,
        "drive_get_quota": 1, "drive_gets_used": 0,
    }))
    cases.append(("gets_used_neg", 31, {
        "phase": PHASE_SELECT, "drive_get_quota": 1, "drive_gets_used": -1,
    }))
    # quota domain
    cases.append(("quota_0_active", 31, {"phase": PHASE_SELECT, "drive_get_quota": 0}))
    cases.append(("quota_65536", 31, {"phase": PHASE_SELECT, "drive_get_quota": 65536}))
    cases.append(("used_gt_quota", 31, {
        "phase": PHASE_SELECT, "drive_get_quota": 1, "drive_gets_used": 2,
    }))
    # IDLE quota must be 0 (review breakthrough)
    cases.append(("idle_quota_1", 31, {"phase": PHASE_IDLE, "drive_get_quota": 1}))
    cases.append(("idle_quota_256", 31, {"phase": PHASE_IDLE, "drive_get_quota": 256}))
    # entry_flags 255 and other illegal
    for ef in range(0, 256):
        if ef not in ENTRY_FLAGS_VALID:
            cases.append((f"entry_flags_{ef}", 31, {"entry_flags": ef}))
    # entry_record_role illegal
    for role in (0xFFFF, 0x0100, 0x0699, 0x0700, 0x1234, 0xFF00, 0x0502, 0x06FF):
        if role not in ENTRY_ROLE_CATALOG:
            cases.append((f"entry_role_{role:#x}", 31, {"entry_record_role": role}))
    # entry_key_length illegal (255, 11, 12, 46.., etc.)
    for kl in list(range(1, 10)) + [11, 12] + list(range(46, 256)) + [255, 256, 0xFFFF]:
        if kl not in ENTRY_KEY_LEN_VALID:
            cases.append((f"entry_key_len_{kl}", 31, {"entry_key_length": kl}))
    # primary raw length 256 (u16 out of array capacity)
    cases.append(("raw_len_256", 31, {
        "phase": PHASE_MEMBER_PIPELINE,
        "expected_primary_raw_len": 256,
        "peer_key_len": 16,
        "entry_record_role": (6 << 8) | 0x20,
        "drive_get_quota": 1, "drive_gets_used": 0,
    }))
    cases.append(("raw2_len_65", 31, {
        "phase": PHASE_MEMBER_PIPELINE,
        "expected_primary_raw2_len": 65,
        "drive_get_quota": 1, "drive_gets_used": 0,
    }))
    cases.append(("aux_len_17", 31, {
        "phase": PHASE_MEMBER_PIPELINE,
        "expected_primary_aux_len": 17,
        "drive_get_quota": 1, "drive_gets_used": 0,
    }))
    # cross-mode count bits
    _q = {"drive_get_quota": 1, "drive_gets_used": 0}
    cases.append(("m32_m31_count_bit", 32, {
        "phase": PHASE_COMPLETE,
        "count_complete_mask": COUNT_BIT_M31,  # wrong mode bit
        "binding_complete_mask": 0,
        "flags": FLAG_COMPLETE_READY,
        **_q,
    }))
    cases.append(("m31_m32_count_bit", 31, {
        "phase": PHASE_COMPLETE,
        "count_complete_mask": COUNT_BIT_M32,
        "binding_complete_mask": 0,
        "flags": FLAG_COMPLETE_READY,
        **_q,
    }))
    # Mode33 bit7 illegal
    cases.append(("m33_bit7", 33, {
        "phase": PHASE_COMPLETE,
        "flags": FLAG_S5_REQUIRED_SEEN,
        "count_complete_mask": 0,
        "binding_complete_mask": BINDING_BIT_M33,
        **_q,
    }))
    # COMPLETE_READY + deferred bits
    cases.append(("complete_ready_bit7", 31, {
        "phase": PHASE_COMPLETE,
        "flags": FLAG_COMPLETE_READY | FLAG_S5_REQUIRED_SEEN,
        "count_complete_mask": COUNT_BIT_M31,
        "binding_complete_mask": 0,
        **_q,
    }))
    cases.append(("complete_ready_bit5", 33, {
        "phase": PHASE_COMPLETE,
        "flags": FLAG_COMPLETE_READY,
        "count_complete_mask": 0,
        "binding_complete_mask": BINDING_BIT_M33 | BINDING_BIT_S6_REQUIRED,
        **_q,
    }))
    # out-of-range masks (byte domain extra)
    cases.append(("count_mask_0xff", 31, {
        "phase": PHASE_COMPLETE,
        "count_complete_mask": 0xFF,
        "binding_complete_mask": 0,
        "flags": FLAG_COMPLETE_READY,
        **_q,
    }))
    cases.append(("binding_mask_0xff", 33, {
        "phase": PHASE_COMPLETE,
        "count_complete_mask": 0,
        "binding_complete_mask": 0xFF,
        "flags": FLAG_COMPLETE_READY,
        **_q,
    }))
    # §18.15.12 combination class probes (phase-disjoint / role-key / length-data)
    cases.append(("idle_role_1", 31, {
        "phase": PHASE_IDLE, "entry_record_role": 1,
    }))
    cases.append(("idle_flags_3", 31, {
        "phase": PHASE_IDLE, "entry_flags": 3,
    }))
    cases.append(("idle_key_len_13", 31, {
        "phase": PHASE_IDLE, "entry_key_length": 13,
    }))
    cases.append(("idle_raw_len_1", 31, {
        "phase": PHASE_IDLE, "expected_primary_raw_len": 1,
    }))
    cases.append(("idle_peer_key_len_13", 31, {
        "phase": PHASE_IDLE, "peer_key_len": 13,
    }))
    cases.append(("idle_role_flags_combo", 31, {
        "phase": PHASE_IDLE, "entry_record_role": (6 << 8) | 0x20,
        "entry_flags": 1, "entry_key_length": 29,
    }))
    cases.append(("primary_live_raw_no_peer", 31, {
        "phase": PHASE_MEMBER_PIPELINE,
        "member_substep": 2,
        "drive_get_quota": 1, "drive_gets_used": 0,
        "expected_primary_raw_len": 16,
        "peer_key_len": 0,
        "entry_record_role": (6 << 8) | 0x20,
    }))
    cases.append(("primary_live_raw_role0", 31, {
        "phase": PHASE_MEMBER_PIPELINE,
        "member_substep": 2,
        "drive_get_quota": 1, "drive_gets_used": 0,
        "expected_primary_raw_len": 16,
        "peer_key_len": 29,
        "entry_record_role": 0,
    }))
    cases.append(("fam3_key_len_29", 31, {
        "phase": PHASE_MEMBER_PIPELINE,
        "drive_get_quota": 1, "drive_gets_used": 0,
        "entry_record_role": (3 << 8),
        "entry_key_length": 29,
    }))
    cases.append(("select_primary_pin_live", 31, {
        "phase": PHASE_SELECT,
        "drive_get_quota": 1, "drive_gets_used": 0,
        "member_substep": 0,
        "expected_primary_raw_len": 8,
        "peer_key_len": 29,
        "entry_record_role": (6 << 8) | 0x20,
        "focus_mode": 31,
    }))
    # r3 breakthrough: SELECT/active illegal combinations that previously false-GREEN
    cases.append(("select_role_1", 31, {
        "phase": PHASE_SELECT, "drive_get_quota": 1, "drive_gets_used": 0,
        "focus_mode": 31, "entry_record_role": 1,
    }))
    cases.append(("active_focus_mode_0", 31, {
        "phase": PHASE_SELECT, "drive_get_quota": 1, "drive_gets_used": 0,
        "focus_mode": 0,
    }))
    cases.append(("idle_focus_mode_31", 31, {
        "phase": PHASE_IDLE, "focus_mode": 31,
    }))
    cases.append(("idle_group_all_new", 31, {
        "phase": PHASE_IDLE, "group_class": GROUP_ALL_NEW,
    }))
    cases.append(("isolated_raw2_substep0", 31, {
        "phase": PHASE_MEMBER_PIPELINE, "member_substep": 0,
        "drive_get_quota": 1, "drive_gets_used": 0, "focus_mode": 31,
        "expected_primary_raw2_len": 8,
    }))
    cases.append(("substep2_primary_pins_missing", 31, {
        "phase": PHASE_MEMBER_PIPELINE, "member_substep": 2,
        "drive_get_quota": 1, "drive_gets_used": 0, "focus_mode": 31,
        "expected_primary_raw_len": 0, "peer_key_len": 0, "entry_record_role": 0,
    }))
    # A2B-R6-006: COMPLETE_READY (flags.bit3) before the COMPLETE transition is
    # terminal corruption in every pre-COMPLETE phase of every mode (§5704).
    _r6006_phases = [
        ("select", PHASE_SELECT, (31, 32, 33, 34), {}),
        ("member", PHASE_MEMBER_PIPELINE, (31, 32), {"member_substep": 1}),
        ("group_close", PHASE_GROUP_CLOSE, (31, 32), {}),
        ("m33_bind", PHASE_MODE33_BIND, (33,), {}),
        ("m34_arm", PHASE_MODE34_ARM, (34,), {"arm_cursor": 0}),
    ]
    for _label, _ph, _modes, _extra in _r6006_phases:
        for _mode in _modes:
            ov = {"phase": _ph, "drive_get_quota": 1, "drive_gets_used": 0,
                  "focus_mode": _mode, "flags": FLAG_BASELINE_DONE | FLAG_COMPLETE_READY}
            ov.update(_extra)
            cases.append((f"r6006_ready_pre_complete_{_label}_m{_mode}", _mode, ov))
    return cases


def gate_a2a2_invalid_enum_mbz_self_test(log: List[str]) -> int:
    """(iii) Full invalid enum/MBZ domain against RefSession.validate_state_invariants."""
    log.append("=== A2-a2(iii) invalid enum/MBZ domain §18.15.12 :5678-5704 ===")
    cases = invalid_state_matrix()
    log.append(f"invalid_probes={len(cases)}")
    failed = 0
    for label, mode, overrides in cases:
        s = RefSession(mode)
        if "phase" in overrides and overrides["phase"] != PHASE_IDLE and "focus_mode" not in overrides:
            s.focus_mode = mode
        if "phase" in overrides and overrides["phase"] != PHASE_IDLE and "pass_kind" not in overrides:
            s.pass_kind = PASS_INTERNAL
        for k, v in overrides.items():
            setattr(s, k, v)
        err = s.validate_state_invariants()
        if err is None:
            log.append(f"RED not-detected: {label} mode={mode} {overrides}")
            print(f"A2-a2(iii) not detected: {label}", file=sys.stderr)
            failed += 1
        # else RED OK (omit per-line flood for thousands of probes)
    if failed:
        log.append(f"RED {failed} probes not detected")
        return 1
    log.append(f"all {len(cases)} invalid probes RED OK")

    for mode in sorted(MODES_VALID):
        s = RefSession(mode)
        err = s.validate_state_invariants()
        if err is not None:
            log.append(f"RED legal default mode={mode}: {err}")
            print(f"A2-a2(iii) legal default mode={mode}: {err}", file=sys.stderr)
            return 1
    log.append("legal defaults PASS for modes 31..34")

    for mode in sorted(MODES_VALID):
        s = RefSession(mode)
        s.begin()
        s.drive()
        err = s.validate_state_invariants()
        if err is not None:
            log.append(f"RED legal active SELECT mode={mode}: {err}")
            print(f"A2-a2(iii) legal active SELECT mode={mode}: {err}", file=sys.stderr)
            return 1
    log.append("legal active SELECT PASS for modes 31..34")

    # Mutation: PHASE_VALID must not contain 11
    if 11 in PHASE_VALID:
        print("A2-a2(iii) PHASE_VALID contains 11", file=sys.stderr)
        return 1
    if COUNT_MBZ != 0xF8:
        print("A2-a2(iii) COUNT_MBZ pin", file=sys.stderr)
        return 1
    if BINDING_MBZ != 0xC0:
        print("A2-a2(iii) BINDING_MBZ pin", file=sys.stderr)
        return 1
    if PHASE_VALID != frozenset({0, 1, 2, 3, 4, 5, 6, 7, 8}):
        print("A2-a2(iii) PHASE_VALID pin", file=sys.stderr)
        return 1
    # Softening phase=11 must be detectable: live validate rejects
    s = RefSession(31)
    s.phase = 11
    if s.validate_state_invariants() is None:
        print("A2-a2(iii) phase=11 not rejected", file=sys.stderr)
        return 1
    log.append("mutation pins COUNT_MBZ/BINDING_MBZ/PHASE_VALID + phase11 RED OK")
    log.append("A2-a2(iii) GREEN")
    return 0


# ---------------------------------------------------------------------------
# (iv) CLI 4-command fail-closed complete net (content-fixed diagnostics)
# ---------------------------------------------------------------------------

def gate_a2a2_cli_fail_closed_self_test(log: List[str]) -> int:
    """(iv) generate/check/emit-c-fixture/self-test with fixed diagnostics."""
    import subprocess

    log.append("=== A2-a2(iv) CLI 4-cmd fail-closed matrix ===")
    script = str(Path(__file__).resolve())
    # Fresh per-run nonce: a replay layer returning previously recorded
    # (stdout,stderr,rc) cannot reproduce a valid attest for a new nonce.
    nonce = os.urandom(16).hex()

    def run(args: List[str]) -> Any:
        env = dict(os.environ)
        env["A2A2_ATTEST_NONCE"] = nonce
        return subprocess.run(
            [sys.executable, script, *args],
            capture_output=True,
            text=True,
            env=env,
        )

    _subprocess_count = [0]
    _child_fingerprints: List[str] = []

    def expect_exit2(
        label: str,
        args: List[str],
        *,
        diag_sub: str,
        validator: str,
        side_path: Optional[Path] = None,
        side_before: Optional[bytes] = None,
    ) -> int:
        _subprocess_count[0] += 1
        r = run(args)
        _fp_input = "|".join(args) + "|" + label
        _fp_output = (r.stderr or "") + str(r.returncode)
        _child_fingerprints.append(
            hashlib.sha256((_fp_input + "||" + _fp_output).encode()).hexdigest()[:16]
        )
        if r.returncode != 2:
            log.append(f"RED {label}: rc={r.returncode} err={r.stderr!r}")
            print(f"A2-a2(iv) {label}: rc={r.returncode}", file=sys.stderr)
            return 1
        if r.stdout.strip():
            log.append(f"RED {label}: stdout nonempty {r.stdout!r}")
            print(f"A2-a2(iv) {label}: stdout", file=sys.stderr)
            return 1
        if "Traceback" in (r.stderr or "") or "AttributeError" in (r.stderr or ""):
            log.append(f"RED {label}: traceback leaked")
            print(f"A2-a2(iv) {label}: traceback", file=sys.stderr)
            return 1
        lines = [ln for ln in (r.stderr or "").splitlines() if ln.strip()]
        if len(lines) != 1 or not lines[0].startswith("error:"):
            log.append(f"RED {label}: stderr grammar {lines!r}")
            print(f"A2-a2(iv) {label}: stderr {lines!r}", file=sys.stderr)
            return 1
        if diag_sub not in lines[0]:
            log.append(
                f"RED {label}: diag missing {diag_sub!r} in {lines[0]!r} "
                f"(validator={validator})"
            )
            print(f"A2-a2(iv) {label}: diag {lines[0]!r}", file=sys.stderr)
            return 1
        if "[MUTATED" in lines[0] or "EXTRA-DIAGNOSTIC" in lines[0]:
            log.append(f"RED {label}: unexpected marker in diag {lines[0]!r}")
            print(f"A2-a2(iv) {label}: mutated marker", file=sys.stderr)
            return 1
        if side_path is not None and side_before is not None:
            after = side_path.read_bytes() if side_path.is_file() else b""
            if after != side_before:
                log.append(f"RED {label}: side-effect mutated {side_path}")
                print(f"A2-a2(iv) {label}: side-effect", file=sys.stderr)
                return 1
        log.append(f"exit2 OK {label} diag={diag_sub!r} via={validator}")
        return 0

    def expect_exit0(
        label: str,
        args: List[str],
        *,
        validator: str,
        side_path: Optional[Path] = None,
        side_before: Optional[bytes] = None,
    ) -> int:
        """Implemented-command success channel: rc=0, empty stderr, no traceback."""
        _subprocess_count[0] += 1
        r = run(args)
        _fp_input = "|".join(args) + "|" + label
        _fp_output = (r.stderr or "") + str(r.returncode)
        _child_fingerprints.append(
            hashlib.sha256((_fp_input + "||" + _fp_output).encode()).hexdigest()[:16]
        )
        if r.returncode != 0:
            log.append(f"RED {label}: rc={r.returncode} err={r.stderr!r}")
            print(f"A2-a2(iv) {label}: rc={r.returncode}", file=sys.stderr)
            return 1
        if (r.stderr or "").strip():
            log.append(f"RED {label}: stderr nonempty {r.stderr!r}")
            print(f"A2-a2(iv) {label}: stderr", file=sys.stderr)
            return 1
        if "Traceback" in (r.stderr or "") or "AttributeError" in (r.stderr or ""):
            log.append(f"RED {label}: traceback leaked")
            print(f"A2-a2(iv) {label}: traceback", file=sys.stderr)
            return 1
        if side_path is not None and side_before is not None:
            after = side_path.read_bytes() if side_path.is_file() else b""
            if after != side_before:
                log.append(f"RED {label}: side-effect mutated {side_path}")
                print(f"A2-a2(iv) {label}: side-effect", file=sys.stderr)
                return 1
        log.append(f"exit0 OK {label} via={validator}")
        return 0

    arity_cases = [
        ("no_args", [], "missing command", "main_arity"),
        ("unknown_cmd", ["nope"], "unknown command", "main_cmd"),
        ("self_test_surplus", ["self-test", "x"], "surplus args for self-test", "main_self_test"),
        ("generate_surplus", ["generate", "a", "b"], "surplus args for generate", "main_generate"),
        ("check_surplus", ["check", "a", "b"], "surplus args for check", "main_check"),
        ("emit_arity0", ["emit-c-fixture"], "emit-c-fixture requires exact", "main_emit"),
        ("emit_arity1", ["emit-c-fixture", "only.json"], "emit-c-fixture requires exact", "main_emit"),
        ("emit_arity3", ["emit-c-fixture", "a.json", "b.h", "c"], "emit-c-fixture requires exact", "main_emit"),
        ("help_surplus", ["--help", "x"], "surplus args for --help", "main_help"),
    ]
    for label, args, diag, val in arity_cases:
        if expect_exit2(f"arity:{label}", args, diag_sub=diag, validator=val) != 0:
            return 1

    with tempfile.TemporaryDirectory() as td:
        td_p = Path(td)
        check_payloads = [
            ("check_array", "[]", "document is not an object", "check_object"),
            ("check_null", "null", "document is not an object", "check_object"),
            ("check_string", '"nope"', "document is not an object", "check_object"),
            ("check_number", "42", "document is not an object", "check_object"),
            ("check_true", "true", "document is not an object", "check_object"),
            ("check_false", "false", "document is not an object", "check_object"),
            ("check_float", "1.5", "document is not an object", "check_object"),
            ("check_empty_obj", "{}", "document shape", "validate_document_shape"),
            ("check_malformed", "{not json", "unreadable/malformed", "check_json"),
            ("check_vectors_string",
             '{"format":"ninlil-domain-scan-crossrow-v1-d3s4","vector_count":0,"vectors":"nope","content_sha256":"' + "0"*64 + '"}',
             "document shape", "validate_document_shape"),
            ("check_vectors_null",
             '{"format":"ninlil-domain-scan-crossrow-v1-d3s4","vector_count":0,"vectors":null,"content_sha256":"' + "0"*64 + '"}',
             "document shape", "validate_document_shape"),
            ("check_vector_count_bool",
             '{"format":"x","vector_count":true,"vectors":[],"content_sha256":"' + "0"*64 + '"}',
             "document shape", "validate_document_shape"),
            ("check_vector_count_float",
             '{"format":"x","vector_count":1.5,"vectors":[],"content_sha256":"' + "0"*64 + '"}',
             "document shape", "validate_document_shape"),
            ("check_nested_float_mode",
             '{"format":"x","vector_count":1,"vectors":[{"id":"a","kind":"x","mode":1.0,"ownership":"t","positive":true,"calls":[],"expected":{}}],"content_sha256":"' + "0"*64 + '"}',
             "document shape", "validate_document_shape"),
            ("check_elem_null",
             '{"format":"x","vector_count":1,"vectors":[null],"content_sha256":"' + "0"*64 + '"}',
             "document shape", "validate_document_shape"),
            ("check_overflow_u32",
             '{"format":"x","vector_count":4294967296,"vectors":[],"content_sha256":"' + "0"*64 + '"}',
             "document shape", "validate_document_shape"),
        ]
        for label, text, diag, val in check_payloads:
            p = td_p / f"{label}.json"
            p.write_text(text + "\n", encoding="utf-8")
            if expect_exit2(f"check:{label}", ["check", str(p)],
                            diag_sub=diag, validator=val) != 0:
                return 1

        gen_payloads = [
            ("gen_array", "[]", "not a usable object", "generate_path_shape"),
            ("gen_null", "null", "not a usable object", "generate_path_shape"),
            ("gen_string", '"x"', "not a usable object", "generate_path_shape"),
            ("gen_number", "0", "not a usable object", "generate_path_shape"),
            ("gen_bool", "true", "not a usable object", "generate_path_shape"),
            ("gen_float", "3.14", "not a usable object", "generate_path_shape"),
            ("gen_malformed", "{bad", "not a usable object", "generate_path_json"),
            ("gen_empty_obj", "{}", "document shape", "validate_prefix_283_authority"),
            ("gen_vectors_null",
             '{"format":"x","vector_count":0,"vectors":null,"content_sha256":"' + "0"*64 + '"}',
             "document shape", "validate_prefix_283_authority"),
        ]
        for label, text, diag, val in gen_payloads:
            p = td_p / f"{label}.json"
            before = (text + "\n").encode()
            p.write_bytes(before)
            if expect_exit2(f"generate:{label}", ["generate", str(p)],
                            diag_sub=diag, validator=val,
                            side_path=p, side_before=before) != 0:
                return 1

        missing = td_p / "no_such.json"
        # main() rejects missing input before emit_c_fixture; fixed diagnostic.
        if expect_exit2("emit:missing",
                        ["emit-c-fixture", str(missing), str(td_p / "o.h")],
                        diag_sub="unreadable input",
                        validator="main_emit_input") != 0:
            return 1
        bad = td_p / "bad_emit.json"
        before = b'{"sentinel":true}\n'
        bad.write_bytes(before)
        out_h = td_p / "out.h"
        if out_h.exists():
            out_h.unlink()
        if expect_exit2("emit:bad", ["emit-c-fixture", str(bad), str(out_h)],
                        diag_sub="d3s4 suffix not generated",
                        validator="emit_check",
                        side_path=bad, side_before=before) != 0:
            return 1
        if out_h.exists():
            log.append("RED emit:bad created out.h (side-effect)")
            print("A2-a2(iv) emit created header on failure", file=sys.stderr)
            return 1
        log.append("emit no-side-effect OK")

        if expect_exit2("check:missing", ["check", str(missing)],
                        diag_sub="unreadable input",
                        validator="main_check_input") != 0:
            return 1

        # Implemented generate/check: generate to a temp path from the live prefix
        # source (rc=0, deterministic, live DEFAULT_JSON NOT mutated by the child),
        # then check the generated d3s4 authority (rc=0).
        if DEFAULT_JSON.is_file():
            before = DEFAULT_JSON.read_bytes()
            gen_out = td_p / "generated_d3s4.json"
            if expect_exit0(
                "generate:to_temp", ["generate", str(gen_out)],
                validator="generate_implemented",
                side_path=DEFAULT_JSON, side_before=before,
            ) != 0:
                return 1
            first_bytes = gen_out.read_bytes()
            if expect_exit0(
                "generate:deterministic", ["generate", str(gen_out)],
                validator="generate_implemented",
                side_path=DEFAULT_JSON, side_before=before,
            ) != 0:
                return 1
            if gen_out.read_bytes() != first_bytes:
                log.append("RED generate:deterministic output not byte-identical")
                print("A2-a2(iv) generate determinism", file=sys.stderr)
                return 1
            log.append("generate determinism OK (byte-identical re-emit)")
            if expect_exit0(
                "check:generated_d3s4", ["check", str(gen_out)],
                validator="check_implemented",
            ) != 0:
                return 1
            # check legal d3s4-format candidate with only prefix (no suffix)
            # Build a d3s4-format doc from live prefix
            try:
                live = load_authority_expanded(
                    DEFAULT_JSON, pin_fixed_authority=True
                )
            except AuthorityError:
                log.append("RED generate: live authority expansion failed")
                return 1
            d3s4_cand = copy.deepcopy(live)
            d3s4_cand["format"] = FORMAT
            d3s4_cand["vector_count"] = D3S3_PREFIX
            d3s4_cand["vectors"] = d3s4_cand["vectors"][:D3S3_PREFIX]
            try:
                d3s4_cand["content_sha256"] = _compute_content_sha(d3s4_cand)
            except Exception:
                d3s4_cand["content_sha256"] = "0" * 64
            p_legal = td_p / "legal_d3s4_prefix_only.json"
            p_legal.write_text(json.dumps(d3s4_cand) + "\n", encoding="utf-8")
            if expect_exit2(
                "check:legal_prefix_only", ["check", str(p_legal)],
                diag_sub="d3s4 suffix not generated",
                validator="validate_prefix_283_authority+suffix",
            ) != 0:
                return 1

            bad_doc = copy.deepcopy(live)
            bad_doc["format"] = FORMAT
            bad_doc["vectors"] = bad_doc["vectors"][:D3S3_PREFIX] + [{
                "id": "X", "kind": "x", "mode": 31, "ownership": "t",
                "positive": True, "calls": [], "expected": {},
            }]
            bad_doc["vector_count"] = True
            p = td_p / "nested_bool_vc.json"
            p.write_text(json.dumps(bad_doc) + "\n", encoding="utf-8")
            if expect_exit2(
                "check:nested_bool_vc", ["check", str(p)],
                diag_sub="document shape",
                validator="validate_document_shape",
            ) != 0:
                return 1

            bad_ov = copy.deepcopy(live)
            bad_ov["format"] = FORMAT
            bad_ov["vectors"] = bad_ov["vectors"][:D3S3_PREFIX] + [{
                "id": "X", "kind": "x", "mode": 31, "ownership": "t",
                "positive": True, "calls": [],
                "expected": {"adopted": 2 ** 40},
            }]
            bad_ov["vector_count"] = D3S3_PREFIX + 1
            try:
                bad_ov["content_sha256"] = _compute_content_sha(bad_ov)
            except Exception:
                bad_ov["content_sha256"] = "0" * 64
            p2 = td_p / "nested_overflow.json"
            p2.write_text(json.dumps(bad_ov) + "\n", encoding="utf-8")
            if expect_exit2(
                "check:nested_overflow", ["check", str(p2)],
                diag_sub="document shape",
                validator="validate_document_shape",
            ) != 0:
                return 1

    # Mutation detector (behavior / in-process reach counters for ALL inspect fns):
    # CLI gate reset/assert expected reach set per case (not name-substring only).
    ALL_REACH = (
        "validate_prefix_283_authority",
        "validate_document_shape",
        "validate_state_invariants",
        "d3s4_d1_row_legality",
    )

    def _assert_reach(label: str, expected_min: Dict[str, int]) -> int:
        for name, want in expected_min.items():
            got = _reach_get(name)
            if got != want:
                log.append(
                    f"RED {label}: reach {name}={got} != expected {want}"
                )
                print(f"A2-a2(iv) {label} reach {name}={got}", file=sys.stderr)
                return 1
        for name in ALL_REACH:
            if name not in expected_min and _reach_get(name) != 0:
                log.append(
                    f"RED {label}: unexpected reach {name}={_reach_get(name)}"
                )
                print(f"A2-a2(iv) {label} unexpected {name}={_reach_get(name)}", file=sys.stderr)
                return 1
        log.append(
            f"reach: {label} "
            + " ".join(f"{n}={_reach_get(n)}" for n in ALL_REACH)
            + " OK"
        )
        return 0

    # Case: empty object → validate_document_shape (not prefix authority)
    with tempfile.TemporaryDirectory() as td_r:
        td_r_p = Path(td_r)
        p_empty = td_r_p / "empty.json"
        p_empty.write_text("{}\n", encoding="utf-8")
        _reach_reset(*ALL_REACH)
        rc = check(p_empty, quiet=True)
        if rc != 2:
            log.append(f"RED check empty rc={rc}")
            return 1
        if _assert_reach(
            "check_empty_obj",
            {"validate_document_shape": 1},
        ) != 0:
            return 1
        if _reach_get("validate_prefix_283_authority") != 0:
            log.append("RED empty obj must not reach validate_prefix_283_authority")
            return 1

        # Case: shape-invalid d3s4 format (missing version) still hits shape via prefix
        bad_shape = {
            "format": FORMAT,
            "vector_count": 0,
            "vectors": [],
            "content_sha256": "0" * 64,
        }
        p_bad = td_r_p / "bad_shape.json"
        p_bad.write_text(json.dumps(bad_shape) + "\n", encoding="utf-8")
        _reach_reset(*ALL_REACH)
        rc = check(p_bad, quiet=True)
        if rc != 2:
            log.append(f"RED check bad_shape rc={rc}")
            return 1
        if _assert_reach(
            "check_bad_shape",
            {
                "validate_prefix_283_authority": 1,
                "validate_document_shape": 1,
            },
        ) != 0:
            return 1

    if DEFAULT_JSON.is_file():
        # R5-005 both-sided gate, SIDE 1: the suffix CONSTRUCTION alone (the inline
        # _build_suffix_vectors path) reaches neither the full suffix gate set nor the
        # independent ordinal checker — validation reach 0. generate's fail-closed check
        # run is a SEPARATE path asserted below (side 2 requires check reach > 0).
        _reach_reset(*ALL_REACH)
        _reach_reset("d3s4_full_validation", "d3s4_ordinal_checker")
        _construction_probe = _build_suffix_vectors()
        if _reach_get("d3s4_full_validation") != 0:
            log.append("RED suffix construction must not run the full suffix gate set")
            print("A2-a2(iv) construction full-validation reach", file=sys.stderr)
            return 1
        if _reach_get("d3s4_ordinal_checker") != 0:
            log.append("RED suffix construction must not run the independent ordinal checker")
            print("A2-a2(iv) construction ordinal-checker reach", file=sys.stderr)
            return 1
        log.append(
            "construction in-process OK full_validation=0 ordinal_checker=0 "
            f"vectors={len(_construction_probe)}"
        )

        # Implemented generate (in-process) writes a temp d3s4 authority without
        # raising; it must reach the prefix-283 authority validator. R5-005: generate
        # now runs the FULL check gate set fail-closed on a temp file before replacing
        # output, so it reaches the full validation + ordinal checker (>0).
        with tempfile.TemporaryDirectory() as td_g:
            td_g_p = Path(td_g)
            gen_in = td_g_p / "generated_inproc.json"
            _reach_reset(*ALL_REACH)
            _reach_reset("d3s4_full_validation", "d3s4_ordinal_checker")
            import io as _io
            _saved_stderr = sys.stderr
            _saved_stdout = sys.stdout
            sys.stderr = _io.StringIO()
            sys.stdout = _io.StringIO()
            try:
                generate(gen_in)
            except SystemExit as e:
                sys.stderr = _saved_stderr
                sys.stdout = _saved_stdout
                log.append(f"RED generate in-process raised SystemExit {e.code}")
                print("A2-a2(iv) generate in-process exit", file=sys.stderr)
                return 1
            sys.stderr = _saved_stderr
            sys.stdout = _saved_stdout
            if _reach_get("validate_prefix_283_authority") < 1:
                log.append("RED generate in-process did not reach prefix authority")
                print("A2-a2(iv) generate reach", file=sys.stderr)
                return 1
            # R5-005 fail-closed: generate ran the full gate set on the temp authority
            # before replacing output (check-equivalent reach > 0). This is the inverse
            # of the superseded "full validation non-reach is green" condition.
            if _reach_get("d3s4_full_validation") < 1:
                log.append("RED generate fail-closed did not run the full suffix gate set")
                print("A2-a2(iv) generate full-validation reach", file=sys.stderr)
                return 1
            if _reach_get("d3s4_ordinal_checker") < 1:
                log.append("RED generate fail-closed did not run the independent ordinal checker")
                print("A2-a2(iv) generate ordinal-checker reach", file=sys.stderr)
                return 1
            log.append(
                "generate in-process OK (fail-closed) "
                f"prefix={_reach_get('validate_prefix_283_authority')} "
                f"shape={_reach_get('validate_document_shape')} "
                f"full_validation={_reach_get('d3s4_full_validation')} "
                f"ordinal_checker={_reach_get('d3s4_ordinal_checker')}"
            )

            # Implemented check (in-process) on the generated authority: rc=0 with
            # prefix authority + document shape + D1 row gate + RefSession re-drive
            # (finalize state-invariants on COMPLETE positives) all reached.
            _suffix_probe = _build_suffix_vectors()
            expected_d1 = (
                sum(len(v.get("rows") or []) for v in _suffix_probe)
                # _gate_idem_tuple_boundaries performs five deliberate
                # D1-negative body probes (scope145, key65, txn15, txn17,
                # and tuple swap) in addition to the per-row legality pass.
                + 5
            )
            # A2-b rev5 step5 (catalog #10) / step8 (R4-005): a P10 composition vector drives
            # its primary session PLUS the second session it accumulates (the +1 main re-drive
            # extra), and the compose gate additionally re-drives BOTH closed multi-session
            # scripts (one validate_state_invariants reach per compose_sessions entry). The P11
            # finalize-script gate replays each scripted finalize through a fresh COMPLETE
            # session (kinds that reach validate_state_invariants: finalize/evaluator_off/
            # cleanup_failure/NULL/invalid_carrier; abort/abort_cleanup_failure use abort(),
            # alias returns before the invariant check). The assertion stays exact.
            compose_extra = sum(
                1 + len(v.get("compose_sessions") or [])
                for v in _suffix_probe if v.get("compose_output")
            )
            p11_replay_extra = sum(
                1 for v in _suffix_probe
                if v.get("id") in D3S4_P11_FAULT_BY_VID
                and D3S4_P11_FAULT_BY_VID[v["id"]].get("op") == "finalize"
                and D3S4_P11_FAULT_BY_VID[v["id"]].get("shape") == "evaluator_off"
            )
            # B1 (R6-002/N15): P11 fault shapes on Port-0 paths (NULL / alias overlap /
            # invalid carrier / prevalidation / invalid-state / incomplete-shape) reject
            # before readiness derivation, so their finalize never reaches
            # validate_state_invariants.
            _P11_NO_SV_SHAPES = frozenset({
                "NULL",
                "alias_overlap_session", "alias_overlap_workspace",
                "alias_overlap_ops", "alias_overlap_handle_slot",
                "alias_overlap_s4_context",
                "invalid_carrier_present_gt1",
                "invalid_carrier_present0_disp_nonzero",
                "invalid_carrier_present1_disp_gt3",
                "prevalidation_disjoint_violation",
                "invalid_state_pre_finalize",
                "incomplete_shape_mid_yield",
            })
            p11_no_sv = sum(
                1 for v in _suffix_probe
                if v.get("positive") and any(
                    f.get("shape") in _P11_NO_SV_SHAPES for f in (v.get("faults") or [])
                )
            )
            expected_sv = (
                sum(1 for v in _suffix_probe if v.get("positive"))
                + compose_extra + p11_replay_extra - p11_no_sv
            )
            _reach_reset(*ALL_REACH)
            _reach_reset("d3s4_full_validation", "d3s4_ordinal_checker")
            rc = check(gen_in, quiet=True)
            if rc != 0:
                log.append(f"RED check generated returned rc={rc} (expected 0)")
                print("A2-a2(iv) check generated rc", file=sys.stderr)
                return 1
            if _assert_reach(
                "check_generated_d3s4",
                {
                    "validate_prefix_283_authority": 1,
                    "validate_document_shape": 1,
                    "d3s4_d1_row_legality": expected_d1,
                    "validate_state_invariants": expected_sv,
                },
            ) != 0:
                return 1
            # R4-008: the check path reaches the full suffix gate set and the independent
            # ordinal checker (both re-derived from stored rows, not RefSession output).
            if _reach_get("d3s4_full_validation") < 1:
                log.append("RED check did not run the full suffix gate set")
                print("A2-a2(iv) check full-validation reach", file=sys.stderr)
                return 1
            if _reach_get("d3s4_ordinal_checker") < 1:
                log.append("RED check did not run the independent ordinal checker")
                print("A2-a2(iv) check ordinal-checker reach", file=sys.stderr)
                return 1

        # Case: validate_state_invariants reached by legal default + one illegal probe
        _reach_reset(*ALL_REACH)
        s = RefSession(31)
        if s.validate_state_invariants() is not None:
            log.append("RED legal default failed state invariants")
            return 1
        s.phase = PHASE_SELECT
        s.focus_mode = 0
        s.drive_get_quota = 1
        if s.validate_state_invariants() is None:
            log.append("RED active focus_mode=0 not rejected")
            return 1
        if _assert_reach("state_invariants_probe", {"validate_state_invariants": 2}) != 0:
            return 1

        # Case: d3s4_d1_row_legality reached on a known family3 short value
        _reach_reset(*ALL_REACH)
        k3 = DOMAIN_KEY_ROOT + bytes([3, 0x01])
        if d3s4_d1_row_legality(k3, b"\x00") is None:
            log.append("RED fam3 one-byte must RED")
            return 1
        if _assert_reach("d1_row_legality_probe", {"d3s4_d1_row_legality": 1}) != 0:
            return 1

        # Shape-valid modification of canonical prefix → RED via prefix authority
        with tempfile.TemporaryDirectory() as td2:
            td2_p = Path(td2)
            try:
                live, _live_raw, _live_manifest = _read_expanded_authority(
                    DEFAULT_JSON, pin_fixed_authority=True
                )
            except AuthorityError:
                log.append("RED canonical authority loader rejected live tree")
                return 1
            tampered = copy.deepcopy(live)
            if isinstance(tampered.get("vectors"), list) and tampered["vectors"]:
                v0 = tampered["vectors"][0]
                if isinstance(v0, dict) and "id" in v0:
                    v0["id"] = str(v0["id"]) + "_TAMPER_SHAPE_VALID"
                try:
                    tampered["content_sha256"] = _compute_content_sha(tampered)
                except Exception:
                    pass
                p_tamper = td2_p / "shape_valid_prefix_tamper.json"
                p_tamper.write_text(json.dumps(tampered) + "\n", encoding="utf-8")
                _reach_reset(*ALL_REACH)
                rc_t = check(p_tamper, quiet=True)
                if rc_t != 2:
                    log.append(f"RED shape-valid prefix tamper rc={rc_t}")
                    return 1
                if _assert_reach(
                    "check_shape_valid_prefix_tamper",
                    {
                        "validate_prefix_283_authority": 1,
                        "validate_document_shape": 1,
                    },
                ) != 0:
                    return 1
                if expect_exit2(
                    "check:shape_valid_prefix_tamper",
                    ["check", str(p_tamper)],
                    diag_sub="prefix-283",
                    validator="validate_prefix_283_authority",
                ) != 0:
                    return 1
                before_b = p_tamper.read_bytes()
                if expect_exit2(
                    "generate:shape_valid_prefix_tamper",
                    ["generate", str(p_tamper)],
                    diag_sub="document shape",
                    validator="validate_prefix_283_authority",
                    side_path=p_tamper,
                    side_before=before_b,
                ) != 0:
                    return 1

    if not DEFAULT_JSON.is_file():
        log.append(f"RED canonical prefix missing: {DEFAULT_JSON}")
        print("A2-a2(iv) canonical prefix missing", file=sys.stderr)
        return 1

    if _subprocess_count[0] < 20:
        log.append(f"RED subprocess execution count {_subprocess_count[0]} < 20")
        print("A2-a2(iv) subprocess count", file=sys.stderr)
        return 1
    if len(_child_fingerprints) != _subprocess_count[0]:
        log.append("RED fingerprint count mismatch")
        return 1
    _fp_set = set(_child_fingerprints)
    if len(_fp_set) < _subprocess_count[0] * 0.8:
        log.append(f"RED fingerprints not unique ({len(_fp_set)}/{_subprocess_count[0]})")
        print("A2-a2(iv) fingerprint uniqueness", file=sys.stderr)
        return 1
    _fp_cumulative = hashlib.sha256("".join(_child_fingerprints).encode()).hexdigest()
    log.append(f"subprocess executions={_subprocess_count[0]} fp={_fp_cumulative[:16]} OK")
    log.append("mutation: reach-counter all-inspectors + shape-valid prefix tamper OK")

    # Real-child causality: a dedicated rc=0 invocation computes an attest over
    # the fresh nonce + used-variants PIN + its exact argv. The parent recomputes
    # it from the same nonce; a replayed prior output (old nonce) cannot match.
    attest_args = ["a2a2-attest", _fp_cumulative]
    r_att = run(attest_args)
    if r_att.returncode != 0:
        log.append(f"RED attest invocation rc={r_att.returncode} err={r_att.stderr!r}")
        print("A2-a2(iv) attest invocation rc", file=sys.stderr)
        return 1
    if (r_att.stderr or "").strip():
        log.append(f"RED attest invocation stderr nonempty {r_att.stderr!r}")
        print("A2-a2(iv) attest stderr", file=sys.stderr)
        return 1
    att_line = None
    for ln in (r_att.stdout or "").splitlines():
        if ln.startswith("a2a2-attest:"):
            att_line = ln.split(":", 1)[1].strip()
            break
    if att_line is None:
        log.append(f"RED attest line missing stdout={r_att.stdout!r}")
        print("A2-a2(iv) attest line missing", file=sys.stderr)
        return 1
    expected_msg = (D3S4_USED_VARIANTS_SHA256 + "|" + "|".join([script, *attest_args])).encode()
    expected_att = hmac.new(nonce.encode(), expected_msg, hashlib.sha256).hexdigest()
    if att_line != expected_att:
        log.append(f"RED attest mismatch got={att_line[:16]} want={expected_att[:16]}")
        print("A2-a2(iv) attest mismatch", file=sys.stderr)
        return 1
    log.append(f"attest OK nonce-bound child causality att={att_line[:16]} fp={_fp_cumulative[:16]}")
    log.append("A2-a2(iv) GREEN")
    return 0


def run_a2a2_gates(log_path: Path) -> int:
    """Run all A2-a2 gates; write the caller-owned ephemeral log; return 0/1.

    The self-test passes a path inside an OS temporary directory.  This keeps a
    verification run read-only with respect to the repository and, in
    particular, never creates the historical ``tmp-a2`` source-tree artifact.
    """
    log: List[str] = [
        "A2-a2 qa_regression log",
        f"script={Path(__file__).name}",
        "authority=docs/17 §18.15 (5176-5823); gates i/ii/iii/iv",
    ]
    rc = 0
    if gate_a2a2_d1_self_test(log) != 0:
        rc = 1
    if gate_a2a2_classifier_self_test(log) != 0:
        rc = 1
    if gate_a2a2_invalid_enum_mbz_self_test(log) != 0:
        rc = 1
    if gate_a2a2_cli_fail_closed_self_test(log) != 0:
        rc = 1
    log.append(f"OVERALL={'GREEN' if rc == 0 else 'RED'} rc={rc}")
    try:
        log_path.parent.mkdir(parents=True, exist_ok=True)
        log_path.write_text("\n".join(log) + "\n", encoding="utf-8")
    except OSError as e:
        print(f"A2-a2 log write failed: {e}", file=sys.stderr)
        return 1
    return rc


