# ---------------------------------------------------------------------------
# A2-b rev2: forward key builders + real Port fixtures (P0-002)
# ---------------------------------------------------------------------------
# Complete Domain keys are forward-rebuilt from raw fixture fields via the
# §5.1 COMPOSITE formula. KEY_DIGEST reverse is forbidden (§18.15 line 5182):
# every request_key_hex below is built from operation raw / witness composite
# identity / member raw key / chunk index, never from a digest preimage.

def _be16(n: int) -> bytes:
    return struct.pack(">H", n & 0xFFFF)


def _fk_composite_key(fam: int, st: int, ident: bytes) -> bytes:
    """Forward family5/6 complete key = root || fam,st,1,5,32 || identity(32)."""
    return DOMAIN_KEY_ROOT + bytes([fam & 0xFF, st & 0xFF, 1, 5, 32]) + ident


def _fk_witness_header_key(op_kind: int, op_id: bytes) -> bytes:
    """Forward WITNESS_HEADER complete key from operation raw (§18.15.7)."""
    d3s1 = _load_d3s1()
    ident = d3s1.composite(
        0x7F, _be16(op_kind) + _be16(len(op_id)) + op_id
    )
    return _fk_composite_key(6, 0x7F, ident)


def _fk_witness_header_identity(op_kind: int, op_id: bytes) -> bytes:
    """The 32-byte WITNESS_HEADER composite identity (chunk witness_digest)."""
    d3s1 = _load_d3s1()
    return d3s1.composite(0x7F, _be16(op_kind) + _be16(len(op_id)) + op_id)


def _fk_witness_chunk_key(witness_digest: bytes, chunk_index: int) -> bytes:
    """Forward WITNESS_MANIFEST_CHUNK complete key from witness composite identity
    (the header identity bytes present in the chunk body) + exact chunk index."""
    d3s1 = _load_d3s1()
    ident = d3s1.composite(0x7E, bytes(witness_digest) + _be16(chunk_index))
    return _fk_composite_key(6, 0x7E, ident)


def _s4_primary_wid_from_carrier(key: bytes, value: bytes) -> Optional[bytes]:
    """§18.15.6/§18.15.8.1: derive the primary target witness identity from the
    carrier body's S4-closed-normalized source raw tuple. The raw is the first 32
    bytes of the semantic body (offset 108); the composite identity uses the
    carrier's own subtype (from the complete key §5.1 grammar)."""
    if len(key) < 10 or len(value) < 108 + 32 + 4:
        return None
    st = key[9]
    raw = bytes(value[108:108 + 32])
    if raw == bytes(32):
        return None
    d3s1 = _load_d3s1()
    return d3s1.composite(st, raw)


def _s4_primary_key_from_carrier(key: bytes, value: bytes) -> Optional[bytes]:
    """Forward-rebuild the primary record complete key (§5.1 chunk grammar)."""
    wid = _s4_primary_wid_from_carrier(key, value)
    if wid is None:
        return None
    return _fk_witness_chunk_key(wid, 0)


def _s4_build_primary_row_from_carrier(
    carrier_key: bytes, carrier_value: bytes, salt: int = 0
) -> Tuple[bytes, bytes, Dict[str, Any]]:
    """Build a D1-valid primary row at the forward-rebuilt key from carrier body
    raw (§18.15.6). The primary is a WITNESS_MANIFEST_CHUNK row whose witness_digest
    is the S4-closed-normalized composite identity from the carrier body raw.
    Returns (primary_key, primary_value, row_dict)."""
    wid = _s4_primary_wid_from_carrier(carrier_key, carrier_value)
    if wid is None:
        return b"", b"", {}
    pt_mk = _d3s4_distinct_member_keys(1, salt=salt)[0]
    pt_mv = bytes.fromhex(_d3s4_pick_member_row(salt)["value_hex"])
    pt_row = _build_witness_chunk_row(
        witness_digest=wid, chunk_index=0, chunk_count=1,
        member_keys=[pt_mk], member_values=[pt_mv],
        tag="prim_fwd_%d" % salt,
    )
    pt_key = bytes.fromhex(pt_row["key_hex"])
    pt_value = bytes.fromhex(pt_row["value_hex"])
    return pt_key, pt_value, pt_row


def _build_witness_header_row(
    *,
    op_kind: int,
    state: int,
    op_id: bytes,
    member_count: int,
    chunk_count: int,
    manifest: bytes,
    successor: bytes,
    ret_kind: int = 0,
    ret_subj: bytes = bytes(32),
    tag: str = "hdr",
) -> Dict[str, Any]:
    """Build a D1-legal WITNESS_HEADER row with a forward-built complete key.

    Body layout matches encode_witness_header (§10): op_kind/state/op_id +
    subject + canonical + M/C + manifest + retention + successor. subject is the
    op_id prefix (op_kind=1 matrix), canonical is the §10 operation canonical SHA.
    """
    d3s1 = _load_d3s1()
    subject = op_id[:16]
    canon_pre = (
        b"NINLIL-DOMAIN-OPERATION-V1" + _be16(op_kind) + _be16(len(op_id)) + op_id
        + subject + manifest + _be16(ret_kind) + ret_subj
    )
    canon = hashlib.sha256(canon_pre).digest()
    body = bytearray()
    body += _be16(op_kind) + _be16(state) + _be16(len(op_id)) + op_id
    body += subject + canon + _be16(member_count) + _be16(chunk_count) + manifest
    body += _be16(ret_kind) + _be16(0) + ret_subj + successor
    body = bytes(body)
    cid = _fk_witness_header_identity(op_kind, op_id)
    key = _fk_composite_key(6, 0x7F, cid)
    value = d3s1.enc_env_full(6, 0x7F, 0, 1, cid[:16], bytes(32), bytes(32), body)
    return {
        "key_hex": key.hex(),
        "value_hex": value.hex(),
        "id": f"witness_header_{tag}",
        "kind": "witness_header",
        "family": 6,
        "subtype": 0x7F,
        "role": (6 << 8) | 0x7F,
    }


def _build_chunk_entry(member_key: bytes, *, action: int = 1, new_value_digest: Optional[bytes] = None) -> bytes:
    """One WITNESS_MANIFEST_CHUNK entry (CREATE shape; old=0/new=1). The entry
    role is the member key's own family/subtype (§10.1 role/key bijection).
    new_value_digest is the real VALUE_DIGEST = SHA-256(complete member value)."""
    fam = member_key[8] if len(member_key) > 8 else 6
    st = member_key[9] if len(member_key) > 9 else 0x20
    # Family3/4 witness-member roles carry role_low=0 (suffix lives in the key, §10.1).
    role = (fam << 8) | (0 if fam in (3, 4) else st)
    if new_value_digest is None:
        new_value_digest = hashlib.sha256(bytes(member_key)).digest()
    e = bytearray()
    e += _be16(role) + bytes([action & 0xFF, 0]) + _be16(len(member_key)) + _be16(0)
    e += member_key
    e += bytes([0, 1]) + _be16(0)
    e += bytes(32) + bytes(32) + bytes(new_value_digest)
    return bytes(e)


def _build_witness_chunk_row(
    *,
    witness_digest: bytes,
    chunk_index: int,
    chunk_count: int,
    member_keys: List[bytes],
    member_values: Optional[List[bytes]] = None,
    tag: str = "chk",
) -> Dict[str, Any]:
    """Build a D1-legal WITNESS_MANIFEST_CHUNK row with a forward-built key.

    witness_digest is the header composite identity (raw bytes present in the
    chunk body); the chunk complete key is forward-built from it + chunk_index.
    member_values (parallel to member_keys) supplies real complete values for
    VALUE_DIGEST computation (§5.1: SHA-256(complete_value)).
    """
    d3s1 = _load_d3s1()
    paired = sorted(zip(
        (bytes(mk) for mk in member_keys),
        (member_values or [None] * len(member_keys)),
    ), key=lambda p: p[0])
    entries_parts: List[bytes] = []
    for mk, mv in paired:
        nvd = hashlib.sha256(mv).digest() if mv is not None else None
        entries_parts.append(_build_chunk_entry(mk, new_value_digest=nvd))
    entries = b"".join(entries_parts)
    body = bytearray()
    body += bytes(witness_digest) + _be16(chunk_index) + _be16(chunk_count)
    body += _be16(len(paired)) + _be16(0)
    body += entries
    body = bytes(body)
    key = _fk_witness_chunk_key(witness_digest, chunk_index)
    ident = d3s1.composite(0x7E, bytes(witness_digest) + _be16(chunk_index))
    value = d3s1.enc_env_full(6, 0x7E, 0, 1, ident[:16], bytes(32), bytes(32), body)
    return {
        "key_hex": key.hex(),
        "value_hex": value.hex(),
        "id": f"witness_chunk_{tag}_{chunk_index}",
        "kind": "witness_manifest_chunk",
        "family": 6,
        "subtype": 0x7E,
        "role": (6 << 8) | 0x7E,
    }


def _compute_manifest_digest_v1(chunk_bodies: List[bytes]) -> bytes:
    """§5.1: SHA-256("NINLIL-DOMAIN-MANIFEST-V1" || chunk_body_0 || ... || chunk_body_n)."""
    acc = hashlib.sha256()
    acc.update(b"NINLIL-DOMAIN-MANIFEST-V1")
    for body in chunk_bodies:
        acc.update(body)
    return acc.digest()


_D3S4_SEMANTIC_ROW_CACHE: Optional[List[Dict[str, Any]]] = None


def _d3s4_semantic_member_rows() -> List[Dict[str, Any]]:
    """Real D1-legal family6 semantic rows (TRANSACTION_ANCHOR 0x20 etc.) used as
    member/primary Port fixtures. Pulled once from the frozen D1 authority so the
    member/primary complete keys + bodies are genuine, not synthesized."""
    global _D3S4_SEMANTIC_ROW_CACHE
    if _D3S4_SEMANTIC_ROW_CACHE is not None:
        return _D3S4_SEMANTIC_ROW_CACHE
    doc = _load_d1_authority()
    out: List[Dict[str, Any]] = []
    seen_keys: set = set()
    for vec in doc["vectors"]:
        if vec.get("op") != "typed_record" or vec.get("expected_status") != "OK":
            continue
        if vec.get("family") != 6:
            continue
        st = vec.get("subtype")
        if st not in (0x20, 0x22, 0x27, 0x40, 0x30):
            continue
        kh = vec.get("key_hex")
        vh = vec.get("value_hex")
        if not isinstance(kh, str) or not isinstance(vh, str):
            continue
        if kh in seen_keys:
            continue
        try:
            kb = bytes.fromhex(kh)
            vb = bytes.fromhex(vh)
        except ValueError:
            continue
        if len(kb) < 13 or len(vb) < 16:
            continue
        seen_keys.add(kh)
        out.append({
            "key_hex": kh,
            "value_hex": vh,
            "id": f"semantic_{int(st):02x}_{len(out)}",
            "kind": "semantic_member",
            "family": 6,
            "subtype": int(st),
            "role": (6 << 8) | int(st),
        })
        if len(out) >= 64:
            break
    _D3S4_SEMANTIC_ROW_CACHE = out
    return out


def _d3s4_pick_member_row(index: int) -> Dict[str, Any]:
    rows = _d3s4_semantic_member_rows()
    return copy.deepcopy(rows[index % len(rows)])


def _d3s4_pick_non_blob_row(index: int) -> Dict[str, Any]:
    rows = [r for r in _d3s4_semantic_member_rows() if r.get("subtype") != 0x30]
    if not rows:
        rows = _d3s4_semantic_member_rows()
    legal = []
    for r in rows:
        kb = bytes.fromhex(r["key_hex"])
        vb = bytes.fromhex(r["value_hex"])
        if d3s4_d1_row_legality(kb, vb) is None:
            legal.append(r)
    if not legal:
        legal = rows
    return copy.deepcopy(legal[index % len(legal)])


def _d3s4_member_key(index: int) -> bytes:
    return bytes.fromhex(_d3s4_pick_member_row(index)["key_hex"])


def _d3s4_distinct_member_keys(count: int, salt: int = 0) -> List[bytes]:
    """`count` distinct real semantic member keys (strict-increasing capable)."""
    rows = _d3s4_semantic_member_rows()
    keys: List[bytes] = []
    seen: set = set()
    i = salt
    while len(keys) < count and i < salt + len(rows):
        k = bytes.fromhex(rows[i % len(rows)]["key_hex"])
        if k not in seen:
            seen.add(k)
            keys.append(k)
        i += 1
    while len(keys) < count:
        # Deterministic synthetic family6 0x20 keys if the authority pool is small.
        d3s1 = _load_d3s1()
        ident = d3s1.composite(0x20, _be16(0x9000 | len(keys)) + bytes([salt & 0xFF]))
        keys.append(_fk_composite_key(6, 0x20, ident))
    return keys


def _d3s4_distinct_member_rows(count: int, salt: int = 0) -> List[Dict[str, Any]]:
    """`count` distinct D1-legal semantic member rows (key+value pairs)."""
    pool = _d3s4_semantic_member_rows()
    out: List[Dict[str, Any]] = []
    seen: set = set()
    i = salt
    while len(out) < count and len(out) < len(pool):
        r = pool[i % len(pool)]
        if r["key_hex"] not in seen:
            seen.add(r["key_hex"])
            out.append(copy.deepcopy(r))
        i += 1
    return out


def _d3s4_build_m31_32_real(
    mode: int, headers: List[Dict[str, Any]], *, salt: int = 0
) -> Tuple[List[Dict[str, Any]], List[str]]:
    """Real Port fixture for Mode31/32: witness header + manifest chunk(s) +
    semantic member rows + primary row per header. Returns (rows, get_key_hexes)
    where get_key_hexes is the forward-built exact-get key column in drive order
    (chunk[i//8], member[i], primary[i]? per member i).

    Manifest digest uses §5.1: SHA-256("NINLIL-DOMAIN-MANIFEST-V1" || chunk_body_0..n).
    Entry new_value_digest = SHA-256(complete member value) from real semantic rows.
    `salt` ensures byte-distinct rows across vectors sharing the same structure.
    """
    rows: List[Dict[str, Any]] = []
    get_keys: List[str] = []
    state = 1 if mode == MODE_31 else 2  # ACTIVE / SUPERSEDED
    member_cursor = salt * 7
    for hi, hdr in enumerate(headers):
        m = int(hdr.get("M", 1))
        p = int(hdr.get("P", 0))
        c = (m + 7) // 8
        members = hdr.get("members", [])
        op_id = hashlib.sha256(
            b"opid|%d|%d|%d" % (mode, hi, salt)
        ).digest()
        successor = bytes(32) if mode == MODE_31 else hashlib.sha256(
            b"succ|%d|%d" % (hi, salt)
        ).digest()
        cid = _fk_witness_header_identity(1, op_id)
        member_rows = _d3s4_distinct_member_rows(m, salt=member_cursor)
        member_cursor += m
        member_keys_sorted = sorted(bytes.fromhex(r["key_hex"]) for r in member_rows)
        member_vals_sorted: List[bytes] = []
        key_to_val = {r["key_hex"]: bytes.fromhex(r["value_hex"]) for r in member_rows}
        for mk in member_keys_sorted:
            member_vals_sorted.append(key_to_val.get(mk.hex(), mk))
        chunk_bodies: List[bytes] = []
        chunk_keys_hex: Dict[int, str] = {}
        for cidx in range(c):
            lo = cidx * 8
            hi_keys = member_keys_sorted[lo:lo + 8]
            hi_vals = member_vals_sorted[lo:lo + 8]
            chk = _build_witness_chunk_row(
                witness_digest=cid, chunk_index=cidx, chunk_count=c,
                member_keys=hi_keys, member_values=hi_vals, tag="h%d" % hi,
            )
            rows.append(chk)
            chunk_keys_hex[cidx] = chk["key_hex"]
            chunk_bodies.append(bytes.fromhex(chk["value_hex"])[108:-4])
        manifest = _compute_manifest_digest_v1(chunk_bodies)
        hdr_row = _build_witness_header_row(
            op_kind=1, state=state, op_id=op_id, member_count=m, chunk_count=c,
            manifest=manifest, successor=successor, tag="h%d" % hi,
        )
        rows.insert(len(rows) - c, hdr_row)
        primary_row = _d3s4_pick_member_row(member_cursor + hi + salt)
        primary_key_hex = primary_row["key_hex"]
        for r in member_rows:
            rows.append(copy.deepcopy(r))
        if p > 0:
            rows.append(copy.deepcopy(primary_row))
        for i in range(m):
            get_keys.append(chunk_keys_hex[i // 8])
            get_keys.append(member_keys_sorted[i].hex())
            minfo = members[i] if i < len(members) else {}
            if minfo.get("has_primary"):
                get_keys.append(primary_key_hex)
    return rows, get_keys


def _build_chunk_entry_ext(
    member_key: bytes, *, action: int = 1, old_p: int = 0, new_p: int = 1,
    old_digest: Optional[bytes] = None, new_digest: Optional[bytes] = None,
    prior_head: Optional[bytes] = None,
) -> bytes:
    fam = member_key[8] if len(member_key) > 8 else 6
    st = member_key[9] if len(member_key) > 9 else 0x20
    role = (fam << 8) | (0 if fam in (3, 4) else st)
    if new_digest is None:
        new_digest = hashlib.sha256(bytes(member_key)).digest()
    if old_digest is None:
        old_digest = bytes(32)
    if prior_head is None:
        prior_head = bytes(32)
    e = bytearray()
    e += _be16(role) + bytes([action & 0xFF, 0]) + _be16(len(member_key)) + _be16(0)
    e += member_key
    e += bytes([old_p & 0xFF, new_p & 0xFF]) + _be16(0)
    e += prior_head + old_digest + new_digest
    return bytes(e)


def _d3s4_build_m31_32_rows_driven(
    mode: int, variant: str, *, salt: int = 0,
) -> Tuple[List[Dict[str, Any]], List[bytes]]:
    """Rows-driven Mode31/32 fixture (A2-b rev5 step2). Builds a unified baseline
    with byte-encoded semantic differences per variant:
      ALL_NEW: M=2, entry new == current member VALUE_DIGEST, head == witness
      ALL_NEW_M1: M=1, single ALL_NEW member
      PROGRESSED: M=2, entry action=REPLACE, digest mismatch, different head
      RETIRED: M=2, SUPERSEDE_WITNESS, predecessor header state=RETIRED
      ABSENT: M=2, SUPERSEDE_WITNESS, predecessor row absent
      ALL_NEW_PRIMARY: M=2, first member has non-zero PVD (primary get)
      ALL_NEW_PRIMARY_M1: M=1, single member with PVD
      ALL_NEW_PRIMARY_M2: M=2, both members have PVD
    Returns rows (header carrier is discovered by the feed iterator)."""
    d3s1 = _load_d3s1()
    state = 1 if mode == MODE_31 else 2
    op_id = hashlib.sha256(
        ("m31_32rd|%d|%d|%s" % (mode, salt, variant)).encode()
    ).digest()
    cid = _fk_witness_header_identity(1, op_id)
    hkey = _fk_composite_key(6, 0x7F, cid)
    successor = bytes(32) if mode == MODE_31 else hashlib.sha256(
        b"succ_rd|%d|%d" % (salt, mode)
    ).digest()
    m1_variants = ("ALL_NEW_M1", "ALL_NEW_PRIMARY_M1")
    m = 1 if variant in m1_variants else 2
    c = 1
    _pvd_forbidden_st = frozenset({0x10, 0x20, 0x27, 0x30, 0x40, 0x60, 0x64, 0x7D, 0x7E, 0x7F})
    has_primary_0 = variant in ("ALL_NEW_PRIMARY", "ALL_NEW_PRIMARY_M1", "ALL_NEW_PRIMARY_M2")
    _exclude_st = frozenset({0x30, 0x22}) if not has_primary_0 else frozenset({0x30})
    all_pool = [
        r for r in _d3s4_distinct_member_rows(max(m, 2) + 10, salt=salt * 10 + 200)
        if r.get("subtype") not in _exclude_st
        and bytes.fromhex(r["key_hex"])[:8] == DOMAIN_KEY_ROOT
    ]
    if has_primary_0:
        pvd_ok = [r for r in all_pool if r.get("subtype") not in _pvd_forbidden_st]
        rest = [r for r in all_pool if r.get("subtype") in _pvd_forbidden_st]
        member_rows_pool = (pvd_ok + rest)[:max(m, 2)]
    else:
        member_rows_pool = all_pool[:max(m, 2)]
    member_keys = sorted(bytes.fromhex(r["key_hex"]) for r in member_rows_pool)
    mk_to_row = {r["key_hex"]: r for r in member_rows_pool}
    k0 = member_keys[0]
    v0_raw = bytes.fromhex(mk_to_row[k0.hex()]["value_hex"])
    rows: List[Dict[str, Any]] = []
    entries: List[bytes] = []
    has_primary_1 = variant == "ALL_NEW_PRIMARY_M2"
    v0_mod = _m31_32_set_head(v0_raw, cid)
    if not has_primary_0:
        v0_mod = _m31_32_set_pvd(v0_mod, D1_ZERO32)
    if has_primary_0:
        prim_src = _d3s4_pick_non_blob_row(salt + 50)
        prim_val_0 = bytes.fromhex(prim_src["value_hex"])
        prim_key_0 = bytes.fromhex(prim_src["key_hex"])
        pvd_0 = hashlib.sha256(prim_val_0).digest()
        k0, v0_mod = _m31_32_build_pvd_member(salt)
        v0_mod = _m31_32_set_head(v0_mod, cid)
        v0_mod = _m31_32_set_pvd(v0_mod, pvd_0)
        v0_mod = _m31_32_embed_primary_key(v0_mod, prim_key_0)
        k0 = _m31_32_rebuild_key_if_needed(k0, v0_mod)
        rows.append(copy.deepcopy(prim_src))
    nd0 = hashlib.sha256(v0_mod).digest()
    entries.append(_build_chunk_entry_ext(k0, action=1, old_p=0, new_p=1, new_digest=nd0))
    rows.append(_m31_32_member_row(k0, v0_mod, salt=salt))
    if m == 2:
        k1 = member_keys[1]
        v1_raw = bytes.fromhex(mk_to_row[k1.hex()]["value_hex"])
        if variant == "ALL_NEW" or variant == "ALL_NEW_PRIMARY" or variant == "ALL_NEW_PRIMARY_M2":
            v1_mod = _m31_32_set_head(v1_raw, cid)
            if not has_primary_1:
                v1_mod = _m31_32_set_pvd(v1_mod, D1_ZERO32)
            if has_primary_1:
                prim_src_1 = _d3s4_pick_non_blob_row(salt + 51)
                prim_val_1 = bytes.fromhex(prim_src_1["value_hex"])
                prim_key_1 = bytes.fromhex(prim_src_1["key_hex"])
                pvd_1 = hashlib.sha256(prim_val_1).digest()
                v1_mod = _m31_32_set_pvd(v1_mod, pvd_1)
                v1_mod = _m31_32_embed_primary_key(v1_mod, prim_key_1)
                rows.append(copy.deepcopy(prim_src_1))
            nd1 = hashlib.sha256(v1_mod).digest()
            entries.append(_build_chunk_entry_ext(k1, action=1, old_p=0, new_p=1, new_digest=nd1))
            rows.append(_m31_32_member_row(k1, v1_mod, salt=salt + 1))
        elif variant == "PROGRESSED":
            other_head = hashlib.sha256(b"other_head|%d|%d" % (salt, mode)).digest()
            v1_mod = _m31_32_set_head(v1_raw, other_head)
            nd1_entry = hashlib.sha256(b"entry_new_wrong|%d" % salt).digest()
            old_d1 = hashlib.sha256(b"entry_old|%d" % salt).digest()
            prior_h1 = hashlib.sha256(b"prior_head|%d|%d" % (salt, mode)).digest()
            entries.append(_build_chunk_entry_ext(
                k1, action=2, old_p=1, new_p=1,
                old_digest=old_d1, new_digest=nd1_entry,
                prior_head=prior_h1,
            ))
            rows.append(_m31_32_member_row(k1, v1_mod, salt=salt + 1))
        elif variant == "RETIRED":
            pred_op_id = hashlib.sha256(b"pred_ret|%d|%d" % (salt, mode)).digest()
            pred_cid = _fk_witness_header_identity(1, pred_op_id)
            pred_hkey = _fk_composite_key(6, 0x7F, pred_cid)
            pred_hdr_row = _build_witness_header_row(
                op_kind=1, state=3, op_id=pred_op_id, member_count=1, chunk_count=1,
                manifest=hashlib.sha256(b"pred_manifest|%d" % salt).digest(),
                successor=cid, tag="pred_ret_%d" % salt,
            )
            pv = bytearray(bytes.fromhex(pred_hdr_row["value_hex"]))
            pv = bytearray(_m31_32_set_pvd(bytes(pv), D1_ZERO32))
            pred_hdr_row["value_hex"] = bytes(pv).hex()
            nd1 = hashlib.sha256(bytes.fromhex(pred_hdr_row["value_hex"])).digest()
            od1 = hashlib.sha256(b"pred_old|%d|%d" % (salt, mode)).digest()
            entries.append(_build_chunk_entry_ext(
                pred_hkey, action=4, old_p=1, new_p=1,
                old_digest=od1, new_digest=nd1,
            ))
            rows.append(pred_hdr_row)
        elif variant == "ABSENT":
            pred_op_id = hashlib.sha256(b"pred_abs|%d|%d" % (salt, mode)).digest()
            pred_cid = _fk_witness_header_identity(1, pred_op_id)
            pred_hkey = _fk_composite_key(6, 0x7F, pred_cid)
            nd1 = hashlib.sha256(b"absent_pred_new|%d" % salt).digest()
            od1 = hashlib.sha256(b"absent_pred_old|%d" % salt).digest()
            entries.append(_build_chunk_entry_ext(
                pred_hkey, action=4, old_p=1, new_p=1,
                old_digest=od1, new_digest=nd1,
            ))
        else:
            v1_mod = _m31_32_set_head(v1_raw, cid)
            nd1 = hashlib.sha256(v1_mod).digest()
            entries.append(_build_chunk_entry_ext(k1, action=1, old_p=0, new_p=1, new_digest=nd1))
            rows.append(_m31_32_member_row(k1, v1_mod, salt=salt + 1))
    entries_raw = b"".join(entries)
    body = bytearray()
    body += bytes(cid) + _be16(0) + _be16(c)
    body += _be16(m) + _be16(0)
    body += entries_raw
    body = bytes(body)
    ckey = _fk_witness_chunk_key(cid, 0)
    ident = d3s1.composite(0x7E, bytes(cid) + _be16(0))
    cval = d3s1.enc_env_full(6, 0x7E, 0, 1, ident[:16], bytes(32), bytes(32), body)
    chunk_row = {
        "key_hex": ckey.hex(),
        "value_hex": cval.hex(),
        "id": f"witness_chunk_rd_{variant}_{salt}",
        "kind": "witness_manifest_chunk",
        "family": 6,
        "subtype": 0x7E,
        "role": (6 << 8) | 0x7E,
    }
    rows.append(chunk_row)
    manifest = _compute_manifest_digest_v1([body])
    hdr_row = _build_witness_header_row(
        op_kind=1, state=state, op_id=op_id, member_count=m, chunk_count=c,
        manifest=manifest, successor=successor, tag="rd_%s_%d" % (variant, salt),
    )
    rows.append(hdr_row)
    return rows


def _d3s4_build_m31_32_primary_tx_rows(
    mode: int, *, salt: int = 0,
) -> List[Dict[str, Any]]:
    """R5-001 P02 fixture: rows-driven Mode31/32 M=2 with member 0 a D1-legal
    TRANSACTION_STATE (6/0x22) secondary carrying a NON-ZERO primary_value_digest.
    The closed §18.15.6 normalizer pins the source raw (transaction_id, body[0:16]),
    forward-rebuilds the TRANSACTION_ANCHOR (6/0x20) primary key from it, exact-gets
    that primary row, and byte-compares the returned body raw + PVD. Member 1 is an
    ordinary ALL_NEW zero-PVD member. Get-budget = 2M+P = 5 (§18.15.9)."""
    d3s1 = _load_d3s1()
    state = 1 if mode == MODE_31 else 2
    op_id = hashlib.sha256(("m31_32ptx|%d|%d" % (mode, salt)).encode()).digest()
    cid = _fk_witness_header_identity(1, op_id)
    successor = bytes(32) if mode == MODE_31 else hashlib.sha256(
        b"succ_ptx|%d|%d" % (salt, mode)
    ).digest()
    sem = _d3s4_semantic_member_rows()
    r20 = next(r for r in sem if r.get("subtype") == 0x20)
    r22 = next(r for r in sem if r.get("subtype") == 0x22)
    prim_key = bytes.fromhex(r20["key_hex"])
    prim_val = bytes.fromhex(r20["value_hex"])
    tx_p = bytes(prim_val[108:124])  # TRANSACTION_ANCHOR body[0:16] = transaction_id
    # Source secondary: real 0x22 with body[0:16]:=tx_p, head:=cid, PVD:=sha256(primary).
    src = bytearray(bytes.fromhex(r22["value_hex"]))
    src[108:124] = tx_p
    src_key = d3s1.bkey(6, 0x22, 2, tx_p)
    src_val = _m31_32_set_head(bytes(src), cid)
    src_val = _m31_32_set_pvd(src_val, hashlib.sha256(prim_val).digest())
    src_row = _m31_32_member_row(src_key, src_val, salt=salt)
    # Member 1: ordinary ALL_NEW zero-PVD member (a distinct D1-legal semantic row).
    other = next(
        r for r in sem
        if r.get("subtype") not in (0x20, 0x22, 0x30)
    )
    m1_key = bytes.fromhex(other["key_hex"])
    m1_val = _m31_32_set_head(bytes.fromhex(other["value_hex"]), cid)
    m1_val = _m31_32_set_pvd(m1_val, D1_ZERO32)
    m1_row = _m31_32_member_row(m1_key, m1_val, salt=salt + 1)
    member_keys = sorted([src_key, m1_key])
    val_by_key = {src_key: src_val, m1_key: m1_val}
    entries = [
        _build_chunk_entry_ext(k, action=1, old_p=0, new_p=1,
                               new_digest=hashlib.sha256(val_by_key[k]).digest())
        for k in member_keys
    ]
    m = 2
    c = 1
    body = bytearray()
    body += bytes(cid) + _be16(0) + _be16(c)
    body += _be16(m) + _be16(0)
    body += b"".join(entries)
    body = bytes(body)
    ckey = _fk_witness_chunk_key(cid, 0)
    ident = d3s1.composite(0x7E, bytes(cid) + _be16(0))
    cval = d3s1.enc_env_full(6, 0x7E, 0, 1, ident[:16], bytes(32), bytes(32), body)
    chunk_row = {
        "key_hex": ckey.hex(), "value_hex": cval.hex(),
        "id": "witness_chunk_ptx_%d" % salt, "kind": "witness_manifest_chunk",
        "family": 6, "subtype": 0x7E, "role": (6 << 8) | 0x7E,
    }
    manifest = _compute_manifest_digest_v1([body])
    hdr_row = _build_witness_header_row(
        op_kind=1, state=state, op_id=op_id, member_count=m, chunk_count=c,
        manifest=manifest, successor=successor, tag="ptx_%d" % salt,
    )
    rows: List[Dict[str, Any]] = [copy.deepcopy(r20), src_row, m1_row, chunk_row, hdr_row]
    return rows


def _d3s4_build_m31_32_collision_companion_rows(
    mode: int, *, salt: int = 0, source_subtype: int = 0x24,
) -> List[Dict[str, Any]]:
    """B2 P02_COLL: rows-driven Mode31/32 M=2 with IDEMPOTENCY_MAP(6/0x24) source + collision
    companion row (same complete primary key + same PVD, different raw2/aux tuple). The closed
    §18.15.6 normalizer pins the witness source raw tuple, forward-rebuilds the TRANSACTION_ANCHOR
    primary key, exact-gets the primary, and byte-compares raw/raw2/aux + PVD. Get-budget
    2M+P = 5 (§18.15.9)."""
    rows = _d3s4_build_m31_32_primary_anchor_rows(
        mode, source_subtype, salt=salt,
    )
    d3s1 = _load_d3s1()
    src_row = next(r for r in rows if r.get("subtype") == source_subtype)
    prim_val = bytes.fromhex(
        next(r["value_hex"] for r in rows if r.get("subtype") == 0x20)
    )
    cid = bytes.fromhex(src_row["value_hex"])[40:72]
    pvd = hashlib.sha256(prim_val).digest()
    witness_body = bytes.fromhex(src_row["value_hex"])[108:-4]
    comp_body = bytearray(witness_body)
    slen = int.from_bytes(comp_body[0:2], "big")
    if slen >= 1:
        comp_body[2] ^= 0x55
    ioff = 2 + slen
    klen = int.from_bytes(comp_body[ioff:ioff + 2], "big")
    if klen >= 1:
        comp_body[ioff + 2] ^= 0xAA
    parsed = d3s1.parse_idem(bytes(comp_body))
    ident = d3s1.composite(
        0x24, d3s1.raw16(bytes(parsed["scope"])) + d3s1.raw16(bytes(parsed["ikey"]))
    )
    comp_key = bytes(d3s1.bkey(6, 0x24, 5, ident))
    tmpl = bytes.fromhex(d3s1.d1_row(_D3S4_P03_ANCHOR_SEC_VID[source_subtype])["value_hex"])
    comp_val = d3s1.enc_env_full(
        6, 0x24, tmpl[15],
        int.from_bytes(tmpl[16:24], "big"),
        bytes(parsed["txn"]), cid, pvd, bytes(comp_body),
    )
    comp_row = _m31_32_member_row(comp_key, comp_val, salt=salt + 100)
    comp_row["id"] = "collision_companion_%02x_%d" % (source_subtype, salt)
    rows.append(comp_row)
    return rows


def _d3s4_m31_32_align_source_pvd(
    rows: List[Dict[str, Any]], src_subtype: int,
) -> None:
    """After a primary-body mutation, patch the witness source member PVD to sha256(primary)."""
    prim_val = bytes.fromhex(
        next(r["value_hex"] for r in rows if r.get("subtype") == 0x20)
    )
    pvd = hashlib.sha256(prim_val).digest()
    for r in rows:
        if r.get("subtype") == src_subtype:
            vb = bytearray(bytes.fromhex(r["value_hex"]))
            vb[72:104] = pvd
            r["value_hex"] = _m31_32_fix_crc(vb).hex()
            return


def _d3s4_m31_32_prim_body(rows: List[Dict[str, Any]]) -> bytearray:
    prim = next(r for r in rows if r.get("subtype") == 0x20)
    return bytearray(bytes.fromhex(prim["value_hex"]))


def _d3s4_m31_32_set_prim_body(rows: List[Dict[str, Any]], val: bytes) -> None:
    prim = next(r for r in rows if r.get("subtype") == 0x20)
    prim["value_hex"] = _m31_32_fix_crc(bytearray(val)).hex()


def _d3s4_m31_32_reencode_domain_value(
    value: bytes, new_body: bytes, *, subtype: int,
) -> bytes:
    """Rebuild a domain NLR1 envelope after a body length change (payload_len + CRC)."""
    d3s1 = _load_d3s1()
    v = bytes(value)
    return d3s1.enc_env_full(
        6, int(subtype) & 0xFF, 0, 1, v[24:40], v[40:72], v[72:104], bytes(new_body),
    )


def _d3s4_m31_32_replace_prim_body(rows: List[Dict[str, Any]], new_body: bytes) -> None:
    prim = next(r for r in rows if r.get("subtype") == 0x20)
    st = int(prim.get("subtype", 0x20))
    prim["value_hex"] = _d3s4_m31_32_reencode_domain_value(
        bytes.fromhex(prim["value_hex"]), new_body, subtype=st,
    ).hex()


def _d3s4_m31_32_replace_row_body(
    row: Dict[str, Any], new_body: bytes, *, subtype: int,
) -> None:
    row["value_hex"] = _d3s4_m31_32_reencode_domain_value(
        bytes.fromhex(row["value_hex"]), new_body, subtype=subtype,
    ).hex()


def _d3s4_anchor_scope_ikey_offsets(d3s1: Any, body: bytes) -> Tuple[int, int, bytes, bytes]:
    """Return (scope_off, ikey_off, scope_bytes, ikey_bytes) in an ANCHOR body."""
    o = 16 + 8 + 8 + 4
    o += d3s1.PARTY_LEN
    o = d3s1.skip_service_identity(body, o)
    o += 32 + 32 + 16 + 8 + 16 + 8 + 16 + 8 + 8 + 4 + 4 + d3s1.TARGET_LEN
    soff = o
    scope, o = d3s1.parse_raw16_at(body, o)
    ioff = o
    ikey, _o2 = d3s1.parse_raw16_at(body, o)
    return soff, ioff, bytes(scope), bytes(ikey)


def _d3s4_replace_anchor_scope_ikey(
    d3s1: Any, body: bytes, *, new_scope: Optional[bytes] = None,
    new_ikey: Optional[bytes] = None,
) -> bytes:
    """Replace scope and/or ikey RAW16 blocks in an ANCHOR body (size may change)."""
    soff, ioff, scope, ikey = _d3s4_anchor_scope_ikey_offsets(d3s1, body)
    tail = body[ioff + 2 + len(ikey):]
    scope_block = d3s1.raw16(new_scope if new_scope is not None else scope)
    ikey_block = d3s1.raw16(new_ikey if new_ikey is not None else ikey)
    new_body = body[:soff] + scope_block + ikey_block + tail
    return d3s1.recompute_anchor_idempotency_map_digest(new_body)


def _d3s4_patch_anchor_scope_ikey(
    d3s1: Any, body: bytes, *, scope_mut: Optional[Any] = None,
    ikey_mut: Optional[Any] = None, zero_scope: bool = False,
    zero_ikey: bool = False, shorten_scope: bool = False,
    shorten_ikey: bool = False,
) -> bytes:
    """Patch TRANSACTION_ANCHOR dual-raw scope/ikey RAW16 fields; recompute derived digest."""
    soff, ioff, scope, ikey = _d3s4_anchor_scope_ikey_offsets(d3s1, body)
    if zero_scope:
        return _d3s4_replace_anchor_scope_ikey(d3s1, body, new_scope=b"")
    if shorten_scope and len(scope) > 1:
        return _d3s4_replace_anchor_scope_ikey(d3s1, body, new_scope=scope[:-1])
    if zero_ikey:
        return _d3s4_replace_anchor_scope_ikey(d3s1, body, new_ikey=b"")
    if shorten_ikey and len(ikey) > 1:
        return _d3s4_replace_anchor_scope_ikey(d3s1, body, new_ikey=ikey[:-1])
    mut = bytearray(body)
    content_mut = False
    if scope_mut is not None and len(scope) > 0:
        sb = bytearray(scope)
        scope_mut(sb)
        mut[soff + 2:soff + 2 + len(scope)] = bytes(sb)
        content_mut = True
    if ikey_mut is not None and len(ikey) > 0:
        kb = bytearray(ikey)
        ikey_mut(kb)
        mut[ioff + 2:ioff + 2 + len(ikey)] = bytes(kb)
        content_mut = True
    if content_mut:
        return d3s1.recompute_anchor_idempotency_map_digest(bytes(mut))
    return bytes(mut)


def _d3s4_build_m31_32_delivery_collision_rows(
    mode: int, *, salt: int = 0,
) -> List[Dict[str, Any]]:
    """CALLBACK/DELIVERY collision companion for N28 raw-length negatives."""
    rows = _d3s4_build_m31_32_primary_delivery_rows(
        mode, "D3S4_M31_P03_DLV_CB", salt=salt,
    )
    src_row = next(r for r in rows if r.get("subtype") == 0x23)
    prim_val = bytes.fromhex(
        next(r["value_hex"] for r in rows if r.get("subtype") == 0x40)
    )
    cid = bytes.fromhex(src_row["value_hex"])[40:72]
    pvd = hashlib.sha256(prim_val).digest()
    d3s1 = _load_d3s1()
    sec = d3s1.d1_row("DSB2_RES_CB_TYPED")
    comp_key = bytes.fromhex(sec["key_hex"])
    comp_val = _m31_32_set_pvd(
        _m31_32_set_head(bytes.fromhex(sec["value_hex"]), cid), pvd,
    )
    comp_row = _m31_32_member_row(comp_key, comp_val, salt=salt + 101)
    comp_row["id"] = "collision_companion_cb_%d" % salt
    rows.append(comp_row)
    return rows


_D3S4_N1_NEG_VIDS: FrozenSet[str] = frozenset(
    "D3S4_NEG_N%d" % n for n in range(24, 35)
)
_D3S4_N1_SAME_KEY_COLL_VIDS: FrozenSet[str] = frozenset(
    {"D3S4_NEG_N28", "D3S4_NEG_N32"}
)


def _d3s4_build_m31_32_n1_neg_rows(
    vid: str, mode: int, *, salt: int = 0,
) -> List[Dict[str, Any]]:
    """B2 N1 series: clone collision companion base + apply exactly one normalization mutation."""
    if vid == "D3S4_NEG_N28":
        rows = _d3s4_build_m31_32_delivery_collision_rows(mode, salt=salt)
        d3s1 = _load_d3s1()
        prim = next(r for r in rows if r.get("subtype") == 0x40)
        prim_body = bytes.fromhex(prim["value_hex"])[108:-4]
        draw, _ = d3s1.parse_raw16_at(prim_body, 0)
        short = bytes(draw[:40])
        new_raw16 = d3s1.raw16(short)
        new_body = new_raw16 + prim_body[len(new_raw16):]
        _d3s4_m31_32_replace_row_body(prim, new_body, subtype=0x40)
        return rows
    elif vid == "D3S4_NEG_N32":
        rows = _d3s4_build_m31_32_delivery_collision_rows(mode, salt=salt)
        _d3s4_patch_chunk_entry0_role(rows, 0x0626)
        _d3s4_refresh_m31_32_header_manifest(rows)
        return rows
    else:
        rows = _d3s4_build_m31_32_collision_companion_rows(
            mode, salt=salt, source_subtype=0x24,
        )
    d3s1 = _load_d3s1()
    prim_vb = _d3s4_m31_32_prim_body(rows)
    prim_body = prim_vb[108:-4]

    if vid == "D3S4_NEG_N24":
        # key/PVD-only pin probe: mutate returned primary raw (txn) but align source PVD
        # so VALUE_DIGEST matches; only byte-exact raw tuple compare may fail.
        prim_body_mut = bytearray(prim_body)
        prim_body_mut[0] ^= 0x01
        prim_vb[108:-4] = bytes(prim_body_mut)
        _d3s4_m31_32_set_prim_body(rows, bytes(prim_vb))
        _d3s4_m31_32_align_source_pvd(rows, 0x24)
        _d3s4_resync_m31_32_chunk_digests(rows)
    elif vid == "D3S4_NEG_N25":
        prim_body_mut = bytearray(prim_body)
        prim_body_mut[0] ^= 0x01
        prim_vb[108:-4] = bytes(prim_body_mut)
        _d3s4_m31_32_set_prim_body(rows, bytes(prim_vb))
    elif vid == "D3S4_NEG_N26":
        new_body = _d3s4_patch_anchor_scope_ikey(
            d3s1, prim_body, scope_mut=lambda s: s.__setitem__(0, s[0] ^ 0x02),
        )
        prim_vb[108:-4] = new_body
        _d3s4_m31_32_set_prim_body(rows, bytes(prim_vb))
    elif vid == "D3S4_NEG_N27":
        new_body = _d3s4_patch_anchor_scope_ikey(
            d3s1, prim_body, ikey_mut=lambda k: k.__setitem__(0, k[0] ^ 0x04),
        )
        prim_vb[108:-4] = new_body
        _d3s4_m31_32_set_prim_body(rows, bytes(prim_vb))
    elif vid == "D3S4_NEG_N28":
        pass  # handled above
    elif vid == "D3S4_NEG_N29":
        new_body = _d3s4_patch_anchor_scope_ikey(d3s1, prim_body, shorten_scope=True)
        _d3s4_m31_32_replace_prim_body(rows, new_body)
    elif vid == "D3S4_NEG_N30":
        new_body = _d3s4_patch_anchor_scope_ikey(d3s1, prim_body, shorten_ikey=True)
        _d3s4_m31_32_replace_prim_body(rows, new_body)
    elif vid == "D3S4_NEG_N31":
        _d3s4_patch_chunk_entry0_role(rows, 0x0622)
        _d3s4_refresh_m31_32_header_manifest(rows)
    elif vid == "D3S4_NEG_N33":
        new_body = _d3s4_patch_anchor_scope_ikey(d3s1, prim_body, zero_scope=True)
        _d3s4_m31_32_replace_prim_body(rows, new_body)
    elif vid == "D3S4_NEG_N34":
        new_body = _d3s4_patch_anchor_scope_ikey(d3s1, prim_body, zero_ikey=True)
        _d3s4_m31_32_replace_prim_body(rows, new_body)
    return rows


def _d3s4_build_m31_32_blob_manifest_rows(
    mode: int, *, salt: int = 0,
) -> List[Dict[str, Any]]:
    """B3 P03 BLOB_OK1: rows-driven Mode31/32 M=1/P=1 with DSB3_BLOB_MAN_TX_CMD_TYPED
    BLOB manifest source (owner_kind=1 TX) + DSB2_ANCHOR_TYPED primary. The closed
    §18.15.6 normalizer pins owner_key_raw, forward-rebuilds TRANSACTION_ANCHOR key,
    exact-gets primary, byte-compares returned txn raw + PVD. Budget 3 (2M+P)."""
    d3s1 = _load_d3s1()
    state = 1 if mode == MODE_31 else 2
    op_id = hashlib.sha256(("m31_32blob|%d|%d" % (mode, salt)).encode()).digest()
    cid = _fk_witness_header_identity(1, op_id)
    successor = bytes(32) if mode == MODE_31 else hashlib.sha256(
        b"succ_blob|%d|%d" % (salt, mode)
    ).digest()
    man = d3s1.d1_row("DSB3_BLOB_MAN_TX_CMD_TYPED")
    prim = d3s1.d1_row("DSB2_ANCHOR_TYPED")
    prim_key = bytes.fromhex(prim["key_hex"])
    prim_val = bytes.fromhex(prim["value_hex"])
    prim_row = {
        "key_hex": prim_key.hex(), "value_hex": prim_val.hex(),
        "id": "primary_blob_tx_%d" % salt, "kind": "semantic_member",
        "family": 6, "subtype": 0x20, "role": (6 << 8) | 0x20,
    }
    src_key = bytes.fromhex(man["key_hex"])
    src_val = _m31_32_set_head(bytes.fromhex(man["value_hex"]), cid)
    src_val = _m31_32_set_pvd(src_val, hashlib.sha256(prim_val).digest())
    src_row = _m31_32_member_row(src_key, src_val, salt=salt)
    m = 1
    c = 1
    entries = [
        _build_chunk_entry_ext(
            src_key, action=1, old_p=0, new_p=1,
            new_digest=hashlib.sha256(src_val).digest(),
        )
    ]
    body = bytes(cid) + _be16(0) + _be16(c) + _be16(m) + _be16(0) + b"".join(entries)
    ckey = _fk_witness_chunk_key(cid, 0)
    ident = d3s1.composite(0x7E, bytes(cid) + _be16(0))
    cval = d3s1.enc_env_full(6, 0x7E, 0, 1, ident[:16], bytes(32), bytes(32), body)
    chunk_row = {
        "key_hex": ckey.hex(), "value_hex": cval.hex(),
        "id": "witness_chunk_blob_%d" % salt, "kind": "witness_manifest_chunk",
        "family": 6, "subtype": 0x7E, "role": (6 << 8) | 0x7E,
    }
    manifest = _compute_manifest_digest_v1([body])
    hdr_row = _build_witness_header_row(
        op_kind=1, state=state, op_id=op_id, member_count=m, chunk_count=c,
        manifest=manifest, successor=successor, tag="blob_%d" % salt,
    )
    return [prim_row, src_row, chunk_row, hdr_row]


def _d3s4_blob_manifest_body_bytes(value: bytes) -> bytearray:
    return bytearray(bytes(value)[108:-4])


def _d3s4_blob_pvd_linked_primary_raw(
    feed: Optional["PortFeed"], pvd: bytes, pf: int, ps: int,
) -> Optional[bytes]:
    """Return anchor txn raw when a feed row's VALUE_DIGEST equals source PVD."""
    if feed is None or pvd == D1_ZERO32:
        return None
    for k, v in feed._store.items():
        if len(k) < 10 or int(k[8]) != int(pf) or int(k[9]) != int(ps):
            continue
        if hashlib.sha256(v).digest() != bytes(pvd):
            continue
        if len(v) < 124:
            return None
        return bytes(v[108:124])
    return None


def _d3s4_recompute_blob_manifest_bid_in_body(body: bytearray) -> None:
    """Refresh manifest blob_id_digest[0:32] after owner_kind/raw mutation."""
    parsed = _d3s4_parse_blob_manifest_body(bytes(body))
    if parsed is None:
        return
    d3s3 = _load_d3s3_d1()
    body[0:32] = d3s3.blob_id_digest(
        int(parsed["owner_kind"]), bytes(parsed["owner_raw"]),
        int(parsed["blob_kind"]), bytes(parsed["content_digest"]),
        int(parsed["total_length"]),
    )


def _d3s4_patch_chunk_entry0_key(rows: List[Dict[str, Any]], new_key: bytes) -> None:
    """Substitute witness-manifest chunk entry 0 member key (BLOB chunk-as-source path)."""
    for r in rows:
        if r.get("family") == 6 and r.get("subtype") == 0x7E:
            vb = bytearray(bytes.fromhex(r["value_hex"]))
            body_off = 108
            o = body_off + 40
            klen = int.from_bytes(vb[o + 4:o + 6], "big")
            if len(new_key) != klen:
                raise SystemExit("error: chunk entry key length mismatch")
            vb[o + 8:o + 8 + klen] = new_key
            r["value_hex"] = _m31_32_fix_crc(vb).hex()
            return
    raise SystemExit("error: chunk row missing for entry key patch")


def _d3s4_patch_blob_manifest_body(row: Dict[str, Any], mut: Any) -> None:
    v = bytes.fromhex(row["value_hex"])
    vb = bytearray(v[108:-4])
    mut(vb)
    d3s1 = _load_d3s1()
    row["value_hex"] = d3s1.enc_env_full(
        6, 0x30, int(v[15]) & 0xFF, int.from_bytes(v[16:24], "big"),
        v[24:40], v[40:72], v[72:104], bytes(vb),
    ).hex()


def _d3s4_m31_32_align_blob_source_pvd(rows: List[Dict[str, Any]]) -> None:
    prim_val = bytes.fromhex(
        next(r["value_hex"] for r in rows if r.get("subtype") == 0x20)
    )
    pvd = hashlib.sha256(prim_val).digest()
    for r in rows:
        if r.get("subtype") == 0x30 and _d3s4_blob_env_flags(bytes.fromhex(r["value_hex"])) == 1:
            vb = bytearray(bytes.fromhex(r["value_hex"]))
            vb[72:104] = pvd
            r["value_hex"] = _m31_32_fix_crc(vb).hex()
            return


_D3S4_N2_NEG_VIDS: FrozenSet[str] = frozenset(
    "D3S4_NEG_N%d" % n for n in range(35, 45)
)


def _d3s4_build_m31_32_n2_neg_rows(
    vid: str, mode: int, *, salt: int = 0,
) -> List[Dict[str, Any]]:
    """B3 N2 series: clone BLOB_OK1 base + apply exactly one BLOB normalization mutation."""
    rows = copy.deepcopy(_d3s4_build_m31_32_blob_manifest_rows(mode, salt=salt))
    d3s1 = _load_d3s1()
    d3s3 = _load_d3s3_d1()
    src_row = next(r for r in rows if r.get("subtype") == 0x30
                   and _d3s4_blob_env_flags(bytes.fromhex(r["value_hex"])) == 1)
    prim_row = next(r for r in rows if r.get("subtype") == 0x20)
    man_k = bytes.fromhex(src_row["key_hex"])
    man_v = bytes.fromhex(src_row["value_hex"])

    if vid == "D3S4_NEG_N35":
        def _n35_mut(b: bytearray) -> None:
            b[32:34] = struct.pack(">H", 2)
            _d3s4_recompute_blob_manifest_bid_in_body(b)
        _d3s4_patch_blob_manifest_body(src_row, _n35_mut)
    elif vid == "D3S4_NEG_N36":
        def _n36_mut(b: bytearray) -> None:
            b[40] ^= 0x01
            _d3s4_recompute_blob_manifest_bid_in_body(b)
        _d3s4_patch_blob_manifest_body(src_row, _n36_mut)
    elif vid == "D3S4_NEG_N37":
        prim_row["key_hex"] = d3s1.d1_row("DSB2_ANCHOR_TYPED")["key_hex"]
        ing = next(r for r in _d3s4_semantic_member_rows() if r.get("subtype") == 0x27)
        prim_row["value_hex"] = ing["value_hex"]
        prim_row["subtype"] = 0x27
        prim_row["role"] = (6 << 8) | 0x27
    elif vid == "D3S4_NEG_N38":
        stream = d3s3.body_of(man_v)
        stream = stream if isinstance(stream, bytes) else bytes(stream)
        if not stream:
            stream = b"\x71"
        chk_k, chk_v = d3s3.rebuild_chunk(man_k, man_v, stream[:1], 0)
        src_row["value_hex"] = _m31_32_set_head(chk_v, man_v[40:72]).hex()
    elif vid == "D3S4_NEG_N39":
        _d3s4_patch_blob_manifest_body(src_row, lambda b: b.__setitem__(0, b[0] ^ 0x01))
    elif vid == "D3S4_NEG_N40":
        stream = d3s3.body_of(man_v)
        stream = stream if isinstance(stream, bytes) else bytes(stream)
        if not stream:
            stream = b"\x71"
        chk_k, chk_v = d3s3.rebuild_chunk(man_k, man_v, stream[:1], 0)
        man_body = bytearray(d3s3.body_of(man_v))
        man_body[0] ^= 0x01
        man_v_mut = d3s1.enc_env_full(
            6, 0x30, 1, 1, man_v[24:40], man_v[40:72], man_v[72:104], bytes(man_body),
        )
        rows.append({
            "key_hex": man_k.hex(), "value_hex": man_v_mut.hex(),
            "id": "returned_manifest_wrong_bid_%d" % salt,
            "kind": "semantic_member", "family": 6, "subtype": 0x30,
            "role": (6 << 8) | 0x30,
        })
        src_row["key_hex"] = chk_k.hex()
        src_row["value_hex"] = _m31_32_set_head(chk_v, man_v[40:72]).hex()
        _d3s4_patch_chunk_entry0_key(rows, chk_k)
    elif vid == "D3S4_NEG_N41":
        stream = d3s3.body_of(man_v)
        stream = stream if isinstance(stream, bytes) else bytes(stream)
        if not stream:
            stream = b"\x71"
        chk_k, chk_v = d3s3.rebuild_chunk(man_k, man_v, stream[:1], 0)
        man_v_bad = d3s1.enc_env_full(
            6, 0x30, 2, 1, man_v[24:40], man_v[40:72], man_v[72:104],
            d3s3.body_of(man_v),
        )
        rows.append({
            "key_hex": man_k.hex(), "value_hex": man_v_bad.hex(),
            "id": "returned_manifest_bad_flags_%d" % salt,
            "kind": "semantic_member", "family": 6, "subtype": 0x30,
            "role": (6 << 8) | 0x30,
        })
        src_row["key_hex"] = chk_k.hex()
        src_row["value_hex"] = _m31_32_set_head(
            chk_v, man_v[40:72],
        ).hex()
        _d3s4_patch_chunk_entry0_key(rows, chk_k)
    elif vid == "D3S4_NEG_N42":
        prim_vb = bytearray(bytes.fromhex(prim_row["value_hex"]))
        prim_body = bytearray(prim_vb[108:-4])
        prim_body[0] ^= 0x01
        prim_vb[108:-4] = bytes(prim_body)
        prim_row["value_hex"] = _m31_32_fix_crc(prim_vb).hex()
        _d3s4_m31_32_align_blob_source_pvd(rows)
    elif vid == "D3S4_NEG_N43":
        prim_vb = bytearray(bytes.fromhex(prim_row["value_hex"]))
        prim_body = bytearray(prim_vb[108:-4])
        prim_body[0] ^= 0x01
        prim_vb[108:-4] = bytes(prim_body)
        prim_row["value_hex"] = _m31_32_fix_crc(prim_vb).hex()
    elif vid == "D3S4_NEG_N44":
        stream = d3s3.body_of(man_v)
        stream = stream if isinstance(stream, bytes) else bytes(stream)
        if not stream:
            stream = b"\x71"
        chk_k, chk_v = d3s3.rebuild_chunk(man_k, man_v, stream[:1], 0)
        man_v_wrong_pvd = d3s1.patch_pvd(man_v, hashlib.sha256(b"wrong-manifest-pvd").digest())
        rows.append({
            "key_hex": man_k.hex(), "value_hex": man_v_wrong_pvd.hex(),
            "id": "returned_manifest_wrong_pvd_%d" % salt,
            "kind": "semantic_member", "family": 6, "subtype": 0x30,
            "role": (6 << 8) | 0x30,
        })
        src_row["key_hex"] = chk_k.hex()
        pvd = hashlib.sha256(man_v).digest()
        src_row["value_hex"] = _m31_32_set_pvd(
            _m31_32_set_head(chk_v, man_v[40:72]), pvd,
        ).hex()
        _d3s4_patch_chunk_entry0_key(rows, chk_k)
    if vid in ("D3S4_NEG_N35", "D3S4_NEG_N36", "D3S4_NEG_N39", "D3S4_NEG_N42", "D3S4_NEG_N43"):
        _d3s4_resync_m31_32_chunk_digests(rows)
        _d3s4_refresh_m31_32_header_manifest(rows)
    if vid in ("D3S4_NEG_N38", "D3S4_NEG_N40", "D3S4_NEG_N41", "D3S4_NEG_N44"):
        _d3s4_resync_m31_32_chunk_digests(rows)
        _d3s4_refresh_m31_32_header_manifest(rows)
    return rows


